insert into public.reading_passages (
  id, language, level, title, body, questions, sort_order
) values
('en-passage-a1-01', 'en', 'A1', 'My Independent Morning', 'Every morning, I wake up at six o''clock. I live alone in a small apartment in Sao Paulo. First, I make my bed and open the windows to let in the fresh air. I feel happy when my room is clean.

After cleaning, I go to the kitchen to prepare breakfast. I drink black coffee and eat a piece of bread with butter. I check my emails on my phone while I eat. This quiet time is important for me to start my day.

At eight o''clock, I leave for work. I take the bus to the city center. I enjoy being independent and managing my own schedule. Being organized helps me feel ready for the busy day ahead of me.', '[{"prompt":"What does the person do immediately after waking up?","options":["Drinks coffee","Checks emails","Makes the bed","Takes the bus"],"answer_index":2,"explanation_pt_br":"O texto afirma explicitamente que a primeira tarefa após acordar é arrumar a cama."},{"prompt":"What does the word ''independent'' mean in this text?","options":["Living and managing things alone","Working in a large office","Taking the bus every day","Eating breakfast very fast"],"answer_index":0,"explanation_pt_br":"O contexto mostra que a pessoa mora sozinha e cuida da própria rotina, caracterizando independência."},{"prompt":"What is the main idea of the story?","options":["How to make coffee","The narrator''s morning routine","The traffic in Sao Paulo","Where the narrator works"],"answer_index":1,"explanation_pt_br":"O texto descreve passo a passo as atividades matinais do narrador."}]'::jsonb, 1),
('en-passage-a1-02', 'en', 'A1', 'A Trip to Salvador', 'Next month, I am going to Salvador for a vacation. I want to see the historic buildings and learn about the local culture. I bought my plane tickets last week and booked a nice hotel near the beach.

I plan to visit the famous Pelourinho area on my first day. I want to walk through the colorful streets and take many photographs. I also hope to listen to traditional music and meet new people during my stay.

Traveling is a great way to discover new places. I am very excited to try the local food and enjoy the warm sun. This trip will be a wonderful experience for me and my family.', '[{"prompt":"When will the person travel to Salvador?","options":["Last week","Next month","Today","Yesterday"],"answer_index":1,"explanation_pt_br":"O texto menciona que a viagem acontecerá no próximo mês."},{"prompt":"What does the narrator want to do in Pelourinho?","options":["Work at a hotel","Buy plane tickets","Take photographs","Cook local food"],"answer_index":2,"explanation_pt_br":"O autor expressa o desejo de caminhar pelas ruas coloridas e tirar muitas fotos."},{"prompt":"What is the order of the narrator''s plans?","options":["Book hotel, buy tickets, travel","Buy tickets, book hotel, visit","Visit, travel, book hotel","Travel, visit, buy tickets"],"answer_index":1,"explanation_pt_br":"O texto diz que ele comprou os bilhetes, reservou o hotel e depois fará a visita."}]'::jsonb, 2),
('en-passage-a1-03', 'en', 'A1', 'Professional Email Habits', 'In my office, communication is very important. I send many emails to my colleagues every day. I always start with a polite greeting like ''Dear'' and finish with ''Best regards''. This shows respect to everyone.

I check my inbox twice a day: once in the morning and once after lunch. When I receive a message, I try to answer quickly. If the request is difficult, I call my manager to ask for help.

Good communication makes our work easier. We share files and talk about projects clearly. When everyone is polite and fast, we finish our tasks on time. I like working in such a professional environment.', '[{"prompt":"How does the narrator start a professional email?","options":["With a phone call","With a polite greeting","With a long document","With a lunch invitation"],"answer_index":1,"explanation_pt_br":"O texto menciona o uso de saudações educadas como ''Dear'' ao iniciar e-mails."},{"prompt":"What does the narrator do when a task is hard?","options":["Ignores the email","Sends a long email","Calls the manager","Finishes the task alone"],"answer_index":2,"explanation_pt_br":"O texto diz que, se o pedido for difícil, a pessoa liga para o gerente para pedir ajuda."},{"prompt":"What is the main goal of good communication at work?","options":["To send many files","To finish work on time","To eat lunch together","To call the manager often"],"answer_index":1,"explanation_pt_br":"O texto afirma que uma boa comunicação ajuda a terminar as tarefas no prazo."}]'::jsonb, 3),
('en-passage-a1-04', 'en', 'A1', 'Healthy Living Choices', 'Staying healthy is a priority for me. Every evening, I go for a walk in the park near my house. Walking is simple, but it makes me feel strong. I also drink eight glasses of water every day.

I try to eat more vegetables and fruits instead of sugary snacks. I feel much better when I eat healthy meals. Sometimes, I cook chicken with salad for dinner. It is delicious and gives me a lot of energy.

Sleep is also very important for well-being. I go to bed at ten o''clock to get enough rest. When I sleep well, I am more productive the next day. Small changes in my habits help me live better.', '[{"prompt":"What does the narrator do in the evening?","options":["Walks in the park","Drinks coffee","Goes to the gym","Sleeps for ten hours"],"answer_index":0,"explanation_pt_br":"O texto diz que o autor caminha no parque todas as noites."},{"prompt":"What does ''productive'' mean in this context?","options":["Tired and sleepy","Feeling very hungry","Working or doing things well","Eating many vegetables"],"answer_index":2,"explanation_pt_br":"O texto associa o sono de qualidade a uma maior capacidade de realizar tarefas no dia seguinte."},{"prompt":"Which food does the narrator prefer to eat?","options":["Sugary snacks","Only chicken","Vegetables and fruits","Only bread"],"answer_index":2,"explanation_pt_br":"O texto diz que o autor tenta comer mais vegetais e frutas em vez de lanches doces."}]'::jsonb, 4),
('en-passage-a1-05', 'en', 'A1', 'Community and Traditions', 'In my neighborhood, we have a big lunch every Sunday. All the families bring a traditional dish to the community center. We share food and talk about our lives. It is a very happy tradition.

I usually make a special rice dish with beans. My neighbor brings a sweet cake that everyone loves. We play music and some people dance together. It is a great time to learn about each other''s culture.

These gatherings make our community strong. We support each other and become good friends. I feel lucky to live in a place with such kind people. Traditions help us stay connected to our roots.', '[{"prompt":"When does the community have a big lunch?","options":["Every Monday","Every Sunday","Once a year","On holidays only"],"answer_index":1,"explanation_pt_br":"O texto especifica que o almoço comunitário ocorre todos os domingos."},{"prompt":"What does the neighbor bring to the lunch?","options":["Rice","Beans","A sweet cake","Traditional music"],"answer_index":2,"explanation_pt_br":"O texto afirma claramente que o vizinho traz um bolo doce."},{"prompt":"What is the main idea of the passage?","options":["How to cook rice","The importance of community traditions","Why dancing is healthy","Where the community center is"],"answer_index":1,"explanation_pt_br":"O texto descreve como as tradições de almoço ajudam a fortalecer os laços entre os vizinhos."}]'::jsonb, 5),
('en-passage-a1-06', 'en', 'A1', 'My Digital Day', 'Every morning, I wake up and check my smartphone. I look at the weather app to see if it will rain today. Then, I check my emails and messages from my friends. Technology is very important for my daily routine.

At work, I use a laptop to write reports and send files to my team. We use video calls to talk with people in other cities. It is fast and easy to stay connected with my colleagues all day long.

In the evening, I relax with my tablet. I read news articles or watch short videos. Sometimes, I play simple games before I go to sleep. My digital devices help me finish my tasks and have fun.', '[{"prompt":"What does the person do first in the morning?","options":["Checks the weather app","Writes reports","Plays digital games","Sends work emails"],"answer_index":0,"explanation_pt_br":"O texto afirma que a primeira ação ao acordar é olhar o aplicativo de previsão do tempo."},{"prompt":"What does the word ''connected'' mean in the text?","options":["To be tired","To be linked","To be late","To be busy"],"answer_index":1,"explanation_pt_br":"No contexto de comunicação por videochamadas, ''connected'' significa estar ligado ou em contato com outros."},{"prompt":"What is the main idea of the passage?","options":["Technology is only for work","The person hates digital devices","Technology is part of the daily routine","The person never uses a smartphone"],"answer_index":2,"explanation_pt_br":"O texto descreve como a tecnologia é usada durante todo o dia, provando ser parte da rotina."}]'::jsonb, 6),
('en-passage-a1-07', 'en', 'A1', 'A Greener Life', 'Maria wants to help the planet. She starts by recycling her plastic bottles and paper at home. She puts these items in special blue and yellow bins. This simple habit keeps her house clean and organized.

Next, she decides to walk to the local market instead of using her car. She carries a reusable bag for her vegetables and fruits. She buys local food because it does not travel far to reach her small town.

Finally, Maria turns off the lights when she leaves a room. She also saves water by taking shorter showers every day. Small changes in her daily life make a big difference for the environment in our community.', '[{"prompt":"Where does Maria put her plastic bottles?","options":["In the trash bin","In the special bins","In her car","In the market"],"answer_index":1,"explanation_pt_br":"O texto menciona que ela coloca os itens recicláveis em lixeiras especiais."},{"prompt":"Why does Maria walk to the market?","options":["To buy a new car","Because she has no money","To avoid using her car","To exercise alone"],"answer_index":2,"explanation_pt_br":"Ela escolhe caminhar como uma escolha sustentável em vez de usar o carro."},{"prompt":"What happens after Maria buys local food?","options":["She turns off the lights","She goes to the park","She throws away the bag","She drives to work"],"answer_index":0,"explanation_pt_br":"A sequência do texto coloca o desligar das luzes após as ações de compra no mercado."}]'::jsonb, 7),
('en-passage-a1-08', 'en', 'A1', 'Friends and Family', 'I have a very large family. Every Sunday, we gather at my grandmother''s house for a big lunch. We share stories, laugh together, and enjoy delicious food. It is the best day of my busy week.

I also have many good friends from school. We like to meet at the park on Saturday afternoons. Sometimes we play sports, and sometimes we just talk about our lives. They are very important to me.

Building strong relationships takes time and effort. I always call my parents on the phone during the week. I try to be a good listener for my friends too. Loving people makes my life very happy.', '[{"prompt":"When does the family meet for lunch?","options":["On Saturdays","On Sundays","Every day","On Fridays"],"answer_index":1,"explanation_pt_br":"O texto especifica que a reunião de família acontece aos domingos."},{"prompt":"What does the word ''gather'' mean in the text?","options":["To eat","To sleep","To meet together","To work hard"],"answer_index":2,"explanation_pt_br":"No contexto da família, ''gather'' significa reunir-se."},{"prompt":"What does the person do to maintain relationships?","options":["Calls parents on the phone","Only meets at the park","Plays sports every day","Never listens to friends"],"answer_index":0,"explanation_pt_br":"O autor menciona que liga para os pais durante a semana para manter o relacionamento."}]'::jsonb, 8),
('en-passage-a1-09', 'en', 'A1', 'Smart Spending', 'My friend Carlos is very good with money. He writes down everything he buys in a small notebook. This helps him see where his money goes every month. He wants to save for a big trip.

Carlos rarely buys expensive clothes or fancy coffee. He prefers to cook healthy meals at home. When he goes to the supermarket, he always looks for sales. This way, he keeps his monthly budget very low.

Saving money is a great skill for everyone. Carlos feels happy because he does not have any debt. He knows that small choices today lead to a better future. He is proud of his financial habits.', '[{"prompt":"Why does Carlos keep a notebook?","options":["To write stories","To track his spending","To draw pictures","To study for school"],"answer_index":1,"explanation_pt_br":"O texto diz que ele anota o que compra para ver para onde o dinheiro vai."},{"prompt":"What does ''rarely'' mean in the passage?","options":["Always","Often","Not very often","Every day"],"answer_index":2,"explanation_pt_br":"O termo ''rarely'' indica algo que acontece com pouca frequência."},{"prompt":"How does Carlos feel about his financial habits?","options":["He feels proud","He feels sad","He feels confused","He feels angry"],"answer_index":0,"explanation_pt_br":"O autor afirma claramente que Carlos sente orgulho de seus hábitos financeiros."}]'::jsonb, 9),
('en-passage-a1-10', 'en', 'A1', 'Learning Forever', 'Education does not stop after school. Many adults enjoy learning new things every year. Some people take online classes to improve their work skills. Others learn to play music or speak a new language.

I decided to study English because I want to travel. I read books, watch movies, and practice with my teacher. It is difficult sometimes, but I feel smart when I learn a new word or sentence.

Lifelong learning keeps our minds active and strong. It is never too late to start a new hobby or project. We can always find time to grow and become better versions of ourselves through education.', '[{"prompt":"Why is the person studying English?","options":["To find a new job","To travel","To play music","To teach children"],"answer_index":1,"explanation_pt_br":"O texto diz explicitamente que a pessoa estuda inglês porque quer viajar."},{"prompt":"What is the main idea of the text?","options":["School is very bad","Learning ends at eighteen","Education is important for all ages","Only children should learn"],"answer_index":2,"explanation_pt_br":"O texto defende a ideia de que o aprendizado deve continuar durante toda a vida."},{"prompt":"What happens after the person learns a new word?","options":["They feel smart","They get tired","They stop studying","They go to sleep"],"answer_index":0,"explanation_pt_br":"A frase afirma que a pessoa se sente inteligente ao aprender algo novo."}]'::jsonb, 10),
('en-passage-a2-01', 'en', 'A2', 'Lucas''s Morning Routine', 'Lucas lives alone in a small apartment in São Paulo. Every weekday, his alarm clock rings at 6:30 AM. He does not like to rush, so he gets up immediately and makes his bed before going to the kitchen to prepare a strong cup of coffee.

After drinking his coffee, Lucas takes a quick shower and gets dressed for his job as a clerk. He usually wears a light blue shirt and dark trousers. He checks his bag to make sure he has his laptop, his keys, and his lunch box. He likes to be very organized.

He leaves his house at 7:45 AM to catch the subway. The commute takes about forty minutes. During this time, he listens to English podcasts to improve his listening skills. He enjoys learning new things while he travels to the city center for his morning shift.

By 8:30 AM, he is at his desk and ready to start the day. Lucas feels proud of his independence. He likes having a clear routine because it helps him stay calm and productive throughout his busy work week.', '[{"prompt":"What does Lucas do immediately after his alarm rings?","options":["He drinks coffee","He prepares his lunch","He gets up","He goes to the subway"],"answer_index":2,"explanation_pt_br":"O texto afirma explicitamente que ele se levanta imediatamente após o despertador tocar."},{"prompt":"What is the meaning of ''commute'' in the third paragraph?","options":["The time spent traveling to work","The act of drinking coffee","The work he does at his desk","The morning exercise"],"answer_index":0,"explanation_pt_br":"No contexto, commute refere-se ao trajeto diário que ele faz entre sua casa e o trabalho."},{"prompt":"What is the sequence of Lucas''s morning?","options":["Work, shower, coffee","Alarm, coffee, shower, subway","Subway, breakfast, work, alarm","Shower, alarm, coffee, work"],"answer_index":1,"explanation_pt_br":"A ordem correta dos eventos descritos é despertar, tomar café, tomar banho e ir para o metrô."},{"prompt":"What is the main idea of the passage?","options":["Lucas hates his job in the city","Lucas finds comfort in his daily schedule","Living alone is very difficult for Lucas","Lucas wants to change his morning habits"],"answer_index":1,"explanation_pt_br":"O texto destaca como Lucas se orgulha de sua independência e gosta de sua rotina organizada."}]'::jsonb, 1),
('en-passage-a2-02', 'en', 'A2', 'A Trip to London', 'Beatriz decided to travel to London last summer to practice her English. She saved money for two years to afford the flight and the hotel. She felt very excited but also a little nervous because it was her first international trip alone.

When she arrived, the city was very different from Brazil. The buildings were old and the weather was quite cold, even in July. She walked through the parks and visited many famous museums. She loved seeing the history of the city in person.

One afternoon, she got lost while looking for a bookstore. She asked a local person for directions, and the woman was very kind. They talked for ten minutes about Brazilian music. It was a great cultural experience for Beatriz to meet someone new.

By the end of the trip, Beatriz felt much more confident. She realized that traveling alone is a wonderful way to learn about the world. She returned home with many photos, new vocabulary, and a strong desire to plan her next big adventure.', '[{"prompt":"Why did Beatriz travel to London?","options":["To visit her family","To work in a museum","To improve her English","To buy a bookstore"],"answer_index":2,"explanation_pt_br":"O texto menciona que ela viajou para praticar o seu inglês."},{"prompt":"What does ''local'' mean in the third paragraph?","options":["A person from the city","A tourist from Brazil","A travel guide book","A map of London"],"answer_index":0,"explanation_pt_br":"Local refere-se a alguém que vive ou é daquela região específica."},{"prompt":"How did Beatriz feel before her trip?","options":["Confident and relaxed","Sad and lonely","Excited and nervous","Bored and tired"],"answer_index":2,"explanation_pt_br":"O primeiro parágrafo diz que ela estava empolgada, mas também um pouco nervosa."},{"prompt":"What is the main point of the story?","options":["London is too cold for Brazilians","Traveling alone helps people grow","Beatriz wants to live in England","Museums are the best part of traveling"],"answer_index":1,"explanation_pt_br":"A conclusão do texto foca no crescimento pessoal e na confiança que Beatriz adquiriu ao viajar sozinha."}]'::jsonb, 2),
('en-passage-a2-03', 'en', 'A2', 'Professional Email Communication', 'Communication is very important in the modern workplace. Ricardo works in an international company and often writes emails to partners in other countries. He knows that being clear and polite is essential to build good professional relationships with his colleagues.

When writing an email, Ricardo always starts with a formal greeting like ''Dear Mr. Smith''. He avoids using slang because he wants to be professional. He double-checks his spelling and grammar before clicking the send button to ensure there are no mistakes.

Sometimes, his colleagues send him long messages. Ricardo reads them carefully and highlights the important dates. If he does not understand a request, he asks a question immediately instead of guessing. This helps him avoid misunderstandings and saves valuable time for everyone.

At the end of the day, Ricardo feels satisfied with his work. He believes that good communication makes the office environment better. By being respectful and clear, he ensures that his team works together effectively to reach their shared goals every single month.', '[{"prompt":"Why does Ricardo check his emails for mistakes?","options":["To practice his typing","To be professional","To make the email longer","To impress his boss"],"answer_index":1,"explanation_pt_br":"O texto afirma que ele revisa para garantir que não haja erros e ser profissional."},{"prompt":"What does ''essential'' mean in the first paragraph?","options":["Very important","A bit difficult","Not necessary","Quite expensive"],"answer_index":0,"explanation_pt_br":"Essential é um adjetivo usado para algo que é fundamental ou muito importante."},{"prompt":"What does Ricardo do if he does not understand a request?","options":["He ignores the email","He guesses the meaning","He asks a question","He deletes the message"],"answer_index":2,"explanation_pt_br":"O texto diz que ele faz uma pergunta imediatamente se não entender algo."},{"prompt":"What is the main idea of the text?","options":["Writing emails is the only task at work","Ricardo prefers to work alone","Clear communication is vital for work success","Companies should use less email"],"answer_index":2,"explanation_pt_br":"O texto centraliza a importância da comunicação clara e educada no ambiente profissional."}]'::jsonb, 3),
('en-passage-a2-04', 'en', 'A2', 'Healthy Living Habits', 'Maintaining good health is a priority for Camila. She believes that a balanced life comes from small daily choices. Every morning, she drinks a large glass of water and eats fresh fruit. She thinks that starting the day with nutrients gives her energy.

In the afternoon, Camila likes to walk in the park near her house. She does not like heavy gym sessions, so walking for thirty minutes is perfect for her heart. She enjoys breathing the fresh air and listening to the birds during her exercise.

Sleep is also a big part of her health routine. She tries to turn off her phone one hour before going to bed. This helps her mind relax after a long day. She wakes up feeling refreshed and ready to face any challenges at work.

Camila knows that being healthy is not just about the body. It is also about feeling happy and calm. By taking care of herself, she feels better every day. She encourages her friends to find simple habits that make them feel good too.', '[{"prompt":"What is Camila''s favorite exercise?","options":["Going to the gym","Running in the park","Walking for thirty minutes","Playing with birds"],"answer_index":2,"explanation_pt_br":"O texto diz que ela caminha por trinta minutos, pois não gosta de sessões pesadas de academia."},{"prompt":"What does ''refreshed'' mean in the third paragraph?","options":["Feeling very cold","Feeling tired again","Feeling energized and rested","Feeling hungry for breakfast"],"answer_index":2,"explanation_pt_br":"Refreshed, neste contexto, significa sentir-se revigorado e descansado após o sono."},{"prompt":"What does Camila do before sleeping?","options":["She walks in the park","She turns off her phone","She drinks a lot of water","She eats fresh fruit"],"answer_index":1,"explanation_pt_br":"O texto menciona que ela desliga o telefone uma hora antes de dormir para relaxar a mente."},{"prompt":"What is the main idea of the text?","options":["Healthy living involves simple, daily habits","You need a gym to be healthy","Sleeping is more important than eating","Camila wants to become a doctor"],"answer_index":0,"explanation_pt_br":"O texto foca na ideia de que a saúde equilibrada vem de pequenas escolhas diárias."}]'::jsonb, 4),
('en-passage-a2-05', 'en', 'A2', 'Community and Food Traditions', 'In the small town where Marcos lives, food is the center of every celebration. Every Sunday, his family gathers for a large lunch. They usually prepare a traditional recipe that his grandmother taught them many years ago. It is a very special time.

The neighbors often join the meal. Everyone brings a different dish to share with the group. There is always a lot of laughter and talking. Marcos believes that sharing food is the best way to keep the community connected and happy.

Cooking these traditional meals takes a lot of time and patience. Marcos helps by chopping vegetables and setting the table. He likes learning the secrets of the recipes. He wants to keep these traditions alive for the younger people in his family.

These gatherings are more than just eating. They are about building strong relationships with people. Marcos loves his community and the warmth of these traditions. He knows that as long as they eat together, they will remain close friends for many years.', '[{"prompt":"When does the family gather for lunch?","options":["Every Saturday","Every Sunday","Once a month","Only on holidays"],"answer_index":1,"explanation_pt_br":"O texto afirma explicitamente que a família se reúne para almoçar todos os domingos."},{"prompt":"What does ''gathers'' mean in the first paragraph?","options":["Cooks food","Comes together","Cleans the house","Goes to the market"],"answer_index":1,"explanation_pt_br":"Gather significa reunir-se ou juntar-se em um mesmo local."},{"prompt":"How does Marcos help with the meal?","options":["He buys the ingredients","He cooks the meat","He chops vegetables and sets the table","He cleans the kitchen"],"answer_index":2,"explanation_pt_br":"O terceiro parágrafo descreve que ele ajuda cortando vegetais e arrumando a mesa."},{"prompt":"What is the main idea of the passage?","options":["Marcos is a professional chef","Traditional food is hard to cook","Food and traditions connect the community","The neighbors do not like to share food"],"answer_index":2,"explanation_pt_br":"O texto enfatiza como compartilhar refeições fortalece os laços e a conexão na comunidade."}]'::jsonb, 5),
('en-passage-a2-06', 'en', 'A2', 'Technology in My Daily Routine', 'Every morning, I wake up to the sound of my smartphone alarm. Before I even get out of bed, I check my email and look at the weather forecast. Technology is a big part of my life, and it helps me organize my busy schedule easily.

At work, I use a laptop to send messages to my colleagues and attend video meetings. We work in different cities, but the internet makes us feel like we are in the same room. It saves a lot of time because we do not need to travel for every meeting.

In the evening, I enjoy relaxing with my tablet. I often watch videos about cooking or read news articles from around the world. Sometimes, I use apps to order food if I am too tired to cook dinner. It is very convenient for my lifestyle.

However, I sometimes feel that I spend too much time looking at screens. I try to turn off my devices two hours before I sleep to rest my eyes. Technology is useful, but I think balance is the most important thing for everyone today.', '[{"prompt":"What is the first thing the narrator does in the morning?","options":["Cooks a healthy breakfast","Checks digital information","Travels to the office","Turns off the alarm clock"],"answer_index":1,"explanation_pt_br":"O narrador diz que verifica e-mails e a previsão do tempo antes mesmo de sair da cama."},{"prompt":"What does the word ''convenient'' mean in the third paragraph?","options":["Difficult and slow","Expensive and rare","Easy and helpful","Boring and long"],"answer_index":2,"explanation_pt_br":"Convenient refere-se a algo que facilita a vida ou é prático."},{"prompt":"Why does the narrator use a laptop at work?","options":["To travel to other cities","To watch cooking videos","To communicate with people","To order food for colleagues"],"answer_index":2,"explanation_pt_br":"O texto menciona o uso do laptop para enviar mensagens e participar de reuniões."},{"prompt":"What is the main idea of the passage?","options":["Technology is bad for health","Work is better with computers","Technology is useful but requires balance","Everyone needs a tablet to live"],"answer_index":2,"explanation_pt_br":"O autor conclui que a tecnologia é útil, mas que o equilíbrio é o mais importante."}]'::jsonb, 6),
('en-passage-a2-07', 'en', 'A2', 'Living a Greener Life', 'Many people are worried about the environment today. Climate change is a real problem, but we can all make small changes in our daily lives to help the planet. It is not always easy, but every action counts for the future.

One simple change is to reduce the use of plastic. I started carrying a reusable water bottle and a fabric bag for my groceries. These simple items help me avoid using plastic bags and bottles that end up in the ocean every single year.

Another way to help is to save electricity at home. I always turn off the lights when I leave a room and unplug my chargers. These habits are not just good for nature; they also help me save money on my monthly energy bills.

Finally, I try to recycle paper, glass, and metal properly. It takes a few extra minutes to sort my trash, but it keeps our city cleaner. I believe that if we all do our part, we can make the world a better place.', '[{"prompt":"What does the narrator carry to the grocery store?","options":["A plastic bag","A fabric bag","A glass bottle","A metal container"],"answer_index":1,"explanation_pt_br":"O narrador menciona que carrega uma sacola de tecido para as compras."},{"prompt":"What does ''unplug'' mean in the third paragraph?","options":["To turn on the light","To fix a broken cable","To remove from the socket","To buy a new charger"],"answer_index":2,"explanation_pt_br":"Unplug significa retirar um aparelho da tomada."},{"prompt":"What is the order of the actions mentioned in the text?","options":["Recycling, then shopping, then electricity","Plastic reduction, then electricity, then recycling","Sorting trash, then buying plastic, then saving energy","Saving energy, then recycling, then using plastic"],"answer_index":1,"explanation_pt_br":"O texto segue a ordem: redução de plástico, economia de energia e reciclagem."},{"prompt":"What is the main message of the text?","options":["Recycling is too difficult for most people","Individual actions can make a positive difference","Electricity is the biggest problem for nature","We should stop using all technology"],"answer_index":1,"explanation_pt_br":"O texto enfatiza que pequenas mudanças individuais ajudam o planeta."}]'::jsonb, 7),
('en-passage-a2-08', 'en', 'A2', 'Building Strong Friendships', 'Social life is very important for our happiness. Having good friends makes the hard days easier and the happy days much better. I have a small group of friends that I have known since I was in high school.

We try to meet at least once every two weeks for dinner or coffee. We usually talk about our jobs, our families, and the things we want to do in the future. It is a great way to stay connected despite our busy lives.

Sometimes, we have different opinions, but we always respect each other. Listening is the most important part of a friendship. When a friend has a problem, I try to listen carefully and offer support without judging them or their mistakes.

Technology also helps us stay in touch when we cannot meet in person. We have a group chat where we share photos and funny stories every day. Even when we are far apart, our friendship remains very strong and very special.', '[{"prompt":"How often does the group of friends meet?","options":["Every day","Every week","Every two weeks","Once a year"],"answer_index":2,"explanation_pt_br":"O texto afirma que eles tentam se encontrar a cada duas semanas."},{"prompt":"What does ''stay in touch'' mean in the fourth paragraph?","options":["To touch someone gently","To maintain communication","To live in the same house","To meet only in person"],"answer_index":1,"explanation_pt_br":"Stay in touch significa manter contato ou comunicação."},{"prompt":"How do the friends handle different opinions?","options":["They stop talking to each other","They argue until one wins","They respect each other","They ask someone else to decide"],"answer_index":2,"explanation_pt_br":"O autor menciona que, apesar das opiniões diferentes, eles sempre se respeitam."},{"prompt":"What is the best title for this passage?","options":["The Importance of High School","How to Use Group Chats","The Value of Good Friendships","Talking About Jobs and Money"],"answer_index":2,"explanation_pt_br":"O texto foca nos benefícios e na manutenção de uma amizade."}]'::jsonb, 8),
('en-passage-a2-09', 'en', 'A2', 'Smart Spending Habits', 'Managing money is a skill that everyone should learn early in life. When I started my first job, I did not know how to save. I spent all my money on clothes and expensive dinners, and I had nothing left at the end of the month.

Now, I use a simple app to track my expenses. I write down everything I buy, from coffee to rent. This helps me see where my money goes and identify things that I do not really need to buy every single week.

I also have a budget for my entertainment. If I want to go to the cinema or buy a new book, I check if I have enough money first. Saving a little bit of money every month makes me feel much more relaxed and secure.

It is not about being cheap, but about being smart. By controlling my consumption, I can save for important goals like traveling or buying a house. Financial freedom is the best reward for being careful with my personal finances today.', '[{"prompt":"What did the narrator do with their money at their first job?","options":["They saved it for a house","They spent it on non-essential things","They gave it to their family","They invested it in an app"],"answer_index":1,"explanation_pt_br":"O narrador diz que gastava todo o dinheiro com roupas e jantares caros."},{"prompt":"What does ''track'' mean in the second paragraph?","options":["To hide or bury","To record or follow","To throw away","To increase quickly"],"answer_index":1,"explanation_pt_br":"Track, neste contexto, significa registrar ou acompanhar gastos."},{"prompt":"What happens after the narrator checks their budget?","options":["They buy everything they want","They stop working","They decide if they can afford an item","They delete the app from their phone"],"answer_index":2,"explanation_pt_br":"O narrador verifica o orçamento para saber se pode pagar pelo lazer."},{"prompt":"What is the main point of the passage?","options":["Eating out is always a bad idea","Apps are the only way to save money","Managing money well brings security","Working is the only way to get money"],"answer_index":2,"explanation_pt_br":"O texto defende que o controle financeiro traz segurança e liberdade."}]'::jsonb, 9),
('en-passage-a2-10', 'en', 'A2', 'Learning Throughout Life', 'Education does not end when we leave school or university. In fact, many people believe that learning is a lifelong process. Whether we want to get a better job or just learn a new hobby, there is always something new to discover.

I recently decided to start a Spanish course online. It is challenging because I am working full-time, but I really enjoy it. I spend thirty minutes every evening studying vocabulary and listening to podcasts to improve my speaking skills.

There are many free resources available on the internet today. You can find videos, articles, and even free classes from top universities. You do not need to spend a lot of money to learn something new if you have a computer and time.

Lifelong learning keeps our brains active and makes us more confident. It allows us to adapt to a changing world and meet interesting people. I am very happy that I started this journey because I feel more prepared for the future.', '[{"prompt":"When does education end, according to the text?","options":["After university","When we get a job","It never really ends","When we start a new hobby"],"answer_index":2,"explanation_pt_br":"O texto afirma que a educação não termina ao sair da escola, sendo um processo contínuo."},{"prompt":"What does ''challenging'' mean in the second paragraph?","options":["Very easy","Quite difficult","Very expensive","Very boring"],"answer_index":1,"explanation_pt_br":"Challenging significa desafiador, ou seja, algo difícil."},{"prompt":"How does the narrator practice Spanish?","options":["By traveling to Spain","By reading books all day","By listening to podcasts","By attending a university class"],"answer_index":2,"explanation_pt_br":"O narrador menciona que ouve podcasts para melhorar a fala."},{"prompt":"What is a benefit of lifelong learning?","options":["It helps you save money on groceries","It keeps the brain active","It makes you quit your job","It allows you to stop using computers"],"answer_index":1,"explanation_pt_br":"O quarto parágrafo diz que o aprendizado contínuo mantém o cérebro ativo."}]'::jsonb, 10),
('en-passage-b1-01', 'en', 'B1', 'Mastering the Morning Routine', 'For many working professionals in Brazil, the start of the day is a carefully choreographed dance. Lucas, a marketing coordinator in São Paulo, wakes up at 5:30 AM to ensure he has enough time for himself before the chaos of the city begins. He believes that a structured morning is the key to maintaining his independence and mental clarity throughout the long workday ahead.

After turning off his alarm, Lucas spends twenty minutes stretching and practicing light yoga. He finds that this physical activity helps him wake up without relying solely on caffeine. By 6:00 AM, he is in the kitchen preparing a nutritious breakfast of fruit, tapioca, and strong coffee. This quiet hour in the kitchen is his favorite part of the morning because it allows him to plan his tasks without interruptions.

Commuting is an inevitable part of his routine. Living in a large metropolis means that he must navigate public transportation with patience. While on the subway, he uses the time to catch up on industry news or listen to podcasts in English. This habit has significantly improved his language skills and keeps him informed about global trends, turning a stressful commute into a productive learning session.

Once he reaches his office, he follows a specific sequence of actions to settle in. He checks his emails, updates his to-do list, and prioritizes his most difficult tasks for the early morning hours. He has learned that tackling the hardest responsibilities first gives him a sense of accomplishment that lasts for the rest of the afternoon, preventing the common feeling of being overwhelmed by late-day fatigue.

Independence, for Lucas, is not just about living alone or paying bills; it is about managing one''s energy and time effectively. By sticking to his morning habits, he feels more in control of his professional life and personal goals. He encourages his colleagues to find their own rhythm, as he believes that a personalized routine can make a significant difference in one''s overall happiness and career satisfaction.', '[{"prompt":"What is the main reason Lucas practices yoga in the morning?","options":["To prepare for his long commute","To help him wake up without caffeine","To meet his friends before work","To finish his tasks more quickly"],"answer_index":1,"explanation_pt_br":"O texto afirma explicitamente que ele faz yoga para acordar sem depender apenas de cafeína."},{"prompt":"How does Lucas feel about his morning time in the kitchen?","options":["He finds it stressful and loud","He feels it is a waste of time","He appreciates the quiet and the planning","He wishes he could skip this part of the day"],"answer_index":2,"explanation_pt_br":"Lucas descreve a hora na cozinha como sua parte favorita, pois permite planejar sem interrupções."},{"prompt":"In the third paragraph, what does the word ''navigating'' imply?","options":["Traveling through a complex system","Driving a large vehicle","Fixing mechanical problems","Buying tickets for the subway"],"answer_index":0,"explanation_pt_br":"Neste contexto, ''navigating'' refere-se à habilidade de se deslocar ou lidar com a complexidade do transporte público."},{"prompt":"What is Lucas''s strategy for managing his workload?","options":["Doing the easiest tasks first","Working late into the evening","Handling the most challenging tasks early","Asking colleagues for help every morning"],"answer_index":2,"explanation_pt_br":"O texto menciona que ele prioriza as tarefas mais difíceis para as primeiras horas da manhã."},{"prompt":"What is the main idea of the passage?","options":["Public transport in São Paulo is difficult","A well-managed routine leads to better independence","Learning English is easier with podcasts","Marketing coordinators are always busy"],"answer_index":1,"explanation_pt_br":"O texto discute como uma rotina estruturada ajuda Lucas a manter independência e equilíbrio profissional."}]'::jsonb, 1),
('en-passage-b1-02', 'en', 'B1', 'The Joy of Cultural Discovery', 'Traveling is often described as the best way to expand one''s perspective, and for Julia, a student from Rio, it has been a transformative experience. Last year, she decided to save money for six months to visit Portugal. Her goal was not just to see the tourist attractions, but to immerse herself in the local culture and understand the historical connections between her country and the destination.

Upon arriving in Lisbon, Julia was immediately struck by the architecture. The tiled walls and narrow streets felt like a living museum. She spent her first few days walking without a map, allowing herself to get lost in the neighborhoods. This method of exploration helped her discover hidden cafes and small shops that were not mentioned in any of the popular travel guides she had purchased.

One of the most significant challenges she faced was the subtle difference in language usage. Although Brazilians and Portuguese speakers share the same tongue, the vocabulary and rhythm are quite distinct. Initially, she felt shy about ordering food or asking for directions. However, after a few days of observation and practice, she gained the confidence to initiate conversations with locals, which enriched her trip immensely.

Cultural discovery also meant attending local events. She was lucky enough to be in the city during a traditional festival. The music, the community dancing, and the traditional costumes provided a deep insight into the regional identity. She realized that by participating in these events, she was no longer a mere observer but a temporary part of the community, experiencing the traditions from the inside.

Returning home, Julia felt a sense of maturity and renewed curiosity. She realized that travel is not just about visiting new places; it is about challenging one''s own assumptions. She now plans to travel at least once a year, believing that every journey offers a lesson that cannot be learned in a classroom. For her, the world has become a much larger and more welcoming place.', '[{"prompt":"Why did Julia choose to travel to Portugal?","options":["To study at a university","To see the major tourist attractions only","To understand historical and cultural connections","To work as a guide in Lisbon"],"answer_index":2,"explanation_pt_br":"O texto menciona que o objetivo era entender as conexões históricas entre os dois países."},{"prompt":"What strategy did Julia use to explore Lisbon?","options":["Following a professional tour guide","Walking without a map to find hidden spots","Taking taxis to save time","Using an app to visit the most famous sites"],"answer_index":1,"explanation_pt_br":"Julia andava sem mapa para descobrir locais que não estavam nos guias turísticos."},{"prompt":"In the third paragraph, what does ''distinct'' mean?","options":["Similar","Difficult","Different","Common"],"answer_index":2,"explanation_pt_br":"No contexto das diferenças linguísticas, ''distinct'' significa diferente ou distinto."},{"prompt":"How did Julia''s attitude toward the locals change?","options":["She became more shy over time","She stopped speaking to avoid mistakes","She felt more confident after practicing","She decided to stop going to festivals"],"answer_index":2,"explanation_pt_br":"O texto diz que ela ganhou confiança para iniciar conversas após observar e praticar."},{"prompt":"What is the author''s primary message regarding travel?","options":["It is expensive but necessary","It challenges assumptions and promotes growth","It is better to stay home","It is only for students"],"answer_index":1,"explanation_pt_br":"O parágrafo final resume que viajar serve para desafiar suposições e promover crescimento pessoal."}]'::jsonb, 2),
('en-passage-b1-03', 'en', 'B1', 'Modern Professional Communication', 'In the fast-paced world of modern business, effective communication is the cornerstone of success. Whether you are working in a large multinational corporation or a small startup, the ability to convey your ideas clearly is essential. Professionals today must navigate a mix of emails, instant messaging, and video conferences, often switching between different platforms several times throughout a single working day.

One common challenge in professional settings is the tone of digital messages. When you cannot see the other person’s facial expressions or hear their tone of voice, misunderstandings can easily occur. Experts suggest that employees should always aim for clarity and politeness. Using bullet points, keeping sentences short, and proofreading before hitting send are simple habits that prevent confusion and maintain professional relationships.

Video meetings have also become a standard part of the professional landscape. While they offer the convenience of connecting people across different time zones, they require a specific set of skills. Participants need to be prepared, keep their cameras on to foster engagement, and respect the allotted time. A meeting that runs too long often leads to frustration and a lack of productivity among the team members.

Cultural awareness plays a vital role when communicating with international partners. Different countries have different expectations regarding formality and directness. For instance, in some cultures, it is important to build a personal relationship before discussing business, while in others, getting straight to the point is considered a sign of respect. Understanding these nuances helps professionals avoid awkward situations and build trust.

Ultimately, professional communication is about building bridges between people. By being an active listener and remaining adaptable, you can improve your reputation and efficiency. As the workplace continues to evolve with new technologies, the core principles of respect, clarity, and patience will remain the most important tools for anyone looking to advance in their career.', '[{"prompt":"Why can digital messages be difficult to interpret?","options":["Because they are too long","Because they lack non-verbal cues","Because they are always too formal","Because people don''t use technology well"],"answer_index":1,"explanation_pt_br":"O texto explica que a falta de expressões faciais e tom de voz causa mal-entendidos."},{"prompt":"What is a recommended habit for professional emails?","options":["Writing long paragraphs","Avoiding proofreading","Using bullet points for clarity","Writing only when necessary"],"answer_index":2,"explanation_pt_br":"O uso de bullet points é sugerido como uma forma de evitar confusão."},{"prompt":"What does the author suggest about video meetings?","options":["They are outdated and should be avoided","They should be kept short and focused","They are only for international partners","They are not very productive"],"answer_index":1,"explanation_pt_br":"O texto menciona que reuniões longas causam frustração, logo, devem ser breves e produtivas."},{"prompt":"In the fourth paragraph, what is the ''nuance'' referring to?","options":["The speed of the internet","The subtle differences in cultural expectations","The cost of business travel","The type of software used for communication"],"answer_index":1,"explanation_pt_br":"O texto discute como diferentes culturas esperam diferentes níveis de formalidade, o que são nuances."},{"prompt":"What is the main takeaway about career advancement?","options":["Technology is the only factor","Soft skills like patience and clarity remain crucial","Directness is always the best policy","Personal relationships are not important"],"answer_index":1,"explanation_pt_br":"O parágrafo final destaca que princípios como respeito e clareza são as ferramentas mais importantes."}]'::jsonb, 3),
('en-passage-b1-04', 'en', 'B1', 'Prioritizing Health and Well-being', 'Maintaining good health in a high-pressure environment is a challenge that many adults face today. With long hours spent sitting at desks and the constant pressure of deadlines, it is easy to forget about physical and mental needs. However, prioritizing well-being is not just a luxury; it is a necessity for long-term success and happiness in both personal and professional life.

Nutrition is the foundation of energy. Instead of relying on processed snacks or quick fast-food meals, many people are rediscovering the benefits of home-cooked food. Preparing simple meals with fresh vegetables, proteins, and whole grains provides the body with the sustained energy needed to focus. Small changes, like drinking more water throughout the day, can also lead to significant improvements in concentration and mood.

Regular physical exercise is another pillar of health. You do not need to spend hours in a gym to see results. A brisk thirty-minute walk, a short cycling session, or even practicing stretching during work breaks can make a massive difference. The goal is to keep the body moving, which helps reduce stress levels and improves the quality of sleep, allowing the brain to recover properly.

Mental well-being is equally important in this equation. Stress management techniques, such as mindfulness or meditation, are becoming increasingly popular. Taking even five minutes to breathe deeply or disconnect from screens can prevent burnout. It is essential to recognize the signs of fatigue early and take proactive steps to rest before reaching a point of exhaustion.

Ultimately, health is a personal journey that requires consistency. By making small, sustainable adjustments to your daily routine, you can create a lifestyle that supports your goals. Remember that listening to your body is the most important skill you can develop. When you feel well, you are better equipped to handle life''s challenges and enjoy the moments that truly matter.', '[{"prompt":"What does the author suggest about nutrition?","options":["Eating only fast food for convenience","Relying on processed snacks for energy","Preparing meals with fresh ingredients","Avoiding proteins to stay healthy"],"answer_index":2,"explanation_pt_br":"O texto incentiva a preparação de comida caseira com ingredientes frescos."},{"prompt":"What is a benefit of regular physical activity mentioned in the text?","options":["It requires a gym membership","It helps reduce stress and improves sleep","It makes you work faster","It eliminates the need for rest"],"answer_index":1,"explanation_pt_br":"O texto afirma que o movimento ajuda a reduzir o estresse e melhora a qualidade do sono."},{"prompt":"What does ''burnout'' mean in the context of the fourth paragraph?","options":["A type of physical exercise","A state of extreme exhaustion","A technique for meditation","A healthy eating plan"],"answer_index":1,"explanation_pt_br":"Burnout descreve um estado de exaustão extrema causado por estresse prolongado."},{"prompt":"What is the author''s advice regarding mental well-being?","options":["Ignore stress until it goes away","Use screen time to relax","Practice mindfulness or deep breathing","Work harder to forget your problems"],"answer_index":2,"explanation_pt_br":"O texto sugere técnicas como mindfulness ou respiração profunda para gerenciar o estresse."},{"prompt":"What is the main idea of the passage?","options":["Exercise is more important than food","Health requires a consistent and balanced approach","Being busy is the best way to stay healthy","Well-being is only for those with a lot of time"],"answer_index":1,"explanation_pt_br":"O texto enfatiza que a saúde é uma jornada que requer ajustes consistentes e equilibrados."}]'::jsonb, 4),
('en-passage-b1-05', 'en', 'B1', 'Food, Traditions, and Community', 'In Brazil, food is much more than just fuel for the body; it is the heart of community life. From the family Sunday lunch to the local street markets, the way we eat reflects our history and values. Sharing a meal is a universal language that brings people together, bridging generational gaps and creating memories that last a lifetime.

Traditional dishes are deeply connected to regional identity. In the Northeast, the smell of acarajé frying in palm oil reminds people of their roots, while in the South, the ritual of drinking chimarrão is a social act that promotes conversation and bonding. These traditions are passed down through generations, ensuring that cultural heritage remains alive in a rapidly changing world.

The community market is another essential space for connection. Walking through the stalls, you can see farmers selling fresh produce, local artisans showcasing their work, and neighbors chatting about the latest news. These markets are the backbone of local economies, supporting small producers and encouraging a more sustainable way of living that prioritizes quality and direct contact.

Modern life has changed how we consume food, but the desire for connection remains strong. Many people are now returning to traditional recipes as a way to feel grounded. Cooking a family dish is an act of love and respect for those who came before us. It is a way to celebrate our heritage while also adapting to the needs of modern, busy schedules.

Building community through food is a powerful way to foster belonging. Whether it is through a neighborhood potluck or a simple dinner with friends, these moments are vital for our well-being. By preserving our culinary traditions and supporting our local food systems, we strengthen the ties that bind us and ensure that our communities continue to thrive for years to come.', '[{"prompt":"Why is food considered the ''heart of community life'' in Brazil?","options":["Because it is very expensive","Because it brings people together and reflects values","Because it is the only way to get energy","Because it is only eaten on weekends"],"answer_index":1,"explanation_pt_br":"O texto afirma que a comida reflete história e valores, unindo as pessoas."},{"prompt":"What is the purpose of the ritual of drinking chimarrão in the South?","options":["It is a way to stay awake","It is a social act that encourages bonding","It is a way to sell more products","It is done only in professional settings"],"answer_index":1,"explanation_pt_br":"O texto descreve o chimarrão como um ato social que promove a conversa e a união."},{"prompt":"What is the role of the community market?","options":["To sell only industrial products","To support local economies and small producers","To provide a place for tourists to sleep","To increase the price of food"],"answer_index":1,"explanation_pt_br":"Os mercados são descritos como a espinha dorsal da economia local, apoiando pequenos produtores."},{"prompt":"Why are people returning to traditional recipes?","options":["Because they have nothing else to eat","Because they want to feel grounded","Because modern food is too healthy","Because cooking is a mandatory chore"],"answer_index":1,"explanation_pt_br":"O texto menciona que cozinhar pratos tradicionais é uma forma de se sentir conectado às raízes."},{"prompt":"What is the main argument regarding culinary traditions?","options":["They should be replaced by modern food","They are a powerful way to foster community and belonging","They are too difficult to learn","They are only important for older generations"],"answer_index":1,"explanation_pt_br":"O texto argumenta que as tradições culinárias são fundamentais para fortalecer os laços comunitários."}]'::jsonb, 5),
('en-passage-b1-06', 'en', 'B1', 'The Digital Transformation of Home Life', 'In the past decade, technology has moved from our offices directly into the heart of our homes. For many Brazilians, the morning routine now begins not with a radio or a newspaper, but with a quick check of notifications on a smartphone. Smart devices have turned ordinary houses into interconnected hubs where appliances communicate with each other to simplify daily chores.

One of the most significant changes is the rise of smart home assistants. These voice-activated devices allow users to control lighting, temperature, and even kitchen appliances without lifting a finger. While some people worry about privacy, others argue that the convenience is worth the trade-off. It is becoming increasingly common to see families organizing their schedules through shared digital calendars.

Remote work has also played a massive role in this shift. With high-speed internet becoming more accessible, many professionals have traded their long commutes for home offices. This transition requires a stable connection and a quiet space, forcing people to rethink how they arrange their furniture. Living rooms are frequently transformed into professional meeting spots during business hours.

However, this constant connectivity is not without its challenges. The lines between personal time and work responsibilities have become blurred, leading to a phenomenon often called digital fatigue. Many experts suggest that it is essential to establish clear boundaries, such as turning off notifications after dinner or dedicating specific rooms to relaxation rather than work.

Ultimately, technology is a tool that serves us best when we use it with intention. Whether it is tracking fitness goals or streaming educational content, the benefits are clear for those who manage their time well. As we look toward the future, it is likely that even more innovative solutions will emerge to help us balance our busy lives.', '[{"prompt":"What is the main idea of the text?","options":["Technology has become a central part of home life, offering both benefits and challenges.","Smart home assistants are the only reason people are working from home now.","Technology has made life much harder for the average person today.","Brazilians are moving away from traditional technology in favor of radio."],"answer_index":0,"explanation_pt_br":"O texto aborda como a tecnologia transformou o lar, mencionando tanto a conveniência quanto os desafios."},{"prompt":"What does the author imply by ''digital fatigue''?","options":["A physical condition caused by using low-quality electronics.","The exhaustion caused by being constantly connected to work and technology.","The feeling of being bored when the internet connection is slow.","A lack of motivation to learn how to use new smart home devices."],"answer_index":1,"explanation_pt_br":"O termo refere-se ao cansaço mental causado pela conexão constante e pela falta de limites entre vida pessoal e trabalho."},{"prompt":"According to the text, what is a common change in home arrangement?","options":["Removing furniture to make space for more smart appliances.","Turning living rooms into professional workspaces for remote work.","Adding more televisions to every room for constant entertainment.","Moving home offices to the garage to save space."],"answer_index":1,"explanation_pt_br":"O texto menciona que salas de estar estão sendo transformadas em espaços de trabalho durante o horário comercial."},{"prompt":"What is the author''s opinion on using smart assistants?","options":["They are completely unnecessary and a waste of money.","They are dangerous and should be avoided at all costs.","They offer convenience, but some people are concerned about privacy.","They are the only way to manage a successful household."],"answer_index":2,"explanation_pt_br":"O autor reconhece a conveniência, mas menciona que algumas pessoas se preocupam com a privacidade."},{"prompt":"What should people do to avoid digital fatigue?","options":["Buy more expensive and modern smart devices.","Work from a different room every single day.","Stop using all technology after the morning check.","Set boundaries like turning off notifications after dinner."],"answer_index":3,"explanation_pt_br":"O texto sugere estabelecer limites, como desligar notificações após o jantar, para evitar a fadiga digital."}]'::jsonb, 6),
('en-passage-b1-07', 'en', 'B1', 'Sustainable Choices for a Better Future', 'Environmental awareness is growing rapidly across Brazil as citizens become more concerned about the impact of their daily habits. From recycling plastics to reducing water waste, individual actions are beginning to add up to meaningful change. Small adjustments in our lifestyle can significantly reduce our carbon footprint, helping to preserve natural resources for the generations to come.

One of the most effective ways to contribute to sustainability is through mindful consumption. Instead of buying cheap, disposable products, many people are now choosing durable goods that last for years. This shift away from fast fashion and single-use items is not only good for the planet but also helps households save money over the long term.

Energy efficiency at home is another critical area where people can make a difference. Simple tasks such as switching to LED bulbs, unplugging unused electronic devices, and choosing energy-efficient appliances can lower electricity bills while reducing strain on the power grid. These habits are easy to adopt and require very little initial investment from the homeowner.

Furthermore, transportation choices play a major role in our environmental impact. While owning a car is convenient, it is often a significant source of pollution. Many urban residents are starting to prefer public transit, cycling, or walking for short distances. These alternatives not only decrease carbon emissions but also improve physical health through increased daily activity.

Ultimately, living sustainably is about making conscious decisions rather than achieving perfection. It is a process of learning, adapting, and encouraging others to participate in the movement. By working together, we can protect our ecosystems and ensure that our cities remain healthy places to live. Even the smallest step counts when it is taken by many.', '[{"prompt":"What is the main goal of the passage?","options":["To explain the history of environmental laws in Brazil.","To encourage readers to adopt small, sustainable habits in their daily lives.","To argue that individual actions are useless without government intervention.","To convince readers to stop using all forms of technology."],"answer_index":1,"explanation_pt_br":"O texto foca em incentivar o leitor a adotar hábitos sustentáveis simples em seu cotidiano."},{"prompt":"What does ''mindful consumption'' mean in the text?","options":["Buying as many products as possible during sales.","Avoiding all purchases to save money.","Choosing durable products instead of cheap, disposable ones.","Buying only organic food products."],"answer_index":2,"explanation_pt_br":"O consumo consciente é descrito como a preferência por bens duráveis em vez de itens descartáveis."},{"prompt":"According to the text, why should people use public transit or bikes?","options":["Because they are faster than driving a car in all situations.","Because they are free for everyone in the city.","To reduce emissions and improve personal health.","Because car ownership is prohibited in most cities."],"answer_index":2,"explanation_pt_br":"O texto afirma que essas alternativas reduzem emissões de carbono e melhoram a saúde física."},{"prompt":"What is one mentioned benefit of energy efficiency at home?","options":["It makes the house look more modern and attractive.","It lowers electricity bills for the homeowner.","It eliminates the need for any electronic devices.","It helps the government increase taxes."],"answer_index":1,"explanation_pt_br":"O texto menciona que a eficiência energética pode reduzir as contas de eletricidade."},{"prompt":"What is the author''s attitude toward sustainability?","options":["It is a difficult task that only experts can accomplish.","It requires perfection from every individual.","It is a continuous process of conscious decisions.","It is not worth the effort for the average person."],"answer_index":2,"explanation_pt_br":"O autor define a sustentabilidade como um processo de decisões conscientes e aprendizado contínuo."}]'::jsonb, 7),
('en-passage-b1-08', 'en', 'B1', 'The Evolution of Social Connections', 'In modern society, the way we build and maintain relationships has undergone a dramatic transformation. While face-to-face interactions remain the foundation of deep connections, digital platforms have become essential tools for keeping in touch with distant friends and family. This hybrid approach allows us to bridge geographical gaps while maintaining our local community ties.

Social media has undeniably changed how we meet new people. Interest-based groups and online forums provide spaces for individuals to connect over shared hobbies, from cooking to professional networking. These platforms can be a great way to overcome shyness and find communities that share our specific values and interests, which might be difficult in our immediate physical environment.

However, there is a growing concern about the quality of these interactions. Many people feel that digital communication often lacks the nuance and warmth of in-person meetings. A text message or a comment on a post cannot fully replicate the emotional impact of a long conversation held over a coffee or a shared meal with friends.

Maintaining a healthy social life requires a delicate balance. It is important to invest time in real-world experiences, such as participating in local clubs or gathering for birthdays and holidays. These moments create lasting memories that strengthen the bonds between people, providing a sense of belonging that digital screens simply cannot provide on their own.

In conclusion, our social world is richer than ever, offering us a variety of ways to connect with others. By using digital tools to facilitate meetings rather than replace them, we can enjoy the best of both worlds. The key is to remain present and prioritize the people who truly matter in our lives.', '[{"prompt":"What is the author''s opinion on digital communication?","options":["It has completely replaced the need for face-to-face contact.","It is a helpful tool, but it lacks the warmth of in-person interaction.","It is harmful and should be avoided by everyone.","It is the only way to make new friends in the modern world."],"answer_index":1,"explanation_pt_br":"O autor reconhece a utilidade da comunicação digital, mas nota que ela carece da profundidade do contato presencial."},{"prompt":"What does ''bridge geographical gaps'' mean?","options":["Building actual bridges between countries.","Connecting with people who live far away.","Closing down local community centers.","Moving to a different city to be closer to friends."],"answer_index":1,"explanation_pt_br":"A expressão significa conectar-se com pessoas que estão fisicamente distantes."},{"prompt":"According to the text, why are interest-based groups useful?","options":["They allow people to make money from their hobbies.","They help people find others with similar values and interests.","They force everyone to participate in local sports.","They are the only way to learn new professional skills."],"answer_index":1,"explanation_pt_br":"O texto destaca que esses grupos ajudam a encontrar pessoas com interesses e valores semelhantes."},{"prompt":"What does the author suggest for a healthy social life?","options":["Spending more time on social media to reach more people.","Focusing only on online relationships to avoid conflict.","Prioritizing in-person experiences and real-world gatherings.","Joining as many clubs as possible, even if you are tired."],"answer_index":2,"explanation_pt_br":"O autor recomenda investir tempo em experiências presenciais para fortalecer os laços."},{"prompt":"What is the main message about social media?","options":["It is a tool that should be used to support real connections.","It is the main cause of loneliness in modern society.","It is only useful for professional networking.","It makes it impossible to meet new people in real life."],"answer_index":0,"explanation_pt_br":"A mensagem central é que as redes sociais devem ser usadas para facilitar conexões, não para substituí-las."}]'::jsonb, 8),
('en-passage-b1-09', 'en', 'B1', 'Managing Personal Finances Wisely', 'Financial literacy is an essential skill for every adult, regardless of their income level. Many Brazilians are learning that managing money is not just about earning a salary, but about how effectively that money is tracked and allocated. Creating a budget is the first step toward financial stability, allowing individuals to distinguish between their needs and their wants.

Impulse buying is a significant challenge in the age of online shopping. With discounts and advertisements constantly appearing on our screens, it is easy to spend money on things we do not really need. Setting a cooling-off period before making non-essential purchases can help prevent regret and keep savings on track for more important goals.

Saving for the future is another pillar of personal finance. Experts recommend building an emergency fund to cover unexpected expenses, such as medical bills or home repairs. Having this safety net provides peace of mind and prevents people from falling into debt when faced with unforeseen circumstances that might arise at any moment.

Investment is also becoming more accessible to the general public. Many people are moving beyond traditional savings accounts and exploring different ways to make their money grow over time. While it is important to be cautious and do thorough research, small, consistent investments can lead to significant long-term benefits for a family’s financial future.

In the end, financial health is about consistency and discipline. It requires regular monitoring of expenses and a commitment to long-term goals. By taking control of their finances early, people can reduce stress, enjoy greater freedom, and build a more secure life for themselves and their families.', '[{"prompt":"What is the first step toward financial stability mentioned?","options":["Investing all your money in the stock market.","Earning a very high salary at your job.","Creating a budget to track income and expenses.","Buying only items that are on sale."],"answer_index":2,"explanation_pt_br":"O texto afirma que criar um orçamento é o primeiro passo para a estabilidade financeira."},{"prompt":"What is a ''cooling-off period'' in the context of shopping?","options":["A time to wait before buying something to avoid impulse spending.","A season where stores are closed for holidays.","The time it takes for a product to be delivered to your house.","A period when you are not allowed to use your credit card."],"answer_index":0,"explanation_pt_br":"É um período de espera recomendado para evitar compras por impulso."},{"prompt":"Why does the author recommend an emergency fund?","options":["To buy luxury items when they are on sale.","To pay for vacations without needing a loan.","To provide security against unexpected financial problems.","To impress friends and family with extra savings."],"answer_index":2,"explanation_pt_br":"O fundo de emergência serve para cobrir despesas inesperadas e oferecer tranquilidade."},{"prompt":"What is the author''s advice regarding investments?","options":["Avoid them because they are too dangerous.","Invest as much as possible, regardless of the risk.","Research thoroughly and start with small, consistent amounts.","Only trust traditional savings accounts at banks."],"answer_index":2,"explanation_pt_br":"O texto aconselha cautela, pesquisa e investimentos pequenos e consistentes."},{"prompt":"What is the overall tone of this passage?","options":["Critical and pessimistic.","Encouraging and practical.","Confusing and technical.","Angry and demanding."],"answer_index":1,"explanation_pt_br":"O tom é prático e encorajador, oferecendo dicas úteis para a gestão financeira."}]'::jsonb, 9),
('en-passage-b1-10', 'en', 'B1', 'Education and Lifelong Learning', 'In the rapidly changing world of the twenty-first century, formal education is only the beginning of our learning journey. The concept of lifelong learning has become increasingly important, as new technologies and industries emerge at a fast pace. Whether it is learning a new language, mastering software, or gaining a new trade, continuous education is key to staying relevant.

Many people are now taking advantage of online platforms to expand their knowledge. Massive Open Online Courses (MOOCs) provide affordable access to high-quality education from universities around the globe. This flexibility allows adults to balance their studies with work and family responsibilities, making it possible to learn at their own pace from the comfort of home.

Lifelong learning is not just about professional advancement; it is also about personal growth. Engaging with new ideas and challenging our perspectives keeps the mind sharp and curious. Many retirees, for example, are finding great joy in picking up hobbies they never had time for during their working years, such as painting, history, or music.

However, the most important trait for a lifelong learner is curiosity. It is the drive to ask questions, seek out new information, and remain open to different ways of thinking. When we stop believing that we know everything, we open the door to endless opportunities for improvement and discovery throughout our lives.

Ultimately, education is a lifelong commitment that enriches our existence. By dedicating time to learn something new every day, we empower ourselves to adapt to any challenge that comes our way. The investment we make in our own knowledge is the only one that will provide returns for the rest of our lives.', '[{"prompt":"What is the primary message about lifelong learning?","options":["It is only necessary for people who do not have a university degree.","It is a continuous process that is important for both work and personal growth.","It is too expensive for the average adult to pursue.","It should be completed as quickly as possible before starting a career."],"answer_index":1,"explanation_pt_br":"O texto destaca que o aprendizado contínuo é essencial para a carreira e para o crescimento pessoal."},{"prompt":"What is a major advantage of online courses mentioned in the text?","options":["They guarantee a high-paying job immediately after completion.","They replace the need for any formal schooling.","They offer flexibility for adults with work and family duties.","They are always completely free for every student."],"answer_index":2,"explanation_pt_br":"O texto menciona que a flexibilidade permite conciliar estudos com trabalho e família."},{"prompt":"How does the author describe the role of curiosity?","options":["As a distraction that keeps people from finishing their work.","As the most important trait for a lifelong learner.","As a trait that only young children possess.","As something that is not needed in the modern professional world."],"answer_index":1,"explanation_pt_br":"O autor chama a curiosidade de a característica mais importante para quem deseja aprender a vida toda."},{"prompt":"What is suggested as a benefit for retirees who continue learning?","options":["They can return to their old jobs at a higher salary.","They find joy and keep their minds active through new hobbies.","They become experts in new technologies very quickly.","They are forced to start a new business."],"answer_index":1,"explanation_pt_br":"O texto menciona que aposentados encontram alegria e mantêm a mente afiada com novos hobbies."},{"prompt":"What does the author mean by ''the only investment that will provide returns''?","options":["Spending money on stocks is better than on education.","Education is the most valuable investment one can make.","Only education will make you wealthy in the future.","You should only spend money on things that help your career."],"answer_index":1,"explanation_pt_br":"O autor enfatiza que investir em conhecimento é um investimento valioso e duradouro."}]'::jsonb, 10),
('en-passage-b2-01', 'en', 'B2', 'The Art of Autonomy in the Modern Age', 'In our fast-paced society, the concept of independence has evolved far beyond simply moving out of a family home or managing one''s own finances. For the modern Brazilian professional, true autonomy is increasingly defined by the ability to curate a daily routine that balances professional ambition with personal well-being. This shift requires a disciplined approach to time management, where the boundaries between productivity and rest are intentionally established to prevent burnout.

Consider the morning ritual of a typical urban dweller in São Paulo. Before the city awakens, a structured routine often involves intentional silence, physical activity, and careful planning. This is not merely about ticking off tasks from a list; it is about reclaiming agency over one''s cognitive resources. By front-loading the most mentally demanding work, individuals create a sense of accomplishment that permeates the rest of their day, reducing the anxiety often associated with unpredictability.

However, autonomy is not synonymous with isolation. Many professionals find that maintaining independence requires sophisticated communication skills. Negotiating boundaries with colleagues, saying no to non-essential commitments, and delegating tasks effectively are all manifestations of a mature, autonomous lifestyle. It is a delicate dance between self-reliance and the collaborative nature of our professional environments, requiring one to be assertive without appearing uncooperative.

Technology plays a paradoxical role in this pursuit. While digital tools provide the flexibility to work from anywhere, they also threaten to erode our autonomy by fostering constant connectivity. To maintain control, many are adopting ''digital minimalism,'' setting strict parameters for email and social media consumption. This intentional disconnection is a powerful form of modern independence, protecting the individual from the relentless demands of the attention economy.

Furthermore, domestic independence involves more than just keeping a clean space; it is about the mastery of one''s environment. Whether it involves learning to cook nutritious meals, managing household maintenance, or navigating public services, these practical skills contribute to a psychological state of self-sufficiency. When individuals feel capable of managing their physical surroundings, their confidence in handling professional and personal challenges inevitably increases.

Ultimately, achieving independence is a lifelong process of iteration and refinement. It is not about reaching a final state of perfection but about continuously aligning one''s actions with personal values. By taking responsibility for our daily habits, we transform from passive participants in our lives into architects of our own destiny. In doing so, we find that the most profound freedom is found in the discipline we impose upon ourselves.', '[{"prompt":"What does the author suggest is the primary goal of modern daily routines?","options":["To maximize the amount of work completed in a single day.","To achieve a balance between ambition and personal health.","To ensure that one never has to rely on others for support.","To completely eliminate the need for technology in the workplace."],"answer_index":1,"explanation_pt_br":"O texto enfatiza que a autonomia moderna é definida pelo equilíbrio entre ambição profissional e bem-estar pessoal."},{"prompt":"What does the author mean by ''front-loading the most mentally demanding work''?","options":["Organizing tasks by their urgency rather than their complexity.","Delegating difficult tasks to colleagues early in the morning.","Completing the hardest tasks before other distractions arise.","Working only on the most difficult projects during the weekend."],"answer_index":2,"explanation_pt_br":"A expressão refere-se a realizar as tarefas mais difíceis logo cedo, antes que outras demandas surjam."},{"prompt":"According to the passage, how is professional autonomy linked to social interaction?","options":["True autonomy requires rejecting all forms of collaborative work.","It involves setting boundaries and communicating effectively with others.","Social interaction is a threat to the development of personal agency.","Independence is only achieved when one works in total isolation."],"answer_index":1,"explanation_pt_br":"O autor explica que a autonomia exige habilidades sociais para negociar limites e delegar tarefas."},{"prompt":"What is the ''paradoxical role'' of technology mentioned in the text?","options":["It makes us more independent while simultaneously increasing our dependence on others.","It is necessary for work but often makes us less productive in the long run.","It offers flexibility while threatening our autonomy through constant connectivity.","It is expensive to maintain yet it is required for modern professional success."],"answer_index":2,"explanation_pt_br":"A tecnologia oferece flexibilidade, mas a conectividade constante mina a autonomia do indivíduo."},{"prompt":"What does ''digital minimalism'' represent in the context of the passage?","options":["A technical failure that prevents people from accessing social media.","A strategy to reclaim control by limiting digital consumption.","The inability of older generations to adapt to modern software.","A style of professional communication that is brief and efficient."],"answer_index":1,"explanation_pt_br":"O minimalismo digital é apresentado como uma estratégia para proteger a atenção contra demandas constantes."},{"prompt":"How does managing domestic tasks impact a person''s life?","options":["It creates more time for professional development and networking.","It allows individuals to rely less on expensive external services.","It increases confidence in managing challenges in other areas.","It is a necessary distraction from the stress of the workplace."],"answer_index":2,"explanation_pt_br":"O texto afirma que o domínio de tarefas domésticas aumenta a confiança para enfrentar desafios pessoais e profissionais."},{"prompt":"Which statement best summarizes the main idea of the passage?","options":["Independence is an inherent trait that some people are born with.","Modern autonomy is a continuous effort to align actions with values.","Living in a large city makes true independence nearly impossible.","Technology is the most significant barrier to personal freedom today."],"answer_index":1,"explanation_pt_br":"A ideia central é que a autonomia é um processo contínuo de alinhar ações aos valores pessoais."}]'::jsonb, 1),
('en-passage-b2-02', 'en', 'B2', 'The Transformative Power of Global Travel', 'Travel has long been celebrated as a gateway to cultural discovery, yet its true value lies in its ability to disrupt our ingrained perspectives. For many, the initial allure of a foreign destination is found in its aesthetic beauty or famous landmarks. However, the most profound experiences often occur when we step outside the well-trodden paths of tourism, engaging directly with the rhythms of daily life in places entirely different from our own.

When we immerse ourselves in a different culture, we are forced to confront the limitations of our own worldviews. What is considered ''normal'' behavior in one country might be perceived as rude or confusing in another. This realization is not merely a social observation; it is a fundamental shift in consciousness. By navigating these cultural nuances, travelers develop a higher degree of empathy, recognizing that there are multiple valid ways to organize a society and live a fulfilling life.

Language, of course, is the primary bridge to this deeper understanding. While English serves as a global lingua franca, attempting to learn even a few phrases of the local language can transform the quality of one''s interactions. It signals a respect for the host culture and often invites a level of hospitality that would otherwise remain inaccessible. This investment of effort is rarely wasted, as it turns a transaction into a human connection.

However, the modern traveler must be wary of the ''Instagram effect,'' where the desire to document a trip often supersedes the desire to experience it. This performative aspect of travel can lead to a superficial engagement with the destination, where the focus shifts from authentic discovery to the curation of an idealized persona. True cultural exploration requires a degree of presence that is incompatible with the constant need to capture and share every moment.

Furthermore, sustainable travel has become an ethical imperative. As tourism grows, the impact on local environments and communities becomes increasingly significant. Being a responsible traveler means making conscious choices—supporting local businesses, respecting local customs, and minimizing one''s carbon footprint. It is about leaving a place better than we found it, or at least, ensuring that our presence does not diminish the quality of life for those who live there permanently.

Ultimately, travel is an act of humility. It reminds us that we are guests in someone else''s home, regardless of how far we have traveled. When we approach our journeys with an open mind and a willingness to be challenged, we return not just with souvenirs, but with a broader understanding of the human condition. The greatest destination is not a point on a map, but the expanded horizon of our own minds.', '[{"prompt":"What does the author suggest is the primary value of travel?","options":["The opportunity to see famous landmarks and take photographs.","The ability to escape from one''s own daily routine and work.","The capacity to disrupt and expand one''s existing perspectives.","The chance to learn a new language fluently in a short time."],"answer_index":2,"explanation_pt_br":"O texto afirma que o verdadeiro valor da viagem é a capacidade de romper com perspectivas enraizadas."},{"prompt":"How does encountering different cultures affect a traveler''s worldview?","options":["It makes them realize that their own culture is superior to others.","It confuses them and makes them want to return home quickly.","It fosters empathy by showing that many ways of living are valid.","It forces them to abandon their own values to fit in abroad."],"answer_index":2,"explanation_pt_br":"O autor explica que o contato com outras culturas desenvolve empatia e mostra que existem várias formas válidas de viver."},{"prompt":"Why is learning local phrases recommended by the author?","options":["Because English is not spoken at all in most foreign countries.","Because it shows respect and often improves local interactions.","Because it is the only way to avoid being overcharged by locals.","Because it is a requirement for entering most historical sites."],"answer_index":1,"explanation_pt_br":"Aprender frases locais é um sinal de respeito que convida à hospitalidade e melhora a qualidade das interações."},{"prompt":"What does the author warn against regarding the ''Instagram effect''?","options":["It makes travel much more expensive than it used to be.","It prevents people from finding good locations for photos.","It turns travel into a superficial, performative experience.","It makes it harder to connect with friends back home."],"answer_index":2,"explanation_pt_br":"O efeito Instagram torna a viagem performática e superficial, priorizando a imagem sobre a experiência real."},{"prompt":"What does ''sustainable travel'' entail according to the text?","options":["Traveling only to places that are close to one''s home.","Making ethical choices that support local communities.","Spending as little money as possible while visiting a country.","Avoiding all forms of transportation that use fossil fuels."],"answer_index":1,"explanation_pt_br":"Viagem sustentável envolve escolhas éticas que apoiam empresas locais e respeitam o meio ambiente e a comunidade."},{"prompt":"What is the tone of the final paragraph?","options":["Cynical and pessimistic about the future of tourism.","Humble and reflective regarding the purpose of travel.","Aggressive and demanding toward future travelers.","Humorous and lighthearted about cultural mistakes."],"answer_index":1,"explanation_pt_br":"O parágrafo final reflete sobre a humildade e o crescimento pessoal, mantendo um tom reflexivo."},{"prompt":"Which of these best summarizes the author''s view on travel?","options":["Travel is a luxury that few people should actually participate in.","Travel is primarily about collecting experiences to share online.","Travel is a profound opportunity for personal and cultural growth.","Travel is a dangerous activity that requires strict preparation."],"answer_index":2,"explanation_pt_br":"A ideia central é que a viagem é uma oportunidade profunda de crescimento pessoal e cultural."}]'::jsonb, 2),
('en-passage-b2-03', 'en', 'B2', 'Navigating the Nuances of Professional Communication', 'In the contemporary globalized workplace, effective communication is often the deciding factor between project success and missed opportunities. It is no longer enough to be technically proficient in one''s field; one must also master the subtle art of professional discourse. This involves understanding the unspoken social contracts that govern meetings, emails, and collaborative projects, ensuring that messages are not only received but also interpreted as intended.

The shift toward remote and hybrid work environments has further complicated these dynamics. Without the benefit of physical presence and non-verbal cues, digital communication requires a higher degree of clarity and intentionality. A brief, poorly phrased message can easily be misinterpreted as dismissive or aggressive, leading to unnecessary friction within a team. Consequently, professionals must learn to compensate for the lack of face-to-face interaction by being more precise in their written language.

Moreover, professional communication is inextricably linked to cultural intelligence. In a multinational company, colleagues may have vastly different approaches to feedback, hierarchy, and decision-making. Some cultures prioritize direct, blunt communication, while others favor a more indirect, diplomatic approach. Successfully navigating these differences requires a willingness to adapt one''s style and a constant effort to build rapport before addressing difficult or sensitive topics.

Active listening remains the most underrated tool in the professional arsenal. Many people enter a conversation with their response already prepared, failing to fully absorb what the other party is saying. True listening is an active process that requires patience and the ability to ask clarifying questions. By demonstrating that we have truly heard and understood our colleagues, we build trust, which is the essential foundation for any successful long-term professional relationship.

Conflict resolution is another critical aspect of professional communication. It is inevitable that disagreements will arise; however, the mark of a skilled professional is the ability to de-escalate these situations and find a common ground. This involves focusing on the issue at hand rather than personalizing the disagreement, and using language that invites collaboration rather than defense. It is about transforming a potential confrontation into a problem-solving exercise.

Ultimately, professional communication is a lifelong craft that requires constant practice. As we move up the career ladder, the stakes increase, and the need for clear, persuasive, and empathetic communication becomes even more pronounced. By investing time in honing these skills, we not only improve our own work performance but also contribute to a culture of transparency and mutual respect, which benefits the organization as a whole.', '[{"prompt":"What does the author suggest is crucial for success in a globalized workplace?","options":["Having high technical skills in one''s specific field.","Being able to communicate effectively and understand social dynamics.","Working exclusively in a physical office to avoid misunderstandings.","Prioritizing one''s own ideas over the team''s collective goals."],"answer_index":1,"explanation_pt_br":"O texto destaca que, além da proficiência técnica, dominar o discurso profissional e as dinâmicas sociais é fundamental."},{"prompt":"Why is remote communication more challenging than face-to-face interaction?","options":["Because digital tools are often too expensive for small teams.","Because it lacks non-verbal cues, making messages easier to misinterpret.","Because people feel less obligated to be polite when working from home.","Because it is impossible to give feedback through email or video calls."],"answer_index":1,"explanation_pt_br":"A falta de pistas não verbais na comunicação digital exige maior clareza para evitar mal-entendidos."},{"prompt":"What is ''cultural intelligence'' in the professional context?","options":["The ability to speak multiple languages fluently.","A strategy to force everyone to follow the same communication style.","Understanding and adapting to different cultural approaches to work.","The skill of avoiding colleagues who come from different countries."],"answer_index":2,"explanation_pt_br":"Inteligência cultural refere-se à habilidade de adaptar o estilo de comunicação ao lidar com diferentes normas culturais."},{"prompt":"Why does the author consider active listening to be ''underrated''?","options":["Because most people prefer to talk rather than listen.","Because it is not taught in universities or training programs.","Because it is too difficult for most people to learn effectively.","Because it is often overshadowed by the focus on speaking skills."],"answer_index":0,"explanation_pt_br":"O texto sugere que muitas pessoas falham em ouvir porque já preparam sua resposta enquanto o outro fala."},{"prompt":"What is the best way to handle professional disagreements according to the text?","options":["Avoid discussing the issue until it goes away naturally.","Focus on the problem and use language that invites collaboration.","Defend one''s position until the other person agrees with it.","Ask a manager to intervene as soon as a disagreement begins."],"answer_index":1,"explanation_pt_br":"A resolução de conflitos deve focar no problema e usar linguagem colaborativa para evitar a defensiva."},{"prompt":"What does the author mean by ''the stakes increase'' as one moves up the ladder?","options":["The work becomes physically more demanding.","The consequences of communication errors become more significant.","The amount of time required to communicate with others decreases.","The number of colleagues one has to supervise becomes smaller."],"answer_index":1,"explanation_pt_br":"À medida que se sobe na carreira, o impacto de falhas na comunicação torna-se maior."},{"prompt":"What is the main objective of the passage?","options":["To explain why remote work is superior to office-based work.","To promote the use of specific digital communication platforms.","To emphasize the importance of communication skills for career success.","To describe the history of professional communication techniques."],"answer_index":2,"explanation_pt_br":"O objetivo principal é destacar como habilidades de comunicação são essenciais para o sucesso profissional."}]'::jsonb, 3),
('en-passage-b2-04', 'en', 'B2', 'The Pillars of Health and Well-being', 'In our modern, high-pressure world, the pursuit of health has often been reduced to a series of aesthetic goals or quick fixes. However, true well-being is a complex tapestry woven from physical, mental, and social threads. It is not merely the absence of disease, but a dynamic state of vitality that allows us to engage fully with our lives. Achieving this state requires a holistic approach that prioritizes long-term sustainability over temporary improvements.

Physical health forms the foundation of this structure, yet it is frequently neglected in favor of professional or social demands. Regular movement, balanced nutrition, and restorative sleep are the three pillars that support every other aspect of our existence. These are not luxuries to be enjoyed when time permits; they are biological necessities. When we consistently fail to prioritize these basics, our cognitive function, emotional stability, and immune systems all suffer the consequences.

Mental well-being, on the other hand, is increasingly recognized as being just as critical as physical health. The prevalence of chronic stress in urban life has made the cultivation of resilience an essential skill. Practices such as mindfulness, cognitive reframing, and setting boundaries are not just trends; they are vital tools for managing the internal noise that often accompanies a busy life. By learning to observe our thoughts without judgment, we can prevent stress from evolving into burnout.

Social connection acts as a powerful buffer against the negative effects of stress. Humans are inherently social creatures, and the quality of our relationships has a direct impact on our longevity and happiness. In an era where digital interactions often replace face-to-face encounters, it is important to invest time in cultivating meaningful bonds. These connections provide the emotional support necessary to navigate life''s inevitable challenges, acting as a safety net during difficult periods.

Furthermore, the environment in which we live plays a significant role in our well-being. Access to green spaces, clean air, and a safe community influences our health in ways we often overlook. While we cannot always control our external circumstances, we can make conscious choices about our surroundings, such as creating a calming home environment or finding ways to connect with nature regularly. Small, intentional changes to our habitat can have a profound impact on our daily stress levels.

Ultimately, well-being is a personal responsibility that requires ongoing attention and adjustment. It is about listening to the signals our bodies and minds send us and responding with compassion rather than discipline. By treating health as a continuous practice rather than a project with a start and end date, we create the conditions for a life that is not just long, but vibrant and fulfilling. True health is the freedom to pursue our passions with energy and focus.', '[{"prompt":"How does the author define true well-being?","options":["As a state of perfection achieved through rigorous exercise.","As the absence of any medical conditions or chronic diseases.","As a dynamic state of vitality involving mind, body, and society.","As the ability to work long hours without feeling any stress."],"answer_index":2,"explanation_pt_br":"O autor define bem-estar como um estado dinâmico de vitalidade que envolve aspectos físicos, mentais e sociais."},{"prompt":"Why does the author call movement, nutrition, and sleep ''biological necessities''?","options":["Because they are the only things that people value in modern life.","Because they are required to maintain basic physical and cognitive function.","Because they are expensive and require a professional to manage.","Because they are the only ways to prevent all diseases."],"answer_index":1,"explanation_pt_br":"O texto descreve esses elementos como necessidades biológicas essenciais para o funcionamento cognitivo e imunológico."},{"prompt":"What role do mindfulness and cognitive reframing play in mental health?","options":["They are trendy activities that help people look more professional.","They help manage internal stress and prevent burnout.","They are replacements for professional medical therapy.","They allow people to ignore the problems in their daily lives."],"answer_index":1,"explanation_pt_br":"Práticas como mindfulness são apresentadas como ferramentas para gerenciar o estresse e evitar o esgotamento."},{"prompt":"According to the text, why are social connections important?","options":["They help us climb the professional ladder faster.","They provide emotional support and increase longevity.","They are the only way to avoid using digital technology.","They ensure that we are never alone in our homes."],"answer_index":1,"explanation_pt_br":"O texto afirma que conexões sociais têm impacto direto na longevidade e na felicidade."},{"prompt":"What does the author suggest about our environment?","options":["We have no control over our surroundings and should accept them.","We should move to the countryside to improve our health.","We can make small choices to improve our living environment.","Our environment is the most important factor in our health."],"answer_index":2,"explanation_pt_br":"O autor sugere que podemos fazer escolhas conscientes para criar um ambiente doméstico mais calmo."},{"prompt":"What is the author''s advice on how to approach well-being?","options":["Treat it as a project with a clear beginning and end.","Use discipline to force the body to follow a strict routine.","View it as a continuous practice based on self-compassion.","Focus only on the physical aspects to get quick results."],"answer_index":2,"explanation_pt_br":"O texto aconselha tratar o bem-estar como uma prática contínua baseada em compaixão, não como um projeto temporário."},{"prompt":"What is the primary message of the passage?","options":["Health is a complex, holistic endeavor that requires lifelong commitment.","Modern urban life makes it impossible to be healthy.","Physical exercise is the only way to achieve mental stability.","Well-being is primarily about having enough free time for hobbies."],"answer_index":0,"explanation_pt_br":"A mensagem principal é que a saúde é um esforço holístico que exige compromisso contínuo."}]'::jsonb, 4),
('en-passage-b2-05', 'en', 'B2', 'Food as a Fabric of Community', 'Food is far more than mere sustenance; it is a profound expression of identity, history, and community. In Brazil, as in many other cultures, the kitchen acts as the heart of the household, a place where traditions are passed down through generations and social bonds are forged. Every recipe carries a narrative, a whisper of the past that connects the individual to a larger collective experience. To share a meal is to participate in a ritual that reinforces our belonging to a group.

The evolution of food traditions reflects the broader changes in our society. While we cherish the recipes of our ancestors, we are also constantly integrating new influences, reflecting the diverse and multicultural nature of our world. This fusion does not dilute our heritage; rather, it enriches it, creating a culinary landscape that is vibrant and ever-changing. The ability to adapt traditional dishes while honoring their origins is a testament to the resilience of our cultural identity.

However, the modern relationship with food is fraught with challenges. The industrialization of the food supply chain has disconnected many of us from the source of our meals. We often consume processed goods without understanding their origins or the impact of their production on the environment. Reclaiming our food heritage involves a return to conscious consumption—choosing local ingredients, supporting small-scale producers, and understanding the labor that goes into every dish we prepare.

Community building is perhaps the most significant benefit of these culinary traditions. Whether it is a large family gathering or a simple neighborhood potluck, the act of preparing and eating together breaks down barriers and encourages dialogue. In these shared spaces, the pressure of professional life fades, and we are reminded of our common humanity. It is in these moments of culinary communion that we find the support and encouragement needed to face the stresses of the outside world.

Furthermore, food festivals and local markets serve as essential hubs of cultural exchange. They allow communities to celebrate their unique flavors and techniques, preserving knowledge that might otherwise be lost to time. For the younger generation, these events are vital opportunities to learn about their roots and develop a sense of pride in their heritage. By keeping these traditions alive, we ensure that our cultural identity remains a living, breathing entity rather than a static relic.

Ultimately, food is an act of care. When we cook for ourselves or others, we are engaging in a practice that nourishes both the body and the soul. By prioritizing quality over convenience and connection over consumption, we transform the daily necessity of eating into a meaningful ritual. In a world that often feels fragmented, the simple act of gathering around a table remains one of the most powerful ways to build community and sustain the human spirit.', '[{"prompt":"What does the author mean by saying food is an ''expression of identity''?","options":["It tells others exactly what our political beliefs are.","It shows our economic status to everyone we know.","It reflects our history, traditions, and connection to a group.","It is the only way to prove where we were born."],"answer_index":2,"explanation_pt_br":"O texto afirma que a comida expressa identidade, história e a conexão com uma experiência coletiva."},{"prompt":"How does the author view the integration of new influences into food traditions?","options":["As a negative process that destroys original cultural heritage.","As a sign that a culture is losing its unique identity.","As an enriching process that makes the culinary landscape vibrant.","As a temporary trend that will eventually disappear."],"answer_index":2,"explanation_pt_br":"O autor vê a fusão de influências como algo que enriquece a herança cultural em vez de diluí-la."},{"prompt":"What challenge does the author highlight regarding modern food supply?","options":["It is becoming too expensive for the average person to afford.","It has disconnected people from the sources of their food.","It has made it impossible to find traditional ingredients.","It requires too much time for people to prepare meals at home."],"answer_index":1,"explanation_pt_br":"A industrialização desconectou as pessoas da origem dos alimentos e do impacto de sua produção."},{"prompt":"What is the primary benefit of shared meals mentioned in the text?","options":["They are the cheapest way to feed a large group of people.","They allow people to discuss business in a relaxed environment.","They help break down barriers and build community ties.","They are necessary to maintain one''s physical health."],"answer_index":2,"explanation_pt_br":"O texto destaca que a partilha de refeições derruba barreiras e fortalece laços comunitários."},{"prompt":"What role do food markets play according to the passage?","options":["They are the only places where healthy food can be purchased.","They serve as hubs for cultural exchange and knowledge preservation.","They are mainly designed to attract tourists to a city.","They allow the younger generation to earn money from cooking."],"answer_index":1,"explanation_pt_br":"Mercados servem como centros de intercâmbio cultural e preservação de conhecimentos culinários."},{"prompt":"What does ''culinary communion'' refer to?","options":["A religious ceremony involving bread and wine.","The process of cooking food in a professional kitchen.","The meaningful connection formed through shared eating.","The competition between different chefs in a festival."],"answer_index":2,"explanation_pt_br":"Refere-se aos momentos em que o ato de comer juntos gera conexão e comunhão entre as pessoas."},{"prompt":"What is the central theme of this passage?","options":["The evolution of Brazilian cuisine over the last century.","The importance of food in maintaining culture and community.","The negative effects of the industrial food industry on health.","The best ways to organize a neighborhood food festival."],"answer_index":1,"explanation_pt_br":"O tema central é como a comida é fundamental para a preservação da cultura e a criação de comunidades."}]'::jsonb, 5),
('en-passage-b2-06', 'en', 'B2', 'The Invisible Web of Modern Living', 'In the contemporary era, technology has transcended the role of a mere tool, embedding itself into the very fabric of our daily existence. For most urban dwellers, the day begins not with the rising sun, but with the subtle chime of a smartphone alarm. This digital ritual acts as a gateway, instantly connecting individuals to a global stream of information, social updates, and professional demands. As we navigate our routines, we are constantly interacting with algorithms that predict our preferences, shaping our consumption habits in ways we rarely stop to analyze.

The integration of smart home devices has further blurred the lines between private life and digital connectivity. From thermostats that learn our temperature preferences to refrigerators that track inventory, the domestic sphere is becoming an automated ecosystem. While these advancements promise unparalleled convenience and efficiency, they also raise significant questions regarding privacy. Every interaction, query, and preference is logged, contributing to a vast repository of data that companies utilize to refine their services and, more importantly, to influence our purchasing behaviors.

Transportation has undergone a radical transformation as well. Ridesharing applications have rendered traditional taxi services obsolete in many metropolitan areas, providing a seamless user experience that emphasizes speed and accessibility. These platforms rely on complex data sets to optimize routes and manage driver supply, effectively turning the city into a dynamic, interconnected grid. However, this reliance on software can occasionally lead to unexpected complications, such as surges in pricing during peak hours or system outages that leave commuters stranded without a digital alternative.

Communication, once dependent on physical proximity or scheduled calls, is now instantaneous and multifaceted. Instant messaging platforms and video conferencing tools have dismantled geographical barriers, allowing for global collaboration and the maintenance of long-distance relationships. Yet, this constant availability often creates a paradoxical sense of isolation. When we are always connected, the distinction between meaningful engagement and superficial interaction becomes thin, often leaving us feeling exhausted by the digital noise that permeates our waking hours.

The impact on cognitive processes is another critical aspect of this technological shift. The accessibility of information means that we no longer need to rely on memory for facts; instead, we rely on our ability to retrieve data efficiently. This externalization of memory has changed how we learn and process information, favoring rapid synthesis over deep, reflective study. While this allows for multitasking on an unprecedented scale, it also challenges our capacity for sustained attention, making it increasingly difficult to engage in tasks that require prolonged focus.

Ultimately, the challenge for the modern individual lies in striking a balance between embracing innovation and maintaining personal agency. We are not merely passive consumers of these technologies; we are participants in an ongoing social experiment. By consciously managing our digital footprints and setting boundaries for our screen time, we can harness the benefits of connectivity without sacrificing the depth of our lived experience. Technology, when used with intention, remains a powerful servant, but it must never be allowed to dictate the terms of our human existence.', '[{"prompt":"What does the author suggest about the role of smartphones in daily life?","options":["They are the primary cause of social isolation.","They have become an essential starting point for modern routines.","They are mainly used for professional tasks during the morning.","They are becoming less relevant due to smart home automation."],"answer_index":1,"explanation_pt_br":"O texto descreve o smartphone como o ''gateway'' que inicia a rotina diária da maioria das pessoas."},{"prompt":"According to the text, what is a potential drawback of smart home devices?","options":["They are too expensive for the average consumer.","They frequently break down due to complexity.","They collect data that influences consumer behavior.","They require constant manual updates by the user."],"answer_index":2,"explanation_pt_br":"O texto menciona que os dispositivos registram dados que são usados para influenciar comportamentos de compra."},{"prompt":"How does the author describe the effect of ridesharing apps on cities?","options":["They have made traditional taxis more efficient.","They have created an interconnected, dynamic grid.","They have solved all issues related to traffic congestion.","They have made physical infrastructure irrelevant."],"answer_index":1,"explanation_pt_br":"O autor afirma que essas plataformas transformam a cidade em uma grade dinâmica e interconectada."},{"prompt":"What does the phrase ''dismantled geographical barriers'' imply?","options":["People no longer need to travel to work.","Physical distance is no longer an obstacle to interaction.","International borders have become less important.","Traditional communication methods are illegal."],"answer_index":1,"explanation_pt_br":"Significa que a distância física não impede mais a comunicação ou a colaboração devido à tecnologia."},{"prompt":"What is the author''s view on the effect of technology on human memory?","options":["It has improved our ability to memorize complex facts.","It has caused a decline in our overall intelligence.","It has shifted our focus from retention to retrieval.","It has made us rely more on physical books."],"answer_index":2,"explanation_pt_br":"O texto explica que a tecnologia mudou a memória para a capacidade de recuperar dados em vez de retê-los."},{"prompt":"Which of the following best describes the author''s attitude toward technology?","options":["Completely optimistic about future advancements.","Deeply cynical and calls for a rejection of digital tools.","Cautious but acknowledges the benefits of intentional use.","Indifferent, viewing technology as an inevitable force."],"answer_index":2,"explanation_pt_br":"O autor defende o equilíbrio e o uso intencional, sem rejeitar a tecnologia completamente."},{"prompt":"What is the main idea of the passage?","options":["Technology has revolutionized transportation systems globally.","We must learn to manage our relationship with technology to maintain personal agency.","Smart homes are the most significant technological development of our time.","Constant connectivity is the primary cause of modern mental health issues."],"answer_index":1,"explanation_pt_br":"O texto foca na necessidade de equilíbrio e agência pessoal frente à onipresença da tecnologia."}]'::jsonb, 6),
('en-passage-b2-07', 'en', 'B2', 'The Path to a Sustainable Future', 'In recent years, the urgency of environmental conservation has shifted from a niche concern to a central pillar of global discourse. As the consequences of climate change become increasingly visible in the form of extreme weather events and ecological degradation, individuals are being called upon to reevaluate their daily choices. Sustainability is no longer just about grand policy changes at the governmental level; it is fundamentally about the cumulative impact of millions of personal decisions made in households across the globe every single day.

The concept of sustainable consumption revolves around the principle of reducing one''s ecological footprint. This involves a conscious move away from the ''throwaway culture'' that has dominated the last few decades. By prioritizing quality over quantity and choosing products that are durable or ethically sourced, consumers can exert significant pressure on industries to adopt greener practices. It is a transition from passive purchasing to active stewardship, where the lifespan and origin of an item are considered just as important as its price tag.

Energy efficiency within the home serves as another vital frontier in the fight against environmental decline. Simple adjustments, such as transitioning to LED lighting, improving insulation, or opting for renewable energy providers, can lead to substantial reductions in carbon emissions. While these actions might seem minor in isolation, their collective adoption represents a powerful force for change. It requires a shift in mindset, viewing the home not just as a place of comfort, but as an active participant in environmental preservation.

Dietary choices also play a profound role in shaping our environmental legacy. The agricultural industry is one of the largest contributors to greenhouse gas emissions, particularly concerning livestock production and water usage. By shifting toward plant-based diets or opting for locally sourced, seasonal produce, individuals can significantly decrease their personal carbon impact. This is not necessarily about radical abstinence, but rather about making informed choices that reflect a deeper awareness of the resources required to put food on our tables.

Waste management remains a complex challenge that requires both personal discipline and systemic change. While recycling is a well-known practice, the focus is increasingly shifting toward the concept of a circular economy, which emphasizes reducing waste at the source and reusing materials whenever possible. Composting organic waste and minimizing single-use plastics are essential steps in this direction. These habits, when ingrained into daily life, help close the loop on consumption and mitigate the overflow of landfills that plague modern urban environments.

Achieving a sustainable future is not a destination, but an ongoing process of adaptation and commitment. It demands that we look beyond short-term convenience and consider the long-term health of the planet. As we navigate this transition, we must recognize that our individual choices are interconnected. By sharing knowledge and fostering a culture of responsibility, we can create the systemic shift necessary to protect the environment for future generations. Sustainability is, at its heart, an act of respect for the world that sustains us.', '[{"prompt":"What is the primary focus of the first paragraph?","options":["The failure of government policies regarding the climate.","The increasing importance of personal responsibility in sustainability.","The scientific evidence behind recent climate change.","The economic benefits of living in an eco-friendly way."],"answer_index":1,"explanation_pt_br":"O texto enfatiza que a sustentabilidade depende das decisões individuais diárias."},{"prompt":"What does ''throwaway culture'' imply in the second paragraph?","options":["A society that prioritizes recycling above all else.","A habit of buying cheap goods and replacing them quickly.","The act of donating unwanted items to charity.","A focus on minimalism and reducing personal possessions."],"answer_index":1,"explanation_pt_br":"O termo refere-se a uma cultura de consumo descartável, onde produtos baratos são trocados frequentemente."},{"prompt":"According to the text, how can consumers influence industries?","options":["By lobbying for stricter government regulations.","By choosing durable and ethically sourced products.","By refusing to pay taxes on environmentally harmful goods.","By starting their own competing green businesses."],"answer_index":1,"explanation_pt_br":"Ao escolher produtos duráveis e éticos, os consumidores pressionam as empresas a adotarem práticas melhores."},{"prompt":"Which of the following is presented as a way to reduce one''s carbon footprint regarding diet?","options":["Increasing the consumption of processed foods.","Prioritizing imported exotic fruits and vegetables.","Choosing locally sourced and seasonal produce.","Eliminating all water usage in the kitchen."],"answer_index":2,"explanation_pt_br":"O texto sugere que optar por alimentos locais e da estação ajuda a diminuir o impacto ambiental."},{"prompt":"What is the main goal of a ''circular economy''?","options":["To increase the speed of manufacturing processes.","To reduce waste at the source and reuse materials.","To maximize the amount of plastic used in packaging.","To simplify the process of recycling for households."],"answer_index":1,"explanation_pt_br":"A economia circular foca em reduzir o desperdício na fonte e reutilizar materiais."},{"prompt":"What does the author mean by calling sustainability an ''ongoing process''?","options":["It is a task that will eventually be completed.","It requires constant adaptation and commitment.","It is a trend that will soon pass and be replaced.","It is a legal requirement that everyone must follow."],"answer_index":1,"explanation_pt_br":"O autor descreve a sustentabilidade como um processo contínuo de adaptação e compromisso, não um destino final."},{"prompt":"What is the overall tone of the passage?","options":["Alarmist and hopeless.","Informative and encouraging.","Academic and disconnected from reality.","Critical and accusatory."],"answer_index":1,"explanation_pt_br":"O tom é informativo e encorajador, propondo ações práticas para um futuro sustentável."}]'::jsonb, 7),
('en-passage-b2-08', 'en', 'B2', 'The Evolution of Modern Relationships', 'Human relationships have always been the bedrock of social life, yet the ways in which we form and maintain these connections are undergoing a significant metamorphosis. In the past, social circles were largely determined by geography, family, and workplace proximity. Today, the digital landscape has expanded our reach exponentially, allowing us to connect with individuals from vastly different backgrounds and regions. While this expansion offers a wealth of new opportunities for companionship, it also introduces complexities in how we define and nurture our interpersonal bonds.

The rise of online dating and social media has fundamentally altered the initial stages of relationship building. The traditional ''meet-cute'' has been replaced by swipes, likes, and direct messages, turning the process of finding a partner into a curated experience. While these tools provide access to a broader pool of potential matches, they also foster a culture of choice paralysis. When there are endless options available at one''s fingertips, the effort required to invest in a single connection can feel daunting, leading to more transient and superficial interactions.

Friendship, too, has been impacted by the blurring of public and private lives. Social media platforms often create a performative version of reality where we curate our experiences for an audience rather than sharing them genuinely with friends. This constant display can lead to social comparison and feelings of inadequacy, as individuals measure their own lives against the polished highlights of others. Consequently, the depth of our friendships is sometimes sacrificed for the sake of maintaining a particular social image, challenging us to reclaim authenticity in our interactions.

Despite these digital shifts, the fundamental human need for meaningful connection remains unchanged. Research consistently shows that the quality of our relationships is a primary predictor of mental well-being and longevity. Whether it is through long-standing friendships or new professional networks, having a support system is essential. The challenge lies in ensuring that our digital interactions complement, rather than replace, the physical presence and emotional vulnerability required to build true intimacy.

Intergenerational relationships are also evolving as social structures become more fluid. With families often living far apart due to career demands, the reliance on chosen families—communities built on shared values and interests—is becoming more prevalent. These networks provide a sense of belonging that was once exclusively provided by kinship. This shift reflects a broader trend toward autonomy in our social lives, where we have the agency to seek out environments that truly support our individual growth and well-being.

Ultimately, navigating relationships in the modern world requires a conscious approach to communication and boundaries. We must be intentional about how we use technology to bridge distances while protecting the sacredness of face-to-face encounters. By prioritizing empathy and active listening over digital efficiency, we can foster stronger bonds that withstand the test of time. In a world that is increasingly connected, the most radical and rewarding act is to cultivate relationships that are deep, authentic, and genuinely supportive.', '[{"prompt":"How have social circles changed according to the text?","options":["They are now limited to local neighborhoods.","They have expanded beyond geographical constraints.","They are strictly defined by family lineage.","They have become smaller and more exclusive."],"answer_index":1,"explanation_pt_br":"O texto afirma que o cenário digital expandiu nosso alcance, permitindo conexões além da geografia."},{"prompt":"What is one negative consequence of online dating mentioned in the text?","options":["It is too expensive for the average person.","It leads to a feeling of choice paralysis.","It prevents people from meeting in person.","It forces people to be too honest with strangers."],"answer_index":1,"explanation_pt_br":"O texto menciona que o excesso de opções pode levar à paralisia de escolha e interações superficiais."},{"prompt":"What does the author suggest about social media''s impact on friendship?","options":["It makes friendships stronger by allowing constant contact.","It encourages people to be more authentic.","It often leads to performative behavior and comparison.","It has eliminated the need for face-to-face meetings."],"answer_index":2,"explanation_pt_br":"O autor sugere que as redes sociais criam versões performativas da realidade, levando à comparação social."},{"prompt":"What is meant by the phrase ''chosen families''?","options":["Families that are legally adopted.","Groups of friends that provide support similar to kin.","People we are forced to interact with at work.","Communities that prioritize professional networking."],"answer_index":1,"explanation_pt_br":"Refere-se a redes de apoio baseadas em valores e interesses compartilhados, que substituem o suporte familiar tradicional."},{"prompt":"What does the author believe is essential for mental well-being?","options":["Having a large number of digital followers.","Maintaining a high level of physical and digital activity.","The quality of our personal relationships.","The ability to live independently from others."],"answer_index":2,"explanation_pt_br":"O texto indica que a qualidade dos relacionamentos é um preditor fundamental do bem-estar."},{"prompt":"What advice does the author give for modern relationships?","options":["Avoid using technology entirely.","Prioritize digital interactions over physical ones.","Be intentional and prioritize empathy.","Focus only on professional connections."],"answer_index":2,"explanation_pt_br":"O autor aconselha ser intencional e priorizar a empatia e a escuta ativa."},{"prompt":"What is the main theme of the passage?","options":["The decline of family values in modern society.","The transformation of human connections in the digital age.","The best apps for finding new friends.","The psychological effects of loneliness."],"answer_index":1,"explanation_pt_br":"O tema central é a evolução dos relacionamentos humanos no contexto da tecnologia moderna."}]'::jsonb, 8),
('en-passage-b2-09', 'en', 'B2', 'Mastering Personal Finance', 'Managing personal finance is a fundamental life skill that often feels daunting in an era of complex economic systems and easy access to credit. For many, money is a source of stress rather than a tool for empowerment. However, achieving financial stability is not solely about earning a high income; it is primarily about developing the discipline to manage resources effectively. By understanding the basics of budgeting, saving, and investing, individuals can move from a state of constant financial anxiety to one of long-term security.

The first step toward financial mastery is the creation of a realistic budget. A budget is not a restriction on one''s freedom, but rather a roadmap for spending that aligns with personal values and goals. By tracking income and expenses, individuals can identify ''leaks'' in their finances—small, unnecessary expenditures that aggregate over time to hinder progress. Once these leaks are plugged, the surplus can be redirected toward savings, debt repayment, or investments, effectively turning money into a tool for future growth.

Consumerism, fueled by aggressive advertising and the ease of digital shopping, poses a significant challenge to financial health. We live in a society that constantly encourages immediate gratification, often at the expense of long-term stability. To combat this, it is crucial to develop a discerning mindset regarding what constitutes a true ''need'' versus a ''want.'' Differentiating between these two categories allows for more intentional consumption, preventing the accumulation of debt that often stems from impulsive purchasing behaviors.

Understanding debt is another critical component of financial literacy. Not all debt is created equal; while high-interest consumer debt can be destructive, strategic debt—such as a mortgage or a student loan for career advancement—can sometimes serve as a catalyst for wealth building. The key is to manage debt responsibly, ensuring that interest rates and repayment schedules are understood and integrated into one''s financial plan. Avoiding the trap of high-interest credit cards is essential for maintaining a healthy balance sheet.

Investing is often misunderstood as being reserved for the wealthy, yet it is a powerful vehicle for building wealth for anyone. Through the power of compound interest, even small, consistent investments over a long period can yield significant returns. Education regarding different asset classes, such as stocks, bonds, or real estate, helps demystify the process. By starting early and maintaining a diversified portfolio, individuals can harness the market''s growth to protect their purchasing power against inflation and secure their financial future.

Financial independence is ultimately about having the freedom to make life choices without being constrained by economic necessity. It requires a shift from short-term thinking to a long-term perspective. By continuously educating oneself about financial matters and staying disciplined in the face of consumer pressure, anyone can improve their situation. Money should serve our goals, not dictate our limitations. With patience, planning, and a commitment to fiscal responsibility, we can build a foundation that supports our dreams and provides peace of mind.', '[{"prompt":"According to the author, what is the key to financial stability?","options":["Earning a very high income.","Having access to many credit cards.","Managing resources effectively.","Spending money as quickly as it is earned."],"answer_index":2,"explanation_pt_br":"O texto afirma que a estabilidade financeira vem da disciplina em gerenciar recursos, não apenas do salário."},{"prompt":"What does the author mean by ''leaks'' in finance?","options":["Illegal banking activities.","Unnecessary and aggregate expenses.","Unexpected emergency costs.","Taxes that are too high."],"answer_index":1,"explanation_pt_br":"Refere-se a gastos pequenos e desnecessários que, acumulados, prejudicam o progresso financeiro."},{"prompt":"What is the primary challenge to financial health mentioned in the third paragraph?","options":["The high cost of education.","Aggressive advertising and impulsive consumption.","A lack of investment opportunities.","The instability of global stock markets."],"answer_index":1,"explanation_pt_br":"O texto cita o consumismo, impulsionado por publicidade, como um grande desafio."},{"prompt":"What is the author''s view on debt?","options":["All debt is bad and should be avoided at all costs.","Debt is only useful for wealthy people.","Some debt can be strategic if managed responsibly.","Credit card debt is the best way to build wealth."],"answer_index":2,"explanation_pt_br":"O autor distingue dívidas destrutivas de dívidas estratégicas que podem ajudar no crescimento financeiro."},{"prompt":"What is the benefit of compound interest mentioned in the text?","options":["It allows people to borrow money interest-free.","It helps investments grow significantly over time.","It eliminates the need for a diversified portfolio.","It protects against tax increases."],"answer_index":1,"explanation_pt_br":"O texto explica que o juro composto faz com que pequenos investimentos cresçam ao longo do tempo."},{"prompt":"What is the main goal of financial independence?","options":["To become richer than everyone else.","To have the freedom to make choices without economic constraints.","To retire as early as possible without any savings.","To avoid paying any taxes to the government."],"answer_index":1,"explanation_pt_br":"A independência financeira é definida como a liberdade de fazer escolhas sem ser limitado por necessidades econômicas."},{"prompt":"What is the overall message of the passage?","options":["Personal finance is too complicated for most people to learn.","Financial success requires a shift in mindset and disciplined planning.","The economy is designed to make people poor.","Investing in stocks is the only way to be happy."],"answer_index":1,"explanation_pt_br":"A mensagem central é que o sucesso financeiro exige uma mudança de mentalidade e um planejamento disciplinado."}]'::jsonb, 9),
('en-passage-b2-10', 'en', 'B2', 'The Era of Lifelong Learning', 'In a world characterized by rapid technological advancement and shifting economic landscapes, the traditional model of education—concluding with a degree in one''s early twenties—is becoming increasingly obsolete. We have entered the era of lifelong learning, where the ability to acquire new skills and adapt to changing environments is the primary determinant of professional and personal success. Education is no longer a finite period of instruction, but a continuous journey that spans an entire lifetime, essential for remaining relevant in a dynamic society.

The primary driver of this shift is the accelerating pace of innovation. Industries that once remained stable for decades are now being disrupted by digital transformation and new business models. As a result, the knowledge and skills acquired in formal education often have a limited shelf life. This creates a necessity for continuous professional development, where individuals must proactively seek out training, certifications, and new perspectives to keep pace with the demands of their respective fields.

However, lifelong learning extends far beyond the professional realm. It is also deeply connected to personal fulfillment and cognitive health. Engaging in new hobbies, learning a foreign language, or exploring complex social issues stimulates the brain and fosters a sense of wonder. By maintaining a ''beginner''s mindset,'' individuals can continue to grow long after their formal schooling has ended. This pursuit of knowledge for its own sake keeps the mind sharp and opens doors to unexpected experiences and connections.

The digital age has democratized access to education in unprecedented ways. Massive Open Online Courses (MOOCs), podcasts, and digital libraries have dismantled the barriers that once limited learning to those with access to elite institutions. Today, a wealth of knowledge is available to anyone with an internet connection. This accessibility empowers individuals to curate their own educational paths, tailoring their learning to their specific interests and needs rather than following a standardized curriculum.

Despite these opportunities, the challenge of lifelong learning lies in discipline and time management. In a busy life filled with professional and social responsibilities, finding the time to learn can be difficult. It requires intentionality—carving out dedicated slots in our schedules for study and reflection. It also requires the humility to acknowledge what we do not know and the courage to start again, regardless of our age or existing expertise in other areas.

Ultimately, the commitment to lifelong learning is an investment in oneself. It is a declaration that we are capable of growth at any stage of life. As we navigate the uncertainties of the future, the most valuable asset we can possess is the ability to learn, unlearn, and relearn. By embracing this mindset, we ensure that we are not just keeping up with the world, but actively participating in its evolution. Learning is the bridge between who we are today and who we have the potential to become.', '[{"prompt":"Why is the traditional model of education considered obsolete?","options":["Because it is too expensive for most people.","Because knowledge now changes faster than formal schooling can keep up with.","Because degrees are no longer valued by employers.","Because it is no longer possible to get a job with a university degree."],"answer_index":1,"explanation_pt_br":"O texto afirma que o ritmo rápido de inovação torna o modelo tradicional de educação insuficiente."},{"prompt":"What does ''shelf life'' mean in the context of the second paragraph?","options":["The amount of time a book stays on a library shelf.","The duration for which knowledge remains useful or relevant.","The time a student spends studying in a classroom.","The physical space available for professional development."],"answer_index":1,"explanation_pt_br":"Refere-se ao período em que o conhecimento adquirido permanece útil."},{"prompt":"Besides professional success, what is another benefit of lifelong learning?","options":["It guarantees a higher salary in all industries.","It leads to increased cognitive health and personal fulfillment.","It allows individuals to work fewer hours per week.","It helps people avoid social interactions."],"answer_index":1,"explanation_pt_br":"O texto menciona que o aprendizado estimula o cérebro e traz satisfação pessoal."},{"prompt":"How has the digital age affected access to education?","options":["It has made education more expensive and elitist.","It has restricted learning to specific academic institutions.","It has democratized access through online resources.","It has made physical libraries completely useless."],"answer_index":2,"explanation_pt_br":"O texto diz que a era digital democratizou o acesso por meio de cursos online e bibliotecas digitais."},{"prompt":"What does the author identify as a main challenge to lifelong learning?","options":["A lack of interesting subjects to study.","The difficulty of managing time and maintaining discipline.","The belief that learning is only for the young.","The absence of reliable information on the internet."],"answer_index":1,"explanation_pt_br":"O autor aponta a disciplina e o gerenciamento de tempo como os maiores desafios."},{"prompt":"What does the phrase ''learn, unlearn, and relearn'' suggest?","options":["That we should only study things we already know.","That our knowledge must be constantly updated and corrected.","That learning is a repetitive and boring process.","That we should forget what we learned in school."],"answer_index":1,"explanation_pt_br":"Sugere a necessidade de atualizar conhecimentos e descartar o que não é mais válido."},{"prompt":"What is the main idea of the passage?","options":["University degrees are no longer important in the modern world.","Continuous learning is essential for navigating the future.","Online courses are better than traditional university education.","The primary goal of education is to find a high-paying job."],"answer_index":1,"explanation_pt_br":"A ideia central é que o aprendizado contínuo é fundamental para se adaptar ao futuro."}]'::jsonb, 10),
('es-passage-a1-01', 'es', 'A1', 'Mi rutina diaria', 'Hola, me llamo Carlos y vivo en São Paulo. Todos los días me despierto a las seis de la mañana. Primero, bebo un café fuerte y leo las noticias en mi teléfono móvil. Me gusta empezar el día con calma antes de salir de casa.

A las siete y media camino hasta la estación de metro. El viaje al trabajo dura cuarenta minutos. Durante el trayecto, escucho música o repaso mis notas para las reuniones. Es un tiempo importante para organizar mis ideas y preparar mis tareas diarias.

Por la tarde, regreso a casa a las seis. Cocino algo sencillo, como arroz con pollo, y estudio español durante una hora. Finalmente, veo una película y duermo a las diez. Estoy muy feliz con mi vida independiente y organizada.', '[{"prompt":"¿A qué hora se despierta Carlos?","options":["A las seis","A las siete","A las ocho","A las nueve"],"answer_index":0,"explanation_pt_br":"O texto afirma explicitamente que ele acorda às seis da manhã."},{"prompt":"¿Qué significa ''trayecto'' en el segundo párrafo?","options":["El trabajo","La oficina","El camino","La casa"],"answer_index":2,"explanation_pt_br":"No contexto da viagem de metrô, trayecto refere-se ao caminho ou percurso."},{"prompt":"¿Qué hace Carlos antes de dormir?","options":["Estudia español","Prepara el desayuno","Ve una película","Lee el periódico"],"answer_index":2,"explanation_pt_br":"O texto menciona que, após estudar espanhol, ele vê um filme antes de dormir."}]'::jsonb, 1),
('es-passage-a1-02', 'es', 'A1', 'Un viaje inolvidable', 'El verano pasado viajé a Buenos Aires con mi mejor amiga. Fue mi primera vez en Argentina y estaba muy emocionado. La ciudad es grande, bonita y tiene mucha historia. Nos alojamos en un hotel pequeño cerca del centro histórico.

Visitamos muchos lugares interesantes como el Obelisco y el famoso barrio de La Boca. Caminamos mucho por las calles y tomamos muchas fotos. También compramos recuerdos para nuestras familias en los mercados locales. Fue una experiencia cultural muy especial para las dos.

Probamos comidas típicas como las empanadas y el dulce de leche. Todo estaba delicioso. Al final del viaje, estábamos muy cansadas pero felices. Argentina es un país maravilloso y queremos regresar muy pronto para conocer otros lugares.', '[{"prompt":"¿Con quién viajó el autor?","options":["Con su familia","Con su amiga","Con su hermano","Solo"],"answer_index":1,"explanation_pt_br":"O autor menciona que viajou com sua melhor amiga."},{"prompt":"¿Qué hicieron al final del viaje?","options":["Estaban tristes","Estaban cansadas","Tenían hambre","Estaban enojadas"],"answer_index":1,"explanation_pt_br":"O texto diz que ao final estavam cansadas, mas felizes."},{"prompt":"¿Cuál es la idea principal del texto?","options":["El trabajo en el hotel","La comida de Buenos Aires","Una experiencia de viaje","La compra de ropa"],"answer_index":2,"explanation_pt_br":"O texto relata a experiência geral de uma viagem a Buenos Aires."}]'::jsonb, 2),
('es-passage-a1-03', 'es', 'A1', 'Trabajo en la oficina', 'Soy Ana y trabajo en una empresa de tecnología en Madrid. Mi oficina es moderna y tiene mucha luz. Todos los días hablo con mis compañeros sobre los proyectos nuevos. Me gusta mucho trabajar aquí porque aprendo algo nuevo cada semana.

Mi jefe es muy amable y siempre me ayuda cuando tengo dudas. A las diez de la mañana tenemos una breve reunión para revisar los objetivos. Después, respondo correos electrónicos y llamo a los clientes por teléfono. Es un trabajo activo y constante.

A la una, almuerzo con mis amigos en la cafetería. Hablamos de temas variados y descansamos un poco antes de terminar la jornada. A las cinco de la tarde, apago mi computadora y regreso a casa muy contenta.', '[{"prompt":"¿Qué hace Ana a las diez de la mañana?","options":["Almuerza","Tiene una reunión","Llama a sus amigos","Se va a casa"],"answer_index":1,"explanation_pt_br":"O texto indica que às dez horas ocorre a reunião de objetivos."},{"prompt":"¿Cómo es el jefe de Ana?","options":["Muy serio","Muy amable","Muy cansado","Muy joven"],"answer_index":1,"explanation_pt_br":"Ana descreve seu chefe como muito gentil/amável."},{"prompt":"¿Qué sucede después del almuerzo?","options":["Ella trabaja más","Ella se va a dormir","Ella se va a casa","Ella busca trabajo"],"answer_index":0,"explanation_pt_br":"Após o almoço, ela retorna ao trabalho para terminar a jornada."}]'::jsonb, 3),
('es-passage-a1-04', 'es', 'A1', 'Cuidar la salud', 'La salud es muy importante para vivir bien. Por eso, intento comer muchas frutas y verduras todos los días. También bebo dos litros de agua, porque el cuerpo necesita hidratación constante para funcionar correctamente durante las largas jornadas de estudio.

Hago ejercicio tres veces por semana en el parque. Correr me ayuda a reducir el estrés y a dormir mejor por la noche. Además, camino siempre que puedo en lugar de usar el autobús o el coche. Es un hábito muy saludable.

Visito al médico una vez al año para un chequeo general. Él dice que estoy muy bien. Mi objetivo es mantener este estilo de vida para tener energía y disfrutar de todas las cosas bonitas de la vida.', '[{"prompt":"¿Cuántas veces hace ejercicio a la semana?","options":["Una vez","Dos veces","Tres veces","Cuatro veces"],"answer_index":2,"explanation_pt_br":"O texto afirma que faz exercício três vezes por semana."},{"prompt":"¿Qué significa ''chequeo'' en el texto?","options":["Un pago","Una receta","Un examen médico","Una cita con amigos"],"answer_index":2,"explanation_pt_br":"No contexto médico, chequeo é um exame ou avaliação de saúde."},{"prompt":"¿Por qué el autor bebe mucha agua?","options":["Por el calor","Por el médico","Por la hidratación","Por el ejercicio"],"answer_index":2,"explanation_pt_br":"O texto menciona que o corpo precisa de hidratação constante."}]'::jsonb, 4),
('es-passage-a1-05', 'es', 'A1', 'Tradiciones y comida', 'En mi pueblo, la comida es el centro de todas las reuniones. Los domingos, mi familia prepara una gran paella. Todos ayudamos en la cocina: unos cortan las verduras, otros preparan el arroz y los niños ponen la mesa con mucho cuidado.

Es una tradición muy antigua que compartimos con los vecinos. Invitamos a las personas que viven cerca y comemos todos juntos en el jardín. Hablamos, reímos y celebramos nuestra amistad. La comida sabe mucho mejor cuando estamos en comunidad y con alegría.

Después de comer, tomamos café y escuchamos música tradicional. Estos momentos son muy importantes para nuestra cultura. Me gusta mucho ver cómo nuestra comunidad se mantiene unida gracias a estas costumbres tan especiales y sencillas.', '[{"prompt":"¿Cuándo prepara la familia la paella?","options":["Los lunes","Los sábados","Los domingos","Los viernes"],"answer_index":2,"explanation_pt_br":"O texto especifica que a paella é feita aos domingos."},{"prompt":"¿Quiénes participan en la comida?","options":["Solo la familia","Los vecinos","Solo los niños","Los turistas"],"answer_index":1,"explanation_pt_br":"O texto menciona que convidam os vizinhos para comer juntos."},{"prompt":"¿Cuál es el tono principal del texto?","options":["Triste","Enojado","Alegre","Aburrido"],"answer_index":2,"explanation_pt_br":"O texto descreve momentos de união, risadas e celebração, indicando um tom alegre."}]'::jsonb, 5),
('es-passage-a1-06', 'es', 'A1', 'La tecnología en mi día', 'Hoy en día, uso mi teléfono inteligente para muchas cosas importantes. Por la mañana, consulto el tiempo y leo las noticias mientras bebo café en casa. Es una herramienta muy útil para organizar mi agenda diaria.

En el trabajo, envío correos electrónicos a mis colegas y clientes. También participo en reuniones virtuales a través de aplicaciones sencillas. La tecnología facilita mi comunicación porque puedo hablar con personas que viven en ciudades muy lejanas.

Por la noche, me gusta relajarme un poco con mi computadora. Veo videos cortos o escucho música antes de dormir. Aunque la tecnología es necesaria, también es importante descansar de las pantallas para tener una vida más tranquila.', '[{"prompt":"¿Qué hace el protagonista al empezar el día?","options":["Trabaja en la computadora","Revisa el clima y las noticias","Llama a sus clientes","Ve videos musicales"],"answer_index":1,"explanation_pt_br":"O texto menciona que pela manhã ele consulta o tempo e lê as notícias."},{"prompt":"¿Qué significa la palabra ''herramienta'' en el texto?","options":["Un tipo de café","Un objeto útil","Un amigo cercano","Una aplicación nueva"],"answer_index":1,"explanation_pt_br":"No contexto, a palavra refere-se ao celular como um objeto de utilidade."},{"prompt":"¿Cuál es la idea principal del texto?","options":["La tecnología es mala para dormir","El trabajo es más importante que el ocio","La tecnología es parte cotidiana de la vida","Es difícil usar aplicaciones modernas"],"answer_index":2,"explanation_pt_br":"O texto descreve como a tecnologia está presente em diversas atividades diárias."}]'::jsonb, 6),
('es-passage-a1-07', 'es', 'A1', 'Cuidamos el planeta', 'Cada día, muchas personas intentan vivir de una manera más ecológica en sus casas. Por ejemplo, mi familia separa la basura en diferentes contenedores. Es una acción pequeña, pero ayuda mucho a reciclar el plástico y el papel correctamente.

Además, intentamos ahorrar agua cuando nos lavamos los dientes o cuando limpiamos la cocina. También compramos frutas y verduras en el mercado local para evitar el transporte largo de los alimentos. Estas elecciones son muy importantes para el medio ambiente.

Finalmente, apagamos las luces cuando salimos de una habitación. Queremos cuidar los recursos naturales de nuestra ciudad. Si todos hacemos pequeños cambios en nuestra rutina, podemos construir un futuro mejor para todos los habitantes de este planeta.', '[{"prompt":"¿Qué hace la familia con la basura?","options":["La quema en el jardín","La lleva al mercado","La separa en contenedores","La tira en la calle"],"answer_index":2,"explanation_pt_br":"O texto afirma explicitamente que a família separa o lixo em diferentes recipientes."},{"prompt":"¿Por qué compran productos en el mercado local?","options":["Porque son más baratos","Para evitar transportes largos","Porque no hay supermercados","Para regalar a los amigos"],"answer_index":1,"explanation_pt_br":"O texto diz que a escolha visa evitar o transporte longo dos alimentos."},{"prompt":"¿Qué hace la familia para ahorrar energía?","options":["Cierra las ventanas","Apaga las luces","Compra mucha comida","Lava los platos a mano"],"answer_index":1,"explanation_pt_br":"Apagar as luzes ao sair é a medida citada para economizar energia."}]'::jsonb, 7),
('es-passage-a1-08', 'es', 'A1', 'Mis amigos y yo', 'Tengo un grupo de amigos muy simpáticos con quienes comparto mi tiempo libre. Casi siempre nos reunimos los sábados por la tarde para caminar por el parque o visitar un museo interesante. Nos gusta conversar sobre nuestros planes futuros.

A veces, organizamos una cena en mi casa. Cada persona trae un plato diferente, como ensalada, pasta o postre. Es un momento muy divertido porque compartimos historias y reímos mucho juntos. La amistad es fundamental para mi bienestar emocional.

Cuando uno de mis amigos tiene un problema, siempre escuchamos con paciencia. Creo que la clave de una buena relación es el respeto y la honestidad. Estoy muy feliz de tener personas tan especiales en mi vida actual.', '[{"prompt":"¿Cuándo se reúne el grupo de amigos?","options":["Los lunes por la mañana","Los sábados por la tarde","Todos los días","Los domingos por la noche"],"answer_index":1,"explanation_pt_br":"O texto indica claramente que os encontros ocorrem aos sábados à tarde."},{"prompt":"¿Qué hacen durante las cenas en casa?","options":["Cada uno trae comida","Compran comida rápida","Solo ven películas","Estudian para el trabajo"],"answer_index":0,"explanation_pt_br":"O texto menciona que cada pessoa traz um prato diferente para a refeição."},{"prompt":"¿Qué valora el autor en una relación?","options":["El dinero y los regalos","La puntualidad y el orden","El respeto y la honestidad","La fama y el éxito"],"answer_index":2,"explanation_pt_br":"O autor cita explicitamente o respeito e a honestidade como chaves para uma boa relação."}]'::jsonb, 8),
('es-passage-a1-09', 'es', 'A1', 'El dinero y el consumo', 'Gestionar el dinero personal es una habilidad muy necesaria para todos los adultos. Cada mes, recibo mi salario y hago una lista de mis gastos básicos como el alquiler, la luz y la comida. Esto ayuda mucho.

Intento no comprar cosas innecesarias en las tiendas. Antes de gastar, pienso si realmente necesito ese objeto nuevo. A veces, es mejor guardar una pequeña cantidad de dinero en el banco para cualquier emergencia o para un viaje futuro.

El consumo responsable significa elegir productos de buena calidad que duren mucho tiempo. Así, no tengo que comprar lo mismo varias veces. Con una buena planificación financiera, puedo vivir tranquilo y disfrutar de mis actividades favoritas sin estrés.', '[{"prompt":"¿Qué hace el autor al recibir su salario?","options":["Compra ropa nueva","Hace una lista de gastos","Viaja a otra ciudad","Regala dinero a amigos"],"answer_index":1,"explanation_pt_br":"O autor menciona que faz uma lista dos gastos básicos ao receber o salário."},{"prompt":"¿Qué significa ''consumo responsable'' en el texto?","options":["Comprar siempre lo más barato","Comprar solo comida","Elegir productos duraderos","No comprar nada nunca"],"answer_index":2,"explanation_pt_br":"O texto define o consumo responsável como a escolha de produtos de qualidade que duram."},{"prompt":"¿Cuál es el beneficio de la planificación financiera?","options":["Vivir sin estrés","Tener muchas casas","Trabajar menos horas","Viajar cada semana"],"answer_index":0,"explanation_pt_br":"O final do texto afirma que o planejamento permite viver tranquilo e sem estresse."}]'::jsonb, 9),
('es-passage-a1-10', 'es', 'A1', 'Aprender siempre', 'La educación no termina cuando salimos de la escuela. Hoy en día, muchas personas estudian cosas nuevas durante toda su vida. Por ejemplo, yo tomo clases de cocina los martes y estudio un idioma los jueves por la noche.

Aprender una habilidad nueva es muy emocionante. Me ayuda a conocer gente nueva y a mejorar mi memoria. Uso libros, videos en internet y cursos presenciales para practicar lo que me gusta. Nunca es tarde para empezar algo diferente.

La curiosidad es el motor de mi aprendizaje constante. Creo que leer mucho y hacer preguntas es fundamental para crecer como persona. Estoy muy motivado porque siempre hay un conocimiento nuevo esperando ser descubierto en nuestro mundo actual.', '[{"prompt":"¿Qué clases toma el autor los jueves?","options":["Cocina","Historia","Un idioma","Matemáticas"],"answer_index":2,"explanation_pt_br":"O autor diz explicitamente que estuda um idioma nas noites de quinta-feira."},{"prompt":"¿Qué recursos usa el autor para aprender?","options":["Solo la televisión","Libros, videos y cursos","Solo habla con amigos","Viajes al extranjero"],"answer_index":1,"explanation_pt_br":"O texto lista livros, vídeos na internet e cursos presenciais como recursos."},{"prompt":"¿Cuál es el mensaje principal sobre la educación?","options":["Es solo para los niños","Es aburrida y difícil","Es un proceso constante","Solo es necesaria para trabajar"],"answer_index":2,"explanation_pt_br":"O texto defende que o aprendizado é contínuo ao longo de toda a vida."}]'::jsonb, 10),
('es-passage-a2-01', 'es', 'A2', 'La rutina de Elena', 'Elena vive sola en un apartamento pequeño cerca del centro de la ciudad. Ella siempre se despierta muy temprano, exactamente a las seis de la mañana, para empezar su día con energía. Después de desayunar café con leche, Elena prepara sus cosas para ir a la oficina donde trabaja como asistente administrativa.

Su rutina matutina es bastante organizada y eficiente. Primero, se ducha rápidamente y elige ropa cómoda para caminar hasta la estación de metro. Durante el trayecto, le gusta escuchar música clásica o podcasts en español para mejorar su comprensión auditiva mientras observa a las personas que van a sus empleos.

Al llegar a su trabajo, revisa todos sus correos electrónicos pendientes y organiza su agenda personal. A mediodía, Elena prefiere almorzar una ensalada fresca con sus compañeros de equipo en un parque cercano. Este momento le permite relajarse y conversar sobre temas interesantes lejos de las pantallas de las computadoras.

Por la tarde, termina sus tareas pendientes y regresa a casa caminando para hacer un poco de ejercicio. Antes de dormir, Elena disfruta de leer un libro durante treinta minutos. Ella siente que esta independencia le ayuda a ser una mujer más segura, tranquila y responsable cada día de su vida.', '[{"prompt":"¿A qué hora se despierta Elena habitualmente?","options":["A las seis de la mañana","A las siete de la mañana","A las ocho de la mañana","A las nueve de la mañana"],"answer_index":0,"explanation_pt_br":"O texto menciona explicitamente que ela acorda exatamente às seis da manhã."},{"prompt":"¿Qué significa la palabra ''trayecto'' en el segundo párrafo?","options":["El trabajo","El camino","La oficina","La comida"],"answer_index":1,"explanation_pt_br":"No contexto da frase, ''trayecto'' refere-se ao percurso ou caminho que ela faz até o trabalho."},{"prompt":"¿Qué hace Elena después de almorzar en el parque?","options":["Duerme un poco","Regresa a trabajar","Escucha música","Lee un libro"],"answer_index":1,"explanation_pt_br":"O texto indica que, após o almoço, ela retorna ao trabalho para terminar as tarefas pendentes."},{"prompt":"¿Cuál es la idea principal del texto?","options":["La importancia del metro","La rutina de una mujer independiente","El trabajo de Elena","La lectura de libros"],"answer_index":1,"explanation_pt_br":"O texto descreve detalhadamente como a protagonista organiza sua rotina diária e valoriza sua independência."}]'::jsonb, 1),
('es-passage-a2-02', 'es', 'A2', 'Un viaje inolvidable', 'El año pasado, Carlos decidió viajar solo por primera vez a un país hispanohablante. Él eligió visitar Perú porque quería conocer la historia de los Incas y probar la comida local. Compró sus boletos de avión con mucha anticipación y reservó un hostal pequeño en el centro de la histórica ciudad de Cusco.

Al llegar al aeropuerto, Carlos se sintió un poco nervioso por el idioma, pero las personas fueron muy amables. Durante su estancia, visitó el famoso sitio arqueológico de Machu Picchu. Allí, caminó por senderos antiguos y tomó muchas fotografías de las montañas verdes que rodeaban las construcciones de piedra de los antiguos habitantes.

Además de los monumentos, Carlos disfrutó mucho de los mercados tradicionales. En estos lugares, él compró artesanías hechas a mano por los artistas locales y aprendió algunas palabras nuevas en quechua. También conoció a otros viajeros de diferentes países con quienes compartió cenas y experiencias inolvidables durante sus recorridos nocturnos por la ciudad.

Este viaje cambió su perspectiva sobre el mundo y su forma de ver otras culturas. Carlos regresó a casa con muchas historias interesantes para contar a su familia. Ahora, él planea ahorrar dinero para visitar otros países en el futuro y seguir descubriendo la belleza de nuestro gran planeta.', '[{"prompt":"¿Por qué Carlos eligió viajar a Perú?","options":["Para visitar a su familia","Para trabajar en un hostal","Para conocer la historia y la comida","Para comprar artesanías baratas"],"answer_index":2,"explanation_pt_br":"O texto diz que ele escolheu o Peru para conhecer a história dos Incas e provar a comida local."},{"prompt":"¿Qué hizo Carlos en Machu Picchu?","options":["Compró ropa típica","Caminó y tomó fotos","Habló con los Incas","Durmió en un hotel"],"answer_index":1,"explanation_pt_br":"O autor menciona que caminhou por senderos e tirou fotos das montanhas."},{"prompt":"¿Cómo se sintió Carlos al llegar al aeropuerto?","options":["Muy feliz","Un poco nervioso","Muy cansado","Muy aburrido"],"answer_index":1,"explanation_pt_br":"O texto afirma explicitamente que ele se sentiu um pouco nervoso por causa do idioma."},{"prompt":"¿Cuál es el propósito principal del relato?","options":["Vender viajes a Perú","Describir una experiencia personal de viaje","Enseñar quechua","Criticar el turismo"],"answer_index":1,"explanation_pt_br":"O texto é um relato pessoal sobre a experiência de viagem de Carlos ao Peru."}]'::jsonb, 2),
('es-passage-a2-03', 'es', 'A2', 'El mundo laboral', 'Trabajar en una empresa internacional requiere habilidades de comunicación muy claras y mucha paciencia. Sofía trabaja en el departamento de ventas de una compañía de tecnología. Su oficina es moderna y tiene muchas ventanas, lo que permite que entre mucha luz natural durante toda la jornada laboral diaria.

Cada mañana, ella tiene una reunión virtual con sus colegas de otros países para organizar los proyectos semanales. Es importante hablar con claridad y escuchar las ideas de los demás. Aunque a veces hay problemas de conexión a internet, el equipo siempre busca soluciones rápidas para no retrasar los objetivos comunes establecidos.

Sofía utiliza herramientas digitales para gestionar su tiempo y enviar informes importantes a su jefe. Ella valora mucho el trabajo en equipo porque sabe que, juntos, pueden lograr resultados mucho mejores que trabajando solos. Además, los viernes son días especiales porque todos comparten un café virtual para relajarse un poco.

La comunicación efectiva es la clave del éxito en su entorno profesional. Sofía estudia constantemente para mejorar su nivel de inglés y español. Ella cree que aprender idiomas es fundamental para tener más oportunidades en el futuro, ya que el mercado actual es global y muy competitivo para todos los profesionales.', '[{"prompt":"¿Qué hace Sofía cada mañana?","options":["Envía correos a su jefe","Tiene una reunión virtual","Limpia su oficina","Estudia inglés"],"answer_index":1,"explanation_pt_br":"O texto menciona que ela tem uma reunião virtual com colegas de outros países todas as manhãs."},{"prompt":"¿Qué significa ''gestionar'' en el tercer párrafo?","options":["Olvidar","Administrar","Imprimir","Comprar"],"answer_index":1,"explanation_pt_br":"No contexto profissional, ''gestionar'' tempo significa administrar ou organizar o tempo."},{"prompt":"¿Por qué son especiales los viernes para el equipo?","options":["Tienen vacaciones","Tienen una reunión virtual de café","Terminan de trabajar temprano","Reciben un aumento de sueldo"],"answer_index":1,"explanation_pt_br":"O texto afirma que às sextas-feiras eles compartilham um café virtual para relaxar."},{"prompt":"¿Cuál es la opinión de Sofía sobre los idiomas?","options":["Son muy difíciles","No son necesarios","Son fundamentales para el futuro","Son solo para viajar"],"answer_index":2,"explanation_pt_br":"Sofía acredita que aprender idiomas é fundamental para ter mais oportunidades no futuro."}]'::jsonb, 3),
('es-passage-a2-04', 'es', 'A2', 'Salud y equilibrio', 'Mantener una vida saludable es una prioridad para muchas personas en la actualidad. No se trata solo de hacer ejercicio físico, sino también de cuidar la salud mental y comer de forma equilibrada. Muchas personas eligen caminar en el parque o practicar yoga para liberar el estrés acumulado durante el día.

La alimentación es otro pilar fundamental para nuestro bienestar general. Es recomendable consumir muchas frutas, verduras y beber suficiente agua para mantener el cuerpo hidratado. Evitar el exceso de azúcar y alimentos procesados ayuda a tener mucha más energía para realizar todas las actividades diarias con mayor entusiasmo y alegría.

Dormir bien es igualmente importante para recuperar las fuerzas. Los médicos sugieren descansar al menos siete u ocho horas cada noche. Un sueño reparador permite que nuestra mente descanse y esté lista para enfrentar los desafíos del día siguiente. Sin un buen descanso, es muy difícil mantener la concentración en el trabajo o estudios.

Finalmente, es necesario buscar momentos para desconectarse de la tecnología. Leer un libro, escuchar música relajante o pasar tiempo con la familia son actividades que ayudan a mantener el equilibrio emocional. Cuidar de uno mismo es la mejor inversión que podemos hacer para disfrutar de una vida plena y saludable.', '[{"prompt":"¿Qué recomienda el texto para mantener el cuerpo hidratado?","options":["Beber mucha agua","Tomar café","Comer muchas frutas","Dormir bien"],"answer_index":0,"explanation_pt_br":"O texto menciona explicitamente que beber água suficiente é necessário para manter o corpo hidratado."},{"prompt":"¿Cuántas horas de sueño sugieren los médicos?","options":["Menos de cinco horas","Entre siete y ocho horas","Más de diez horas","Seis horas exactamente"],"answer_index":1,"explanation_pt_br":"O texto indica que os médicos sugerem descansar entre sete e oito horas por noite."},{"prompt":"¿Qué sucede si una persona no duerme bien?","options":["Tiene mucha energía","Mejora su salud mental","Pierde la concentración","Se siente muy feliz"],"answer_index":2,"explanation_pt_br":"O texto afirma que sem um bom descanso é difícil manter a concentração."},{"prompt":"¿Cuál es el tema central del texto?","options":["Cómo hacer ejercicio","La importancia de la tecnología","Consejos para una vida saludable","La dieta de los médicos"],"answer_index":2,"explanation_pt_br":"O texto aborda diversos pilares para manter o bem-estar e uma vida saudável."}]'::jsonb, 4),
('es-passage-a2-05', 'es', 'A2', 'Tradiciones en la mesa', 'La comida es un elemento esencial que une a las familias y a las comunidades en todo el mundo. En muchas culturas, preparar platos tradicionales es una forma de celebrar la historia y los valores de los antepasados. Estas recetas pasan de generación en generación, manteniendo viva la identidad de cada pueblo.

Cada domingo, la familia de María se reúne en la casa de sus abuelos para almorzar juntos. Ella ayuda a preparar una receta especial de arroz con vegetales que es famosa en toda la ciudad. Mientras cocinan, todos comparten historias sobre sus vidas, ríen y planean proyectos futuros para la familia unida.

Compartir una comida no es solo alimentarse, es también fortalecer los vínculos afectivos entre las personas. En la mesa, se resuelven conflictos y se celebran los éxitos personales de cada miembro. Los ingredientes frescos y el amor puesto en la preparación hacen que cada bocado sea una experiencia única y muy reconfortante.

Las tradiciones culinarias nos ayudan a sentirnos parte de algo más grande. Cuando cocinamos para otros, estamos ofreciendo nuestro cuidado y nuestro cariño. Es una forma de comunicación universal que trasciende las palabras y nos permite conectar profundamente con nuestros amigos, vecinos y toda la comunidad local.', '[{"prompt":"¿Cuándo se reúne la familia de María?","options":["Todos los lunes","Los sábados por la tarde","Cada domingo","Una vez al mes"],"answer_index":2,"explanation_pt_br":"O texto diz que a família se reúne todos os domingos na casa dos avós."},{"prompt":"¿Qué significa ''vínculos'' en el tercer párrafo?","options":["Comidas","Relaciones","Recetas","Problemas"],"answer_index":1,"explanation_pt_br":"Nesse contexto, ''vínculos afectivos'' refere-se às relações ou laços emocionais entre as pessoas."},{"prompt":"¿Qué hacen María y su familia mientras cocinan?","options":["Miran la televisión","Comparten historias","Leen libros","Trabajan en computadoras"],"answer_index":1,"explanation_pt_br":"O texto menciona que enquanto cozinham, eles compartilham histórias e riem."},{"prompt":"¿Cuál es la idea principal de este texto?","options":["La cocina es difícil","Las recetas son secretas","La comida une a la comunidad","Es mejor comer solo"],"answer_index":2,"explanation_pt_br":"O foco do texto é como a comida e as tradições fortalecem as relações e a comunidade."}]'::jsonb, 5),
('es-passage-a2-06', 'es', 'A2', 'La vida conectada', 'Hoy en día, la tecnología forma parte de nuestra rutina desde que despertamos. Muchas personas usan sus teléfonos inteligentes para revisar el correo electrónico, ver las noticias o consultar el clima antes de salir de casa hacia el trabajo.

Además de la comunicación, las aplicaciones digitales facilitan tareas cotidianas como pedir comida o solicitar un transporte privado. Estos servicios ahorran mucho tiempo a los trabajadores que tienen horarios muy ocupados durante la semana laboral.

Sin embargo, el uso excesivo de dispositivos electrónicos puede causar distracciones importantes. Algunos expertos recomiendan limitar el tiempo frente a la pantalla para mejorar la concentración y reducir el estrés acumulado durante la jornada diaria.

En conclusión, la tecnología es una herramienta muy útil si sabemos cómo utilizarla con equilibrio. Aprender a desconectarse por unas horas es fundamental para mantener nuestra salud mental y disfrutar de las interacciones reales con amigos.', '[{"prompt":"¿Qué hacen las personas generalmente antes de ir a trabajar?","options":["Hacen ejercicio en el parque","Revisan el clima y las noticias","Llaman a sus jefes por teléfono","Escriben correos en papel"],"answer_index":1,"explanation_pt_br":"O texto menciona que as pessoas usam o celular para revisar o e-mail, notícias ou o clima antes de sair de casa."},{"prompt":"En el texto, ¿qué significa la palabra ''cotidianas''?","options":["Difíciles y costosas","Nuevas y extrañas","Diarias y habituales","Lentas y aburridas"],"answer_index":2,"explanation_pt_br":"No contexto, ''cotidianas'' refere-se a tarefas que fazemos todos os dias, ou seja, diárias."},{"prompt":"¿Qué sucede si usamos demasiado el teléfono según los expertos?","options":["Mejoramos nuestra memoria","Perdemos la concentración","Ganamos mucho más dinero","Dormimos mejor por la noche"],"answer_index":1,"explanation_pt_br":"O texto afirma que o uso excessivo pode causar distrações e afetar a concentração."},{"prompt":"¿Cuál es la idea principal del texto?","options":["La tecnología es mala para los trabajadores","Debemos usar la tecnología con equilibrio","Las aplicaciones son siempre gratuitas","Es imposible vivir sin internet hoy"],"answer_index":1,"explanation_pt_br":"A conclusão do texto destaca a importância de usar a tecnologia com equilíbrio."}]'::jsonb, 6),
('es-passage-a2-07', 'es', 'A2', 'Cuidar nuestro planeta', 'El medio ambiente necesita nuestra atención inmediata para evitar problemas futuros. Muchas ciudades han comenzado a implementar programas de reciclaje para reducir la enorme cantidad de basura que producimos cada día en nuestros hogares.

Una acción sencilla pero efectiva es evitar el uso de plásticos de un solo uso. Cambiar las bolsas de plástico por bolsas de tela reutilizables es un paso pequeño que ayuda a disminuir la contaminación en los océanos.

El ahorro de energía también juega un papel crucial en la sostenibilidad. Apagar las luces innecesarias y utilizar electrodomésticos eficientes permite consumir menos recursos naturales, lo cual beneficia tanto a la economía familiar como al ecosistema global.

Finalmente, el cambio empieza con decisiones personales. Si cada persona elige productos locales y respeta el entorno natural, lograremos proteger la diversidad biológica para que las próximas generaciones puedan disfrutar de un planeta limpio y saludable.', '[{"prompt":"¿Qué hacen las ciudades para gestionar la basura?","options":["Prohíben el uso de camiones","Implementan programas de reciclaje","Envían toda la basura al mar","Queman los residuos en fábricas"],"answer_index":1,"explanation_pt_br":"O texto menciona que as cidades começaram a implementar programas de reciclagem."},{"prompt":"¿Qué sugiere el autor para reducir la contaminación?","options":["Usar más bolsas de plástico","Comprar productos de otros países","Usar bolsas de tela reutilizables","Dejar las luces encendidas siempre"],"answer_index":2,"explanation_pt_br":"O autor sugere substituir bolsas de plástico por bolsas de tecido."},{"prompt":"¿Qué pasa después de ahorrar energía en casa?","options":["El planeta se vuelve más pobre","La economía familiar se beneficia","Las luces dejan de funcionar","Es necesario comprar más aparatos"],"answer_index":1,"explanation_pt_br":"O texto afirma que economizar energia beneficia a economia familiar."},{"prompt":"¿Cuál es el objetivo principal de este texto?","options":["Promover el consumo de plástico","Explicar cómo reciclar metal","Fomentar acciones sostenibles","Criticar a las ciudades grandes"],"answer_index":2,"explanation_pt_br":"O texto foca em incentivar hábitos sustentáveis para proteger o meio ambiente."}]'::jsonb, 7),
('es-passage-a2-08', 'es', 'A2', 'Nuestras relaciones sociales', 'Mantener buenas relaciones con los demás es esencial para nuestra felicidad. La amistad verdadera requiere tiempo, honestidad y mucha paciencia, especialmente cuando las personas tienen opiniones diferentes sobre temas importantes de la vida cotidiana.

Hoy en día, las redes sociales permiten estar en contacto con amigos lejanos, pero no reemplazan los encuentros cara a cara. Una conversación en persona permite entender mejor las emociones y fortalece el vínculo entre las personas de manera real.

En el trabajo, colaborar con los compañeros es fundamental para lograr buenos resultados. Cuando existe un ambiente de apoyo y respeto, es mucho más sencillo resolver problemas y alcanzar las metas establecidas por el equipo profesional.

En resumen, cultivar la empatía es el secreto para mejorar nuestras interacciones. Escuchar con atención y tratar a los demás con amabilidad nos ayuda a construir una red social sólida que nos acompaña en los momentos de alegría y dificultad.', '[{"prompt":"¿Qué se necesita para tener una amistad verdadera?","options":["Mucho dinero y regalos","Tiempo, honestidad y paciencia","Estar de acuerdo en todo","Vivir en la misma ciudad"],"answer_index":1,"explanation_pt_br":"O texto lista explicitamente tempo, honestidade e paciência como requisitos para a amizade."},{"prompt":"Según el texto, ¿qué ofrecen las redes sociales?","options":["La solución a la soledad total","Contacto con amigos lejanos","Mejores resultados laborales","Una vida sin problemas reales"],"answer_index":1,"explanation_pt_br":"O texto diz que as redes permitem contato com amigos distantes."},{"prompt":"¿Qué sucede en un equipo de trabajo donde hay respeto?","options":["Es más fácil resolver problemas","El equipo trabaja más lento","Nadie quiere hablar entre sí","Los objetivos son imposibles"],"answer_index":0,"explanation_pt_br":"O texto diz que, com respeito, é mais fácil resolver problemas e atingir metas."},{"prompt":"¿Qué significa ''cultivar la empatía'' en el último párrafo?","options":["Hablar siempre de uno mismo","Ignorar las opiniones ajenas","Entender y valorar a los demás","Competir con los amigos"],"answer_index":2,"explanation_pt_br":"Empatia, no contexto, refere-se a entender e tratar os outros com consideração."}]'::jsonb, 8),
('es-passage-a2-09', 'es', 'A2', 'Finanzas y consumo', 'Gestionar el dinero personal es una habilidad clave para vivir con tranquilidad. Muchas personas cometen el error de gastar más de lo que ganan cada mes, lo que genera deudas difíciles de pagar a corto plazo.

Para organizar las finanzas, es necesario crear un presupuesto mensual. Anotar todos los gastos, desde el alquiler hasta los pequeños caprichos, ayuda a identificar dónde se puede ahorrar dinero para metas futuras importantes.

El consumo responsable también es importante al comprar productos. Antes de adquirir algo nuevo, debemos preguntarnos si realmente lo necesitamos o si es solo un deseo impulsivo del momento. Comprar menos ayuda a vivir mejor.

Finalmente, ahorrar una pequeña parte del salario cada mes permite tener un fondo de emergencia. Este dinero extra nos da seguridad ante situaciones imprevistas, permitiendo que nuestra economía familiar sea estable y mucho más equilibrada con el tiempo.', '[{"prompt":"¿Cuál es un error común que menciona el autor?","options":["Gastar más dinero del que se gana","Ahorrar demasiado cada mes","No comprar nada necesario","Tener un presupuesto muy estricto"],"answer_index":0,"explanation_pt_br":"O texto aponta que gastar mais do que se ganha é um erro comum."},{"prompt":"¿Qué se debe incluir en un presupuesto mensual?","options":["Solo los gastos del trabajo","Todos los gastos, incluidos caprichos","Únicamente el dinero de la cuenta","Las compras que haremos el próximo año"],"answer_index":1,"explanation_pt_br":"O autor recomenda anotar todos os gastos no orçamento."},{"prompt":"¿Qué debemos hacer antes de comprar algo nuevo?","options":["Preguntar a un amigo cercano","Esperar a que el precio suba","Preguntar si realmente es necesario","Comprar siempre lo más caro"],"answer_index":2,"explanation_pt_br":"O texto sugere perguntar se o produto é realmente necessário antes de comprar."},{"prompt":"¿Para qué sirve tener un fondo de emergencia?","options":["Para viajar por todo el mundo","Para comprar ropa de lujo","Para tener seguridad ante imprevistos","Para pagar deudas de amigos"],"answer_index":2,"explanation_pt_br":"O fundo de emergência serve para dar segurança em situações inesperadas."}]'::jsonb, 9),
('es-passage-a2-10', 'es', 'A2', 'Aprender toda la vida', 'La educación no termina cuando salimos de la escuela o la universidad. En el mundo actual, el aprendizaje continuo es vital para adaptarse a los cambios constantes del mercado laboral y mejorar nuestras habilidades personales.

Existen muchas formas de aprender cosas nuevas hoy en día. Desde cursos en línea hasta talleres presenciales, las opciones son infinitas para quienes desean mejorar sus conocimientos en idiomas, tecnología o cualquier otra área de interés.

Muchas personas estudian después del trabajo para cambiar de carrera o buscar mejores oportunidades. Aunque requiere esfuerzo y dedicación, los beneficios de aprender algo nuevo son gratificantes y aumentan nuestra confianza en nosotros mismos.

En conclusión, nunca es tarde para empezar un nuevo proyecto educativo. Mantener la curiosidad activa nos permite seguir creciendo como personas, lo cual enriquece nuestra vida y nos prepara mejor para los desafíos que vendrán en el futuro.', '[{"prompt":"¿Por qué es importante el aprendizaje continuo hoy?","options":["Para terminar la universidad","Para adaptarse a los cambios laborales","Para descansar más tiempo","Para ganar dinero sin trabajar"],"answer_index":1,"explanation_pt_br":"O texto menciona que o aprendizado é vital para se adaptar às mudanças no mercado."},{"prompt":"¿Qué opciones existen para aprender cosas nuevas?","options":["Solo cursos en la universidad","Cursos en línea y talleres","Únicamente clases de idiomas","Solo libros de la biblioteca"],"answer_index":1,"explanation_pt_br":"O autor cita tanto cursos online quanto oficinas presenciais."},{"prompt":"¿Qué beneficio personal produce aprender algo nuevo?","options":["Aumenta la confianza propia","Causa mucho estrés y cansancio","Hace que queramos dejar de estudiar","Reduce nuestro tiempo libre"],"answer_index":0,"explanation_pt_br":"O texto afirma que aprender algo novo aumenta a autoconfiança."},{"prompt":"¿Cuál es el mensaje final del texto?","options":["La educación es solo para jóvenes","Es tarde para aprender cosas nuevas","Nunca es tarde para seguir aprendiendo","El aprendizaje es una pérdida de tiempo"],"answer_index":2,"explanation_pt_br":"A conclusão enfatiza que nunca é tarde para começar um novo projeto educativo."}]'::jsonb, 10),
('es-passage-b1-01', 'es', 'B1', 'La nueva vida de Lucas', 'Lucas es un joven brasileño que recientemente se mudó a Madrid para empezar un máster. Al principio, adaptarse a la vida independiente fue un desafío considerable, especialmente porque estaba acostumbrado a que su familia le ayudara con las tareas domésticas en Brasil. Ahora, él es el único responsable de organizar su tiempo, mantener su apartamento limpio y gestionar su propio presupuesto mensual con mucha disciplina.

Su rutina comienza a las siete de la mañana, cuando suena el despertador. Lo primero que hace es preparar un café fuerte mientras revisa su agenda del día. A diferencia de su vida anterior, Lucas ha aprendido a planificar sus comidas semanalmente. Esto no solo le ayuda a ahorrar dinero, sino que también garantiza que coma de manera más saludable durante los días de mucho estudio.

Después de desayunar, se desplaza a la universidad utilizando el transporte público. Durante el trayecto, aprovecha para leer artículos académicos o escuchar podcasts en español para mejorar su comprensión auditiva. Esta técnica ha sido fundamental para que se sienta más seguro al participar en los debates de clase, donde antes le daba vergüenza hablar frente a sus compañeros españoles.

Al regresar a casa por la tarde, Lucas dedica un par de horas a completar sus deberes. Una vez terminadas sus responsabilidades académicas, suele ir al gimnasio o pasear por el parque cercano para desconectar. Es importante para él tener este momento de ocio, ya que considera que el equilibrio entre el esfuerzo intelectual y el descanso es la clave para no sufrir de estrés.

Los fines de semana, Lucas dedica tiempo a socializar. Sale con sus amigos a conocer nuevos lugares o simplemente organiza una cena en su casa. Aunque extraña a su familia, se siente orgulloso de su autonomía. La experiencia de vivir solo le ha permitido descubrir facetas de su personalidad que antes no conocía, convirtiéndose en una etapa transformadora y necesaria para su madurez personal.', '[{"prompt":"¿Cuál es el cambio principal en la vida de Lucas tras mudarse a Madrid?","options":["Ya no tiene que estudiar tanto como en Brasil.","Debe gestionar todas sus responsabilidades de forma independiente.","Ha dejado de hablar portugués con su familia.","Ahora tiene mucho más tiempo libre para viajar."],"answer_index":1,"explanation_pt_br":"O texto destaca que Lucas agora é o único responsável por tarefas, orçamento e organização, marcando sua nova autonomia."},{"prompt":"¿Qué técnica utiliza Lucas para mejorar su español durante el transporte?","options":["Hablar con desconocidos en el autobús.","Escribir diarios de sus experiencias pasadas.","Escuchar podcasts y leer textos académicos.","Ver películas en su teléfono móvil."],"answer_index":2,"explanation_pt_br":"O texto menciona explicitamente que ele lê artigos e ouve podcasts durante o trajeto para melhorar sua compreensão."},{"prompt":"Según el texto, ¿por qué Lucas planifica sus comidas semanalmente?","options":["Porque le gusta cocinar platos muy complejos.","Para evitar comer en restaurantes caros.","Para ahorrar dinero y comer de forma más saludable.","Para invitar a sus amigos a cenar todos los días."],"answer_index":2,"explanation_pt_br":"A passagem afirma que isso ajuda a economizar dinheiro e garante uma alimentação mais saudável."},{"prompt":"¿Qué significa la expresión ''desconectar'' en el contexto del cuarto párrafo?","options":["Apagar todos los aparatos electrónicos.","Relajarse y alejarse de las preocupaciones diarias.","Desenchufar los cables del gimnasio.","Perder la conexión a internet de la casa."],"answer_index":1,"explanation_pt_br":"Nesse contexto, desconectar refere-se a descansar e aliviar o estresse após o trabalho intelectual."},{"prompt":"¿Cuál es la idea principal del texto?","options":["La dificultad de vivir en una ciudad grande como Madrid.","El proceso de adaptación de Lucas y su crecimiento personal al vivir solo.","La importancia de estudiar un máster en el extranjero para tener éxito.","La superioridad de la rutina española sobre la brasileña."],"answer_index":1,"explanation_pt_br":"O texto foca na jornada de Lucas em se adaptar à vida independente e como isso contribuiu para seu amadurecimento."}]'::jsonb, 1),
('es-passage-b1-02', 'es', 'B1', 'Un viaje inolvidable por los Andes', 'El verano pasado, Elena decidió embarcarse en una aventura solitaria por los Andes peruanos. Siempre había soñado con caminar por senderos rodeados de montañas majestuosas y conocer de cerca la cultura andina. A pesar de que sus amigos le sugirieron viajar en grupo, ella prefirió la experiencia de la introspección, buscando un contacto más directo con los paisajes y las comunidades locales que encontraría en el camino.

Al llegar a Cusco, Elena se sintió inmediatamente cautivada por la mezcla de historia colonial y herencia inca. Dedicó sus primeros días a aclimatarse a la altura, recorriendo mercados llenos de colores y texturas. La gente local, con sus vestimentas tradicionales, le pareció fascinante. Aprendió que cada patrón en los tejidos tiene un significado profundo relacionado con la historia de sus antepasados y la naturaleza.

Durante su travesía hacia Machu Picchu, Elena tuvo la oportunidad de alojarse en casas de familias quechuas. Aunque la comunicación a veces era difícil, las sonrisas y los gestos fueron suficientes para entenderse. Compartió cenas sencillas basadas en papas y granos locales, escuchando historias sobre leyendas de la montaña que se han transmitido de generación en generación durante siglos.

Uno de los momentos más memorables fue cuando alcanzó la cima de una colina al amanecer. El silencio absoluto y la inmensidad del paisaje la hicieron reflexionar sobre la importancia de preservar estos lugares. Comprendió que viajar no es solo visitar puntos turísticos, sino también aprender a respetar otras formas de vida y valorar la simplicidad que a menudo olvidamos en nuestras ciudades modernas.

Al regresar a su hogar, Elena no solo trajo fotografías en su maleta, sino también una nueva perspectiva. La experiencia andina le enseñó que el mundo es vasto y diverso. Ahora, cada vez que siente la presión de la vida cotidiana, cierra los ojos y recuerda la calma de las montañas, sintiéndose agradecida por haber tenido la valentía de explorar un destino tan lejano y enriquecedor.', '[{"prompt":"¿Por qué Elena decidió viajar sola a los Andes?","options":["Porque no tenía amigos interesados en viajar.","Porque quería una experiencia de introspección y contacto directo.","Porque era una opción mucho más económica.","Porque quería evitar las aglomeraciones de los grupos turísticos."],"answer_index":1,"explanation_pt_br":"O texto afirma que ela preferiu a experiência de introspeção e um contato mais direto com a cultura e a paisagem."},{"prompt":"¿Qué aprendió Elena sobre los tejidos en los mercados de Cusco?","options":["Que eran muy baratos y de mala calidad.","Que se fabricaban rápidamente con máquinas modernas.","Que cada diseño tiene un significado histórico.","Que eran solo para uso de los turistas extranjeros."],"answer_index":2,"explanation_pt_br":"Ela aprendeu que os padrões nos tecidos têm significados profundos sobre a história e os antepassados locais."},{"prompt":"¿Cómo se comunicaba Elena con las familias locales durante su viaje?","options":["Hablando un español perfecto con ellos.","Utilizando traductores automáticos.","A través de sonrisas y gestos.","Escribiendo mensajes en una libreta."],"answer_index":2,"explanation_pt_br":"O texto menciona que, embora a comunicação fosse difícil, sorrisos e gestos eram suficientes para o entendimento."},{"prompt":"¿Qué significa la palabra ''aclimatarse'' en el segundo párrafo?","options":["Adaptarse gradualmente a las condiciones, como la altura.","Comprar ropa adecuada para el clima frío.","Conocer a muchas personas nuevas en poco tiempo.","Preparar las maletas para subir a la montaña."],"answer_index":0,"explanation_pt_br":"Aclimatar-se, neste contexto de altitude, significa preparar o corpo para as novas condições ambientais."},{"prompt":"¿Cuál es la lección principal que Elena aprendió de su viaje?","options":["Que Perú es el mejor lugar para ir de vacaciones.","Que siempre es mejor viajar con un guía profesional.","Que viajar implica respetar diversas formas de vida.","Que la tecnología es esencial para disfrutar de la naturaleza."],"answer_index":2,"explanation_pt_br":"A lição central é o valor de respeitar outras formas de vida e valorizar a simplicidade."}]'::jsonb, 2),
('es-passage-b1-03', 'es', 'B1', 'La comunicación en el entorno laboral', 'En el mundo profesional actual, la capacidad de comunicarse de manera clara y efectiva es una habilidad valorada por encima de muchas otras competencias técnicas. Las empresas buscan empleados que no solo sepan realizar sus tareas, sino que también puedan expresar sus ideas, negociar soluciones y colaborar con equipos diversos sin generar conflictos innecesarios. La comunicación asertiva se ha convertido en el pilar fundamental del éxito laboral.

Un problema común en muchas oficinas es la falta de claridad en las instrucciones. Cuando un jefe asigna una tarea sin especificar los objetivos o los plazos, es probable que surjan malentendidos que afecten la productividad general. Por ello, fomentar una cultura donde preguntar sea visto como un signo de interés y profesionalismo, en lugar de una falta de conocimiento, es vital para el crecimiento de cualquier organización.

La era digital ha transformado nuestra forma de trabajar. Las videollamadas y el correo electrónico permiten trabajar desde cualquier lugar del mundo, pero también han eliminado parte del lenguaje no verbal que es esencial para entender las intenciones de los demás. Un mensaje escrito puede interpretarse de muchas formas, por lo que es necesario practicar la empatía al redactar correos, asegurándose de que el tono sea siempre respetuoso y profesional.

Además de la comunicación externa, es crucial prestar atención a la escucha activa. Escuchar no significa simplemente esperar el turno para hablar, sino procesar la información del interlocutor, validar sus sentimientos y responder de manera coherente. Quienes dominan el arte de escuchar suelen ser los mejores líderes, ya que logran que sus compañeros se sientan valorados y escuchados en todo momento dentro del entorno de trabajo.

En conclusión, mejorar la comunicación es un proceso continuo. Requiere paciencia, autocrítica y la disposición constante de aprender nuevas formas de transmitir mensajes. Aquellos profesionales que invierten tiempo en desarrollar estas habilidades interpersonales no solo mejoran su clima laboral, sino que también abren puertas a nuevas oportunidades de carrera, demostrando que hablar bien es, en definitiva, trabajar mejor.', '[{"prompt":"¿Qué habilidad es considerada fundamental en el mundo profesional actual?","options":["Tener muchas competencias técnicas.","Saber comunicarse de forma clara y efectiva.","Trabajar solo sin necesidad de hablar con nadie.","Tener la capacidad de trabajar durante muchas horas."],"answer_index":1,"explanation_pt_br":"O texto destaca que a capacidade de se comunicar é valorizada acima de muitas competências técnicas."},{"prompt":"¿Por qué es importante preguntar sobre las tareas según el texto?","options":["Porque demuestra que no hemos leído las instrucciones.","Porque es un signo de interés y profesionalismo.","Porque así evitamos trabajar más de lo necesario.","Porque los jefes se sienten importantes cuando preguntamos."],"answer_index":1,"explanation_pt_br":"O texto menciona que perguntar é visto como sinal de interesse e profissionalismo, evitando mal-entendidos."},{"prompt":"¿Cuál es un desafío negativo de la comunicación digital?","options":["Que es demasiado lenta para el trabajo actual.","Que no permite trabajar desde casa.","La pérdida de lenguaje no verbal en la interacción.","La obligación de usar siempre videollamadas."],"answer_index":2,"explanation_pt_br":"O texto explica que a comunicação digital elimina parte da linguagem não verbal, essencial para entender intenções."},{"prompt":"¿Qué significa ''escucha activa'' según el texto?","options":["Hablar constantemente para demostrar que estamos presentes.","Procesar la información y validar al interlocutor.","Estar de acuerdo con todo lo que dice el jefe.","Tomar notas rápidas mientras la otra persona habla."],"answer_index":1,"explanation_pt_br":"A escuta ativa envolve processar a informação e validar os sentimentos do outro, não apenas esperar a vez de falar."},{"prompt":"¿Cuál es la idea central de este artículo?","options":["La tecnología ha arruinado las relaciones laborales.","La importancia de las habilidades interpersonales para el éxito profesional.","Que trabajar desde casa es mejor que trabajar en la oficina.","Que los jefes deben hablar menos y escuchar más."],"answer_index":1,"explanation_pt_br":"O texto argumenta que a comunicação é o pilar do sucesso e que investir nisso abre portas na carreira."}]'::jsonb, 3),
('es-passage-b1-04', 'es', 'B1', 'La importancia del bienestar integral', 'En la sociedad actual, solemos confundir estar sanos con la simple ausencia de enfermedades. Sin embargo, el bienestar integral abarca mucho más que la salud física; incluye también el equilibrio emocional, mental y social. Muchas personas viven inmersas en un ritmo frenético, descuidando señales importantes que su cuerpo les envía, lo cual puede derivar en problemas de salud a largo plazo si no se toman medidas a tiempo.

El sueño es uno de los pilares básicos que más se pasan por alto. Durante el descanso, el cerebro procesa las experiencias del día y el cuerpo se repara. Dormir menos de las horas recomendadas no solo afecta nuestra concentración y humor, sino que también debilita nuestro sistema inmunológico. Establecer un horario regular para ir a dormir es un hábito sencillo que puede mejorar drásticamente nuestra calidad de vida cotidiana.

La alimentación también juega un papel crucial en cómo nos sentimos día a día. Consumir alimentos frescos y naturales nos proporciona la energía necesaria para enfrentar los retos diarios. Sin embargo, muchas veces optamos por comida rápida debido a la falta de tiempo. Priorizar opciones nutritivas no tiene que ser complicado; pequeños cambios en la despensa pueden marcar una gran diferencia en nuestros niveles de energía y claridad mental.

Otro aspecto vital es la gestión del estrés. En un mundo hiperconectado, es fácil sentirse abrumado por las notificaciones constantes y las expectativas sociales. Practicar actividades como la meditación, el ejercicio físico o simplemente dedicar tiempo a un pasatiempo ayuda a reducir los niveles de cortisol. Estas pausas no son una pérdida de tiempo, sino una inversión necesaria para mantener la salud mental bajo control.

Cuidar de uno mismo es un acto de responsabilidad. No podemos dar lo mejor de nosotros en el trabajo o con nuestra familia si no nos sentimos bien. Al adoptar hábitos saludables, no solo prevenimos enfermedades, sino que también disfrutamos más de cada momento. La salud es, en última instancia, la base sobre la cual construimos todos nuestros proyectos y sueños en la vida.', '[{"prompt":"¿Cómo define el autor el bienestar integral?","options":["Como la capacidad de no enfermarse nunca.","Como un equilibrio entre salud física, mental y social.","Como tener mucho dinero para pagar médicos.","Como hacer ejercicio todos los días sin falta."],"answer_index":1,"explanation_pt_br":"O texto define o bem-estar como algo que vai além da saúde física, incluindo aspectos emocionais e sociais."},{"prompt":"¿Qué consecuencia negativa tiene dormir poco según el texto?","options":["Aumento del apetito por comida rápida.","Debilitamiento del sistema inmunológico.","Necesidad de dormir más durante el día.","Mejora de la concentración en el trabajo."],"answer_index":1,"explanation_pt_br":"O texto menciona explicitamente que dormir pouco debilita o sistema imunológico."},{"prompt":"¿Qué sugiere el autor sobre la alimentación?","options":["Que debemos comer solo comida preparada en casa.","Que los alimentos frescos son difíciles de conseguir.","Que pequeños cambios en la dieta pueden mejorar la energía.","Que la comida rápida es necesaria cuando no hay tiempo."],"answer_index":2,"explanation_pt_br":"O autor sugere que pequenas mudanças na despensa podem fazer grande diferença na energia e clareza mental."},{"prompt":"¿Qué significa la frase ''gestión del estrés'' en el cuarto párrafo?","options":["Eliminar el trabajo por completo.","Controlar y reducir los niveles de tensión.","Ignorar los problemas para estar tranquilo.","Comprar medicamentos para dormir mejor."],"answer_index":1,"explanation_pt_br":"Gerir o estresse refere-se a práticas como meditação e exercícios para reduzir a tensão."},{"prompt":"¿Cuál es el mensaje principal del texto?","options":["Que trabajar es lo más importante para la salud.","Que debemos priorizar nuestra salud para vivir mejor.","Que es imposible estar sano en la sociedad actual.","Que la tecnología es la única causa del estrés."],"answer_index":1,"explanation_pt_br":"A mensagem central é que cuidar de si mesmo é uma responsabilidade e base para todos os projetos de vida."}]'::jsonb, 4),
('es-passage-b1-05', 'es', 'B1', 'La cocina como lenguaje comunitario', 'La comida es mucho más que una necesidad biológica; es un lenguaje que conecta a las personas, cuenta historias y preserva tradiciones. En casi todas las culturas, las recetas familiares se transmiten de padres a hijos, actuando como un hilo invisible que une a las generaciones. Cuando cocinamos un plato tradicional, no solo estamos alimentando el cuerpo, sino que también estamos honrando nuestra historia y cultura.

En muchas comunidades, los mercados locales son el corazón de la vida social. Allí, los vecinos no solo compran ingredientes frescos, sino que intercambian consejos, comparten noticias y fortalecen los lazos de amistad. Estos espacios permiten que la comunidad se mantenga unida, creando un sentido de pertenencia que a menudo se pierde en las grandes ciudades. Comprar localmente es una forma de apoyar a los pequeños productores y al medio ambiente.

La globalización ha traído consigo una enorme variedad de sabores a nuestras mesas. Hoy en día, podemos disfrutar de ingredientes de cualquier parte del mundo en nuestra cocina cotidiana. Esta mezcla cultural es enriquecedora, ya que nos permite experimentar nuevas sensaciones y aprender sobre otros países a través de sus fogones. Sin embargo, es vital no perder la esencia de nuestra propia gastronomía en este proceso de intercambio.

Cocinar para otros es también una de las formas más puras de generosidad. Cuando organizamos una comida para amigos o familiares, estamos creando un espacio seguro para la conversación y el disfrute. La mesa se convierte en un lugar donde los problemas parecen más pequeños y las relaciones se fortalecen. Es en estos momentos compartidos donde realmente construimos comunidad y nos sentimos parte de algo más grande.

Al final del día, la gastronomía refleja quiénes somos y cómo nos relacionamos con los demás. Mantener vivas nuestras tradiciones culinarias mientras estamos abiertos a nuevas influencias es un equilibrio necesario. La próxima vez que prepares una receta especial, recuerda que no solo estás cocinando ingredientes, sino que estás participando en una tradición milenaria que celebra la vida, la familia y la unión entre las personas.', '[{"prompt":"¿Por qué el autor afirma que la comida es un ''lenguaje''?","options":["Porque se necesita hablar mucho al cocinar.","Porque conecta personas, cuenta historias y preserva tradiciones.","Porque se escribe en libros de recetas.","Porque es necesario aprender idiomas para cocinar."],"answer_index":1,"explanation_pt_br":"O texto explica que a comida conecta pessoas e preserva tradições, funcionando como uma forma de comunicação cultural."},{"prompt":"¿Qué función cumplen los mercados locales en la comunidad?","options":["Son lugares donde solo se venden productos caros.","Son el centro de la vida social y fortalecen la amistad.","Son lugares donde la gente prefiere no hablar con nadie.","Son solo para turistas que visitan la ciudad."],"answer_index":1,"explanation_pt_br":"Os mercados são descritos como o coração da vida social, onde vizinhos trocam conselhos e fortalecem laços."},{"prompt":"¿Qué opina el autor sobre la influencia de la globalización en la cocina?","options":["Que es algo negativo que debemos evitar.","Que es una forma de olvidar nuestras raíces.","Que es enriquecedora pero debemos mantener nuestra esencia.","Que es la única forma de comer saludable hoy en día."],"answer_index":2,"explanation_pt_br":"O autor vê a mistura como enriquecedora, mas enfatiza a importância de não perder a essência da gastronomia própria."},{"prompt":"¿Qué significa ''fogones'' en el tercer párrafo?","options":["El lugar donde se cocina o los aparatos de cocina.","Una forma de referirse a los restaurantes caros.","El nombre de un tipo de comida muy picante.","El fuego que se usa para calentar la casa."],"answer_index":0,"explanation_pt_br":"Fogones refere-se ao local onde se cozinha (o fogão) ou, figurativamente, à culinária de um lugar."},{"prompt":"¿Cuál es el propósito principal del texto?","options":["Enseñar a cocinar platos tradicionales.","Destacar la importancia social y cultural de la gastronomía.","Convencer a los lectores de dejar de comprar en supermercados.","Explicar la historia de los mercados mundiales."],"answer_index":1,"explanation_pt_br":"O texto busca refletir sobre como a culinária é uma ferramenta de união, tradição e identidade comunitária."}]'::jsonb, 5),
('es-passage-b1-06', 'es', 'B1', 'La vida conectada: ¿Progreso o distracción?', 'En la última década, la tecnología ha dejado de ser una herramienta de trabajo para convertirse en una extensión de nuestra vida cotidiana. Desde que despertamos, el teléfono móvil nos dicta el ritmo de la jornada, consultando el clima, las noticias y los mensajes pendientes. Esta hiperconectividad ha transformado profundamente la manera en que interactuamos con nuestro entorno inmediato.

Para muchos, el mayor beneficio es la eficiencia en tareas domésticas. Aplicaciones que controlan la iluminación, la seguridad del hogar o las compras de supermercado permiten ahorrar un tiempo valioso. Sin embargo, esta comodidad tiene un precio invisible: la dependencia constante de las pantallas. La sensación de estar siempre disponible genera una fatiga mental que pocos logran ignorar al final del día.

El ámbito laboral también ha experimentado una metamorfosis radical. El trabajo remoto, facilitado por plataformas de videoconferencia, rompió las barreras geográficas. Si bien esto ofrece mayor flexibilidad para equilibrar la vida personal, también ha difuminado los límites entre el tiempo de descanso y el horario de oficina, provocando que muchos trabajadores se sientan conectados las veinticuatro horas.

Otro aspecto relevante es la socialización digital. Aunque podemos mantener contacto con seres queridos que viven lejos, la calidad de las interacciones cara a cara ha disminuido notablemente. A menudo, vemos grupos de amigos en un restaurante que, en lugar de conversar, dedican su tiempo a navegar por redes sociales, perdiendo la oportunidad de conectar verdaderamente con quienes los rodean.

En conclusión, el impacto de la tecnología depende de cómo decidamos integrarla. No se trata de rechazar los avances, sino de establecer límites saludables que protejan nuestro bienestar emocional. La tecnología debe servirnos como un medio para mejorar nuestra calidad de vida, y no convertirse en el fin último que dirija nuestras decisiones y nuestro tiempo libre.', '[{"prompt":"¿Cuál es la idea principal del texto?","options":["La tecnología es perjudicial y debemos evitarla.","El trabajo remoto es la mejor invención tecnológica.","Debemos usar la tecnología con equilibrio y límites.","Las aplicaciones facilitan mucho la vida doméstica."],"answer_index":2,"explanation_pt_br":"O texto argumenta que a tecnologia é útil, mas que seu uso deve ser equilibrado para não prejudicar o bem-estar."},{"prompt":"Según el texto, ¿qué significa que la tecnología ha ''difuminado los límites''?","options":["Que ya no existen horarios definidos entre trabajo y vida personal.","Que las oficinas ya no tienen paredes físicas.","Que es más difícil usar aplicaciones de videoconferencia.","Que los trabajadores tienen menos tiempo para descansar."],"answer_index":0,"explanation_pt_br":"A expressão indica que as fronteiras entre o tempo de trabalho e o tempo de descanso se tornaram imprecisas."},{"prompt":"¿Qué consecuencia negativa de la tecnología se menciona sobre la vida social?","options":["Es imposible comunicarse con amigos que viven lejos.","Las personas prefieren usar el móvil a conversar en persona.","Los restaurantes prohíben el uso de dispositivos digitales.","La gente ya no tiene amigos debido a las redes sociales."],"answer_index":1,"explanation_pt_br":"O autor aponta que as interações presenciais perderam qualidade porque as pessoas focam mais nas telas."},{"prompt":"¿Cómo describe el autor la relación actual con el teléfono móvil al despertar?","options":["Como algo opcional que revisamos cuando tenemos tiempo.","Como una herramienta que solo sirve para ver noticias.","Como un dispositivo que dicta el ritmo de nuestra jornada.","Como un elemento que causa problemas técnicos graves."],"answer_index":2,"explanation_pt_br":"O texto afirma explicitamente que o celular dita o ritmo da jornada desde o despertar."},{"prompt":"¿Qué se infiere sobre el trabajo remoto?","options":["Es una opción que todos los trabajadores rechazan.","Ofrece flexibilidad, pero puede dificultar la desconexión.","Elimina completamente la fatiga mental de los empleados.","Impide que las personas tengan una vida personal."],"answer_index":1,"explanation_pt_br":"O texto menciona que, embora ofereça flexibilidade, também torna mais difícil separar o tempo de trabalho do pessoal."}]'::jsonb, 6),
('es-passage-b1-07', 'es', 'B1', 'Hacia un futuro más sostenible', 'El cambio climático es, sin duda, el mayor desafío que enfrenta nuestra generación. La manera en que consumimos recursos naturales ha llevado al planeta a una situación crítica que exige cambios inmediatos. Ya no es suficiente con reciclar ocasionalmente; necesitamos transformar profundamente nuestros hábitos diarios para reducir nuestra huella ecológica en el entorno.

Uno de los pilares del cambio es el consumo consciente. Antes de realizar una compra, es fundamental preguntarse si realmente necesitamos el producto o si estamos siendo impulsados por la publicidad. Adoptar el minimalismo y priorizar la calidad sobre la cantidad ayuda a disminuir la acumulación de residuos y el desperdicio de materiales que terminan en los vertederos.

La movilidad urbana también juega un papel crucial en la sostenibilidad. El uso excesivo del automóvil privado es una de las principales fuentes de emisiones de carbono en las ciudades. Optar por el transporte público, la bicicleta o caminar no solo reduce la contaminación del aire, sino que también mejora nuestra salud física y reduce los niveles de estrés diario.

La alimentación es otro sector donde nuestras decisiones tienen un impacto directo. Reducir el consumo de carne y aumentar la ingesta de productos locales y de temporada es una estrategia poderosa. Al elegir alimentos cultivados cerca de casa, disminuimos la energía necesaria para el transporte y apoyamos la economía local, fortaleciendo la resiliencia de nuestra comunidad.

Finalmente, la educación ambiental debe ser constante. No podemos esperar que los gobiernos resuelvan todo mientras nosotros seguimos ignorando el impacto de nuestras acciones. Al adoptar pequeñas mejoras en nuestro estilo de vida, inspiramos a otros a hacer lo mismo, creando una red colectiva de responsabilidad que es esencial para garantizar un futuro habitable para todos.', '[{"prompt":"¿Qué propone el autor sobre el consumo?","options":["Comprar productos de lujo para que duren más.","Comprar solo lo necesario y priorizar la calidad.","Evitar comprar cualquier tipo de objeto nuevo.","Confiar totalmente en lo que dice la publicidad."],"answer_index":1,"explanation_pt_br":"O texto sugere questionar a necessidade da compra e priorizar a qualidade em vez da quantidade."},{"prompt":"¿Qué significa la expresión ''huella ecológica'' en el texto?","options":["El rastro que dejamos al caminar por la naturaleza.","La cantidad de basura que producimos en casa.","El impacto total de nuestras actividades en el medio ambiente.","El dinero que gastamos en productos sostenibles."],"answer_index":2,"explanation_pt_br":"Huella ecológica refere-se ao impacto ambiental causado pelas atividades humanas."},{"prompt":"¿Cuál es uno de los beneficios de consumir productos locales?","options":["Se gasta menos energía en transporte.","Son siempre más baratos que los importados.","Permite eliminar totalmente los vertederos.","Garantiza que el clima no cambie nunca más."],"answer_index":0,"explanation_pt_br":"O texto afirma que ao escolher alimentos locais diminui-se a energia gasta no transporte."},{"prompt":"¿Qué sugiere el autor sobre el uso del automóvil?","options":["Que es la forma más sana de transportarse.","Que debería ser prohibido en todas las ciudades.","Que es preferible usar alternativas como la bicicleta.","Que solo debe usarse para viajes muy largos."],"answer_index":2,"explanation_pt_br":"O texto aponta o uso do carro como fonte de emissões e sugere alternativas como a bicicleta ou transporte público."},{"prompt":"¿Cuál es el tono principal de este texto?","options":["Pesimista y desesperanzado.","Crítico y motivador.","Indiferente y neutral.","Científico y académico."],"answer_index":1,"explanation_pt_br":"O autor critica os hábitos atuais, mas incentiva o leitor a adotar mudanças positivas."}]'::jsonb, 7),
('es-passage-b1-08', 'es', 'B1', 'La evolución de las relaciones sociales', 'Las relaciones humanas han atravesado cambios significativos en las últimas décadas, influenciadas por la tecnología y un ritmo de vida acelerado. Antiguamente, la socialización ocurría principalmente en espacios físicos compartidos, como plazas, clubes o reuniones familiares. Hoy en día, muchas de estas interacciones han migrado al plano virtual, transformando nuestra percepción de la cercanía y la intimidad.

La amistad, por ejemplo, se ha vuelto más diversa pero quizás más superficial. Es común tener cientos de contactos en redes sociales, pero pocos amigos cercanos con quienes compartir momentos difíciles. La capacidad de mantener una conversación profunda parece estar compitiendo con la necesidad de gratificación instantánea que ofrecen las notificaciones constantes de nuestros dispositivos.

En el ámbito de la pareja, las aplicaciones de citas han modificado las reglas del juego. Conocer a alguien nuevo es más accesible que nunca, lo que genera una sensación de abundancia de opciones. Sin embargo, esta facilidad también puede derivar en una falta de compromiso, donde el miedo a perderse algo mejor impide consolidar vínculos estables y profundos.

A pesar de estos desafíos, la esencia de la conexión humana permanece intacta. La necesidad de pertenecer, de ser comprendidos y de apoyar a otros sigue siendo el motor de nuestras vidas. La diferencia radica en cómo gestionamos estas necesidades; la clave parece estar en encontrar un equilibrio entre el mundo digital y los encuentros reales.

Para fortalecer los vínculos, es necesario invertir tiempo y paciencia. Escuchar activamente, mostrar empatía y estar presente físicamente son acciones que no pueden ser reemplazadas por un mensaje de texto. En última instancia, la calidad de nuestras relaciones depende del esfuerzo consciente que dedicamos a cuidar a las personas que realmente importan en nuestro día a día.', '[{"prompt":"¿Qué cambio ha ocurrido en la socialización según el texto?","options":["Ya no nos reunimos en espacios físicos.","Las interacciones se han trasladado al entorno virtual.","Es más difícil conocer personas nuevas hoy en día.","Las familias ya no se comunican entre sí."],"answer_index":1,"explanation_pt_br":"O texto explica que grande parte da socialização migrou para o ambiente virtual."},{"prompt":"¿Qué efecto tienen las aplicaciones de citas según el autor?","options":["Garantizan el éxito en todas las relaciones.","Hacen que sea imposible conocer a alguien.","Generan opciones, pero pueden dificultar el compromiso.","Obligan a las personas a ser más superficiales."],"answer_index":2,"explanation_pt_br":"O texto menciona que as apps trazem abundância, mas podem causar medo de compromisso."},{"prompt":"En el contexto del texto, ¿qué significa ''gratificación instantánea''?","options":["La alegría de ver a un amigo en persona.","La satisfacción rápida y breve que dan las notificaciones.","El tiempo que dedicamos a estudiar profundamente.","La recompensa de un trabajo bien hecho."],"answer_index":1,"explanation_pt_br":"Refere-se ao prazer rápido obtido através de notificações no celular."},{"prompt":"¿Cuál es la recomendación del autor para mejorar las relaciones?","options":["Usar más redes sociales para comunicarse.","Dedicar tiempo, paciencia y presencia física.","Tener muchos amigos para no sentirse solo.","Evitar las conversaciones profundas."],"answer_index":1,"explanation_pt_br":"O autor enfatiza que ações como ouvir ativamente e estar presente são indispensáveis."},{"prompt":"¿Qué opina el autor sobre la esencia de la conexión humana?","options":["Ha desaparecido por culpa de la tecnología.","Es más fuerte gracias a las aplicaciones.","Sigue siendo la misma, aunque cambien los medios.","Es menos importante que antes."],"answer_index":2,"explanation_pt_br":"O autor afirma que a necessidade de pertencer e de apoio continua a mesma, apesar das mudanças tecnológicas."}]'::jsonb, 8),
('es-passage-b1-09', 'es', 'B1', 'Finanzas personales: el arte de administrar', 'Administrar el dinero es una habilidad esencial que, lamentablemente, no siempre se enseña en las escuelas. Muchas personas viven al día, gastando todo lo que ganan sin considerar el futuro. Sin embargo, tener control sobre nuestras finanzas personales es el primer paso hacia una vida con menos estrés y más posibilidades de alcanzar nuestras metas personales.

El primer paso para una salud financiera sólida es el presupuesto. Anotar cada gasto, por pequeño que sea, permite identificar fugas de dinero innecesarias. Es común descubrir que pequeñas compras impulsivas, como cafés diarios o suscripciones que apenas usamos, suman cantidades significativas al final del mes. La disciplina es el factor determinante aquí.

El ahorro debe ser visto como una prioridad y no como lo que sobra al final del mes. Una técnica efectiva es separar una parte del salario apenas recibimos el pago. Este fondo de emergencia es vital para enfrentar imprevistos, como reparaciones del hogar o gastos médicos, evitando así recurrir al uso de tarjetas de crédito con intereses elevados.

El consumo inteligente también implica entender cómo funcionan las deudas. A menudo, las cuotas parecen inofensivas, pero acumuladas pueden asfixiar nuestro presupuesto. Es fundamental evitar financiar bienes de consumo que pierden valor rápidamente. Si no puedes pagar algo al contado, quizás sea necesario esperar y ahorrar antes de realizar la compra.

En conclusión, la libertad financiera no significa ser rico, sino tener tranquilidad y opciones. Al tomar decisiones conscientes y planificar, dejamos de ser esclavos de los números y empezamos a usar el dinero a nuestro favor. La educación financiera es un proceso continuo que beneficia tanto a individuos como a familias, proporcionando estabilidad en un mundo económico incierto.', '[{"prompt":"¿Cuál es la recomendación sobre el ahorro?","options":["Ahorrar solo si sobra dinero al final del mes.","Ahorrar una parte apenas se recibe el ingreso.","No ahorrar para poder disfrutar del dinero hoy.","Ahorrar solo cuando hay una emergencia real."],"answer_index":1,"explanation_pt_br":"O texto sugere tratar a poupança como prioridade, separando o valor assim que se recebe o salário."},{"prompt":"¿Por qué el autor sugiere anotar cada gasto?","options":["Para impresionar al banco.","Para evitar pagar impuestos.","Para identificar gastos innecesarios.","Para saber cuánto dinero ganan nuestros amigos."],"answer_index":2,"explanation_pt_br":"O registro ajuda a identificar gastos supérfluos que passam despercebidos."},{"prompt":"¿Qué opina el autor sobre las cuotas?","options":["Son siempre la mejor opción para comprar.","Deben usarse para cualquier tipo de compra.","Pueden acumularse y afectar negativamente el presupuesto.","Son inofensivas y no afectan la economía personal."],"answer_index":2,"explanation_pt_br":"O autor alerta que as parcelas podem se acumular e sufocar o orçamento."},{"prompt":"¿Qué significa ''vivir al día'' en el texto?","options":["Gastar todo el dinero sin planificar el futuro.","Vivir cada momento con mucha alegría.","Ahorrar diariamente una parte del sueldo.","Trabajar muchas horas cada día."],"answer_index":0,"explanation_pt_br":"Viver ''al día'' significa gastar tudo o que se ganha sem reservas para o futuro."},{"prompt":"¿Qué es la libertad financiera según el autor?","options":["Tener una cantidad infinita de dinero.","Tener tranquilidad y opciones gracias a la planificación.","Dejar de trabajar para siempre.","Poder comprar todo lo que vemos en internet."],"answer_index":1,"explanation_pt_br":"O autor define liberdade financeira como ter paz e opções através de boas decisões."}]'::jsonb, 9),
('es-passage-b1-10', 'es', 'B1', 'La educación a lo largo de la vida', 'Durante mucho tiempo, se pensó que la educación terminaba al obtener un título universitario. Sin embargo, en el siglo veintiuno, esta idea ha quedado obsoleta. El mercado laboral cambia con tanta rapidez que los conocimientos adquiridos hace diez años pueden ser insuficientes hoy. Por ello, el aprendizaje continuo se ha convertido en una necesidad para el desarrollo profesional.

La educación no se limita a cursos formales en instituciones académicas. Hoy en día, tenemos acceso a una cantidad inmensa de información a través de plataformas en línea, seminarios, podcasts y libros. Esta democratización del conocimiento permite que cualquier persona, sin importar su ubicación geográfica, pueda aprender una nueva habilidad o profundizar en un tema de interés.

El mayor beneficio de seguir aprendiendo es la flexibilidad mental. Adaptarse a nuevos programas informáticos, aprender un idioma extranjero o entender nuevas metodologías de gestión nos mantiene activos y competitivos. Además, el hábito de aprender fomenta la curiosidad, lo cual mejora nuestra capacidad para resolver problemas complejos tanto en la vida laboral como en la personal.

Sin embargo, aprender requiere tiempo y, sobre todo, autodisciplina. Muchos abandonan sus objetivos por falta de organización o porque se sienten abrumados por la cantidad de opciones disponibles. Establecer metas claras y dedicar momentos específicos de la semana al estudio es fundamental para convertir el aprendizaje en una rutina sostenible y gratificante.

En definitiva, nunca es tarde para empezar algo nuevo. Ya sea por motivos profesionales o por puro placer intelectual, el aprendizaje constante enriquece nuestra visión del mundo. Quien decide seguir formándose a lo largo de la vida no solo mejora sus perspectivas de futuro, sino que también mantiene su mente abierta ante los cambios constantes de nuestra sociedad.', '[{"prompt":"¿Por qué el autor dice que la idea de que la educación termina tras la universidad es obsoleta?","options":["Porque ahora es obligatorio estudiar hasta los 60 años.","Porque el mercado cambia rápido y requiere actualización.","Porque los títulos universitarios ya no valen nada.","Porque es más fácil estudiar en línea que presencialmente."],"answer_index":1,"explanation_pt_br":"O texto justifica que as mudanças rápidas no mercado exigem atualização contínua."},{"prompt":"¿Qué significa ''democratización del conocimiento'' en el texto?","options":["Que solo los políticos tienen acceso a la información.","Que la educación es gratuita en todo el mundo.","Que el acceso a la información es más fácil para todos.","Que las universidades ahora son lugares públicos."],"answer_index":2,"explanation_pt_br":"Refere-se à facilidade de acesso à informação e aprendizado para qualquer pessoa."},{"prompt":"¿Qué obstáculo menciona el autor para quienes desean aprender?","options":["La falta de interés de las nuevas generaciones.","El alto costo de todos los libros en el mercado.","La falta de tiempo y la dificultad para organizarse.","La imposibilidad de encontrar cursos en línea."],"answer_index":2,"explanation_pt_br":"O autor cita a falta de organização e o tempo como principais barreiras."},{"prompt":"¿Qué beneficio de aprender se destaca en el tercer párrafo?","options":["La capacidad de ganar más dinero inmediatamente.","La flexibilidad mental y la resolución de problemas.","La posibilidad de viajar a otros países.","La mejora en la calidad de las relaciones sociales."],"answer_index":1,"explanation_pt_br":"O texto menciona que o aprendizado constante melhora a flexibilidade mental e a resolução de problemas."},{"prompt":"¿Cuál es la conclusión principal sobre el aprendizaje?","options":["Es una tarea difícil que solo deben hacer los jóvenes.","Es un proceso enriquecedor que debe durar toda la vida.","Es una pérdida de tiempo si no se obtiene un diploma.","Es algo que solo sirve para mejorar el currículum."],"answer_index":1,"explanation_pt_br":"O autor conclui que o aprendizado contínuo enriquece a visão de mundo e deve ser um processo vitalício."}]'::jsonb, 10),
('es-passage-b2-01', 'es', 'B2', 'La autonomía como pilar de la vida moderna', 'La vida contemporánea exige una capacidad de adaptación constante, donde la gestión del tiempo se convierte en el mayor desafío para el individuo independiente. A menudo, nos despertamos con una lista de tareas que parece interminable, tratando de equilibrar las responsabilidades domésticas con las ambiciones personales. Esta rutina no es simplemente una sucesión de actos mecánicos, sino una estructura que sostiene nuestra identidad frente al caos del entorno urbano.

Para muchos, el día comienza antes de la salida del sol, aprovechando el silencio matutino para organizar las prioridades. Este momento de introspección es crucial, pues permite establecer el tono de las horas venideras y reducir la ansiedad que genera la incertidumbre. Sin embargo, la verdadera independencia radica en la habilidad de mantener este orden incluso cuando los imprevistos amenazan con desmoronar nuestra planificación meticulosamente diseñada.

El teletrabajo ha transformado radicalmente nuestra relación con el hogar, difuminando las fronteras entre el espacio de descanso y el lugar de producción profesional. Antes, el trayecto al trabajo servía como un umbral psicológico; hoy, ese ritual ha desaparecido, obligándonos a crear nuevas fronteras simbólicas para no sucumbir al agotamiento. La disciplina necesaria para cerrar la computadora a una hora fija es, actualmente, una forma de autocuidado indispensable.

La independencia también se manifiesta en la capacidad de tomar decisiones conscientes sobre nuestra alimentación y actividad física. No se trata solo de cumplir con una dieta, sino de reconocer qué necesidades biológicas demanda nuestro cuerpo tras una jornada intensa. Elegir cocinar en casa, en lugar de recurrir a la comida rápida, es un acto de soberanía personal que refuerza nuestro compromiso con un estilo de vida sostenible y saludable.

Por otro lado, la interacción social durante el tiempo libre suele verse afectada por la fatiga acumulada. A pesar de ello, la conexión con los demás es el contrapeso necesario para evitar el aislamiento. Es vital aprender a decir no a compromisos que nos agotan, priorizando encuentros que realmente aporten valor a nuestra salud mental. Esta selección de actividades refleja un nivel de madurez que define nuestra calidad de vida en la edad adulta.

Finalmente, la verdadera libertad consiste en integrar todas estas facetas sin sentir que estamos perdiendo el control. La rutina no debe ser una cárcel, sino una herramienta flexible que nos permita evolucionar. Al dominar nuestro día a día con consciencia, no solo ganamos tiempo, sino que construimos una existencia más auténtica, donde cada elección es un reflejo de nuestros valores y metas personales a largo plazo.', '[{"prompt":"¿Cuál es la idea principal del texto respecto a la rutina?","options":["La rutina es un conjunto de actos mecánicos sin significado.","La rutina es una herramienta flexible para construir una vida auténtica.","La rutina es la principal causa de ansiedad en la vida urbana.","La rutina debe ser estrictamente rígida para lograr independencia."],"answer_index":1,"explanation_pt_br":"O texto argumenta que a rotina, quando bem gerida, serve como base para a autonomia e a identidade."},{"prompt":"Según el autor, ¿qué ha provocado el teletrabajo?","options":["Un aumento en la productividad laboral global.","La eliminación necesaria de los rituales matutinos.","La dificultad de separar el espacio laboral del personal.","Una mejora sustancial en la salud mental de los empleados."],"answer_index":2,"explanation_pt_br":"O texto menciona que o teletrabalho apagou as fronteiras entre descanso e trabalho, exigindo novas formas de autocuidado."},{"prompt":"¿Qué significa la expresión ''umbral psicológico'' en el contexto del trayecto al trabajo?","options":["Una barrera física que impide el acceso a la oficina.","Un periodo de transición mental entre el hogar y el trabajo.","El nivel máximo de estrés antes de llegar al empleo.","La puerta de entrada a un edificio corporativo."],"answer_index":1,"explanation_pt_br":"O termo refere-se ao tempo de deslocamento como um espaço mental de transição entre papéis sociais."},{"prompt":"¿Cómo se define la independencia en el cuarto párrafo?","options":["Como la capacidad de elegir conscientemente hábitos saludables.","Como el rechazo total a la comida rápida externa.","Como la obligación de seguir una dieta estricta.","Como el éxito profesional alcanzado mediante el teletrabajo."],"answer_index":0,"explanation_pt_br":"O texto define a independência como a capacidade de tomar decisões conscientes sobre bem-estar e alimentação."},{"prompt":"¿Qué papel juega la interacción social en la vida del adulto, según el texto?","options":["Es un obstáculo para la productividad diaria.","Es un factor que genera aislamiento innecesario.","Es un contrapeso esencial para la salud mental.","Es una actividad que debe evitarse por completo."],"answer_index":2,"explanation_pt_br":"O autor descreve a conexão social como um contrapeso necessário para evitar o isolamento."},{"prompt":"A partir del texto, se infiere que el autor considera el agotamiento como:","options":["Un resultado inevitable de cualquier tipo de empleo.","Algo que puede gestionarse estableciendo límites claros.","Un fenómeno causado exclusivamente por la falta de ejercicio.","Un indicador de que la persona no es independiente."],"answer_index":1,"explanation_pt_br":"O texto sugere que o esgotamento pode ser mitigado ao estabelecer fronteiras e priorizar o autocuidado."},{"prompt":"¿Cuál es la actitud del autor frente a los imprevistos?","options":["Los considera una prueba de la fragilidad del plan.","Sugiere que deben evitarse a toda costa.","Los ve como una oportunidad para demostrar resiliencia.","Los describe como elementos que destruyen la rutina."],"answer_index":2,"explanation_pt_br":"O autor menciona a habilidade de manter a ordem mesmo quando imprevistos surgem, sugerindo resiliência."}]'::jsonb, 1),
('es-passage-b2-02', 'es', 'B2', 'Viajar más allá de los mapas turísticos', 'El acto de viajar ha experimentado una metamorfosis profunda en la última década. Ya no se trata simplemente de visitar monumentos icónicos o coleccionar fotografías en lugares masificados, sino de sumergirse en la esencia de las culturas ajenas. Este cambio de paradigma nos invita a cuestionar qué buscamos realmente al desplazarnos a miles de kilómetros de nuestra zona de confort: ¿evasión o aprendizaje?

La verdadera inmersión cultural comienza cuando decidimos alejarnos de las rutas convencionales sugeridas por las guías turísticas. Al perdernos en los barrios menos conocidos, descubrimos la cotidianidad de los habitantes locales, sus mercados de barrio y sus cafeterías silenciosas. Es en esos espacios donde el idioma, la gastronomía y las costumbres se entrelazan para ofrecer una visión mucho más honesta de la realidad nacional.

Sin embargo, este tipo de turismo requiere una dosis considerable de humildad y respeto. No somos observadores pasivos, sino invitados en una tierra que tiene sus propias reglas y ritmos. La capacidad de observar sin juzgar es fundamental para evitar caer en estereotipos que a menudo nublan nuestra capacidad de comprensión. Aceptar que nuestra forma de ver el mundo es solo una entre muchas es el primer paso para un intercambio significativo.

La tecnología juega un papel ambivalente en nuestras expediciones actuales. Por un lado, nos permite conectar con servicios locales y acceder a información histórica valiosa con un simple clic. Por otro lado, la obsesión por documentar cada instante en redes sociales puede distanciarnos del momento presente. Aprender a guardar el teléfono y observar con los ojos, en lugar de a través de una lente, es una lección de presencia necesaria.

La sostenibilidad es otro pilar fundamental del viajero consciente del siglo XXI. El impacto ambiental y social de nuestras visitas no debe ser ignorado. Elegir transportes menos contaminantes, apoyar el comercio local y respetar el patrimonio cultural son acciones que definen la calidad de nuestra huella como visitantes. Cada decisión cuenta para preservar los destinos para las generaciones futuras, evitando la mercantilización excesiva de la cultura.

En conclusión, viajar no es solo una actividad de ocio, sino un ejercicio de empatía global. Al regresar a casa, lo que realmente permanece no son los recuerdos materiales, sino las transformaciones internas que hemos experimentado al enfrentarnos a lo desconocido. Viajar, en su sentido más amplio, nos hace más tolerantes, más curiosos y, sobre todo, más conscientes de nuestra posición en este vasto y complejo tejido humano.', '[{"prompt":"¿Cuál es el cambio principal en la forma de viajar hoy en día?","options":["El aumento en la cantidad de fotografías tomadas en monumentos.","La preferencia por destinos que no aparecen en las guías.","La transición de la simple visita a la inmersión cultural.","El uso masivo de aplicaciones para encontrar hoteles baratos."],"answer_index":2,"explanation_pt_br":"O texto enfatiza que o foco mudou da visita a monumentos para a experiência imersiva na cultura local."},{"prompt":"¿Qué se requiere para una verdadera inmersión, según el tercer párrafo?","options":["Un dominio perfecto del idioma local.","Evitar cualquier contacto con los residentes locales.","Seguir estrictamente las rutas marcadas en los mapas.","Humildad, respeto y la capacidad de no juzgar."],"answer_index":3,"explanation_pt_br":"O texto afirma explicitamente que a humildade e o respeito são fundamentais para evitar estereótipos."},{"prompt":"El autor describe la tecnología como ''ambivalente'' porque:","options":["Es costosa y difícil de usar durante los viajes.","Facilita el acceso a información pero puede distraer del presente.","Solo sirve para publicar fotos y no aporta conocimiento.","Funciona mal en lugares fuera de las rutas convencionales."],"answer_index":1,"explanation_pt_br":"O autor explica que a tecnologia ajuda na logística, mas pode impedir que o viajante viva o momento."},{"prompt":"¿Qué implica la ''sostenibilidad'' para un viajero consciente?","options":["Viajar exclusivamente a lugares que no tengan turismo.","Minimizar el impacto ambiental y apoyar la economía local.","Gastar la mayor cantidad de dinero posible en el destino.","Evitar cualquier tipo de transporte que utilice combustible."],"answer_index":1,"explanation_pt_br":"O texto define a sustentabilidade através do respeito ao patrimônio, apoio ao comércio e cuidado ambiental."},{"prompt":"¿Qué quiere decir el autor con ''mercantilización excesiva de la cultura''?","options":["Vender productos artesanales a precios muy altos.","Transformar las tradiciones en simples productos de consumo.","La falta de interés por parte de los turistas en la cultura.","El exceso de impuestos aplicados a los visitantes extranjeros."],"answer_index":1,"explanation_pt_br":"Refere-se ao processo onde a cultura é esvaziada de seu significado real para ser vendida como mercadoria."},{"prompt":"Según el texto, ¿cuál es el resultado final de viajar de manera consciente?","options":["La acumulación de recuerdos materiales inolvidables.","Una transformación personal que genera mayor empatía.","La capacidad de enseñar a otros cómo deben viajar.","El reconocimiento social por ser un viajero diferente."],"answer_index":1,"explanation_pt_br":"O autor conclui que a viagem gera transformações internas e maior empatia com o mundo."},{"prompt":"¿Qué actitud sugiere el autor hacia los estereotipos?","options":["Son herramientas útiles para entender una nueva cultura.","Deben ser evitados mediante la observación sin prejuicios.","Son inevitables y forman parte natural de cualquier viaje.","Se eliminan automáticamente al usar tecnología de traducción."],"answer_index":1,"explanation_pt_br":"O texto indica que observar sem julgar é a chave para não cair em estereótipos."}]'::jsonb, 2),
('es-passage-b2-03', 'es', 'B2', 'La comunicación efectiva en el ámbito profesional', 'En el entorno corporativo actual, la capacidad de comunicarse con claridad no es un lujo, sino una competencia técnica esencial. A medida que las organizaciones se vuelven más planas y colaborativas, los silos de información se desmoronan, exigiendo que cada empleado sea capaz de transmitir ideas complejas de forma concisa. La eficacia comunicativa es, en última instancia, el motor que impulsa la ejecución de los proyectos y la resolución de conflictos internos.

La asertividad se erige como el equilibrio perfecto entre la pasividad y la agresividad. Ser asertivo significa defender nuestras ideas con firmeza, pero manteniendo siempre un respeto absoluto por las opiniones ajenas. Este estilo de comunicación fomenta un clima de confianza en el que el debate constructivo es posible, permitiendo que el equipo explore diferentes perspectivas antes de tomar una decisión estratégica que afecte a toda la compañía.

La escucha activa es, paradójicamente, la parte más olvidada de la comunicación profesional. Muchos profesionales se enfocan únicamente en preparar su respuesta en lugar de procesar lo que su interlocutor está expresando. Escuchar activamente implica prestar atención no solo al contenido verbal, sino también a las señales no verbales y al contexto emocional del mensaje. Solo al comprender realmente la intención del otro podemos construir acuerdos sólidos.

La comunicación digital presenta retos particulares. El correo electrónico y las plataformas de mensajería instantánea carecen de los matices del lenguaje corporal y la entonación, lo que suele derivar en malentendidos evitables. Es crucial desarrollar una etiqueta digital que priorice la claridad y el tono profesional. La brevedad no debe confundirse con la brusquedad; un mensaje bien estructurado ahorra tiempo y minimiza la necesidad de aclaraciones posteriores.

La retroalimentación, o feedback, es una herramienta poderosa que a menudo se gestiona de manera deficiente. Para que el feedback sea constructivo, debe centrarse en comportamientos específicos y resultados, evitando juicios de valor sobre la persona. Un profesional competente sabe que recibir críticas no es un ataque personal, sino una oportunidad de mejora y crecimiento. La cultura de la transparencia es lo que diferencia a los equipos mediocres de los de alto rendimiento.

Finalmente, la adaptabilidad comunicativa es la capacidad de ajustar nuestro mensaje según nuestra audiencia. No es lo mismo presentar un informe técnico ante un grupo de expertos que explicar la visión del proyecto a un cliente externo o a los accionistas. La versatilidad lingüística y la inteligencia emocional nos permiten conectar con diferentes grupos, garantizando que el mensaje no solo se escuche, sino que se comprenda y se interiorice con éxito.', '[{"prompt":"¿Por qué se considera la comunicación una ''competencia técnica esencial''?","options":["Porque permite que los empleados hablen menos y trabajen más.","Porque es fundamental para la ejecución de proyectos y resolución de problemas.","Porque las empresas modernas ya no utilizan correos electrónicos.","Porque evita que los empleados tengan que interactuar entre ellos."],"answer_index":1,"explanation_pt_br":"O texto descreve a comunicação como motor essencial para projetos e resolução de conflitos."},{"prompt":"¿Qué define la asertividad según el segundo párrafo?","options":["Imponer nuestras ideas por encima de las de los demás.","Evitar cualquier tipo de conflicto para mantener la calma.","Equilibrar la firmeza personal con el respeto a los demás.","Hablar siempre con agresividad para mostrar autoridad."],"answer_index":2,"explanation_pt_br":"O texto define a assertividade como o equilíbrio entre firmeza e respeito aos outros."},{"prompt":"¿Cuál es el error común en la ''escucha activa''?","options":["Prestar demasiada atención a la comunicación no verbal.","Centrarse en preparar la respuesta propia en lugar de escuchar.","Analizar demasiado el contexto emocional del interlocutor.","Hacer demasiadas preguntas durante la conversación."],"answer_index":1,"explanation_pt_br":"O autor aponta que muitos profissionais focam na resposta antes mesmo de terminarem de ouvir."},{"prompt":"¿Qué consejo da el autor respecto a la comunicación digital?","options":["Evitarla siempre que sea posible por los malentendidos.","Ser lo más breve posible, incluso si parece brusco.","Priorizar la claridad y el tono profesional para evitar errores.","Usar siempre emojis para compensar la falta de entonación."],"answer_index":2,"explanation_pt_br":"O texto sugere que se deve priorizar a clareza e o profissionalismo para compensar a falta de linguagem corporal."},{"prompt":"¿Cómo debe ser el feedback constructivo?","options":["Centrado en la personalidad del empleado para que cambie.","Basado en juicios generales sobre el desempeño pasado.","Enfocado en comportamientos específicos y resultados.","Entregado siempre de manera escrita para evitar discusiones."],"answer_index":2,"explanation_pt_br":"O texto afirma que o feedback deve focar em comportamentos e resultados, não na pessoa."},{"prompt":"¿Qué significa ''adaptabilidad comunicativa''?","options":["Cambiar nuestra opinión según lo que quiera el jefe.","Ajustar el mensaje y el tono a las distintas audiencias.","Aprender nuevos idiomas para hablar con clientes extranjeros.","Utilizar diferentes plataformas digitales cada semana."],"answer_index":1,"explanation_pt_br":"Refere-se à capacidade de ajustar a forma e o conteúdo da mensagem conforme o público-alvo."},{"prompt":"¿Cuál es la idea principal del texto?","options":["La comunicación profesional requiere habilidades sociales y técnicas.","El correo electrónico es el medio más ineficiente de comunicación.","La asertividad es la única forma de comunicación exitosa.","Las empresas planas son mejores que las empresas jerárquicas."],"answer_index":0,"explanation_pt_br":"O texto aborda a comunicação como um conjunto de habilidades necessárias para o sucesso no ambiente de trabalho."}]'::jsonb, 3),
('es-passage-b2-04', 'es', 'B2', 'Salud y bienestar: un enfoque integral', 'La salud no debe entenderse simplemente como la ausencia de enfermedad, sino como un estado de equilibrio dinámico entre el cuerpo, la mente y el entorno. En una sociedad obsesionada con la productividad rápida, a menudo descuidamos las señales que nuestro organismo nos envía. Reconocer estas alertas tempranas es el primer paso hacia una prevención efectiva, lo cual es fundamental para mantener nuestra calidad de vida a largo plazo.

El sueño reparador es, con diferencia, el componente más subestimado del bienestar. Durante las horas de descanso, el cerebro procesa la información del día y el cuerpo repara los tejidos dañados. La falta de sueño crónico no solo reduce la capacidad cognitiva, sino que debilita el sistema inmunológico, exponiéndonos a múltiples afecciones. Priorizar la higiene del sueño es una inversión directa en nuestra resiliencia física y mental.

La nutrición consciente va mucho más allá de contar calorías o seguir dietas restrictivas. Se trata de entender cómo los alimentos afectan nuestro estado de ánimo y niveles de energía. La industria alimentaria actual, cargada de productos ultraprocesados, nos desafía constantemente. Optar por alimentos naturales y procesar nuestra propia comida es un acto de resistencia que nos devuelve el control sobre nuestra salud metabólica.

La actividad física, más allá de la estética, es el mecanismo mediante el cual regulamos nuestro sistema nervioso. El ejercicio libera endorfinas y reduce los niveles de cortisol, la hormona del estrés. No es necesario realizar entrenamientos de alta intensidad todos los días; caminar a paso ligero, practicar yoga o realizar estiramientos puede ser suficiente para mejorar la circulación y reducir la tensión acumulada en el día a día.

La salud mental requiere una atención constante, especialmente en un mundo hiperconectado. La gestión de las emociones y la capacidad de establecer límites saludables son pilares fundamentales para evitar el síndrome de agotamiento. Practicar técnicas de atención plena o simplemente dedicar momentos al silencio puede ayudar a reducir la rumiación mental, permitiendo que nuestra mente descanse de la sobreestimulación constante a la que estamos sometidos.

En conclusión, el bienestar es un proceso continuo que requiere autoconocimiento y disciplina. No existen soluciones mágicas ni píldoras que sustituyan a los hábitos saludables. Al integrar pequeños cambios en nuestra rutina diaria, construimos una base sólida para afrontar los retos de la vida. La salud, en última instancia, es la libertad de vivir nuestra vida con plena capacidad y energía, siendo conscientes de nuestro potencial personal.', '[{"prompt":"¿Qué visión de la salud propone el autor al inicio del texto?","options":["La salud es simplemente no padecer ninguna enfermedad.","La salud es un equilibrio dinámico entre cuerpo, mente y entorno.","La salud depende exclusivamente de la genética y el azar.","La salud es un estado que se logra mediante la productividad."],"answer_index":1,"explanation_pt_br":"O texto define a saúde como um equilíbrio dinâmico entre vários aspectos da vida."},{"prompt":"¿Por qué es importante el sueño, según el segundo párrafo?","options":["Porque permite evitar el consumo de café durante el día.","Porque es el momento en que el cuerpo repara los tejidos.","Porque ayuda a memorizar datos para el trabajo profesional.","Porque es la única forma de descansar la vista de las pantallas."],"answer_index":1,"explanation_pt_br":"O texto explica que, durante o sono, o corpo repara tecidos e o cérebro processa informações."},{"prompt":"¿Qué se entiende por ''nutrición consciente''?","options":["Seguir estrictamente una dieta basada en el conteo de calorías.","Comer solo alimentos orgánicos sin importar el costo.","Comprender la relación entre alimentos, energía y estado de ánimo.","Eliminar por completo cualquier alimento procesado de la dieta."],"answer_index":2,"explanation_pt_br":"A nutrição consciente envolve entender como os alimentos impactam o humor e os níveis de energia."},{"prompt":"¿Cuál es la función del ejercicio físico según el cuarto párrafo?","options":["Mejorar únicamente la apariencia física y estética.","Regular el sistema nervioso mediante la reducción de cortisol.","Aumentar los niveles de estrés para ser más productivo.","Sustituir la necesidad de descanso mental y sueño."],"answer_index":1,"explanation_pt_br":"O autor explica que o exercício ajuda a regular o sistema nervoso reduzindo o cortisol."},{"prompt":"¿Qué recomienda el autor para la salud mental en un mundo hiperconectado?","options":["Desconectarse por completo de toda tecnología permanentemente.","Establecer límites y practicar momentos de silencio o atención plena.","Aumentar el uso de aplicaciones para monitorear las emociones.","Trabajar más horas para evitar pensar en preocupaciones."],"answer_index":1,"explanation_pt_br":"O texto sugere limites e a prática de atenção plena para lidar com a sobreestimulação."},{"prompt":"¿Cuál es la actitud del autor frente a las ''soluciones mágicas'' para la salud?","options":["Recomienda buscarlas si los hábitos fallan.","Las considera el futuro de la medicina preventiva.","Las rechaza, afirmando que solo los hábitos funcionan.","Sugiere que pueden ser útiles como complemento rápido."],"answer_index":2,"explanation_pt_br":"O autor deixa claro que não existem soluções mágicas e que a disciplina é o caminho."},{"prompt":"¿Qué significado tiene la palabra ''rumiación'' en el contexto del quinto párrafo?","options":["Comer de manera rápida y sin masticar bien.","Dar vueltas a los pensamientos de forma repetitiva.","La capacidad de aprender nuevos temas rápidamente.","El proceso de socializar con personas nuevas."],"answer_index":1,"explanation_pt_br":"Ruminar mentalmente refere-se a pensar obsessivamente sobre problemas ou preocupações."}]'::jsonb, 4),
('es-passage-b2-05', 'es', 'B2', 'El sabor de la identidad: comida y comunidad', 'La gastronomía es, probablemente, el lenguaje más universal que existe. A través de los ingredientes y las recetas transmitidas de generación en generación, las sociedades cuentan su historia, su geografía y su visión del mundo. Un plato de comida no es solo una mezcla de nutrientes, sino un recipiente de memoria colectiva que une a individuos en torno a una mesa, reforzando los vínculos que sostienen a la comunidad.

En muchas culturas, la preparación de alimentos tradicionales es un ritual que trasciende la mera necesidad de alimentarse. Es un acto de preservación cultural. Cuando una familia se reúne para cocinar un plato típico, está protegiendo una herencia que corre el riesgo de desaparecer en la estandarización global. Este proceso de cocción lenta es también una forma de resistencia contra la velocidad de la vida moderna, invitándonos a pausar y saborear.

Los mercados locales actúan como el corazón vibrante de las comunidades. Son espacios donde la identidad se manifiesta en aromas, colores y texturas. Comprar productos de temporada a productores locales no solo garantiza una mayor calidad nutricional, sino que fortalece la economía comunitaria y fomenta el sentido de pertenencia. Al elegir productos locales, el consumidor se convierte en un agente activo que protege la diversidad agrícola de su región.

Sin embargo, la globalización ha transformado nuestros hábitos alimentarios de manera drástica. La homogeneización de los sabores y la disponibilidad de productos fuera de temporada han creado una desconexión entre el origen del alimento y el consumidor. Recuperar esta conexión es fundamental para entender el impacto de nuestras elecciones. Saber de dónde viene lo que comemos es, en esencia, un acto de responsabilidad ética hacia el planeta.

La mesa compartida es el espacio donde se dirimen diferencias y se celebran los éxitos. La comida actúa como un catalizador social que suaviza las asperezas de la comunicación. Al compartir el pan, se rompen barreras invisibles. Este valor de la hospitalidad es común a casi todas las culturas, recordándonos que, a pesar de nuestras diferencias, todos compartimos necesidades biológicas y deseos de conexión humana.

En última instancia, valorar nuestras tradiciones culinarias es valorar quiénes somos. No se trata de rechazar influencias externas, sino de enriquecer nuestra cultura sin perder nuestra esencia. Al mantener vivos estos sabores, estamos asegurando que las futuras generaciones tengan un punto de referencia sobre sus raíces. La cocina es, por tanto, un puente entre el pasado y el futuro, un legado que seguimos construyendo con cada bocado.', '[{"prompt":"¿Cómo describe el autor la gastronomía en el primer párrafo?","options":["Como un conjunto de nutrientes necesarios para sobrevivir.","Como un lenguaje universal cargado de memoria colectiva.","Como una industria que genera muchos empleos globales.","Como un pasatiempo que solo tiene valor en las celebraciones."],"answer_index":1,"explanation_pt_br":"O autor descreve a gastronomia como um meio de contar a história e unir as pessoas."},{"prompt":"¿Por qué es un ''acto de resistencia'' cocinar platos tradicionales?","options":["Porque es mucho más caro que comprar comida rápida.","Porque es una forma de preservar la herencia cultural ante la estandarización.","Porque obliga a los miembros de la familia a discutir entre ellos.","Porque requiere herramientas que ya no existen en el mercado."],"answer_index":1,"explanation_pt_br":"Cozinhar pratos tradicionais é uma forma de resistir à uniformidade cultural global."},{"prompt":"¿Qué papel juegan los mercados locales, según el texto?","options":["Son lugares donde se encuentran alimentos más baratos.","Actúan como el corazón de la comunidad y fortalecen la economía.","Son espacios obsoletos que deben ser reemplazados por supermercados.","Solo sirven para vender productos que no se encuentran en otro sitio."],"answer_index":1,"explanation_pt_br":"O texto destaca os mercados como centros de identidade e fortalecimento econômico."},{"prompt":"¿Qué problema ha causado la globalización en la alimentación?","options":["Ha hecho que los alimentos sean más nutritivos que antes.","Ha provocado una desconexión entre el consumidor y el origen del alimento.","Ha eliminado por completo el uso de productos de temporada.","Ha hecho que cocinar en casa sea más fácil y rápido."],"answer_index":1,"explanation_pt_br":"A globalização causou a homogeneização e a perda da conexão com a origem dos alimentos."},{"prompt":"¿Qué significa la expresión ''la mesa compartida'' como catalizador social?","options":["Que comer juntos ayuda a resolver diferencias y conectar personas.","Que la mesa es el lugar donde se trabaja mejor en equipo.","Que todas las personas tienen los mismos gustos culinarios.","Que el acto de comer es siempre una reunión de negocios."],"answer_index":0,"explanation_pt_br":"O autor usa a mesa como um símbolo de união e mediação de conflitos."},{"prompt":"¿Cuál es la postura del autor respecto a las influencias externas en la cocina?","options":["Deben ser prohibidas para proteger la pureza de la tradición.","Son bienvenidas si enriquecen sin borrar la esencia original.","Son la única razón por la cual la cocina evoluciona hoy.","Deben ignorarse para que las tradiciones no cambien nunca."],"answer_index":1,"explanation_pt_br":"O texto sugere que influências externas podem enriquecer a cultura sem destruir a essência."},{"prompt":"¿Cuál es la idea principal del último párrafo?","options":["La cocina es un legado que conecta el pasado con el futuro.","Es necesario cambiar todas las recetas para sobrevivir.","Las futuras generaciones no tendrán interés en la gastronomía.","La cocina es solo una forma de mantener las tradiciones familiares."],"answer_index":0,"explanation_pt_br":"O autor conclui que a culinária é uma ponte geracional que preserva a identidade."}]'::jsonb, 5),
('es-passage-b2-06', 'es', 'B2', 'La paradoja digital: más conectados, menos presentes', 'En la última década, la tecnología ha dejado de ser una herramienta externa para convertirse en una extensión de nuestra propia identidad. Desde que despertamos hasta que conciliamos el sueño, interactuamos con interfaces que gestionan nuestra agenda, nuestras finanzas y nuestras relaciones sociales. Esta hiperconectividad ha transformado radicalmente la estructura de nuestra cotidianidad, eliminando tiempos muertos que antes dedicábamos a la reflexión o al simple ocio contemplativo.

El fenómeno del internet de las cosas (IoT) ha permitido que nuestros hogares se vuelvan inteligentes, optimizando el consumo energético y la seguridad mediante comandos de voz. Sin embargo, esta automatización, aunque cómoda, plantea interrogantes sobre nuestra autonomía. ¿Hasta qué punto somos nosotros quienes tomamos las decisiones, y hasta qué punto son los algoritmos de recomendación los que moldean nuestros gustos, preferencias y hábitos diarios de consumo?

Un aspecto crítico de esta evolución es la mediación tecnológica en la comunicación interpersonal. Aunque las plataformas de mensajería instantánea prometen acortar distancias, a menudo observamos una paradoja: la calidad de la interacción disminuye a medida que aumenta la frecuencia. La inmediatez de la respuesta ha desplazado a la profundidad del diálogo, priorizando la cantidad de intercambios sobre la autenticidad de los vínculos afectivos.

La salud mental también se ha visto afectada por la economía de la atención. Las aplicaciones están diseñadas bajo principios de refuerzo intermitente, similares a las máquinas tragaperras, para mantener al usuario cautivo el mayor tiempo posible. Este diseño no es accidental, sino que responde a un modelo de negocio basado en la recolección de datos personales, los cuales se traducen en anuncios altamente segmentados que persiguen al usuario en cada clic.

A pesar de estos desafíos, la tecnología sigue siendo un motor indiscutible de progreso cuando se utiliza con intención. El acceso ilimitado a la información permite que cualquier persona con conexión pueda aprender nuevas disciplinas, desde la programación hasta la filosofía. La clave, según los expertos, no reside en el rechazo absoluto a los dispositivos, sino en el desarrollo de una alfabetización digital que nos devuelva el control sobre nuestro tiempo y atención.

En conclusión, el reto para las próximas generaciones no será técnico, sino ético y psicológico. Necesitamos redefinir nuestra relación con los objetos digitales para que estos sirvan a nuestras necesidades humanas en lugar de dictar nuestra conducta. El equilibrio es posible, pero requiere una disciplina consciente para establecer límites claros, priorizando siempre la experiencia física y el contacto directo con el mundo que nos rodea.', '[{"prompt":"¿Cuál es la tesis central del texto sobre la tecnología?","options":["La tecnología debe ser eliminada para recuperar la salud mental.","La tecnología es beneficiosa siempre y cuando se gestione con un enfoque ético y consciente.","Los algoritmos son los únicos responsables de nuestras decisiones actuales.","La tecnología ha mejorado la calidad de nuestras relaciones personales."],"answer_index":1,"explanation_pt_br":"O texto defende que a tecnologia é progressista, mas exige uma gestão consciente e ética para não nos controlar."},{"prompt":"Según el texto, ¿qué significa ''economía de la atención''?","options":["El ahorro de dinero que supone usar aplicaciones gratuitas.","La capacidad de las empresas para pagar por nuestra publicidad.","El diseño de aplicaciones para capturar y retener el tiempo del usuario.","La habilidad de los usuarios para enfocarse en tareas importantes."],"answer_index":2,"explanation_pt_br":"O texto descreve como as aplicações são desenhadas para manter o usuário capturado, maximizando o tempo de uso."},{"prompt":"¿Qué paradoja se menciona respecto a la comunicación?","options":["Hablamos más pero nos entendemos menos.","Usamos más tecnología pero estamos más aislados físicamente.","Aumenta la frecuencia de los mensajes pero disminuye la calidad de las interacciones.","La tecnología es más rápida pero las respuestas son más lentas."],"answer_index":2,"explanation_pt_br":"O texto aponta que a rapidez e a frequência das mensagens digitais prejudicam a profundidade das relações."},{"prompt":"¿Cómo describe el autor la influencia de los algoritmos?","options":["Como una ayuda necesaria para gestionar la vida moderna.","Como un factor que moldea nuestros gustos de forma sutil.","Como una herramienta que garantiza nuestra total independencia.","Como un error técnico que debe ser corregido urgentemente."],"answer_index":1,"explanation_pt_br":"O texto questiona até que ponto os algoritmos moldam nossos gostos e preferências de forma oculta."},{"prompt":"En el cuarto párrafo, ¿qué significa el término ''refuerzo intermitente''?","options":["Una técnica para fortalecer la memoria del usuario.","Un mecanismo de recompensa impredecible que genera adicción.","Un fallo técnico que interrumpe la conexión a internet.","Un método de publicidad tradicional y poco eficaz."],"answer_index":1,"explanation_pt_br":"O texto compara as notificações a máquinas de caça-níqueis que usam recompensas aleatórias para manter o usuário engajado."},{"prompt":"¿Qué sugiere el autor para mejorar nuestra relación con la tecnología?","options":["Aprender a programar para entender mejor los sistemas.","Limitar estrictamente el uso de dispositivos a una hora diaria.","Desarrollar una alfabetización digital y establecer límites.","Confiar plenamente en las recomendaciones de los algoritmos."],"answer_index":2,"explanation_pt_br":"O autor sugere que a solução é a alfabetização digital e o estabelecimento de limites conscientes."},{"prompt":"¿Cuál es el tono predominante del texto?","options":["Optimista y entusiasta.","Crítico y reflexivo.","Irónico y pesimista.","Técnico y neutral."],"answer_index":1,"explanation_pt_br":"O texto analisa os problemas da tecnologia, mantendo um tom crítico, porém equilibrado e reflexivo."}]'::jsonb, 6),
('es-passage-b2-07', 'es', 'B2', 'El dilema verde: sostenibilidad más allá de la moda', 'En la era actual, el concepto de sostenibilidad ha pasado de ser una preocupación marginal a convertirse en un pilar central del discurso público y empresarial. Sin embargo, existe una brecha notable entre la intención declarada de los ciudadanos y sus acciones concretas. Mientras que la mayoría reconoce la urgencia de la crisis climática, los hábitos de consumo siguen estando dominados por el modelo lineal de usar y tirar, que es intrínsecamente insostenible a largo plazo.

El fenómeno del ''greenwashing'' o lavado de imagen verde ha complicado la toma de decisiones para el consumidor promedio. Muchas empresas utilizan etiquetas vagas como ''ecológico'' o ''natural'' sin respaldarlas con certificaciones rigurosas. Esto genera una desconfianza justificada, ya que el comprador se siente incapaz de discernir entre una iniciativa genuinamente comprometida con el medio ambiente y una mera estrategia de marketing para aumentar las ventas.

La verdadera sostenibilidad requiere un cambio en nuestra mentalidad sobre la propiedad. Históricamente, hemos vinculado nuestro estatus social a la acumulación de bienes materiales. No obstante, estamos viendo un auge en modelos de economía circular, como el intercambio, el alquiler y la reparación de productos. Estas alternativas no solo reducen la presión sobre los recursos naturales, sino que también fomentan comunidades más fuertes y colaborativas.

El impacto de nuestras elecciones alimentarias es otro frente crítico. La dieta actual, altamente dependiente del consumo de carne y productos procesados con largas cadenas de suministro, tiene una huella de carbono devastadora. La transición hacia dietas basadas en plantas o el consumo de productos locales y de temporada no es solo una elección saludable para el individuo, sino una de las herramientas más potentes para mitigar la degradación de los ecosistemas locales.

La tecnología, a menudo vista como parte del problema, también ofrece soluciones prometedoras. Desde el desarrollo de materiales biodegradables hasta aplicaciones que calculan la huella de carbono de nuestros desplazamientos, la innovación está facilitando la adopción de comportamientos más responsables. No obstante, la tecnología por sí sola es insuficiente si no se acompaña de políticas públicas que incentiven el consumo consciente y penalicen la obsolescencia programada.

En última instancia, el camino hacia una sociedad sostenible no reside en soluciones mágicas, sino en la suma de pequeñas decisiones diarias. Adoptar una postura crítica frente al consumo excesivo y exigir transparencia a las corporaciones son pasos fundamentales. La sostenibilidad no debe entenderse como un sacrificio, sino como una oportunidad para rediseñar nuestra forma de habitar el planeta de manera más armónica y duradera.', '[{"prompt":"¿Qué problema principal plantea el texto sobre el consumo actual?","options":["La falta de productos ecológicos en el mercado.","La brecha entre la intención de ser sostenible y el comportamiento real.","La imposibilidad técnica de reciclar la mayoría de los residuos.","El alto costo de los productos etiquetados como ecológicos."],"answer_index":1,"explanation_pt_br":"O texto destaca a lacuna entre o que as pessoas dizem querer fazer pelo meio ambiente e suas ações de consumo."},{"prompt":"¿Qué es el ''greenwashing'' según el texto?","options":["Un proceso industrial para limpiar residuos tóxicos.","Una estrategia de marketing engañosa sobre la sostenibilidad.","Una técnica de agricultura orgánica muy eficiente.","El nombre de una nueva ley de protección ambiental."],"answer_index":1,"explanation_pt_br":"O termo refere-se ao uso de marketing para parecer ecológico sem medidas reais de sustentabilidade."},{"prompt":"¿Qué modelo de economía se propone como alternativa al consumo lineal?","options":["La economía de libre mercado sin regulaciones.","La economía circular basada en el intercambio y la reparación.","La economía de subsistencia sin tecnología.","La economía de acumulación de bienes de lujo."],"answer_index":1,"explanation_pt_br":"O texto menciona a economia circular, focada em aluguel, troca e reparo, como alternativa."},{"prompt":"¿Cuál es la relación entre la dieta y el medio ambiente en el texto?","options":["La dieta no tiene impacto en la huella de carbono.","Consumir productos locales reduce la huella de carbono.","La dieta vegana es la única forma de salvar el ecosistema.","Los productos procesados ayudan a conservar los recursos."],"answer_index":1,"explanation_pt_br":"O texto enfatiza que escolher produtos locais e de temporada é uma ferramenta poderosa de mitigação ambiental."},{"prompt":"¿Qué papel juegan las políticas públicas según el autor?","options":["Son innecesarias si los individuos consumen bien.","Deben prohibir totalmente la tecnología.","Son necesarias para incentivar el consumo responsable.","Solo sirven para recaudar impuestos verdes."],"answer_index":2,"explanation_pt_br":"O texto afirma que a tecnologia precisa de políticas públicas para incentivar comportamentos responsáveis."},{"prompt":"¿Cómo se define la ''obsolescencia programada'' en el contexto del texto?","options":["La planificación del tiempo de estudio de los alumnos.","La reducción deliberada de la vida útil de los productos.","El diseño de productos ecológicos que duran para siempre.","Una técnica para fabricar productos más baratos."],"answer_index":1,"explanation_pt_br":"Refere-se à prática das empresas de criar produtos que estragam ou ficam obsoletos rapidamente."},{"prompt":"¿Cuál es el mensaje final del autor?","options":["La sostenibilidad es un sacrificio inalcanzable.","La sostenibilidad es una oportunidad para rediseñar nuestra vida.","El cambio climático es irreversible, por lo que no debemos preocuparnos.","Solo las grandes empresas pueden cambiar el futuro del planeta."],"answer_index":1,"explanation_pt_br":"O autor conclui que a sustentabilidade é uma oportunidade de melhoria e não um fardo."}]'::jsonb, 7),
('es-passage-b2-08', 'es', 'B2', 'El tejido social: la calidad de nuestros vínculos', 'En la sociedad contemporánea, el concepto de comunidad ha sufrido una transformación profunda. Mientras que en décadas anteriores el sentido de pertenencia estaba ligado al entorno geográfico inmediato, hoy los vínculos sociales se expanden a través de fronteras físicas. Esta democratización del contacto humano ha enriquecido nuestras perspectivas, pero también ha generado una paradoja: podemos estar conectados con personas en todo el mundo mientras nos sentimos profundamente solos en nuestra vida cotidiana.

La calidad de las relaciones humanas se ha visto alterada por la velocidad del estilo de vida actual. La amistad, una vez cultivada a través de encuentros prolongados y conversaciones pausadas, a menudo se reduce a interacciones digitales rápidas. Este fenómeno erosiona la intimidad, ya que la comunicación mediada por pantallas carece de las sutilezas del lenguaje corporal y el contacto visual, elementos esenciales para construir una empatía genuina.

Los conflictos sociales también han cambiado de escenario. La polarización, alimentada por algoritmos que nos exponen mayoritariamente a opiniones afines, ha limitado nuestra capacidad para gestionar la diversidad de pensamiento. Cuando perdemos la habilidad de dialogar con quienes piensan distinto, el tejido social se debilita, convirtiendo el debate constructivo en una serie de monólogos paralelos que no buscan el entendimiento, sino la validación de nuestras propias posturas.

Un componente fundamental del bienestar es la capacidad de establecer límites saludables en nuestras interacciones. Muchas personas sufren de fatiga social al intentar mantener una imagen pública impecable en redes sociales mientras descuidan los espacios de vulnerabilidad. La verdadera conexión requiere la valentía de mostrar nuestras imperfecciones, permitiendo que otros también lo hagan, lo cual es la base de la confianza y el apoyo mutuo.

La importancia de los espacios físicos de encuentro no debería subestimarse en este contexto. Los cafés, los parques, los clubes deportivos y los centros culturales funcionan como ''terceros espacios'' donde la gente puede interactuar fuera de las jerarquías laborales o familiares. Estos lugares son vitales para la cohesión social, ya que nos obligan a convivir con personas de diferentes orígenes y realidades, fomentando una comprensión mucho más amplia de nuestra comunidad.

En conclusión, fortalecer nuestro tejido social requiere un esfuerzo consciente por priorizar la profundidad sobre la superficialidad. Esto implica no solo cultivar amistades reales, sino también participar activamente en nuestra comunidad local. La sociedad que queremos construir depende de nuestra capacidad para ver al otro no como un competidor o una imagen digital, sino como un ser humano con el que compartimos un destino común.', '[{"prompt":"¿Qué paradoja sobre la conexión social destaca el texto?","options":["Estamos más conectados globalmente pero más solos en el ámbito personal.","Tenemos más amigos virtuales pero menos amigos en la vida real.","La tecnología facilita el trabajo pero dificulta el descanso.","La gente viaja mucho pero no conoce a sus vecinos."],"answer_index":0,"explanation_pt_br":"O texto descreve exatamente essa contradição entre a conectividade global e a solidão individual."},{"prompt":"¿Por qué la comunicación digital puede erosionar la intimidad?","options":["Porque consume mucho tiempo y energía.","Porque carece de lenguaje corporal y contacto visual.","Porque la gente miente más en los mensajes digitales.","Porque las aplicaciones son muy caras para el usuario."],"answer_index":1,"explanation_pt_br":"O texto afirma que a falta de sinais não verbais dificulta a empatia genuína."},{"prompt":"¿Qué efecto tienen los algoritmos en el debate social según el autor?","options":["Fomentan el debate constructivo entre personas diversas.","Reducen la exposición a opiniones diferentes y aumentan la polarización.","Aumentan la velocidad con la que nos informamos sobre política.","Ayudan a las personas a encontrar grupos de amigos más grandes."],"answer_index":1,"explanation_pt_br":"O texto menciona que os algoritmos nos expõem apenas a opiniões similares, limitando o diálogo."},{"prompt":"¿Qué se entiende por ''fatiga social'' en el texto?","options":["El cansancio físico derivado de hacer mucho ejercicio.","El agotamiento por intentar mantener una imagen perfecta en redes.","La incapacidad de hablar con desconocidos en la calle.","El aburrimiento de ver siempre las mismas noticias."],"answer_index":1,"explanation_pt_br":"O texto associa a fadiga ao esforço de manter uma imagem pública impecável."},{"prompt":"¿Qué son los ''terceros espacios''?","options":["Lugares de trabajo donde se fomenta la amistad.","Espacios físicos para la interacción comunitaria y la convivencia.","Aplicaciones digitales para conocer gente nueva.","Casas de amigos donde se realizan reuniones privadas."],"answer_index":1,"explanation_pt_br":"O texto define os terceiros espaços como locais como cafés e parques, fora do trabalho ou casa."},{"prompt":"¿Qué es necesario para construir la confianza y el apoyo mutuo?","options":["Mantener una imagen pública impecable siempre.","Mostrar nuestras imperfecciones y vulnerabilidad.","Evitar cualquier tipo de conflicto con los demás.","Tener una gran red de contactos en redes sociales."],"answer_index":1,"explanation_pt_br":"O autor afirma que a vulnerabilidade é a base da confiança nas relações."},{"prompt":"¿Cuál es la idea principal del último párrafo?","options":["Debemos centrarnos únicamente en nuestras amistades locales.","La tecnología es el enemigo principal de la cohesión social.","Es fundamental priorizar la profundidad de las relaciones y la participación comunitaria.","El destino de nuestra sociedad está predeterminado por el gobierno."],"answer_index":2,"explanation_pt_br":"O parágrafo final resume a necessidade de priorizar o real e participar da comunidade."}]'::jsonb, 8),
('es-passage-b2-09', 'es', 'B2', 'Gestión financiera: más allá de los números', 'La salud financiera es un componente frecuentemente ignorado del bienestar integral. En una cultura que glorifica el consumo inmediato, la planificación financiera a menudo se percibe como una restricción a la libertad personal. Sin embargo, la realidad es la opuesta: un control adecuado de nuestros recursos es la herramienta definitiva para conquistar la independencia y reducir la ansiedad asociada a la incertidumbre del futuro.

Uno de los mayores desafíos en la gestión personal es la distinción entre necesidades y deseos. La mercadotecnia está diseñada para difuminar esta línea, creando una sensación de urgencia por adquirir bienes que, en realidad, no aportan un valor duradero a nuestra vida. Aprender a identificar cuándo estamos comprando por necesidad real y cuándo por impulso es el primer paso para alcanzar una estabilidad financiera sostenible.

La cultura del crédito fácil ha facilitado el acceso a bienes de consumo, pero ha ocultado los costos reales del endeudamiento. Muchos individuos se encuentran atrapados en ciclos de pagos que consumen gran parte de sus ingresos mensuales, limitando su capacidad de ahorro y, por ende, su libertad de elección. La educación financiera, en este sentido, no se trata solo de hacer presupuestos, sino de comprender cómo funcionan las tasas de interés y el costo de oportunidad.

El ahorro, a menudo malentendido como un acto de privación, es en realidad un fondo de libertad. Tener una reserva de emergencia permite tomar decisiones profesionales más valientes, como cambiar de empleo o emprender un proyecto personal, sin el miedo paralizante a la escasez inmediata. La inversión, por su parte, es el siguiente paso lógico, donde el ahorro se pone a trabajar para combatir la inflación y preservar el poder adquisitivo a largo plazo.

La tecnología ha democratizado el acceso a herramientas de gestión financiera que antes eran exclusivas de expertos. Hoy, aplicaciones de seguimiento de gastos y plataformas de inversión permiten que cualquier persona pueda gestionar sus finanzas con precisión. No obstante, la tecnología no sustituye la disciplina personal. Sin un plan claro y un compromiso con nuestros objetivos, las herramientas digitales son solo espejismos que no alterarán nuestra situación económica.

En resumen, la gestión de nuestras finanzas personales es un reflejo de nuestras prioridades vitales. Al tomar el control de nuestro dinero, no solo estamos asegurando nuestro futuro material, sino que estamos liberando recursos mentales para enfocarnos en lo que realmente importa. La riqueza, más que una cifra en una cuenta bancaria, es la capacidad de vivir una vida alineada con nuestros valores y propósitos personales.', '[{"prompt":"¿Por qué el autor argumenta que la gestión financiera aumenta la libertad?","options":["Porque permite comprar más productos de lujo.","Porque reduce la ansiedad y proporciona control sobre el futuro.","Porque elimina la necesidad de trabajar a largo plazo.","Porque obliga a las personas a vivir de forma austera."],"answer_index":1,"explanation_pt_br":"O texto explica que o controle financeiro traz independência e reduz a ansiedade."},{"prompt":"¿Qué problema principal causa la mercadotecnia según el texto?","options":["Hace que los productos sean demasiado caros.","Crea una falsa urgencia por comprar cosas innecesarias.","Impide que las empresas vendan sus productos.","Obliga a los consumidores a ahorrar demasiado."],"answer_index":1,"explanation_pt_br":"O texto menciona como a mercadotecnia confunde necessidades e desejos, criando urgência."},{"prompt":"¿Qué concepto es fundamental para entender el crédito según el autor?","options":["El valor de reventa de los productos comprados.","El costo de oportunidad y las tasas de interés.","La facilidad de obtener préstamos bancarios.","La cantidad de dinero que podemos ahorrar cada mes."],"answer_index":1,"explanation_pt_br":"O autor destaca a importância de entender juros e custo de oportunidade ao se endividar."},{"prompt":"¿Cómo define el autor el ahorro?","options":["Como un acto de sacrificio personal.","Como un fondo de libertad para tomar decisiones.","Como una pérdida de capacidad de consumo.","Como una obligación para los jóvenes."],"answer_index":1,"explanation_pt_br":"O texto redefine o ahorro como um fundo que permite maior liberdade de escolha."},{"prompt":"¿Qué función cumplen las aplicaciones financieras según el autor?","options":["Reemplazan totalmente la necesidad de disciplina.","Son herramientas útiles pero no sustituyen la disciplina personal.","Son la causa principal del sobreendeudamiento.","Solo sirven para expertos en finanzas."],"answer_index":1,"explanation_pt_br":"O texto esclarece que a tecnologia é um apoio, mas a disciplina é essencial."},{"prompt":"¿Qué significa que la gestión financiera es un ''reflejo de nuestras prioridades''?","options":["Que solo las personas ricas pueden tener prioridades.","Que el modo en que gastamos dinero muestra lo que valoramos.","Que no podemos tener prioridades sin dinero.","Que las prioridades cambian según el banco que elijamos."],"answer_index":1,"explanation_pt_br":"O texto indica que a forma como usamos nosso dinheiro revela nossas prioridades de vida."},{"prompt":"¿Cuál es la conclusión principal sobre la riqueza?","options":["Es simplemente el número de cuenta bancaria.","Es la capacidad de vivir alineado con nuestros valores.","Es la acumulación de bienes materiales.","Es la libertad de no trabajar nunca más."],"answer_index":1,"explanation_pt_br":"O autor redefine riqueza como uma vida alinhada aos valores pessoais."}]'::jsonb, 9),
('es-passage-b2-10', 'es', 'B2', 'Educación permanente: el aprendizaje como estilo de vida', 'El modelo educativo tradicional, que limitaba la adquisición de conocimientos a los años de juventud, ha quedado obsoleto. En un mundo caracterizado por una aceleración tecnológica sin precedentes, la capacidad de aprender, desaprender y reaprender se ha convertido en la habilidad más valiosa. La educación ya no es un periodo de la vida que se cierra con un título, sino un proceso continuo que debe acompañarnos durante toda nuestra existencia.

La cultura del ''aprendizaje permanente'' o ''lifelong learning'' no es solo una necesidad profesional para mantenerse relevante en el mercado laboral. Es, sobre todo, una forma de enriquecimiento intelectual que mantiene nuestra mente activa y curiosa. Al explorar nuevas disciplinas, no solo adquirimos habilidades técnicas, sino que expandimos nuestras fronteras mentales, mejorando nuestra capacidad de resolución de problemas y adaptabilidad ante situaciones imprevistas.

El acceso a la educación nunca ha sido tan democrático como hoy. Plataformas de cursos en línea, podcasts, bibliotecas digitales y comunidades de práctica ofrecen recursos de alta calidad para cualquier persona con voluntad de aprender. Sin embargo, esta abundancia de información conlleva un riesgo: la dispersión. Sin una guía o un plan de aprendizaje estructurado, es fácil saltar de un tema a otro sin profundizar, acumulando fragmentos de información superficial.

Es fundamental distinguir entre la acumulación de datos y el conocimiento profundo. En la era de la inteligencia artificial, las máquinas pueden procesar información mucho más rápido que nosotros. Lo que nos diferencia es nuestra capacidad de síntesis, juicio crítico y creatividad. Por lo tanto, el aprendizaje debe enfocarse en cultivar estas capacidades humanas superiores, en lugar de intentar competir con la memoria enciclopédica de los ordenadores.

La motivación intrínseca juega un papel clave en este proceso. Cuando aprendemos por el simple placer de descubrir, el esfuerzo se transforma en satisfacción. La educación debe dejar de verse como una carga o una obligación impuesta por las circunstancias y empezar a valorarse como un ejercicio de libertad. Elegir qué aprender es, en última instancia, elegir en qué tipo de persona queremos convertirnos con el paso del tiempo.

En conclusión, el aprendizaje a lo largo de la vida es la mejor estrategia para navegar la incertidumbre del futuro. A medida que envejecemos, nuestra experiencia se suma al nuevo conocimiento, creando una perspectiva única que es difícil de replicar. Adoptar una actitud de estudiante permanente no solo mejora nuestras oportunidades, sino que le otorga un sentido profundo a nuestro camino, haciendo de la vida una aventura de crecimiento constante.', '[{"prompt":"¿Por qué el modelo educativo tradicional se considera obsoleto?","options":["Porque los profesores ya no enseñan bien.","Porque limitaba el aprendizaje a una etapa temprana de la vida.","Porque las escuelas son demasiado caras para los ciudadanos.","Porque ya no existen los títulos universitarios."],"answer_index":1,"explanation_pt_br":"O texto aponta que o modelo antigo, que terminava com um título, não atende às necessidades atuais de mudança constante."},{"prompt":"¿Qué es el ''lifelong learning'' según el texto?","options":["Un curso universitario de larga duración.","Un proceso de aprendizaje continuo durante toda la vida.","Un método para aprender a enseñar a otros.","La obligación de estudiar por motivos laborales."],"answer_index":1,"explanation_pt_br":"O termo refere-se ao conceito de aprendizagem ao longo de toda a existência."},{"prompt":"¿Cuál es el riesgo de la abundancia de información actual?","options":["Que todo el mundo se vuelve demasiado inteligente.","La dispersión y la falta de profundidad en el aprendizaje.","Que las bibliotecas digitales sean demasiado grandes.","Que no haya suficiente información sobre temas técnicos."],"answer_index":1,"explanation_pt_br":"O texto alerta que, com tanta informação, é fácil ficar na superfície sem aprofundar nada."},{"prompt":"¿Qué diferencia a los humanos de las máquinas en el aprendizaje?","options":["La velocidad de procesamiento de datos.","La capacidad de síntesis, juicio crítico y creatividad.","La cantidad de información que pueden memorizar.","La habilidad para trabajar sin descanso."],"answer_index":1,"explanation_pt_br":"O autor destaca que a nossa vantagem reside na criatividade e no julgamento, não na memória."},{"prompt":"¿Qué papel tiene la motivación intrínseca?","options":["Es irrelevante si el curso es bueno.","Convierte el esfuerzo de aprender en un acto de satisfacción.","Es necesaria solo cuando estamos trabajando.","Hace que el aprendizaje sea una obligación impuesta."],"answer_index":1,"explanation_pt_br":"O texto enfatiza que aprender por prazer transforma o esforço em algo positivo."},{"prompt":"¿Cuál es la relación entre el aprendizaje y la incertidumbre?","options":["El aprendizaje aumenta la incertidumbre.","El aprendizaje es la mejor estrategia para navegar la incertidumbre.","La incertidumbre hace imposible aprender cosas nuevas.","Solo los expertos en incertidumbre deben seguir aprendiendo."],"answer_index":1,"explanation_pt_br":"O parágrafo final afirma que o aprendizado constante nos prepara para lidar com o futuro incerto."},{"prompt":"¿Cuál es el tono general del texto?","options":["Desalentador y pesimista.","Inspirador y pragmático.","Técnico y frío.","Irónico y crítico."],"answer_index":1,"explanation_pt_br":"O tom é encorajador e prático, incentivando o leitor a buscar o aprendizado constante."}]'::jsonb, 10),
('fr-passage-a1-01', 'fr', 'A1', 'Ma journée à São Paulo', 'Je m''appelle Lucas et j''habite à São Paulo. Chaque matin, je me réveille à six heures pour commencer ma journée. Je prends une douche rapide, je m''habille proprement et je prépare un café fort pour bien démarrer.

À sept heures, je quitte mon appartement pour aller au travail. Je prends le métro parce que c''est très pratique. Pendant le trajet, je lis les actualités sur mon téléphone ou j''écoute un peu de musique brésilienne.

Le soir, je rentre chez moi vers dix-huit heures. Je cuisine un dîner simple avec des légumes frais. Après manger, je regarde une série et je me couche tôt pour être en forme le lendemain.', '[{"prompt":"À quelle heure Lucas se réveille-t-il ?","options":["À sept heures","À six heures","À huit heures","À dix-huit heures"],"answer_index":1,"explanation_pt_br":"O texto afirma explicitamente que ele acorda às seis horas."},{"prompt":"Quel moyen de transport Lucas utilise-t-il ?","options":["Le bus","La voiture","Le vélo","Le métro"],"answer_index":3,"explanation_pt_br":"Lucas menciona que usa o metrô por ser prático."},{"prompt":"Que fait Lucas après le dîner ?","options":["Il travaille","Il regarde une série","Il fait du sport","Il téléphone"],"answer_index":1,"explanation_pt_br":"O texto diz que ele assiste a uma série após jantar."}]'::jsonb, 1),
('fr-passage-a1-02', 'fr', 'A1', 'Un voyage à Paris', 'Marie visite la France pour ses vacances. Elle arrive à Paris le lundi matin avec une petite valise. Elle réserve une chambre dans un hôtel situé près de la tour Eiffel pour admirer la vue.

Le mardi, elle marche beaucoup dans le quartier du Marais. Elle visite le musée du Louvre et elle prend beaucoup de photos. Elle adore découvrir les monuments historiques et les vieilles rues de la capitale française.

Le mercredi, elle achète des souvenirs pour sa famille au Brésil. Elle trouve des chocolats et des petits cadeaux typiques. Elle est très heureuse de découvrir cette nouvelle culture et de parler un peu français.', '[{"prompt":"Où est l''hôtel de Marie ?","options":["Près de la tour Eiffel","Au centre du Brésil","Dans un aéroport","Loin de Paris"],"answer_index":0,"explanation_pt_br":"O texto especifica que o hotel fica perto da Torre Eiffel."},{"prompt":"Que fait Marie le mardi ?","options":["Elle se repose","Elle visite le Louvre","Elle part au Brésil","Elle cuisine"],"answer_index":1,"explanation_pt_br":"A visita ao Louvre ocorre no dia terça-feira conforme o texto."},{"prompt":"Que pense Marie de son voyage ?","options":["Elle est triste","Elle est fatiguée","Elle est heureuse","Elle est en colère"],"answer_index":2,"explanation_pt_br":"O texto menciona explicitamente que ela está muito feliz."}]'::jsonb, 2),
('fr-passage-a1-03', 'fr', 'A1', 'Une journée au bureau', 'Thomas travaille dans une grande entreprise à Lyon. Il arrive à son bureau à neuf heures. Il salue ses collègues avec le sourire et il prépare son ordinateur pour commencer les activités de la journée.

Pendant la matinée, il répond à beaucoup d''emails importants. Il participe aussi à une réunion avec son chef pour discuter des nouveaux projets. Il prend des notes sur son cahier pour ne rien oublier.

À midi, il mange avec son équipe dans la cafétéria. Ils parlent de travail mais aussi de leurs loisirs. L''ambiance est très sympathique et professionnelle. Thomas aime beaucoup travailler dans cette équipe dynamique et ouverte.', '[{"prompt":"À quelle heure Thomas commence-t-il son travail ?","options":["À huit heures","À neuf heures","À dix heures","À midi"],"answer_index":1,"explanation_pt_br":"Thomas chega ao escritório às nove horas."},{"prompt":"Que fait Thomas pendant la matinée ?","options":["Il dort","Il fait du sport","Il répond aux emails","Il voyage"],"answer_index":2,"explanation_pt_br":"O texto menciona que ele responde a muitos e-mails importantes."},{"prompt":"Comment est l''ambiance au travail ?","options":["Difficile","Triste","Sympathique","Silencieuse"],"answer_index":2,"explanation_pt_br":"O texto descreve o ambiente como muito simpático."}]'::jsonb, 3),
('fr-passage-a1-04', 'fr', 'A1', 'La santé avant tout', 'Pour être en bonne santé, Julie fait attention à son alimentation. Elle mange des fruits et des légumes tous les jours. Elle boit aussi beaucoup d''eau pendant la journée pour rester toujours très bien hydratée.

Le week-end, Julie pratique du sport au parc. Elle aime courir pendant trente minutes le samedi matin. Cette activité physique lui permet de réduire son stress après une semaine de travail intense au bureau.

Elle dort aussi huit heures par nuit. Le repos est très important pour son équilibre. Grâce à ces habitudes simples, Julie se sent pleine d''énergie et elle est rarement malade pendant l''année.', '[{"prompt":"Que boit Julie pour rester hydratée ?","options":["Du café","Du soda","De l''eau","Du thé"],"answer_index":2,"explanation_pt_br":"O texto diz que ela bebe água para se hidratar."},{"prompt":"Quand Julie court-elle ?","options":["Le lundi","Le samedi matin","Tous les soirs","Le dimanche"],"answer_index":1,"explanation_pt_br":"A atividade de corrida acontece nas manhãs de sábado."},{"prompt":"Quel est l''effet de ces habitudes sur Julie ?","options":["Elle est fatiguée","Elle est pleine d''énergie","Elle a faim","Elle est malade"],"answer_index":1,"explanation_pt_br":"O texto afirma que ela se sente cheia de energia."}]'::jsonb, 4),
('fr-passage-a1-05', 'fr', 'A1', 'Un déjeuner en famille', 'Le dimanche, toute la famille se réunit chez la grand-mère. C''est une tradition très importante pour nous. Nous préparons ensemble un grand repas avec des produits locaux et des recettes anciennes de la région.

Nous mangeons du poulet rôti avec des pommes de terre. Tout le monde discute et rit autour de la table. C''est un moment de partage très agréable qui renforce les liens entre tous les membres de la famille.

Après le repas, nous buvons un café et nous partageons des histoires. Nous aimons beaucoup ces traditions qui nous permettent de rester unis. Pour moi, ces moments sont les meilleurs instants de toute la semaine.', '[{"prompt":"Où la famille se réunit-elle le dimanche ?","options":["Au restaurant","Chez la grand-mère","Au travail","Au parc"],"answer_index":1,"explanation_pt_br":"O texto indica que a família se reúne na casa da avó."},{"prompt":"Quel plat la famille mange-t-elle ?","options":["Du poisson","Du poulet rôti","De la salade","Des pâtes"],"answer_index":1,"explanation_pt_br":"O texto menciona explicitamente o frango assado."},{"prompt":"Quel est le but de ce repas ?","options":["Travailler","Renforcer les liens","Apprendre le français","Faire du sport"],"answer_index":1,"explanation_pt_br":"O texto diz que é um momento que reforça os laços familiares."}]'::jsonb, 5),
('fr-passage-a1-06', 'fr', 'A1', 'Ma vie numérique', 'Chaque matin, je me réveille et je regarde mon téléphone portable. Je vérifie mes messages et mes courriels pour le travail. C''est très pratique pour organiser ma journée rapidement.

Pendant le déjeuner, j''utilise une tablette pour lire les nouvelles du monde. J''aime aussi regarder des vidéos sur internet pour apprendre des choses nouvelles ou pour me détendre un peu.

Le soir, je préfère éteindre tous mes appareils électroniques. Je lis un livre en papier dans mon lit. Cette routine simple m''aide à bien dormir et à oublier un peu la technologie.', '[{"prompt":"Que fait la personne avec son téléphone le matin ?","options":["Elle joue à des jeux","Elle lit ses messages","Elle appelle ses amis","Elle regarde la météo"],"answer_index":1,"explanation_pt_br":"O texto afirma explicitamente que a pessoa verifica mensagens e e-mails logo ao acordar."},{"prompt":"Que signifie le mot ''pratique'' dans le premier paragraphe ?","options":["Difficile","Utile","Rapide","Fatiguant"],"answer_index":1,"explanation_pt_br":"No contexto, ''pratique'' descreve algo que facilita a organização do dia, ou seja, algo útil."},{"prompt":"Quelle est l''habitude de la personne avant de dormir ?","options":["Elle utilise sa tablette","Elle regarde des vidéos","Elle lit un livre","Elle travaille encore"],"answer_index":2,"explanation_pt_br":"O texto menciona que, à noite, a pessoa prefere desligar os aparelhos e ler um livro em papel."}]'::jsonb, 6),
('fr-passage-a1-07', 'fr', 'A1', 'Le geste vert', 'Aujourd''hui, beaucoup de personnes font attention à la nature. Pour protéger l''environnement, je recycle mes bouteilles en plastique et mes papiers chaque semaine dans des bacs spéciaux.

Je vais aussi au supermarché avec mon sac en tissu. Je n''achète jamais de sacs en plastique parce qu''ils sont mauvais pour la planète. C''est un petit changement très facile.

Enfin, je préfère manger des produits locaux et de saison. C''est meilleur pour ma santé et pour les agriculteurs de ma région. Ces habitudes simples aident à construire un futur plus vert pour nous.', '[{"prompt":"Où la personne met-elle ses bouteilles en plastique ?","options":["Dans la rue","Dans des bacs spéciaux","Dans son sac en tissu","Dans un grand carton"],"answer_index":1,"explanation_pt_br":"O texto diz que a pessoa recicla garrafas em ''bacs spéciaux'' (recipientes especiais)."},{"prompt":"Pourquoi la personne n''utilise-t-elle pas de sacs en plastique ?","options":["Ils sont trop chers","Ils sont trop petits","Ils sont mauvais pour la planète","Elle oublie de les prendre"],"answer_index":2,"explanation_pt_br":"O texto afirma diretamente que sacos plásticos são ''mauvais pour la planète'' (ruins para o planeta)."},{"prompt":"Quelle est l''idée principale du texte ?","options":["Le recyclage est obligatoire","Le plastique est utile","Les gestes écologiques sont importants","La nourriture locale est chère"],"answer_index":2,"explanation_pt_br":"O texto descreve várias ações individuais para proteger o meio ambiente, destacando sua importância."}]'::jsonb, 7),
('fr-passage-a1-08', 'fr', 'A1', 'Mes amis et moi', 'J''aime beaucoup passer du temps avec mes amis. Le samedi, nous allons souvent au café pour discuter de notre semaine. Nous aimons rire et partager nos histoires personnelles.

Quand un ami est triste, je l''écoute avec attention. C''est important d''aider les personnes qu''on aime dans les moments difficiles. Une bonne amitié demande du temps et beaucoup de confiance.

Parfois, nous organisons un dîner chez moi. Je prépare un repas simple et nous écoutons de la musique ensemble. Ces moments sont précieux pour garder une relation forte et heureuse avec mon groupe d''amis.', '[{"prompt":"Où les amis se retrouvent-ils le samedi ?","options":["Au restaurant","Au café","Chez l''auteur","Au parc"],"answer_index":1,"explanation_pt_br":"O texto indica claramente que eles vão ao café (''au café'') aos sábados."},{"prompt":"Que fait la personne quand un ami est triste ?","options":["Elle change de sujet","Elle l''écoute","Elle part rapidement","Elle rit beaucoup"],"answer_index":1,"explanation_pt_br":"O texto menciona que, quando um amigo está triste, a pessoa o escuta com atenção."},{"prompt":"D''après le texte, que faut-il pour une bonne amitié ?","options":["Beaucoup d''argent","Du temps et de la confiance","Des cadeaux chers","Un grand appartement"],"answer_index":1,"explanation_pt_br":"O autor afirma explicitamente que uma boa amizade exige tempo e confiança."}]'::jsonb, 8),
('fr-passage-a1-09', 'fr', 'A1', 'Gérer son argent', 'Gérer ses finances est très important pour vivre tranquillement. Chaque mois, je note mes dépenses dans un petit carnet. Cela m''aide à comprendre où va mon argent exactement.

J''essaie aussi d''économiser une petite somme pour mes projets futurs. Je ne dépense pas tout mon salaire dans des vêtements ou des objets inutiles. C''est une question de discipline personnelle.

Avant d''acheter quelque chose de cher, je réfléchis pendant deux jours. Si j''en ai vraiment besoin, je l''achète. Sinon, j''attends. Cette méthode m''évite beaucoup de problèmes financiers et me permet de vivre sans stress inutile chaque mois.', '[{"prompt":"Que fait la personne chaque mois ?","options":["Elle achète des vêtements","Elle note ses dépenses","Elle travaille beaucoup","Elle va à la banque"],"answer_index":1,"explanation_pt_br":"O texto diz que a pessoa anota suas despesas (''dépenses'') em um caderno todo mês."},{"prompt":"Que signifie ''économiser'' dans le deuxième paragraphe ?","options":["Gagner beaucoup","Dépenser trop","Mettre de côté","Emprunter de l''argent"],"answer_index":2,"explanation_pt_br":"No contexto financeiro, economizar significa guardar dinheiro para o futuro."},{"prompt":"Pourquoi la personne attend-elle deux jours avant un achat cher ?","options":["Parce que le magasin est fermé","Pour réfléchir si c''est nécessaire","Parce qu''elle n''a pas d''argent","Pour comparer les prix"],"answer_index":1,"explanation_pt_br":"O autor explica que reflete por dois dias para decidir se realmente precisa do objeto."}]'::jsonb, 9),
('fr-passage-a1-10', 'fr', 'A1', 'Apprendre toute la vie', 'L''éducation ne s''arrête jamais après l''école. J''aime beaucoup apprendre de nouvelles compétences pendant mon temps libre. Cette année, je prends des cours de cuisine pour améliorer mes recettes.

C''est une expérience très enrichissante. Je rencontre des personnes différentes et nous partageons nos astuces. Apprendre quelque chose de nouveau garde mon esprit actif et curieux chaque jour.

Je pense qu''il est essentiel de continuer à étudier toute sa vie. Cela nous aide à mieux comprendre le monde qui change rapidement. Peu importe l''âge, il y a toujours une nouvelle chose intéressante à découvrir pour progresser personnellement.', '[{"prompt":"Quel cours la personne suit-elle cette année ?","options":["La langue française","La cuisine","L''informatique","La peinture"],"answer_index":1,"explanation_pt_br":"O texto menciona especificamente que a pessoa está fazendo aulas de culinária (''cours de cuisine'')."},{"prompt":"Que gagne la personne en apprenant ?","options":["Plus d''argent","Un esprit actif","Un nouveau travail","Plus de temps libre"],"answer_index":1,"explanation_pt_br":"O texto diz que aprender mantém a mente ativa e curiosa."},{"prompt":"Quelle est l''idée générale sur l''éducation ?","options":["C''est seulement pour les enfants","C''est difficile et ennuyeux","C''est important toute la vie","C''est trop cher pour beaucoup"],"answer_index":2,"explanation_pt_br":"O autor defende que é essencial continuar estudando durante toda a vida, independentemente da idade."}]'::jsonb, 10),
('fr-passage-a2-01', 'fr', 'A2', 'Une journée bien remplie', 'Chaque matin, Lucas se réveille à sept heures précises. Il prend une douche rapide, s''habille avec soin et prépare un café fort pour bien commencer sa journée. Il aime ce moment de calme avant le chaos habituel.

Il quitte son appartement à huit heures pour prendre le métro. Le trajet dure trente minutes, ce qui lui laisse le temps de lire les nouvelles ou d''écouter un podcast en français. Il trouve cela très utile pour progresser.

Au bureau, il travaille sur des dossiers importants jusqu''à midi. Il déjeune souvent avec ses collègues dans un petit restaurant près de l''entreprise. Ils discutent de leurs projets futurs et de leurs loisirs personnels pendant ce temps.

Le soir, Lucas rentre chez lui vers dix-huit heures. Il fait quelques courses, cuisine un repas léger et regarde un film. Avant de dormir, il range son salon pour que tout soit prêt pour demain matin.', '[{"prompt":"Que fait Lucas juste après s''être réveillé ?","options":["Il prépare son café","Il prend une douche","Il lit les nouvelles","Il range son salon"],"answer_index":1,"explanation_pt_br":"O texto afirma explicitamente que ele toma um banho rápido logo após acordar."},{"prompt":"Dans le texte, que signifie le mot ''trajet'' ?","options":["Le temps de travail","Le voyage quotidien","Le repas du midi","Le dossier important"],"answer_index":1,"explanation_pt_br":"No contexto, refere-se ao tempo gasto no deslocamento entre casa e trabalho."},{"prompt":"Quel est l''ordre des activités de Lucas le soir ?","options":["Cuisiner, faire les courses, regarder un film","Faire les courses, cuisiner, regarder un film","Regarder un film, cuisiner, faire les courses","Faire les courses, regarder un film, cuisiner"],"answer_index":1,"explanation_pt_br":"O texto segue a ordem: fazer compras, cozinhar e depois assistir a um filme."},{"prompt":"Quelle est l''idée principale de ce texte ?","options":["La vie professionnelle de Lucas","La passion de Lucas pour le métro","La routine organisée de Lucas","Les difficultés de Lucas le matin"],"answer_index":2,"explanation_pt_br":"O texto descreve de forma geral a rotina estruturada e organizada do protagonista."}]'::jsonb, 1),
('fr-passage-a2-02', 'fr', 'A2', 'Un voyage inoubliable', 'Sophie a décidé de visiter Lyon pendant ses prochaines vacances. Elle veut découvrir l''histoire de cette ville célèbre pour sa gastronomie et ses beaux bâtiments anciens. Elle a déjà réservé un petit hôtel dans le centre.

Pour arriver à Lyon, elle choisit de prendre le train à grande vitesse. C''est un moyen de transport confortable et rapide qui lui permet d''admirer les paysages magnifiques de la campagne française à travers la fenêtre.

Une fois sur place, elle prévoit de visiter le vieux quartier et de monter sur la colline de Fourvière pour voir toute la ville. Elle espère rencontrer des habitants locaux pour apprendre quelques expressions typiques de la région.

Ce voyage est une opportunité pour elle de pratiquer son français et de se détendre. Elle sait que chaque découverte culturelle enrichit son esprit et lui donne envie de voyager encore plus souvent dans le futur.', '[{"prompt":"Où Sophie va-t-elle passer ses vacances ?","options":["Dans la campagne française","À Lyon","À Paris","Sur une colline"],"answer_index":1,"explanation_pt_br":"O texto menciona claramente que o destino das férias de Sophie é Lyon."},{"prompt":"Que signifie ''moyen de transport'' dans le texte ?","options":["La destination finale","Le billet de train","Le mode de déplacement","Le paysage extérieur"],"answer_index":2,"explanation_pt_br":"Refere-se ao veículo ou forma usada para se locomover, neste caso, o trem."},{"prompt":"Qu''est-ce que Sophie veut faire en priorité ?","options":["Prendre le train","Visiter le vieux quartier","Travailler à Lyon","Réserver un hôtel"],"answer_index":1,"explanation_pt_br":"O texto indica que visitar o bairro antigo é uma de suas atividades planejadas."},{"prompt":"Pourquoi Sophie voyage-t-elle ?","options":["Pour trouver un emploi","Pour visiter sa famille","Pour se détendre et apprendre","Pour vivre à Lyon"],"answer_index":2,"explanation_pt_br":"A autora afirma que a viagem é uma oportunidade para praticar francês e relaxar."}]'::jsonb, 2),
('fr-passage-a2-03', 'fr', 'A2', 'Le monde du travail', 'Marc travaille dans une grande entreprise de technologie depuis trois ans. Il occupe un poste de gestionnaire de projet, ce qui demande beaucoup d''organisation et une excellente communication avec toute son équipe chaque jour.

Le matin, il commence par vérifier ses courriels et répondre aux messages urgents. Ensuite, il participe à une réunion hebdomadaire pour discuter des objectifs de la semaine et résoudre les problèmes techniques rencontrés par les collègues.

La collaboration est essentielle pour réussir dans son métier. Marc aime aider les nouveaux employés à comprendre les outils numériques utilisés par la société. Il pense que partager ses connaissances est très bénéfique pour tout le groupe.

Parfois, le travail est stressant, surtout avant les dates limites. Cependant, Marc apprécie son environnement professionnel moderne et dynamique. Il est fier de contribuer au succès des projets innovants développés par son équipe dévouée.', '[{"prompt":"Depuis combien de temps Marc travaille-t-il dans cette entreprise ?","options":["Une année","Deux ans","Trois ans","Dix ans"],"answer_index":2,"explanation_pt_br":"O texto diz explicitamente ''depuis trois ans''."},{"prompt":"Que veut dire ''dates limites'' ?","options":["Les réunions","Les délais finaux","Les pauses déjeuner","Les messages"],"answer_index":1,"explanation_pt_br":"Refere-se aos prazos ou datas finais para a entrega de tarefas."},{"prompt":"Que fait Marc avec les nouveaux employés ?","options":["Il les forme aux outils","Il les critique","Il les ignore","Il les invite au restaurant"],"answer_index":0,"explanation_pt_br":"O texto menciona que ele gosta de ajudá-los a entender as ferramentas digitais."},{"prompt":"Quel est le sentiment de Marc concernant son travail ?","options":["Il veut changer d''entreprise","Il est fier et satisfait","Il trouve cela ennuyeux","Il est trop stressé"],"answer_index":1,"explanation_pt_br":"Marc demonstra orgulho e apreciação pelo ambiente dinâmico da empresa."}]'::jsonb, 3),
('fr-passage-a2-04', 'fr', 'A2', 'Prendre soin de soi', 'La santé est la priorité de Julie. Elle fait attention à ce qu''elle mange et pratique du sport régulièrement pour rester en forme. Pour elle, un esprit sain commence toujours par un corps bien entretenu.

Chaque samedi matin, elle va courir dans le parc près de chez elle. L''air frais et le calme lui permettent d''oublier le stress de la semaine. Elle aime aussi faire du yoga pour améliorer sa souplesse.

En plus de l''activité physique, Julie boit beaucoup d''eau et privilégie les fruits frais. Elle consulte son médecin une fois par an pour faire un bilan de santé complet, car la prévention est très importante pour elle.

Elle dort huit heures par nuit pour avoir assez d''énergie le lendemain. Grâce à ces habitudes simples, elle se sent toujours dynamique, positive et prête à affronter les défis quotidiens avec beaucoup de détermination et de calme.', '[{"prompt":"Quelle activité Julie pratique-t-elle le samedi ?","options":["La natation","Le yoga","La course à pied","Le tennis"],"answer_index":2,"explanation_pt_br":"O texto menciona especificamente que ela vai correr no parque aos sábados."},{"prompt":"Que signifie ''prévention'' dans ce contexte ?","options":["Le sport intensif","Le traitement des maladies","L''action d''anticiper","Le repos total"],"answer_index":2,"explanation_pt_br":"Prevenção refere-se a agir antes que algo aconteça, para evitar problemas de saúde."},{"prompt":"Pourquoi Julie consulte-t-elle son médecin ?","options":["Parce qu''elle est malade","Pour faire un bilan de santé","Pour acheter des fruits","Pour faire du yoga"],"answer_index":1,"explanation_pt_br":"O texto explica que ela faz um check-up anual para prevenção."},{"prompt":"Quelle est l''idée principale du texte ?","options":["Le sport est dangereux","L''importance des habitudes saines","La vie d''un médecin","Le besoin de dormir peu"],"answer_index":1,"explanation_pt_br":"O foco é descrever as escolhas de vida de Julie para manter a saúde e o bem-estar."}]'::jsonb, 4),
('fr-passage-a2-05', 'fr', 'A2', 'La fête du village', 'Chaque année, le village organise une grande fête pour célébrer les traditions locales. Les habitants préparent des plats typiques, comme la quiche lorraine ou la tarte aux pommes, pour partager avec tous les voisins.

La place principale se transforme en une immense salle à manger en plein air. Les familles installent de longues tables décorées avec des fleurs. C''est l''occasion idéale pour parler et renforcer les liens de la communauté.

La musique traditionnelle résonne dans tout le village. Des musiciens jouent de l''accordéon pendant que les enfants dansent et jouent ensemble. Cette atmosphère joyeuse attire aussi beaucoup de touristes curieux de découvrir cette culture unique.

À la fin de la journée, tout le monde est heureux. Ces moments de partage montrent que les traditions sont vivantes. La fête est un succès qui permet à chacun de se sentir fier de son village.', '[{"prompt":"Que préparent les habitants pour la fête ?","options":["Des pizzas","Des gâteaux au chocolat","Des plats traditionnels","Rien du tout"],"answer_index":2,"explanation_pt_br":"O texto cita que eles preparam pratos típicos, como quiche e torta de maçã."},{"prompt":"Dans le texte, que signifie ''renforcer'' ?","options":["Détruire","Ignorer","Solidifier","Changer"],"answer_index":2,"explanation_pt_br":"Renforcer significa tornar mais forte, neste caso, os laços da comunidade."},{"prompt":"Où se déroule la fête ?","options":["Dans une salle de sport","Sur la place principale","Dans une école","À la mairie"],"answer_index":1,"explanation_pt_br":"O texto indica que a praça principal vira o local da celebração."},{"prompt":"Quel est le but de cette fête ?","options":["Gagner de l''argent","Célébrer les traditions ensemble","Rencontrer des politiciens","Dormir toute la journée"],"answer_index":1,"explanation_pt_br":"A finalidade principal é celebrar as tradições e unir a comunidade."}]'::jsonb, 5),
('fr-passage-a2-06', 'fr', 'A2', 'La technologie à la maison', 'Aujourd''hui, Lucas utilise beaucoup d''appareils numériques dans sa vie quotidienne. Dès son réveil, il consulte son smartphone pour vérifier ses messages et son calendrier. Il trouve que cela facilite son organisation personnelle et professionnelle.

Plus tard, il travaille sur son ordinateur portable. Il participe à des réunions en ligne avec ses collègues qui habitent dans d''autres villes. Cette technologie lui permet de gagner beaucoup de temps chaque semaine.

Le soir, il aime se détendre devant la télévision connectée. Il choisit souvent des documentaires sur des plateformes de streaming pour apprendre des choses intéressantes. Il apprécie la qualité de l''image et la facilité d''utilisation.

Cependant, Lucas pense qu''il est important de faire des pauses. Il éteint tous ses écrans une heure avant de dormir pour mieux se reposer. Il préfère lire un livre en papier pour finir sa longue journée.', '[{"prompt":"Que fait Lucas juste après son réveil ?","options":["Il travaille sur son ordinateur.","Il regarde la télévision.","Il regarde son smartphone.","Il lit un livre en papier."],"answer_index":2,"explanation_pt_br":"O texto afirma explicitamente que, logo ao acordar, Lucas consulta seu smartphone."},{"prompt":"Que signifie le mot ''faciliter'' dans le premier paragraphe ?","options":["Rendre plus difficile.","Rendre plus simple.","Rendre plus rapide.","Rendre plus cher."],"answer_index":1,"explanation_pt_br":"No contexto, facilitar significa tornar algo mais simples ou fácil de realizar."},{"prompt":"Pourquoi Lucas éteint-il ses écrans avant de dormir ?","options":["Parce qu''il n''a plus de batterie.","Parce qu''il veut économiser de l''électricité.","Parce qu''il veut mieux se reposer.","Parce qu''il n''aime pas la technologie."],"answer_index":2,"explanation_pt_br":"O texto menciona que ele desliga os aparelhos para descansar melhor."},{"prompt":"Quel est le thème principal de ce texte ?","options":["Les problèmes de santé des écrans.","L''utilisation quotidienne de la technologie.","Le travail à la maison.","La lecture des livres."],"answer_index":1,"explanation_pt_br":"O texto descreve como Lucas integra diferentes dispositivos tecnológicos em sua rotina diária."}]'::jsonb, 6),
('fr-passage-a2-07', 'fr', 'A2', 'Des choix écologiques', 'Marie habite à Curitiba et elle veut protéger l''environnement. Elle a décidé de faire des changements dans sa maison pour vivre de manière plus durable. Elle trie ses déchets chaque semaine avec beaucoup de soin.

Elle achète souvent des produits locaux au marché du quartier. En choisissant des fruits et des légumes de saison, elle aide les agriculteurs de la région et réduit la pollution liée au transport.

Elle utilise aussi moins d''eau dans la salle de bain et elle éteint la lumière quand elle quitte une pièce. Ces petites habitudes permettent de réduire sa consommation d''énergie de façon très efficace.

Enfin, elle se déplace à vélo pour aller travailler. Elle pense que ces gestes sont importants pour la planète. Elle espère que ses voisins vont suivre son exemple bientôt.', '[{"prompt":"Où Marie achète-t-elle ses fruits et légumes ?","options":["Dans un supermarché lointain.","Au marché du quartier.","Directement chez le voisin.","Sur un site internet."],"answer_index":1,"explanation_pt_br":"O texto diz que ela compra produtos locais no mercado do bairro."},{"prompt":"Que signifie ''trier ses déchets'' ?","options":["Jeter tout ensemble.","Nettoyer les poubelles.","Séparer les matériaux recyclables.","Acheter moins de produits."],"answer_index":2,"explanation_pt_br":"Trier, no contexto de lixo, significa separar os resíduos para reciclagem."},{"prompt":"Quel est l''ordre des actions de Marie pour l''écologie ?","options":["D''abord le vélo, puis le tri.","D''abord le marché, puis le tri.","D''abord le tri, puis le marché.","D''abord la lumière, puis le vélo."],"answer_index":2,"explanation_pt_br":"O texto menciona o tri (parágrafo 1) antes de falar das compras no mercado (parágrafo 2)."},{"prompt":"Quelle est l''idée principale du texte ?","options":["Le recyclage est difficile à faire.","Le vélo est le seul moyen de transport.","Marie adopte un mode de vie plus écologique.","Il faut arrêter de manger des fruits."],"answer_index":2,"explanation_pt_br":"O texto foca nas ações de Marie para viver de forma mais sustentável."}]'::jsonb, 7),
('fr-passage-a2-08', 'fr', 'A2', 'La vie sociale et les amis', 'Paul aime beaucoup passer du temps avec ses amis le week-end. Samedi dernier, il a invité ses collègues à dîner chez lui. Ils ont préparé une grande salade et mangé ensemble dans le jardin.

Ils ont discuté de leurs projets de vacances et de leurs films préférés. Paul pense que ces moments sont essentiels pour maintenir de bonnes relations. Il se sent toujours très heureux après ces rencontres.

Parfois, ils vont au cinéma ou dans un café du centre-ville. Ces sorties permettent de changer d''air et de oublier les problèmes du travail. C''est une habitude qu''ils partagent depuis deux ans.

La semaine prochaine, Paul organise une fête pour l''anniversaire de son amie Julie. Il a déjà envoyé les invitations à tout le monde. Il espère que tout le monde sera présent pour célébrer cet événement.', '[{"prompt":"Qu''ont mangé Paul et ses amis samedi dernier ?","options":["Une pizza au restaurant.","Une grande salade.","Un gâteau d''anniversaire.","Rien du tout."],"answer_index":1,"explanation_pt_br":"O texto diz claramente que prepararam uma grande salada."},{"prompt":"Que signifie ''maintenir de bonnes relations'' ?","options":["Se disputer souvent.","Cesser de parler aux autres.","Entretenir l''amitié.","Ignorer les amis."],"answer_index":2,"explanation_pt_br":"Manter boas relações refere-se ao ato de cultivar e preservar a amizade."},{"prompt":"Quelle est la prochaine activité prévue par Paul ?","options":["Une sortie au cinéma.","Un dîner dans le jardin.","Une fête d''anniversaire.","Un voyage à la plage."],"answer_index":2,"explanation_pt_br":"O último parágrafo menciona que ele está organizando uma festa de aniversário para Julie."},{"prompt":"Pourquoi Paul aime-t-il voir ses amis ?","options":["Pour parler du travail.","Pour oublier ses problèmes.","Pour cuisiner des plats compliqués.","Pour dormir chez eux."],"answer_index":1,"explanation_pt_br":"O texto afirma que as saídas permitem esquecer os problemas do trabalho."}]'::jsonb, 8),
('fr-passage-a2-09', 'fr', 'A2', 'Gérer son argent', 'Sophie travaille dans une banque et elle fait très attention à son budget. Chaque mois, elle note toutes ses dépenses dans un petit carnet. Elle veut économiser pour voyager en Europe l''année prochaine.

Elle évite les achats inutiles. Avant d''acheter un nouveau vêtement, elle réfléchit pendant deux jours. Elle demande toujours si elle a vraiment besoin de cet objet avant de sortir sa carte bancaire.

Elle cuisine souvent à la maison au lieu d''aller au restaurant tous les jours. Cela lui permet de faire des économies importantes. Elle trouve que c''est une méthode simple pour avoir un budget équilibré.

Sophie partage aussi ses conseils avec ses amis. Elle pense que la gestion financière est une compétence utile pour tout le monde. Avec de la discipline, elle est sûre de réaliser son projet de voyage.', '[{"prompt":"Pourquoi Sophie note-t-elle ses dépenses ?","options":["Pour travailler à la banque.","Pour économiser pour un voyage.","Pour acheter de nouveaux vêtements.","Pour aider ses amis."],"answer_index":1,"explanation_pt_br":"O texto menciona que ela economiza para viajar para a Europa."},{"prompt":"Que signifie ''dépenses'' dans le texte ?","options":["L''argent gagné.","L''argent qu''on donne.","Le temps libre.","Le travail quotidien."],"answer_index":1,"explanation_pt_br":"Dépenses refere-se ao dinheiro gasto (despesas)."},{"prompt":"Quelle est la méthode de Sophie pour les vêtements ?","options":["Elle achète tout en solde.","Elle réfléchit avant d''acheter.","Elle demande à ses amis.","Elle achète uniquement en ligne."],"answer_index":1,"explanation_pt_br":"O texto diz que ela reflete por dois dias antes de comprar uma roupa nova."},{"prompt":"Quel est le message principal du texte ?","options":["Il faut travailler dans une banque.","Le restaurant est mauvais pour la santé.","La discipline aide à gérer son argent.","Voyager est très cher."],"answer_index":2,"explanation_pt_br":"O texto destaca a importância da disciplina financeira para atingir objetivos."}]'::jsonb, 9),
('fr-passage-a2-10', 'fr', 'A2', 'Apprendre toute la vie', 'Marc aime apprendre de nouvelles choses, même s''il a déjà terminé ses études universitaires. Il pense que l''éducation ne s''arrête jamais. Il s''inscrit régulièrement à des cours en ligne sur Internet.

Ce mois-ci, il apprend la photographie. Il regarde des vidéos et il pratique avec son appareil photo le week-end. Il trouve cette nouvelle activité passionnante et très relaxante après son travail.

L''année dernière, il a étudié l''espagnol dans une école de langues. Il voulait pouvoir parler avec ses voisins qui viennent de Madrid. Apprendre une langue est une expérience très enrichissante pour lui.

Il encourage aussi ses collègues à suivre des formations. Marc croit que le savoir est une richesse personnelle. Il cherche toujours des opportunités pour améliorer ses compétences professionnelles et personnelles chaque année.', '[{"prompt":"Quelle activité Marc fait-il ce mois-ci ?","options":["Il apprend l''espagnol.","Il étudie à l''université.","Il apprend la photographie.","Il donne des cours."],"answer_index":2,"explanation_pt_br":"O segundo parágrafo afirma que ele está aprendendo fotografia este mês."},{"prompt":"Que signifie ''enrichissante'' ?","options":["Qui coûte beaucoup d''argent.","Qui apporte quelque chose de positif.","Qui est très difficile.","Qui est inutile."],"answer_index":1,"explanation_pt_br":"Algo enriquecedor é algo que traz um valor positivo ou desenvolvimento pessoal."},{"prompt":"Quelle est la chronologie des études de Marc ?","options":["Espagnol, puis photographie.","Photographie, puis espagnol.","Université, puis espagnol.","Photographie, puis université."],"answer_index":2,"explanation_pt_br":"Ele terminou a universidade, depois estudou espanhol no ano passado e agora faz fotografia."},{"prompt":"Quel est l''objectif de Marc en apprenant ?","options":["Gagner plus d''argent.","Avoir moins de travail.","Améliorer ses compétences.","Devenir un professeur."],"answer_index":2,"explanation_pt_br":"O texto menciona que ele busca melhorar suas competências profissionais e pessoais."}]'::jsonb, 10),
('fr-passage-b1-01', 'fr', 'B1', 'Une nouvelle autonomie', 'Depuis que Marc a déménagé dans son propre appartement, sa routine a radicalement changé. Auparavant, il vivait chez ses parents et ne s''occupait jamais des tâches ménagères. Aujourd''hui, il doit apprendre à gérer son emploi du temps de manière autonome, ce qui demande une organisation rigoureuse au quotidien.

Le matin, Marc se lève à sept heures précises. Il commence par préparer un café fort avant de consulter ses courriels. Ensuite, il prend le temps de faire un peu de sport, car cela l''aide à se concentrer pour la journée. Cette habitude matinale est devenue essentielle pour son équilibre personnel et son efficacité.

Après le sport, il se consacre aux corvées domestiques. Il a appris à utiliser le lave-linge et à faire les courses de façon hebdomadaire. Bien que cela puisse paraître fastidieux, il apprécie le sentiment de contrôle qu''il ressent en maintenant son intérieur propre et ordonné. Il a même commencé à cuisiner des recettes simples.

L''après-midi est dédié à son travail de bureau. Il préfère travailler dans le calme de son salon, où il a installé un petit bureau confortable. Il évite de regarder son téléphone pendant ces heures pour rester productif. Vers dix-sept heures, il termine ses tâches et s''accorde une petite pause pour lire ou écouter de la musique.

Le soir, Marc aime préparer un repas léger tout en écoutant la radio. Il se couche généralement tôt pour être en forme le lendemain. Cette nouvelle vie, bien que exigeante, lui apporte une satisfaction profonde. Il réalise enfin que l''indépendance est un processus d''apprentissage continu qui demande de la discipline et de la patience.', '[{"prompt":"Qu''est-ce qui a le plus changé dans la vie de Marc ?","options":["Il travaille désormais dans un bureau prestigieux.","Il doit gérer seul ses responsabilités quotidiennes.","Il a arrêté de faire du sport le matin.","Il ne parle plus avec ses parents."],"answer_index":1,"explanation_pt_br":"O texto enfatiza que ele deixou a casa dos pais e agora precisa ser autônomo nas tarefas domésticas e na rotina."},{"prompt":"Que signifie le mot ''fastidieux'' dans le troisième paragraphe ?","options":["Amusant et très stimulant.","Rapide et facile à accomplir.","Ennuyeux ou répétitif.","Dangereux pour la santé."],"answer_index":2,"explanation_pt_br":"No contexto das tarefas domésticas, ''fastidieux'' refere-se a algo que é monótono ou cansativo."},{"prompt":"Quelle est la première action de Marc après le réveil ?","options":["Il fait du sport intensif.","Il prépare un café.","Il fait ses courses.","Il nettoie son appartement."],"answer_index":1,"explanation_pt_br":"O segundo parágrafo indica que, após levantar, ele começa preparando um café forte."},{"prompt":"Où Marc travaille-t-il l''après-midi ?","options":["Dans une grande entreprise.","Dans une bibliothèque publique.","Dans son salon personnel.","Dans un café du quartier."],"answer_index":2,"explanation_pt_br":"O quarto parágrafo especifica que ele montou um escritório confortável em sua sala de estar."},{"prompt":"Quel est le sentiment principal de Marc concernant sa nouvelle routine ?","options":["Il regrette son ancienne vie chez ses parents.","Il se sent dépassé par trop de responsabilités.","Il trouve cette vie difficile mais gratifiante.","Il s''ennuie énormément chaque jour."],"answer_index":2,"explanation_pt_br":"O último parágrafo conclui que, apesar de ser exigente, ele sente uma profunda satisfação."}]'::jsonb, 1),
('fr-passage-b1-02', 'fr', 'B1', 'Escapade dans le sud', 'Julie a toujours rêvé de découvrir le sud de la France. Après des mois d''économie, elle a enfin réservé un voyage d''une semaine dans la région de Provence. Elle cherche non seulement à se reposer, mais aussi à s''imprégner de la culture locale, des paysages colorés et des traditions provençales qui font la renommée de cette zone.

Le premier jour, elle est arrivée à Avignon sous un soleil radieux. Elle a immédiatement visité le Palais des Papes, un monument historique impressionnant. En marchant dans les ruelles étroites, elle a remarqué l''architecture médiévale préservée. C''était le début d''une aventure culturelle qu''elle attendait depuis bien longtemps avec beaucoup d''enthousiasme et de curiosité.

Le lendemain, Julie a loué un vélo pour explorer les champs de lavande. La vue était spectaculaire et le parfum des fleurs était enivrant. Elle a rencontré un agriculteur local qui lui a expliqué comment il récolte la lavande de manière artisanale. Cet échange a été le moment fort de son voyage, car il lui a permis de comprendre le lien profond entre la terre et les habitants.

Au cours de la semaine, elle a également visité plusieurs marchés provençaux. Elle y a acheté des produits locaux comme du miel et de l''huile d''olive. Chaque interaction avec les commerçants était une occasion de pratiquer son français et d''en apprendre davantage sur les coutumes régionales. Ces petits moments de partage ont rendu son séjour inoubliable et très authentique.

En rentrant chez elle, Julie se sent transformée par cette expérience. Voyager ne signifie pas seulement voir de nouveaux endroits, mais aussi s''ouvrir à de nouvelles perspectives. Elle a déjà hâte de planifier sa prochaine aventure, convaincue que chaque voyage enrichit sa compréhension du monde et renforce son désir de découvrir de nouveaux horizons culturels.', '[{"prompt":"Pourquoi Julie a-t-elle choisi la Provence ?","options":["Pour visiter sa famille.","Pour travailler dans les champs.","Pour se reposer et découvrir la culture.","Pour acheter une maison de vacances."],"answer_index":2,"explanation_pt_br":"O primeiro parágrafo afirma que ela busca descansar e conhecer a cultura, as paisagens e as tradições."},{"prompt":"Quel est le ''moment fort'' du voyage selon Julie ?","options":["La visite du Palais des Papes.","La rencontre avec un agriculteur.","L''achat de miel sur le marché.","La location d''un vélo confortable."],"answer_index":1,"explanation_pt_br":"O terceiro parágrafo descreve a conversa com o agricultor como o ponto alto da viagem."},{"prompt":"Que signifie l''adjectif ''enivrant'' dans le troisième paragraphe ?","options":["Qui est très calme et ennuyeux.","Qui est difficile à trouver.","Qui séduit ou enivre par son odeur.","Qui est très sombre et inquiétant."],"answer_index":2,"explanation_pt_br":"No contexto, o perfume das flores é tão forte e agradável que ''enivrant'' significa que encanta ou embriaga os sentidos."},{"prompt":"Comment Julie a-t-elle pratiqué son français pendant son voyage ?","options":["En regardant la télévision locale.","En parlant avec les commerçants.","En lisant des livres historiques.","En écoutant des guides touristiques."],"answer_index":1,"explanation_pt_br":"O quarto parágrafo menciona explicitamente que as interações com os comerciantes foram a oportunidade para praticar o idioma."},{"prompt":"Quelle est l''idée principale du dernier paragraphe ?","options":["Les voyages sont trop coûteux pour être répétés.","Le voyage a changé la vision du monde de Julie.","La Provence est le plus bel endroit de France.","Julie préfère désormais rester chez elle."],"answer_index":1,"explanation_pt_br":"O texto conclui que a viagem a transformou e ampliou sua perspectiva de vida."}]'::jsonb, 2),
('fr-passage-b1-03', 'fr', 'B1', 'La communication au travail', 'Dans le monde professionnel actuel, une communication efficace est devenue le pilier de toute réussite collective. Thomas, chef de projet dans une entreprise de technologie, insiste souvent sur l''importance de la clarté dans les échanges. Il pense que les malentendus proviennent souvent d''une mauvaise interprétation des messages, ce qui peut freiner considérablement l''avancement des projets en cours.

Chaque lundi matin, Thomas organise une réunion d''équipe pour définir les objectifs de la semaine. Il encourage ses collaborateurs à poser des questions et à exprimer leurs préoccupations sans crainte. Selon lui, le feedback régulier est indispensable pour ajuster les stratégies. Cette culture de transparence permet de créer un environnement de travail sain et productif.

La technologie joue également un rôle clé dans la communication de son équipe. Ils utilisent des outils de messagerie instantanée pour les échanges rapides et des plateformes de gestion de projets pour le suivi des tâches. Cependant, Thomas rappelle que ces outils ne doivent jamais remplacer totalement les discussions en face à face, qui permettent de mieux comprendre les émotions des collègues.

Il arrive parfois que des conflits surviennent entre les membres de l''équipe. Dans ces situations, Thomas intervient toujours avec diplomatie. Il privilégie l''écoute active pour laisser chaque partie exprimer son point de vue. Il estime que résoudre un problème ensemble renforce la cohésion du groupe et permet d''éviter la répétition des mêmes erreurs à l''avenir.

En conclusion, la communication professionnelle demande des efforts constants et une grande adaptabilité. Ce n''est pas seulement transmettre des informations, mais aussi bâtir des relations de confiance. Pour Thomas, un manager qui sait écouter est le meilleur atout pour garantir la motivation et la loyauté de ses employés, assurant ainsi la pérennité de l''entreprise.', '[{"prompt":"Quelle est l''opinion de Thomas sur les malentendus au travail ?","options":["Ils sont inévitables et sans importance.","Ils sont causés par une mauvaise interprétation.","Ils aident à améliorer la créativité.","Ils sont la faute des outils technologiques."],"answer_index":1,"explanation_pt_br":"O primeiro parágrafo afirma que ele acredita que os mal-entendidos vêm de uma interpretação errada das mensagens."},{"prompt":"Pourquoi Thomas organise-t-il des réunions le lundi ?","options":["Pour vérifier les heures de travail.","Pour critiquer les erreurs passées.","Pour fixer les objectifs hebdomadaires.","Pour manger avec ses collègues."],"answer_index":2,"explanation_pt_br":"O segundo parágrafo explica que o objetivo é definir os objetivos da semana."},{"prompt":"Que pense Thomas des outils technologiques de communication ?","options":["Ils doivent remplacer les réunions physiques.","Ils sont inutiles pour le travail moderne.","Ils sont utiles mais ne remplacent pas le contact humain.","Ils sont la seule source de conflits."],"answer_index":2,"explanation_pt_br":"O terceiro parágrafo diz que, embora úteis, não devem substituir as conversas presenciais."},{"prompt":"Que signifie l''expression ''écoute active'' dans le quatrième paragraphe ?","options":["Écouter tout en faisant autre chose.","Écouter avec attention pour bien comprendre.","Écouter seulement ce qui nous intéresse.","Écouter sans jamais répondre."],"answer_index":1,"explanation_pt_br":"A ''escuta ativa'' é uma técnica de comunicação focada em ouvir atentamente para compreender a mensagem do interlocutor."},{"prompt":"Quel est le but ultime de la méthode de management de Thomas ?","options":["Réduire le salaire des employés.","Garantir la motivation et la confiance.","Travailler le plus vite possible.","Éviter tout contact avec les clients."],"answer_index":1,"explanation_pt_br":"O último parágrafo destaca que o objetivo é garantir a motivação e a lealdade dos empregados."}]'::jsonb, 3),
('fr-passage-b1-04', 'fr', 'B1', 'Vivre sainement', 'Le bien-être est devenu une priorité pour beaucoup de personnes dans notre société moderne. Sophie, une infirmière passionnée, consacre une grande partie de son temps libre à sensibiliser son entourage aux bonnes habitudes de santé. Elle croit fermement que de petits changements dans le mode de vie peuvent avoir un impact significatif sur la santé physique et mentale à long terme.

Le premier pilier de la santé, selon Sophie, est une alimentation équilibrée. Elle suggère de privilégier les aliments frais et locaux plutôt que les produits transformés, souvent riches en sucres et en graisses saturées. Elle prépare elle-même ses repas pour contrôler la qualité des ingrédients. Pour elle, cuisiner est un acte de respect envers son propre corps et son énergie.

Le deuxième pilier est l''activité physique régulière. Sophie recommande au moins trente minutes de marche par jour. Elle explique que le mouvement aide non seulement à maintenir un poids stable, mais aussi à réduire le stress et à améliorer la qualité du sommeil. Elle pratique régulièrement le yoga pour renforcer sa souplesse et trouver un moment de calme intérieur.

La gestion du stress est le troisième aspect crucial. Dans un monde où tout va très vite, il est facile de se laisser submerger. Sophie pratique la méditation chaque soir avant de se coucher. Cela lui permet de déconnecter après des journées de travail intenses à l''hôpital. Elle insiste sur le fait que le repos n''est pas un luxe, mais une nécessité biologique.

Enfin, Sophie rappelle que la santé est un équilibre personnel. Il ne s''agit pas de suivre des règles strictes de manière obsessionnelle, mais de trouver ce qui fonctionne pour soi. En prenant soin de sa santé, on est mieux armé pour affronter les défis quotidiens et profiter pleinement de la vie avec ses proches, ce qui constitue le véritable bonheur.', '[{"prompt":"Quel est le métier de Sophie ?","options":["Professeure de yoga.","Diététicienne.","Infirmière.","Médecin généraliste."],"answer_index":2,"explanation_pt_br":"O primeiro parágrafo identifica Sophie como uma enfermeira apaixonada."},{"prompt":"Pourquoi Sophie prépare-t-elle ses repas elle-même ?","options":["Pour économiser beaucoup d''argent.","Pour contrôler la qualité des ingrédients.","Parce qu''elle n''aime pas les restaurants.","Parce qu''elle ne sait pas acheter en magasin."],"answer_index":1,"explanation_pt_br":"O segundo parágrafo diz que ela prepara as refeições para controlar a qualidade dos ingredientes."},{"prompt":"Quelle activité Sophie pratique-t-elle pour sa souplesse ?","options":["La course à pied.","La natation.","Le yoga.","La musculation."],"answer_index":2,"explanation_pt_br":"O terceiro parágrafo menciona que ela pratica yoga para reforçar sua flexibilidade."},{"prompt":"Que fait Sophie pour gérer le stress ?","options":["Elle regarde la télévision.","Elle pratique la méditation.","Elle travaille plus longtemps.","Elle boit beaucoup de café."],"answer_index":1,"explanation_pt_br":"O quarto parágrafo explica que ela medita todas as noites antes de dormir."},{"prompt":"Quelle est la conclusion principale de Sophie ?","options":["Il faut suivre des règles très strictes.","Le bien-être est un équilibre personnel.","La santé est impossible dans la société moderne.","Le travail est plus important que la santé."],"answer_index":1,"explanation_pt_br":"O último parágrafo enfatiza que a saúde é um equilíbrio pessoal e não uma regra rígida."}]'::jsonb, 4),
('fr-passage-b1-05', 'fr', 'B1', 'La fête du partage', 'Dans le petit village de Saint-Céneri, la fête annuelle du village est un événement très attendu. Chaque année, en automne, les habitants se réunissent pour célébrer les récoltes et partager un grand repas communautaire. Cette tradition, qui remonte à plusieurs générations, renforce les liens entre les voisins et permet de transmettre les valeurs locales aux plus jeunes générations.

La préparation commence plusieurs semaines à l''avance. Chaque famille apporte une spécialité culinaire préparée avec les produits de saison. On y trouve des tartes aux pommes, du pain artisanal et des plats mijotés avec les légumes du jardin. L''odeur des épices et du pain chaud embaume les rues, créant une atmosphère chaleureuse et accueillante pour tous les visiteurs.

Le jour de la fête, la place principale est décorée avec des fleurs et des guirlandes. Les anciens du village racontent des histoires sur le passé, tandis que les enfants jouent dans le parc. Il y a une véritable sensation de communauté où chacun se sent à sa place. C''est le moment idéal pour oublier les soucis quotidiens et célébrer la simplicité de la vie.

Le repas se déroule sur de longues tables installées au centre du village. Le partage est le mot d''ordre de cette journée. Même les inconnus sont invités à se joindre à la fête. Pour les habitants, c''est une manière de montrer leur générosité et leur hospitalité, des qualités essentielles dans cette région de France où l''entraide est très valorisée.

La soirée se termine souvent par de la musique traditionnelle et des danses folkloriques. Cette fête est bien plus qu''un simple repas ; elle représente l''identité du village. En protégeant ces traditions, les habitants de Saint-Céneri veillent à ce que leur culture reste vivante. C''est une célébration qui rappelle l''importance de l''unité dans un monde qui change rapidement.', '[{"prompt":"Quel est l''objectif principal de la fête à Saint-Céneri ?","options":["Gagner de l''argent pour le village.","Célébrer les récoltes et renforcer les liens.","Attirer des touristes étrangers.","Élire le nouveau maire du village."],"answer_index":1,"explanation_pt_br":"O primeiro parágrafo diz que os habitantes se reúnem para celebrar as colheitas e fortalecer os laços."},{"prompt":"Que signifie l''expression ''embaume les rues'' dans le deuxième paragraphe ?","options":["Les rues sont sales.","Les rues sont très calmes.","Les rues sont remplies d''odeurs agréables.","Les rues sont décorées de lumières."],"answer_index":2,"explanation_pt_br":"No contexto, o cheiro de especiarias e pão perfuma as ruas."},{"prompt":"Qui est invité à manger pendant la fête ?","options":["Seulement les familles riches.","Uniquement les anciens du village.","Tout le monde, même les inconnus.","Seulement les personnes nées au village."],"answer_index":2,"explanation_pt_br":"O quarto parágrafo afirma que até mesmo os estranhos são convidados."},{"prompt":"Quel est le ''mot d''ordre'' de la fête selon le quatrième paragraphe ?","options":["La compétition.","Le silence.","Le partage.","Le travail."],"answer_index":2,"explanation_pt_br":"O texto declara explicitamente que o ''partage'' (compartilhamento) é a palavra de ordem."},{"prompt":"Pourquoi est-il important de protéger ces traditions ?","options":["Pour éviter de devoir travailler.","Pour maintenir l''identité et la culture du village.","Pour augmenter la population du village.","Pour cacher le passé aux nouvelles générations."],"answer_index":1,"explanation_pt_br":"O último parágrafo explica que proteger as tradições ajuda a manter a cultura e a identidade do vilarejo vivas."}]'::jsonb, 5),
('fr-passage-b1-06', 'fr', 'B1', 'La révolution numérique au quotidien', 'La technologie occupe désormais une place centrale dans notre vie quotidienne, transformant radicalement nos habitudes. Chaque matin, dès le réveil, nous consultons nos smartphones pour vérifier les nouvelles, consulter nos courriels professionnels ou planifier notre journée. Cette omniprésence numérique facilite grandement la gestion de nos tâches, mais elle impose également un rythme soutenu qui peut s''avérer stressant pour beaucoup d''utilisateurs.

Le télétravail est devenu une pratique courante, soutenue par des outils de communication performants comme la vidéoconférence. Ces plateformes permettent aux équipes dispersées géographiquement de collaborer efficacement sans avoir besoin de se déplacer physiquement. Cette flexibilité géographique offre un meilleur équilibre entre la vie personnelle et professionnelle pour ceux qui savent organiser leur temps de manière autonome et rigoureuse.

Cependant, cette dépendance technologique soulève des questions sur la déconnexion. Beaucoup de gens ressentent une pression sociale pour être joignables à tout moment, ce qui nuit parfois à la qualité de leur repos. Il devient essentiel d''apprendre à mettre des limites pour préserver sa santé mentale, en pratiquant par exemple des périodes sans écrans durant les soirées ou les week-ends.

L''intelligence artificielle commence également à jouer un rôle discret mais significatif dans nos foyers. Des appareils intelligents régulent le chauffage, gèrent la sécurité ou aident aux courses hebdomadaires. Bien que ces innovations simplifient la gestion domestique, elles nécessitent une certaine vigilance concernant la protection des données personnelles, un sujet devenu crucial à l''ère du tout connecté.

En conclusion, si la technologie apporte des bénéfices incontestables en termes d''efficacité et de confort, elle demande une utilisation réfléchie. Il ne s''agit pas de rejeter ces outils, mais de les maîtriser pour qu''ils restent des alliés au service de notre bien-être plutôt que des sources de distraction constante. L''équilibre reste la clé pour naviguer sereinement dans ce monde hyperconnecté.', '[{"prompt":"Quel est l''effet principal du télétravail mentionné dans le texte ?","options":["Il réduit la nécessité de compétences organisationnelles.","Il permet une meilleure collaboration à distance.","Il oblige les employés à voyager très fréquemment.","Il élimine totalement les besoins de communication."],"answer_index":1,"explanation_pt_br":"O texto afirma que ferramentas de videoconferência permitem que equipes dispersas colaborem de forma eficiente."},{"prompt":"Que signifie l''expression ''omniprésence numérique'' dans le premier paragraphe ?","options":["Une technologie rare et difficile à trouver.","Le fait que la technologie est partout.","Une méthode de travail ancienne et dépassée.","Le rejet total des appareils électroniques."],"answer_index":1,"explanation_pt_br":"O termo sugere que a tecnologia está presente em todos os lugares e momentos do cotidiano."},{"prompt":"Pourquoi l''auteur recommande-t-il des périodes sans écrans ?","options":["Pour économiser de l''énergie électrique.","Pour apprendre à réparer les smartphones.","Pour améliorer la qualité du repos.","Parce que les écrans tombent souvent en panne."],"answer_index":2,"explanation_pt_br":"O autor menciona que o uso excessivo prejudica o descanso e sugere limites para preservar a saúde mental."},{"prompt":"Quelle préoccupation est liée à l''utilisation de l''intelligence artificielle à la maison ?","options":["La difficulté à installer les logiciels.","La sécurité des données personnelles.","Le coût trop élevé des appareils.","La mauvaise qualité du chauffage."],"answer_index":1,"explanation_pt_br":"O texto alerta que a IA requer vigilância sobre a proteção de dados pessoais."},{"prompt":"Quel est le message principal de ce texte ?","options":["Il faut arrêter d''utiliser la technologie.","La technologie est inutile pour le travail.","Il faut utiliser la technologie avec modération.","Le télétravail est la seule solution pour l''avenir."],"answer_index":2,"explanation_pt_br":"O texto argumenta que a tecnologia é benéfica, mas exige um uso refletido e equilibrado."}]'::jsonb, 6),
('fr-passage-b1-07', 'fr', 'B1', 'Vers un mode de vie durable', 'Face aux défis climatiques actuels, adopter des gestes écoresponsables devient une priorité pour de nombreux citoyens. Ce changement de comportement ne se limite pas au recyclage des déchets ; il englobe une réflexion globale sur notre manière de consommer et de nous déplacer. Chaque petit geste compte pour réduire notre empreinte carbone et protéger les ressources naturelles de notre planète pour les générations futures.

L''alimentation locale représente l''un des piliers de cette transition écologique. En achetant des produits de saison cultivés dans notre région, nous soutenons les agriculteurs locaux tout en réduisant les émissions de gaz à effet de serre liées au transport des marchandises sur de longues distances. C''est un acte de consommation conscient qui favorise également une alimentation plus saine et plus riche en nutriments essentiels.

La gestion de l''énergie à la maison est un autre aspect fondamental pour limiter notre impact environnemental. L''isolation thermique des bâtiments, l''utilisation d''appareils électroménagers moins gourmands en électricité ou la réduction du chauffage en hiver sont autant de solutions efficaces. Ces efforts permettent non seulement de réaliser des économies financières substantielles, mais ils participent activement à la préservation des ressources énergétiques globales.

Par ailleurs, la réduction des déchets plastiques est un combat quotidien que beaucoup d''entre nous mènent avec détermination. Remplacer les emballages jetables par des alternatives réutilisables, comme des gourdes en inox ou des sacs en tissu, est une habitude simple à adopter. Cette démarche de réduction à la source est beaucoup plus efficace que le simple recyclage, car elle évite la production de déchets inutiles.

En conclusion, la transition écologique est une responsabilité partagée qui demande de la persévérance. Bien que les changements individuels puissent sembler modestes à l''échelle mondiale, leur accumulation génère un impact significatif sur l''environnement. En faisant des choix plus durables chaque jour, nous contribuons collectivement à bâtir un avenir plus respectueux de la nature et de la santé humaine.', '[{"prompt":"Pourquoi privilégier les produits de saison locaux ?","options":["Parce qu''ils sont toujours moins chers.","Pour réduire les émissions de gaz liées au transport.","Parce qu''ils sont exportés dans le monde entier.","Pour éviter de manger des légumes frais."],"answer_index":1,"explanation_pt_br":"O texto explica que comprar produtos locais reduz as emissões de gases de efeito estufa do transporte."},{"prompt":"Que signifie ''écoresponsables'' dans le premier paragraphe ?","options":["Des actions qui respectent l''environnement.","Des décisions basées uniquement sur le prix.","Des activités liées à la technologie moderne.","Des comportements qui augmentent la pollution."],"answer_index":0,"explanation_pt_br":"O termo refere-se a práticas que levam em conta o impacto ambiental."},{"prompt":"Quelle action est jugée plus efficace que le recyclage ?","options":["Acheter plus d''emballages plastiques.","Produire davantage de déchets jetables.","Réduire les déchets à la source.","Ignorer la gestion des ressources."],"answer_index":2,"explanation_pt_br":"O quarto parágrafo afirma que reduzir o lixo na fonte é mais eficaz do que apenas reciclar."},{"prompt":"Quels sont les avantages d''une meilleure isolation thermique ?","options":["Une augmentation des factures d''énergie.","Une maison plus chaude en été seulement.","Des économies financières et une préservation des ressources.","Une réduction du confort à la maison."],"answer_index":2,"explanation_pt_br":"O texto cita que isolar bem a casa traz economia financeira e preserva recursos energéticos."},{"prompt":"Quel est le ton général de ce texte ?","options":["Pessimiste et décourageant.","Incitant et encourageant.","Technique et trop complexe.","Indifférent et neutre."],"answer_index":1,"explanation_pt_br":"O autor incentiva o leitor a adotar hábitos sustentáveis, mostrando que pequenas ações importam."}]'::jsonb, 7),
('fr-passage-b1-08', 'fr', 'B1', 'L''importance des liens sociaux', 'Dans notre société actuelle, la qualité des relations humaines demeure essentielle pour notre équilibre émotionnel. Malgré la multiplication des réseaux sociaux qui facilitent les échanges virtuels, le besoin de contacts réels et authentiques reste primordial. Les interactions en face à face permettent de créer des liens plus profonds et durables, fondés sur l''empathie, l''écoute active et le partage d''expériences vécues ensemble.

Le milieu professionnel est également un lieu privilégié pour tisser des relations sociales importantes. Travailler en équipe ne signifie pas seulement atteindre des objectifs communs, mais aussi apprendre à connaître ses collègues, à respecter leurs différences et à collaborer dans un climat de confiance. Ces relations de travail peuvent souvent évoluer vers des amitiés solides, enrichissant ainsi notre vie bien au-delà des heures de bureau.

Cependant, maintenir des liens sociaux demande du temps et des efforts constants. Avec le rythme effréné de la vie moderne, il est parfois difficile de trouver des moments pour voir ses amis ou sa famille. Il est donc crucial de prioriser ces moments de convivialité, qu''il s''agisse d''un simple café, d''un dîner ou d''une activité sportive partagée, pour ne pas s''isoler dans une routine uniquement centrée sur le travail.

Les associations et les clubs de loisirs jouent un rôle majeur dans la création de nouveaux liens. En participant à des activités communes, comme le bénévolat, le sport ou des cours d''art, nous rencontrons des personnes qui partagent nos centres d''intérêt. Ces espaces favorisent la mixité sociale et permettent de sortir de son cercle habituel pour découvrir d''autres perspectives et enrichir sa vision du monde.

En somme, cultiver ses relations sociales est un investissement précieux pour soi-même et pour les autres. La solitude peut être un choix, mais l''isolement subi est une réalité difficile. En multipliant les occasions de rencontre et en valorisant la qualité des échanges humains, nous renforçons notre sentiment d''appartenance et contribuons à une communauté plus solidaire et plus chaleureuse.', '[{"prompt":"Selon le texte, quel est l''avantage des interactions en face à face ?","options":["Elles sont plus rapides que les réseaux sociaux.","Elles permettent de créer des liens plus profonds.","Elles ne demandent aucun effort de communication.","Elles évitent d''avoir à parler aux gens."],"answer_index":1,"explanation_pt_br":"O texto afirma que o contato presencial permite conexões mais profundas baseadas na empatia."},{"prompt":"Que signifie l''expression ''rythme effréné'' dans le troisième paragraphe ?","options":["Un rythme très calme et lent.","Un rythme très rapide et intense.","Un rythme qui n''existe plus.","Un rythme que personne ne suit."],"answer_index":1,"explanation_pt_br":"O contexto sugere uma vida moderna acelerada que dificulta ver os amigos."},{"prompt":"Pourquoi les associations sont-elles importantes ?","options":["Elles permettent de rencontrer des gens ayant des intérêts communs.","Elles obligent tout le monde à faire du sport.","Elles sont le seul endroit pour se faire des amis.","Elles empêchent les gens de travailler."],"answer_index":0,"explanation_pt_br":"O autor indica que clubes e associações ajudam a encontrar pessoas com interesses parecidos."},{"prompt":"Quelle est la recommandation de l''auteur concernant la vie sociale ?","options":["Il faut privilégier les contacts virtuels.","Il faut travailler plus pour avoir plus d''amis.","Il faut prioriser des moments de convivialité.","Il faut s''isoler pour être plus heureux."],"answer_index":2,"explanation_pt_br":"O texto sugere priorizar momentos de convívio para evitar o isolamento."},{"prompt":"Quel est le thème central de ce texte ?","options":["La gestion du temps au travail.","L''importance de la vie associative.","La valeur des relations humaines.","Le fonctionnement des réseaux sociaux."],"answer_index":2,"explanation_pt_br":"O texto discute a importância de cultivar relações humanas para o bem-estar."}]'::jsonb, 8),
('fr-passage-b1-09', 'fr', 'B1', 'Maîtriser son budget au quotidien', 'La gestion des finances personnelles est une compétence indispensable pour vivre sereinement dans le monde actuel. Beaucoup de gens se sentent submergés par leurs dépenses quotidiennes, ne sachant pas toujours où va leur argent à la fin du mois. Apprendre à établir un budget clair est la première étape pour reprendre le contrôle de sa situation financière et éviter les dettes inutiles.

La consommation responsable joue un rôle clé dans la santé de notre portefeuille. Avant d''effectuer un achat, il est utile de se demander si l''objet est réellement nécessaire. La publicité nous incite souvent à consommer par impulsion, ce qui peut rapidement déséquilibrer un budget mensuel. En pratiquant la réflexion avant l''achat, nous pouvons économiser des sommes importantes sur le long terme.

L''épargne constitue également un pilier essentiel de la sécurité financière. Même de petites sommes mises de côté régulièrement peuvent constituer un fonds d''urgence précieux en cas d''imprévu, comme une réparation automobile ou des frais médicaux soudains. Cette discipline financière procure une tranquillité d''esprit non négligeable, permettant d''affronter les aléas de la vie avec plus de confiance et de sérénité.

L''utilisation intelligente des outils numériques facilite désormais le suivi de nos comptes. De nombreuses applications bancaires permettent d''analyser nos habitudes de dépense en temps réel, classant nos achats par catégories. Cette transparence nous aide à identifier les postes où nous pourrions réduire nos coûts, comme les abonnements inutilisés ou les sorties trop fréquentes, pour mieux prioriser nos dépenses futures.

En conclusion, gérer son argent n''est pas une contrainte, mais un moyen d''atteindre ses objectifs personnels. En associant une discipline de base, une consommation réfléchie et une épargne régulière, chacun peut améliorer sa situation. Une bonne maîtrise financière ne signifie pas se priver de tout, mais faire des choix éclairés qui correspondent à nos véritables priorités et à nos valeurs de vie.', '[{"prompt":"Quelle est la première étape conseillée pour gérer ses finances ?","options":["Faire des achats par impulsion.","Établir un budget clair.","Demander un prêt à la banque.","Ignorer ses dépenses quotidiennes."],"answer_index":1,"explanation_pt_br":"O primeiro parágrafo afirma que fazer um orçamento claro é o passo inicial para retomar o controle financeiro."},{"prompt":"Que signifie ''achat par impulsion'' dans le deuxième paragraphe ?","options":["Un achat réfléchi et planifié.","Un achat fait sans réflexion préalable.","Un achat pour une autre personne.","Un achat que l''on ne peut pas payer."],"answer_index":1,"explanation_pt_br":"Compras por impulso são feitas sem planejamento, conforme o texto sugere."},{"prompt":"Quel est l''intérêt du fonds d''urgence mentionné ?","options":["Partir en vacances de luxe.","Acheter des objets inutiles.","Faire face à des dépenses imprévues.","Investir en bourse rapidement."],"answer_index":2,"explanation_pt_br":"O terceiro parágrafo diz que o fundo serve para situações inesperadas."},{"prompt":"Comment les applications bancaires aident-elles l''utilisateur ?","options":["En automatisant les achats de produits.","En analysant les habitudes de dépense.","En augmentant automatiquement le salaire.","En bloquant tous les paiements."],"answer_index":1,"explanation_pt_br":"O quarto parágrafo explica que apps ajudam a analisar hábitos e categorizar gastos."},{"prompt":"Quelle est la vision de l''auteur sur la gestion financière ?","options":["C''est une obligation pénible et triste.","C''est un moyen d''atteindre ses objectifs.","C''est réservé uniquement aux personnes riches.","C''est une activité inutile et dépassée."],"answer_index":1,"explanation_pt_br":"O texto conclui que a gestão financeira é uma ferramenta para atingir metas pessoais."}]'::jsonb, 9),
('fr-passage-b1-10', 'fr', 'B1', 'L''apprentissage tout au long de la vie', 'Dans un monde en constante évolution, l''éducation ne s''arrête plus aux portes de l''école ou de l''université. La notion d''apprentissage tout au long de la vie est devenue une réalité incontournable pour s''adapter aux mutations technologiques et sociales. Que ce soit pour progresser dans sa carrière ou pour enrichir ses connaissances personnelles, la formation continue est un atout précieux pour chaque individu.

Les plateformes d''apprentissage en ligne ont démocratisé l''accès au savoir. Désormais, il est possible de suivre des cours sur des sujets variés, allant de la programmation informatique à la cuisine gastronomique, depuis le confort de son foyer. Cette flexibilité permet aux personnes actives de combiner leurs obligations professionnelles avec le désir d''acquérir de nouvelles compétences à leur propre rythme.

Le développement de compétences transversales, telles que la pensée critique, la résolution de problèmes ou la maîtrise des langues étrangères, est particulièrement valorisé sur le marché du travail actuel. Ces capacités permettent de rester compétitif et agile face à des métiers qui se transforment rapidement. Investir du temps dans son propre développement intellectuel est donc un choix stratégique pour sécuriser son avenir professionnel.

L''apprentissage ne doit pas être uniquement utilitaire ; il peut aussi être une source de plaisir et d''épanouissement personnel. Apprendre à jouer d''un instrument, découvrir l''histoire de l''art ou s''initier au jardinage permet d''explorer des passions insoupçonnées. Ces activités stimulent la curiosité, maintiennent l''esprit alerte et contribuent grandement à une meilleure qualité de vie et à un bien-être mental durable.

En conclusion, cultiver son esprit est un voyage sans fin. En restant ouvert aux nouvelles idées et en saisissant les opportunités d''apprendre chaque jour, nous enrichissons non seulement notre parcours professionnel mais aussi notre vie intérieure. L''éducation est un moteur puissant de changement qui nous permet de mieux comprendre le monde et de nous y épanouir pleinement, quel que soit notre âge.', '[{"prompt":"Pourquoi l''apprentissage tout au long de la vie est-il nécessaire ?","options":["Pour rester à l''école le plus longtemps possible.","Pour s''adapter aux changements du monde.","Parce que les universités sont obligatoires.","Pour éviter de travailler plus tard."],"answer_index":1,"explanation_pt_br":"O primeiro parágrafo menciona que é preciso se adaptar às mudanças tecnológicas e sociais."},{"prompt":"Que permettent les plateformes en ligne ?","options":["D''apprendre depuis chez soi avec flexibilité.","De voyager gratuitement dans le monde.","De remplacer totalement le travail réel.","De ne jamais avoir à étudier seul."],"answer_index":0,"explanation_pt_br":"O texto destaca que a flexibilidade dessas plataformas permite estudar de casa no próprio ritmo."},{"prompt":"Quelles compétences sont valorisées sur le marché du travail ?","options":["La cuisine et le jardinage.","La pensée critique et les langues.","Le repos et le sommeil.","La paresse et l''indifférence."],"answer_index":1,"explanation_pt_br":"O terceiro parágrafo cita a pensée critique e línguas como habilidades valorizadas."},{"prompt":"L''apprentissage doit-il être seulement utile professionnellement ?","options":["Oui, c''est la seule raison d''apprendre.","Non, c''est aussi une source de plaisir personnel.","Oui, car le plaisir n''est pas important.","Non, car le plaisir est une perte de temps."],"answer_index":1,"explanation_pt_br":"O quarto parágrafo afirma que aprender também traz prazer e satisfação pessoal."},{"prompt":"Quel est le message principal de ce texte ?","options":["Il faut arrêter d''apprendre après l''école.","L''éducation continue est bénéfique pour tous.","Le travail est plus important que l''éducation.","L''apprentissage est trop difficile pour les adultes."],"answer_index":1,"explanation_pt_br":"O texto defende que a educação contínua é um motor de crescimento profissional e pessoal."}]'::jsonb, 10),
('fr-passage-b2-01', 'fr', 'B2', 'L''équilibre quotidien entre autonomie et contraintes', 'Dans la société contemporaine, la notion d''autonomie dépasse largement la simple capacité à subvenir à ses besoins fondamentaux. Pour beaucoup d''adultes actifs, la gestion du quotidien devient une discipline quasi militaire, où chaque minute est optimisée pour conjuguer impératifs professionnels et aspirations personnelles. Cette quête d''indépendance est souvent entravée par une surcharge cognitive invisible, née de la multiplication des tâches domestiques et administratives qui ponctuent nos journées.

Le matin commence souvent par une série de rituels visant à structurer l''esprit avant d''affronter le tumulte extérieur. Certains privilégient la méditation ou le sport, tandis que d''autres se plongent immédiatement dans la consultation effrénée de leurs messages. Ce choix initial dicte souvent la tonalité de la journée : une approche réactive génère une sensation de précipitation constante, alors qu''une routine structurée favorise un sentiment de contrôle, pilier essentiel de l''indépendance psychologique chez l''adulte moderne.

Cependant, l''autonomie ne signifie pas l''isolement. Au contraire, les personnes les plus épanouies sont celles qui savent déléguer et s''appuyer sur des réseaux de soutien, qu''ils soient technologiques ou humains. L''utilisation d''applications de gestion du temps ou le recours à des services de proximité permet de libérer un espace mental précieux. Cette externalisation de certaines tâches routinières n''est pas un aveu de faiblesse, mais une stratégie délibérée pour préserver son énergie créative.

Le défi majeur réside dans la frontière poreuse entre le domicile et le lieu de travail. Avec la généralisation du télétravail, la maison est devenue un espace hybride où les frontières s''effacent. Cette mutation exige une discipline accrue pour ne pas se laisser submerger par les sollicitations permanentes. L''adulte B2 doit donc apprendre à établir des limites claires, non seulement pour protéger son temps de repos, mais aussi pour maintenir une distinction saine entre identité professionnelle et vie privée.

Un autre aspect fondamental est la gestion des imprévus. L''autonomie véritable se mesure à notre capacité à réagir face à l''inattendu sans perdre pied. Plutôt que de subir les perturbations, l''individu autonome ajuste ses priorités avec agilité, conscient que la rigidité est souvent l''ennemie de la sérénité. Cette flexibilité cognitive permet de transformer des obstacles potentiels en opportunités d''apprentissage, renforçant ainsi la confiance en soi sur le long terme.

En conclusion, l''indépendance quotidienne est un processus dynamique qui nécessite une réflexion constante sur ses propres habitudes. Il ne s''agit pas de viser une perfection inatteignable, mais de cultiver un mode de vie aligné avec ses valeurs. En prenant conscience des mécanismes qui régissent notre quotidien, nous pouvons reprendre le pouvoir sur notre emploi du temps et, par extension, sur la trajectoire de notre propre existence, transformant ainsi la routine en un vecteur d''épanouissement personnel.', '[{"prompt":"Quel est le principal défi mentionné concernant l''autonomie dans la société actuelle ?","options":["La difficulté à trouver un emploi stable","La surcharge cognitive liée aux tâches quotidiennes","Le manque de soutien technologique","La dépendance excessive envers les réseaux sociaux"],"answer_index":1,"explanation_pt_br":"O texto destaca que a autonomia é frequentemente prejudicada pela sobrecarga cognitiva causada pelo acúmulo de tarefas domésticas e administrativas."},{"prompt":"Que signifie l''expression ''approche réactive'' dans le contexte du deuxième paragraphe ?","options":["Une méthode proactive pour réussir","Une manière réfléchie de planifier sa journée","Un comportement qui subit les événements extérieurs","Une technique de relaxation matinale"],"answer_index":2,"explanation_pt_br":"No contexto, ser reativo significa deixar que as mensagens e estímulos externos ditem o ritmo da manhã, em vez de seguir um plano próprio."},{"prompt":"Pourquoi l''auteur suggère-t-il de déléguer certaines tâches ?","options":["Pour réduire les coûts financiers","Pour éviter d''avoir des responsabilités","Pour préserver son énergie créative","Pour travailler moins d''heures au bureau"],"answer_index":2,"explanation_pt_br":"O texto afirma que a delegação ou terceirização de tarefas é uma estratégia para liberar espaço mental e energia criativa."},{"prompt":"Quel est l''impact principal du télétravail sur la vie quotidienne, selon le texte ?","options":["Il facilite la gestion du temps de repos","Il efface les limites entre la vie professionnelle et privée","Il améliore la productivité des entreprises","Il rend les travailleurs plus isolés socialement"],"answer_index":1,"explanation_pt_br":"O autor aponta que o teletrabalho torna as fronteiras entre casa e trabalho porosas, exigindo maior disciplina."},{"prompt":"Comment un individu autonome doit-il gérer les imprévus ?","options":["En suivant une routine rigide","En ignorant les problèmes mineurs","En ajustant ses priorités avec agilité","En demandant systématiquement de l''aide"],"answer_index":2,"explanation_pt_br":"A verdadeira autonomia é demonstrada pela capacidade de ajustar prioridades com flexibilidade diante de situações inesperadas."},{"prompt":"Quel est le ton général de cet article ?","options":["Critique et pessimiste","Conseiller et réfléchi","Scientifique et impersonnel","Humoristique et léger"],"answer_index":1,"explanation_pt_br":"O texto adota um tom reflexivo e oferece conselhos sobre como gerenciar a vida cotidiana com mais autonomia."},{"prompt":"Quelle est l''idée principale du passage ?","options":["L''autonomie est un état inné","La technologie est la seule solution aux problèmes quotidiens","L''indépendance est une construction dynamique qui nécessite de la réflexion","Le travail à domicile est la cause de tous les stress modernes"],"answer_index":2,"explanation_pt_br":"A ideia central é que a autonomia é um processo contínuo e dinâmico que exige reflexão e ajustes conscientes."}]'::jsonb, 1),
('fr-passage-b2-02', 'fr', 'B2', 'L''art du voyage : une immersion culturelle', 'Le voyage moderne a considérablement évolué, passant d''une simple consommation touristique à une quête de sens et de connexion. Si autrefois, le vacancier se contentait de visiter les sites emblématiques avec un guide à la main, le voyageur d''aujourd''hui aspire à une immersion authentique. Il ne s''agit plus seulement de voir des monuments, mais de comprendre le tissu social et les traditions qui composent l''identité d''une destination lointaine.

Cette approche nécessite une préparation mentale autant que logistique. Avant même le départ, l''esprit s''évade à travers des lectures, des films ou l''apprentissage de quelques rudiments linguistiques. Cette curiosité intellectuelle est le premier pas vers une découverte réussie. Elle permet de briser la glace avec les populations locales, transformant une simple transaction commerciale en un échange humain, parfois éphémère, mais toujours enrichissant pour les deux parties.

Cependant, le tourisme de masse pose un défi majeur à cette quête d''authenticité. Dans les grandes capitales mondiales, les quartiers historiques se transforment parfois en décors muséifiés, vidés de leurs habitants originaux. Le voyageur averti cherche alors à sortir des sentiers battus, privilégiant des destinations moins médiatisées où le quotidien des locaux reste préservé. Cette démarche exige de renoncer au confort standardisé des grands hôtels pour embrasser une forme de vulnérabilité.

La gastronomie joue également un rôle central dans cette exploration. Manger local n''est pas seulement un acte de nutrition, c''est une porte d''entrée dans l''histoire d''un pays. Chaque ingrédient, chaque technique de préparation raconte un passé, une géographie et une lutte pour la survie ou la prospérité. En partageant un repas sur un marché ou dans une taverne familiale, le voyageur capte des nuances culturelles que les musées, aussi complets soient-ils, ne pourront jamais transmettre.

Le voyage est aussi un miroir qui nous renvoie à notre propre identité. En observant des cultures radicalement différentes, nous sommes obligés de questionner nos propres certitudes. Ce dépaysement, parfois inconfortable, est nécessaire à la croissance personnelle. Il nous apprend la tolérance et la relativité, des qualités indispensables dans un monde globalisé où les malentendus culturels sont souvent le terreau des tensions politiques et sociales.

En fin de compte, le succès d''un voyage ne se mesure pas au nombre de photos prises ou de pays visités, mais à la transformation intérieure qu''il opère. Le retour à la réalité est souvent le moment le plus difficile, car il demande d''intégrer ces nouvelles perspectives dans notre routine quotidienne. Voyager reste, malgré les défis écologiques et éthiques, l''une des expériences les plus puissantes pour élargir nos horizons et cultiver une citoyenneté mondiale plus éclairée.', '[{"prompt":"Quelle est la différence entre le touriste d''autrefois et le voyageur d''aujourd''hui, selon le texte ?","options":["Le voyageur d''aujourd''hui voyage moins loin","Le touriste d''autrefois cherchait l''immersion","Le voyageur actuel cherche le sens et la connexion","Le touriste d''autrefois préférait les zones rurales"],"answer_index":2,"explanation_pt_br":"O texto diferencia o turista que apenas visitava monumentos do viajante atual que busca sentido e conexão profunda."},{"prompt":"Pourquoi l''apprentissage de la langue est-il considéré comme important ?","options":["Pour éviter de dépenser de l''argent","Pour faciliter les échanges humains","Pour obtenir des réductions dans les musées","Pour ne pas avoir besoin de guides"],"answer_index":1,"explanation_pt_br":"Aprender o idioma local é visto como uma forma de quebrar barreiras e promover trocas humanas significativas."},{"prompt":"Quel est le problème posé par le tourisme de masse ?","options":["Il rend les voyages trop coûteux","Il détruit les écosystèmes marins","Il transforme des quartiers en décors sans vie","Il empêche l''accès aux monuments historiques"],"answer_index":2,"explanation_pt_br":"O texto explica que o turismo de massa pode esvaziar bairros históricos de seus moradores originais, tornando-os artificiais."},{"prompt":"Que signifie l''expression ''sortir des sentiers battus'' ?","options":["Visiter des zones dangereuses","Se rendre dans des lieux peu fréquentés","Voyager sans bagages","Ignorer les conseils des guides"],"answer_index":1,"explanation_pt_br":"A expressão significa ir a lugares menos conhecidos ou menos turísticos, fora do circuito tradicional."},{"prompt":"Pourquoi la gastronomie est-elle importante dans le voyage ?","options":["Elle permet de faire des économies","Elle est plus saine que la cuisine domestique","Elle est un moyen de comprendre l''histoire locale","Elle facilite la rencontre avec d''autres touristes"],"answer_index":2,"explanation_pt_br":"A gastronomia é descrita como uma forma de acessar a história, a geografia e a cultura de um local."},{"prompt":"Quel est l''effet du voyage sur l''individu ?","options":["Il renforce les préjugés","Il oblige à remettre en question ses certitudes","Il rend le retour à la maison inutile","Il permet de devenir riche rapidement"],"answer_index":1,"explanation_pt_br":"O texto afirma que o choque cultural nos obriga a questionar nossas próprias certezas e crenças."},{"prompt":"Quelle est la conclusion de l''auteur sur le voyage ?","options":["C''est une activité dépassée","C''est une expérience de transformation personnelle","C''est un privilège réservé aux élites","C''est la cause principale de la pollution"],"answer_index":1,"explanation_pt_br":"O autor conclui que o sucesso de uma viagem se mede pela transformação interior que ela proporciona."}]'::jsonb, 2),
('fr-passage-b2-03', 'fr', 'B2', 'Communication et performance en milieu professionnel', 'Dans l''univers professionnel contemporain, la communication ne se limite plus à la simple transmission d''informations. Elle est devenue le ciment de la culture d''entreprise et le moteur de la performance collective. Une équipe qui communique bien est une équipe capable d''anticiper les crises, de résoudre les conflits avec diplomatie et de maintenir une dynamique positive, même sous une forte pression opérationnelle. La clarté et l''empathie sont désormais des compétences aussi valorisées que l''expertise technique.

La montée en puissance des outils numériques a toutefois complexifié nos échanges. Si les messageries instantanées permettent une réactivité accrue, elles favorisent également une fragmentation de l''attention et une surcharge d''informations inutiles. Le défi pour le cadre moderne est de savoir hiérarchiser les canaux de communication : privilégier l''entretien en face à face pour les sujets sensibles, et réserver les courriels pour les suivis factuels, afin d''éviter tout malentendu préjudiciable au climat social.

La gestion des conflits demeure un indicateur clé de la maturité professionnelle. Au sein d''une équipe, les divergences d''opinions sont inévitables et, bien gérées, elles peuvent être sources d''innovation. Le problème survient lorsque ces désaccords deviennent personnels. Un bon communicant sait dissocier la critique du travail de la valeur de la personne. Encourager un débat constructif, où chaque voix est entendue, est essentiel pour favoriser un sentiment d''appartenance et d''engagement.

La transparence dans la communication interne est également un levier puissant de motivation. Lorsqu''une direction partage honnêtement les objectifs, les succès mais aussi les difficultés, elle renforce la confiance des employés. La rétention d''information, autrefois perçue comme un outil de pouvoir, est aujourd''hui considérée comme un frein au développement. L''agilité organisationnelle dépend de la circulation fluide des idées, permettant à chaque collaborateur d''être acteur de la stratégie globale.

Par ailleurs, le langage corporel et l''écoute active jouent un rôle sous-estimé dans nos interactions professionnelles. Une posture ouverte, un contact visuel approprié et la capacité à reformuler les propos de son interlocuteur transmettent un message de respect et de considération. Ces signaux non verbaux complètent et renforcent le discours parlé. Dans un contexte de réunions hybrides ou virtuelles, ces éléments deviennent encore plus cruciaux pour maintenir une connexion humaine réelle.

En résumé, la communication en entreprise est un art qui s''apprend et se perfectionne. Elle demande une remise en question constante de ses propres habitudes. En cultivant l''empathie, la clarté et l''écoute, les professionnels peuvent non seulement améliorer leur productivité, mais aussi contribuer à un environnement de travail plus épanouissant. La réussite collective repose in fine sur la qualité des liens tissés au quotidien, transformant les défis opérationnels en succès partagés.', '[{"prompt":"Quelle est l''évolution du rôle de la communication en entreprise selon le texte ?","options":["Elle est devenue inutile avec les outils numériques","Elle est passée de la transmission simple à un moteur de performance","Elle se limite désormais aux échanges techniques","Elle est devenue une responsabilité exclusive de la direction"],"answer_index":1,"explanation_pt_br":"O texto explica que a comunicação evoluiu de uma simples transmissão de dados para um elemento central de cultura e desempenho."},{"prompt":"Quel est le risque lié aux outils numériques mentionné ?","options":["Leur coût trop élevé","La fragmentation de l''attention","La difficulté de les apprendre","L''impossibilité de les utiliser à distance"],"answer_index":1,"explanation_pt_br":"O texto menciona que as ferramentas digitais favorecem a fragmentação da atenção e a sobrecarga de informações."},{"prompt":"Que conseille l''auteur pour les sujets sensibles ?","options":["Utiliser la messagerie instantanée","Envoyer un e-mail détaillé","Préférer un entretien en face à face","Attendre une réunion trimestrielle"],"answer_index":2,"explanation_pt_br":"O autor recomenda privilegiar o encontro presencial para temas sensíveis, visando evitar mal-entendidos."},{"prompt":"Comment transformer un conflit en opportunité ?","options":["En ignorant les avis divergents","En dissociant la critique du travail de la personne","En imposant la vision du chef","En évitant tout débat au sein de l''équipe"],"answer_index":1,"explanation_pt_br":"A gestão de conflitos eficaz envolve separar a crítica ao trabalho da valorização pessoal do indivíduo."},{"prompt":"Quel est l''effet de la transparence en communication ?","options":["Elle réduit le pouvoir des managers","Elle crée de la confusion chez les employés","Elle renforce la confiance des employés","Elle augmente le nombre de réunions"],"answer_index":2,"explanation_pt_br":"A transparência na comunicação interna é apresentada como um meio eficaz para reforçar a confiança da equipe."},{"prompt":"Quelle est l''importance du langage non verbal ?","options":["Il est inutile dans les réunions virtuelles","Il remplace totalement le discours parlé","Il complète le discours et renforce le respect","Il est trop difficile à maîtriser"],"answer_index":2,"explanation_pt_br":"O texto afirma que os sinais não verbais complementam a fala e transmitem respeito e consideração."},{"prompt":"Quelle est la thèse centrale de ce texte ?","options":["La technologie remplacera bientôt les relations humaines","La qualité de la communication est déterminante pour la réussite collective","Le travail en entreprise est devenu trop complexe","L''empathie n''a pas sa place au travail"],"answer_index":1,"explanation_pt_br":"A ideia central é que a qualidade da comunicação é um pilar essencial para o sucesso e o ambiente de trabalho."}]'::jsonb, 3),
('fr-passage-b2-04', 'fr', 'B2', 'Santé et bien-être : une approche globale', 'La définition de la santé a radicalement changé au cours des dernières décennies. Longtemps réduite à l''absence de maladie, elle est aujourd''hui envisagée comme un état de complet bien-être physique, mental et social. Cette vision holistique place l''individu au cœur de son propre processus de soin. Il ne s''agit plus de attendre les symptômes pour consulter, mais de cultiver une hygiène de vie proactive qui prévient les déséquilibres avant qu''ils ne s''installent durablement.

Le sommeil, souvent sacrifié sur l''autel de la productivité, constitue le socle de cette santé globale. Pourtant, les recherches sont unanimes : une privation chronique de repos altère les fonctions cognitives, diminue la résistance immunitaire et fragilise la stabilité émotionnelle. Réapprendre à dormir, en respectant son rythme biologique et en limitant l''exposition aux écrans avant le coucher, est une révolution silencieuse mais indispensable pour ceux qui souhaitent maintenir un haut niveau d''énergie.

L''alimentation, quant à elle, ne doit plus être perçue sous le prisme restrictif des régimes amaigrissants. C''est avant tout un carburant nécessaire au bon fonctionnement cellulaire. La tendance actuelle privilégie les produits bruts, locaux et de saison, soulignant le lien indissociable entre la santé de notre assiette et celle de notre environnement. Manger en pleine conscience, en prenant le temps de savourer chaque bouchée, permet également de retrouver une relation apaisée avec la nourriture.

L''activité physique, au-delà de ses bienfaits esthétiques ou cardiovasculaires, est un puissant régulateur de l''humeur. La pratique régulière d''un exercice, même modéré, stimule la production d''endorphines, véritables antidotes naturels au stress. Que ce soit par la marche rapide, le yoga ou la natation, l''essentiel est la régularité. L''objectif n''est pas la performance sportive, mais l''intégration du mouvement dans une routine quotidienne pour libérer les tensions accumulées.

La dimension mentale et sociale de la santé est souvent la plus négligée. Le sentiment d''isolement est un facteur de risque majeur pour la santé physique. Entretenir des liens sociaux de qualité, pratiquer la gratitude et savoir poser des limites pour protéger son espace intérieur sont des actes de santé publique. Dans un monde hyper-connecté, la capacité à s''accorder des moments de silence et d''introspection devient un luxe nécessaire pour préserver son équilibre psychique.

En conclusion, prendre soin de soi est un acte de responsabilité individuelle qui profite à l''ensemble de la collectivité. En adoptant des habitudes plus saines, nous réduisons non seulement notre propre vulnérabilité, mais nous devenons aussi des modèles pour notre entourage. La santé n''est pas une destination figée, mais un cheminement quotidien où chaque petit changement, s''il est soutenu par la persévérance, contribue à une vie plus longue, plus sereine et plus harmonieuse.', '[{"prompt":"Comment la définition de la santé a-t-elle évolué ?","options":["Elle se limite à l''absence de maladie","Elle est devenue une question purement esthétique","Elle inclut désormais le bien-être physique, mental et social","Elle est devenue une responsabilité exclusive du médecin"],"answer_index":2,"explanation_pt_br":"O texto explica que a saúde hoje é vista de forma holística, abrangendo o bem-estar físico, mental e social."},{"prompt":"Quel est l''impact de la privation de sommeil sur l''individu ?","options":["Elle augmente la productivité","Elle fragilise la stabilité émotionnelle","Elle améliore la résistance aux maladies","Elle n''a aucun impact sur les fonctions cognitives"],"answer_index":1,"explanation_pt_br":"O texto aponta que a privação de sono afeta negativamente as funções cognitivas e a estabilidade emocional."},{"prompt":"Que signifie ''manger en pleine conscience'' ?","options":["Manger des produits très chers","Manger rapidement pour gagner du temps","Prendre le temps de savourer chaque bouchée","Manger uniquement des produits de saison"],"answer_index":2,"explanation_pt_br":"Comer com atenção plena (mindfulness) envolve saborear cada mordida, promovendo uma relação saudável com a comida."},{"prompt":"Quel est le bénéfice principal de l''activité physique selon le texte ?","options":["Gagner des compétitions sportives","Devenir un athlète de haut niveau","Réguler l''humeur grâce aux endorphines","Réduire les dépenses en vêtements"],"answer_index":2,"explanation_pt_br":"O exercício físico é destacado principalmente como um regulador de humor através da produção de endorfinas."},{"prompt":"Pourquoi le lien social est-il important pour la santé ?","options":["Il aide à gagner plus d''argent","L''isolement est un facteur de risque majeur","Il permet de ne plus faire de sport","Il est obligatoire pour le travail"],"answer_index":1,"explanation_pt_br":"O texto enfatiza que o isolamento é um fator de risco, tornando o contato social essencial para a saúde."},{"prompt":"Quel est le ton de l''auteur concernant les habitudes de santé ?","options":["Il impose des règles strictes","Il encourage une approche proactive et responsable","Il propose des solutions miracles","Il critique ceux qui font du sport"],"answer_index":1,"explanation_pt_br":"O tom é de incentivo a uma abordagem proativa e responsável, sem prometer soluções mágicas."},{"prompt":"Quelle est l''idée centrale du passage ?","options":["La santé dépend uniquement de la génétique","La santé est un cheminement quotidien holistique","Le sport est plus important que l''alimentation","Les médecins sont les seuls responsables de notre santé"],"answer_index":1,"explanation_pt_br":"A ideia central é que a saúde é um processo contínuo e holístico que depende de hábitos diários."}]'::jsonb, 4),
('fr-passage-b2-05', 'fr', 'B2', 'Gastronomie, traditions et lien social', 'Dans toutes les cultures du monde, la cuisine occupe une place centrale, bien au-delà de la simple nécessité biologique de se nourrir. Elle constitue le socle des traditions, le langage silencieux de l''hospitalité et le vecteur privilégié de la transmission intergénérationnelle. Partager un repas est un acte social fondateur qui permet de renforcer les liens au sein de la communauté, de célébrer les événements marquants et de maintenir une identité culturelle forte dans un monde globalisé.

Les traditions culinaires ne sont pas des reliques figées dans le temps ; elles sont vivantes et évolutives. Elles s''adaptent aux migrations, aux nouveaux ingrédients et aux préoccupations éthiques contemporaines. Cependant, le cœur de ces traditions demeure : la préparation minutieuse, le choix des produits et le temps consacré à la table. Dans une société où tout s''accélère, retrouver ces moments de partage devient une forme de résistance contre l''effritement du lien social.

La communauté se manifeste souvent autour de la table. Les marchés locaux, par exemple, ne sont pas seulement des lieux de commerce, mais des espaces de rencontre où les générations se croisent. Les recettes transmises par les aînés sont des trésors qui racontent l''histoire d''un territoire, ses ressources et son climat. Préserver ces savoir-faire, c''est protéger une part de notre patrimoine immatériel contre l''uniformisation des goûts imposée par l''industrie agroalimentaire.

Le repas partagé est aussi un espace de dialogue et de médiation. Autour d''un plat, les barrières sociales s''estompent parfois. C''est le moment idéal pour écouter, échanger des idées et construire une vision commune. L''hospitalité, cette capacité à accueillir l''autre, est une valeur universelle qui trouve son expression la plus concrète dans le partage du pain. Cette dimension humaine de la nourriture est ce qui transforme un simple repas en un véritable festin de partage.

Pourtant, il faut être conscient des défis environnementaux liés à nos modes de consommation alimentaire. La recherche de la tradition doit désormais s''accompagner d''une réflexion sur la durabilité. Choisir des produits locaux, respecter les saisons et réduire le gaspillage sont autant d''actes qui honorent la terre nourricière. La gastronomie de demain devra concilier le respect des héritages culinaires avec la nécessité de préserver les ressources pour les générations futures.

En définitive, la cuisine est un miroir de la société. En observant ce que nous mangeons et comment nous le partageons, nous pouvons comprendre les évolutions de nos valeurs collectives. Cultiver nos traditions culinaires, c''est nourrir non seulement notre corps, mais aussi notre esprit et notre appartenance à une communauté. C''est un engagement envers le passé, une célébration du présent et une promesse pour l''avenir, où la table reste le lieu privilégié de notre humanité commune.', '[{"prompt":"Selon le texte, quelle est la fonction principale de la cuisine ?","options":["Elle sert uniquement à se nourrir","Elle est un vecteur de lien social et de tradition","Elle est un outil de marketing pour les entreprises","Elle sert à prouver la richesse d''une famille"],"answer_index":1,"explanation_pt_br":"O texto destaca que a cozinha vai além da nutrição, sendo um pilar social e cultural."},{"prompt":"Pourquoi les traditions culinaires sont-elles qualifiées de ''vivantes'' ?","options":["Parce qu''elles ne changent jamais","Parce qu''elles sont imposées par la loi","Parce qu''elles évoluent avec le temps et les cultures","Parce qu''elles sont réservées aux jeunes"],"answer_index":2,"explanation_pt_br":"As tradições são descritas como vivas porque se adaptam a novas influências e contextos históricos."},{"prompt":"Quel rôle jouent les marchés locaux dans la communauté ?","options":["Ce sont des lieux de commerce uniquement","Ce sont des espaces de rencontre intergénérationnels","Ce sont des endroits réservés aux touristes","Ce sont des lieux de travail pour les enfants"],"answer_index":1,"explanation_pt_br":"O autor menciona que os mercados são espaços de encontro onde gerações diferentes se cruzam."},{"prompt":"Que représente la transmission des recettes ?","options":["Une perte de temps inutile","La protection d''un patrimoine immatériel","Une obligation commerciale","Une technique de survie dépassée"],"answer_index":1,"explanation_pt_br":"A transmissão de receitas é vista como a proteção de um patrimônio cultural imaterial."},{"prompt":"Quelle est la valeur universelle liée à la nourriture ?","options":["La compétition","L''hospitalité","L''individualisme","La productivité"],"answer_index":1,"explanation_pt_br":"A hospitalidade é descrita como uma valor universal que se expressa no ato de compartilhar comida."},{"prompt":"Quel défi environnemental est mentionné ?","options":["La surconsommation d''eau potable","La nécessité de la durabilité et de la réduction du gaspillage","L''interdiction de manger de la viande","Le coût trop élevé des produits locaux"],"answer_index":1,"explanation_pt_br":"O autor alerta para a necessidade de conciliar tradição com sustentabilidade e combate ao desperdício."},{"prompt":"Quelle est la conclusion principale de l''auteur ?","options":["Nous devons abandonner nos traditions","La cuisine est un miroir de nos valeurs collectives","L''industrie agroalimentaire est la seule solution","Il faut manger seul pour être en bonne santé"],"answer_index":1,"explanation_pt_br":"A conclusão é que a culinária reflete os valores da sociedade e é fundamental para a coesão social."}]'::jsonb, 5),
('fr-passage-b2-06', 'fr', 'B2', 'La révolution numérique au quotidien', 'L''intégration des technologies numériques dans notre routine quotidienne a radicalement transformé la manière dont nous interagissons avec le monde. Ce qui était autrefois perçu comme un luxe futuriste est devenu une infrastructure invisible mais essentielle, influençant chaque décision, du choix de notre itinéraire matinal à la gestion de notre calendrier professionnel.

Le smartphone, véritable extension de notre identité, agit désormais comme une interface centrale. Les applications de domotique permettent de contrôler l''éclairage, la température et la sécurité de nos logements à distance, offrant un confort accru tout en soulevant des questions légitimes sur la protection des données personnelles et l''intrusion technologique.

Cependant, cette hyper-connectivité ne va pas sans défis. Le phénomène de la fatigue numérique, causé par une exposition constante aux notifications et aux flux d''informations, pousse de nombreux individus à adopter des stratégies de déconnexion volontaire, cherchant à restaurer une forme de présence authentique et de calme mental.

Le travail hybride, rendu possible par des outils de collaboration avancés, a également redéfini les frontières entre vie privée et vie professionnelle. Si cette flexibilité est saluée pour son gain de temps, elle engendre paradoxalement un sentiment d''être « toujours au travail », rendant la déconnexion psychologique plus ardue que dans un bureau traditionnel.

Les algorithmes de recommandation, quant à eux, façonnent nos choix de consommation culturelle. En anticipant nos préférences, ils créent une expérience personnalisée mais risquent également de nous enfermer dans des bulles de filtres, limitant ainsi notre exposition à des perspectives divergentes et à la sérendipité intellectuelle.

En somme, la technologie impose un équilibre subtil. Il ne s''agit plus de refuser ces outils, mais de développer une littératie numérique critique pour naviguer dans ce paysage complexe. La maîtrise de notre environnement technologique est devenue une compétence civique indispensable pour maintenir notre autonomie dans une société de plus en plus automatisée.', '[{"prompt":"Quelle est la fonction principale du smartphone selon le texte ?","options":["Un outil de divertissement pur","Une interface centrale de gestion quotidienne","Un vecteur de fatigue mentale chronique","Un substitut à l''interaction sociale réelle"],"answer_index":1,"explanation_pt_br":"O texto descreve o smartphone como uma interface central que facilita a gestão de tarefas e a vida cotidiana."},{"prompt":"Que signifie l''expression « bulles de filtres » dans le cinquième paragraphe ?","options":["Des outils de protection contre les virus","Des filtres photographiques pour les réseaux sociaux","Un isolement intellectuel dû aux algorithmes","Un système de sécurité pour les données privées"],"answer_index":2,"explanation_pt_br":"Refere-se ao fenômeno onde algoritmos restringem a visão do usuário a conteúdos similares, limitando o contato com ideias diferentes."},{"prompt":"Quel est le paradoxe du travail hybride mentionné ?","options":["Il est très productif mais très coûteux","Il offre de la flexibilité mais rend la déconnexion difficile","Il est techniquement simple mais socialement complexe","Il favorise la créativité mais réduit la collaboration"],"answer_index":1,"explanation_pt_br":"O texto aponta que, embora o trabalho remoto dê flexibilidade, ele cria a sensação de estar sempre trabalhando."},{"prompt":"Pourquoi certains individus choisissent-ils de se déconnecter ?","options":["Pour éviter les coûts des abonnements","Pour protéger leur vie privée contre les hackers","Pour retrouver un état de calme mental","Pour apprendre à utiliser de nouveaux outils"],"answer_index":2,"explanation_pt_br":"O texto menciona que a desconexão voluntária busca restaurar a presença autêntica e o calme mental diante da fadiga digital."},{"prompt":"Quelle est l''attitude recommandée par l''auteur face à la technologie ?","options":["Le rejet total pour préserver sa vie privée","L''acceptation passive des innovations","Une adoption prudente et critique","La dépendance totale aux outils automatisés"],"answer_index":2,"explanation_pt_br":"O autor defende o desenvolvimento de uma literacia digital crítica para manter a autonomia."},{"prompt":"Quelle est la principale préoccupation liée à la domotique ?","options":["Le coût élevé de l''installation","La complexité de l''interface utilisateur","La sécurité et la vie privée","Le manque de compatibilité entre les marques"],"answer_index":2,"explanation_pt_br":"O texto cita explicitamente preocupações sobre a proteção de dados pessoais e intrusão tecnológica."},{"prompt":"Quel est le thème central de ce texte ?","options":["L''évolution historique de l''informatique","L''impact nuancé de la technologie sur notre quotidien","Le guide pratique pour choisir son smartphone","Les dangers de l''intelligence artificielle"],"answer_index":1,"explanation_pt_br":"O texto aborda como a tecnologia permeia a rotina e as implicações positivas e negativas dessa relação."}]'::jsonb, 6),
('fr-passage-b2-07', 'fr', 'B2', 'Vers un mode de vie durable', 'La transition écologique n''est plus une option théorique, mais une nécessité urgente qui redéfinit nos habitudes de consommation. Face à l''épuisement des ressources naturelles, les citoyens sont de plus en plus nombreux à adopter des comportements écoresponsables, transformant des gestes individuels en un mouvement collectif de grande ampleur.

La réduction des déchets, notamment plastiques, est devenue le pilier de cette transformation. Le passage vers le « zéro déchet » implique une remise en question profonde de nos achats, privilégiant le vrac, la réparation des objets cassés plutôt que leur remplacement immédiat, et la valorisation des produits locaux de saison.

Cependant, le défi majeur réside dans la pérennité de ces engagements. Il est facile de changer de comportement lors d''une impulsion écologique, mais maintenir ces efforts sur le long terme exige une restructuration de notre mode de vie. La pression sociale et le marketing incitent toujours à une surconsommation qui entrave la transition.

Le secteur de l''énergie joue également un rôle crucial. L''amélioration de l''efficacité énergétique de nos logements, par l''isolation thermique et l''utilisation d''appareils basse consommation, représente un investissement initial lourd mais nécessaire. C''est un choix qui allie économie financière et réduction significative de l''empreinte carbone.

Les transports constituent un autre levier puissant. Privilégier les mobilités douces, comme le vélo ou les transports en commun, permet non seulement de diminuer les émissions de gaz à effet de serre, mais aussi d''améliorer la qualité de vie en ville en réduisant le bruit et la pollution atmosphérique quotidienne.

En conclusion, la durabilité est une démarche holistique. Elle demande de passer d''une logique de possession à une logique d''usage. Si chaque petit geste compte, c''est l''agrégation de ces choix conscients qui permettra de construire une société résiliente, capable de respecter les limites planétaires tout en préservant le bien-être des générations futures.', '[{"prompt":"Selon le texte, quelle est la base du mouvement « zéro déchet » ?","options":["Le recyclage systématique des plastiques","L''achat de produits en vrac et la réparation d''objets","L''interdiction totale de consommer des produits importés","Le remplacement régulier des appareils par des modèles neufs"],"answer_index":1,"explanation_pt_br":"O texto menciona que o ''zero desperdício'' envolve comprar a granel e reparar objetos em vez de substituí-los."},{"prompt":"Que signifie l''expression « démarche holistique » dans le dernier paragraphe ?","options":["Une approche qui considère tous les aspects du problème","Une méthode strictement scientifique et technique","Une stratégie réservée aux gouvernements","Une solution rapide et peu coûteuse"],"answer_index":0,"explanation_pt_br":"No contexto, indica uma visão abrangente que une vários aspectos da vida e da sociedade."},{"prompt":"Quel est le principal obstacle au maintien des comportements écologiques ?","options":["Le manque de volonté politique","La difficulté de trouver des produits écologiques","La pression sociale et le marketing de la surconsommation","Le prix trop bas des produits traditionnels"],"answer_index":2,"explanation_pt_br":"O texto afirma que a pressão social e o marketing da superconsumo dificultam a sustentabilidade a longo prazo."},{"prompt":"Pourquoi l''amélioration de l''isolation est-elle qualifiée d''« investissement » ?","options":["Parce qu''elle rapporte de l''argent immédiatement","Parce qu''elle demande un coût initial pour des économies futures","Parce qu''elle est obligatoire par la loi","Parce qu''elle augmente la valeur immobilière des terrains"],"answer_index":1,"explanation_pt_br":"Investimento implica um gasto inicial que trará benefícios (neste caso, financeiros e ambientais) a longo prazo."},{"prompt":"Quel bénéfice supplémentaire du transport doux est souligné ?","options":["La baisse du prix de l''essence","L''amélioration de la santé physique","La diminution de la pollution sonore et atmosphérique","La réduction du temps de trajet travail-domicile"],"answer_index":2,"explanation_pt_br":"O texto destaca explicitamente que o transporte suave reduz o ruído e a poluição atmosférica."},{"prompt":"Quelle est la distinction faite entre « possession » et « usage » ?","options":["La possession est plus écologique que l''usage","L''usage est illégal tandis que la possession est encouragée","La possession implique la propriété, l''usage privilégie la fonction","L''usage est réservé aux entreprises, la possession aux particuliers"],"answer_index":2,"explanation_pt_br":"O texto sugere que devemos focar no uso (utilidade do objeto) em vez de apenas possuí-lo (acumulação)."},{"prompt":"Quelle est l''idée principale du texte ?","options":["Les gouvernements doivent agir seuls pour le climat","La transition écologique nécessite des changements de comportement durables","Le recyclage est la seule solution à la crise climatique","La technologie résoudra tous les problèmes environnementaux"],"answer_index":1,"explanation_pt_br":"O texto argumenta que a transição exige uma mudança profunda e duradoura nas escolhas individuais."}]'::jsonb, 7),
('fr-passage-b2-08', 'fr', 'B2', 'Les dynamiques des relations humaines', 'Dans un monde de plus en plus atomisé, la qualité de nos relations sociales devient le socle de notre équilibre psychologique. Qu''il s''agisse de liens familiaux, amicaux ou professionnels, la communication est l''outil fondamental qui structure ces interactions et permet de construire une confiance mutuelle sur le long terme.

L''amitié à l''âge adulte, contrairement à celle de l''enfance, demande un investissement conscient. Avec les contraintes professionnelles et les responsabilités domestiques, le temps disponible se raréfie. Il devient alors nécessaire de hiérarchiser nos priorités sociales pour cultiver les liens qui nous apportent un véritable soutien émotionnel.

Le conflit, bien qu''inévitable, est souvent perçu à tort comme un signe de rupture. En réalité, une gestion saine des différends permet de clarifier les besoins de chacun et de renforcer l''engagement mutuel. L''empathie et l''écoute active sont ici des compétences clés pour transformer une tension en une opportunité de croissance relationnelle.

Les réseaux sociaux ont complexifié ce paysage relationnel en introduisant le concept de « connexion permanente ». Si ces outils facilitent le maintien des liens à distance, ils peuvent également créer une illusion de proximité. Le nombre de contacts en ligne ne remplace pas la profondeur d''une conversation réelle, où le langage non-verbal joue un rôle crucial.

La solitude, souvent stigmatisée, est un aspect parfois nécessaire de la vie sociale. Apprendre à être bien avec soi-même est un préalable indispensable à des relations saines avec les autres. Une personne qui ne dépend pas exclusivement de l''approbation d''autrui pour se sentir valorisée est capable d''entretenir des liens plus équilibrés et moins possessifs.

En conclusion, le tissu social se construit par la patience et l''authenticité. La multiplication des interactions superficielles ne peut se substituer à la qualité des échanges profonds. En cultivant une communication honnête et une présence réelle, nous renforçons les fondations de notre vie sociale, essentielle à notre épanouissement personnel dans une société complexe.', '[{"prompt":"Pourquoi l''amitié adulte est-elle qualifiée d''« investissement conscient » ?","options":["Parce qu''elle coûte très cher en sorties","Parce qu''elle demande un effort volontaire malgré le manque de temps","Parce qu''elle nécessite des contrats juridiques","Parce qu''elle est basée uniquement sur l''utilité professionnelle"],"answer_index":1,"explanation_pt_br":"O texto explica que a falta de tempo exige uma escolha deliberada para nutrir as amizades."},{"prompt":"Quelle est la vision de l''auteur sur le conflit ?","options":["Un échec relationnel irréparable","Une occasion de croissance si bien gérée","Un comportement à éviter à tout prix","Une preuve de manque d''empathie"],"answer_index":1,"explanation_pt_br":"O texto apresenta o conflito como uma oportunidade de clarificar necessidades e crescer."},{"prompt":"Quelle est la limite des réseaux sociaux selon le texte ?","options":["Ils sont trop coûteux pour les utilisateurs","Ils ne permettent pas de communiquer à distance","Ils créent une illusion de proximité sans profondeur","Ils empêchent toute forme de langage non-verbal"],"answer_index":2,"explanation_pt_br":"O texto alerta que a conexão online cria uma falsa sensação de intimidade."},{"prompt":"Quel rôle joue la solitude dans les relations sociales ?","options":["Elle est un signe d''échec social","Elle est essentielle pour être bien avec soi-même","Elle est la cause principale de la rupture","Elle doit être évitée pour rester équilibré"],"answer_index":1,"explanation_pt_br":"O texto sugere que a autossuficiência emocional é a base para relações mais equilibradas."},{"prompt":"Que signifie « atomisé » dans le premier paragraphe ?","options":["Très rapide et dynamique","Divisé en petites unités isolées","Saturé d''informations technologiques","Extrêmement solidaire et soudé"],"answer_index":1,"explanation_pt_br":"No contexto, descreve uma sociedade onde as pessoas estão cada vez mais isoladas umas das outras."},{"prompt":"Quelle compétence est essentielle pour gérer un conflit ?","options":["L''écoute active","L''évitement des sujets sensibles","La supériorité intellectuelle","L''utilisation intensive des réseaux"],"answer_index":0,"explanation_pt_br":"O texto cita explicitamente a empatia e a escuta ativa como ferramentas fundamentais."},{"prompt":"Quel est le message principal du texte ?","options":["La technologie est le seul moyen de garder des amis","La qualité des relations prime sur la quantité","Les conflits doivent être évités pour rester heureux","La vie sociale est une perte de temps pour l''adulte"],"answer_index":1,"explanation_pt_br":"O autor enfatiza que a profundidade e a autenticidade são mais importantes que a superficialidade."}]'::jsonb, 8),
('fr-passage-b2-09', 'fr', 'B2', 'La gestion des finances personnelles', 'La gestion des finances personnelles constitue un pilier de la stabilité et de la liberté individuelle. Dans une économie marquée par l''instabilité et l''inflation, la capacité à anticiper ses dépenses et à épargner intelligemment devient une compétence essentielle pour tout adulte souhaitant construire un avenir serein.

L''élaboration d''un budget rigoureux ne doit pas être perçue comme une privation, mais comme une feuille de route vers ses objectifs. En distinguant les besoins fondamentaux des désirs superflus, chacun peut reprendre le contrôle sur ses flux financiers et éviter le piège de l''endettement excessif, souvent alimenté par une consommation impulsive.

L''épargne de précaution est le premier rempart contre les imprévus de la vie. Qu''il s''agisse d''une réparation urgente ou d''une perte de revenus temporaire, disposer d''une réserve financière permet de traverser les crises sans subir de stress financier majeur. La discipline est ici le facteur déterminant pour constituer ce fonds de sécurité.

Au-delà de l''épargne, l''investissement représente une étape vers la création de richesse sur le long terme. Comprendre les mécanismes des marchés financiers ou de l''immobilier permet de faire fructifier son capital. Toutefois, cette démarche exige une éducation financière solide pour évaluer les risques et éviter les promesses de gains rapides, souvent trompeuses.

La consommation responsable, quant à elle, s''inscrit dans cette gestion budgétaire. En privilégiant la qualité et la durabilité des biens achetés, on réduit les coûts de remplacement à long terme. C''est une approche qui aligne nos valeurs personnelles avec nos habitudes de dépenses, transformant ainsi notre consommation en un acte réfléchi.

En fin de compte, la santé financière est intimement liée à notre bien-être global. Une bonne gestion réduit l''anxiété et offre les ressources nécessaires pour réaliser ses projets. En développant une conscience financière éclairée, nous passons du statut de consommateur passif à celui d''acteur responsable de notre propre destin économique.', '[{"prompt":"Selon le texte, quel est le but d''un budget ?","options":["Réduire tous les plaisirs de la vie","Atteindre ses objectifs personnels","Payer ses dettes le plus rapidement possible","Accumuler de l''argent sans jamais le dépenser"],"answer_index":1,"explanation_pt_br":"O orçamento é apresentado como um mapa para atingir objetivos, não como uma privação."},{"prompt":"Qu''est-ce que l''épargne de précaution ?","options":["Un investissement risqué en bourse","Une réserve pour les imprévus","Un fonds destiné aux vacances","Un crédit accordé par la banque"],"answer_index":1,"explanation_pt_br":"O texto define a poupança de precaução como uma reserva contra imprevistos."},{"prompt":"Pourquoi l''éducation financière est-elle importante pour l''investissement ?","options":["Pour éviter de se faire arnaquer par des promesses trompeuses","Pour obtenir des prêts bancaires plus facilement","Pour réduire ses impôts légalement","Pour acheter des produits de luxe à bas prix"],"answer_index":0,"explanation_pt_br":"O texto avisa que é preciso conhecimento para avaliar riscos e evitar promessas falsas."},{"prompt":"Quel est le lien entre la consommation responsable et le budget ?","options":["Elle augmente les dépenses inutiles","Elle réduit les coûts à long terme par la durabilité","Elle empêche tout investissement futur","Elle est sans impact sur les finances personnelles"],"answer_index":1,"explanation_pt_br":"A compra de produtos de qualidade evita gastos frequentes com substituições."},{"prompt":"Que signifie « flux financiers » dans le deuxième paragraphe ?","options":["Les mouvements d''argent (entrées et sorties)","Les dettes auprès des banques","Le salaire mensuel fixe","Les impôts à payer chaque année"],"answer_index":0,"explanation_pt_br":"Refere-se ao fluxo de dinheiro que entra e sai."},{"prompt":"Quel est le facteur déterminant pour constituer une épargne ?","options":["Avoir un salaire élevé","La discipline","Avoir des connaissances en bourse","Éviter de sortir avec des amis"],"answer_index":1,"explanation_pt_br":"O texto cita explicitamente a disciplina como fator crucial."},{"prompt":"Quel est le message principal concernant la santé financière ?","options":["L''argent est la seule source de bonheur","Elle est nécessaire pour diminuer l''anxiété","La consommation est le moteur de l''économie","Il faut dépenser tout son argent pour vivre le présent"],"answer_index":1,"explanation_pt_br":"O texto afirma que a boa gestão financeira reduz a ansiedade e melhora o bem-estar."}]'::jsonb, 9),
('fr-passage-b2-10', 'fr', 'B2', 'L''éducation tout au long de la vie', 'Dans une société en perpétuelle mutation, le concept d''éducation ne s''arrête plus au diplôme universitaire initial. La formation continue est devenue un impératif pour rester compétitif sur le marché du travail et pour enrichir son existence intellectuelle, quel que soit l''âge.

Le monde professionnel évolue à un rythme effréné. Des compétences qui étaient valorisées il y a dix ans peuvent devenir obsolètes aujourd''hui. L''apprentissage autodidacte, facilité par les plateformes numériques et les ressources en ligne, permet désormais à chacun d''actualiser ses savoir-faire de manière flexible et autonome.

Cependant, l''éducation ne se limite pas aux aspects techniques. Apprendre une nouvelle langue, s''initier à un art ou approfondir une discipline humaniste sont des démarches qui stimulent la plasticité cérébrale. Ces activités favorisent une ouverture d''esprit nécessaire pour appréhender la complexité du monde actuel.

Le défi de la formation tout au long de la vie réside dans la gestion du temps. Concilier vie familiale, obligations professionnelles et désir de se cultiver demande une organisation rigoureuse. La motivation intrinsèque devient alors le moteur principal, car il n''y a plus de cadre scolaire imposé pour nous pousser à réussir.

L''échange intergénérationnel est une dimension souvent sous-estimée de l''apprentissage. En partageant nos expériences avec des profils plus jeunes ou plus âgés, nous acquérons des perspectives inédites. Cette forme d''éducation informelle est une richesse humaine qui complète les savoirs académiques et renforce la cohésion sociale.

En somme, adopter une posture d''apprenant permanent est une attitude qui favorise la résilience. En restant curieux et ouvert au changement, nous transformons chaque étape de notre vie en une opportunité d''apprentissage, nous permettant ainsi de mieux naviguer dans un futur incertain avec confiance et agilité intellectuelle.', '[{"prompt":"Pourquoi la formation continue est-elle devenue un impératif ?","options":["Parce que les diplômes ne sont plus reconnus","Parce que le marché du travail change rapidement","Parce que les entreprises imposent des études longues","Parce que l''éducation est devenue gratuite partout"],"answer_index":1,"explanation_pt_br":"O texto explica que a evolução rápida do mundo profissional exige atualização constante."},{"prompt":"Quel est l''avantage de l''apprentissage autodidacte selon le texte ?","options":["Il est gratuit pour tout le monde","Il est très rapide et facile","Il offre une grande flexibilité et autonomie","Il remplace obligatoirement les diplômes universitaires"],"answer_index":2,"explanation_pt_br":"O texto destaca a flexibilidade e a autonomia proporcionadas pelas plataformas online."},{"prompt":"Quel est le bénéfice intellectuel des disciplines humanistes ?","options":["Elles garantissent une promotion salariale","Elles stimulent la plasticité cérébrale","Elles permettent d''obtenir des diplômes rapidement","Elles sont obligatoires pour travailler"],"answer_index":1,"explanation_pt_br":"O texto menciona que aprender artes ou humanidades estimula a plasticidade cerebral."},{"prompt":"Quel est le principal moteur de l''éducation à l''âge adulte ?","options":["La peur de perdre son emploi","La motivation intrinsèque","Les examens imposés par l''État","La pression de la famille"],"answer_index":1,"explanation_pt_br":"O texto afirma que, sem o ambiente escolar, a motivação interna é o que impulsiona o aprendizado."},{"prompt":"Que signifie « posture d''apprenant permanent » dans le dernier paragraphe ?","options":["Être toujours étudiant à l''université","Refuser de travailler pour continuer à étudier","Rester curieux et prêt à apprendre toujours","Avoir un diplôme dans chaque domaine"],"answer_index":2,"explanation_pt_br":"Refere-se a manter uma mentalidade aberta e curiosa para aprender durante toda a vida."},{"prompt":"Quelle est la valeur de l''échange intergénérationnel ?","options":["Il permet de réduire les coûts de formation","Il apporte des perspectives nouvelles et humaines","Il est la seule façon d''apprendre des langues","Il remplace les outils numériques"],"answer_index":1,"explanation_pt_br":"O texto aponta que trocar experiências com gerações diferentes enriquece o conhecimento."},{"prompt":"Quelle est l''idée principale du texte ?","options":["L''école est inutile pour la carrière","L''apprentissage tout au long de la vie est essentiel pour s''adapter","Il faut arrêter de travailler pour se former","Seuls les jeunes peuvent apprendre efficacement"],"answer_index":1,"explanation_pt_br":"O texto enfatiza que o aprendizado contínuo é fundamental para a adaptação em um mundo mutável."}]'::jsonb, 10),
('it-passage-a1-01', 'it', 'A1', 'La mia giornata a Roma', 'Ogni mattina mi sveglio alle sette. Prendo un caffè veloce in cucina e leggo le notizie sul mio telefono. Dopo, mi vesto e preparo lo zaino per uscire di casa.

Prendo l''autobus per andare in centro. Lavoro in un ufficio vicino al Colosseo. Il mio lavoro inizia alle nove e finisco alle cinque del pomeriggio. Mi piace molto il mio ufficio.

La sera torno a casa e cucino una buona pasta. Guardo la televisione o leggo un libro prima di dormire. Sono molto stanco, ma sono felice perché sono indipendente e vivo in una bella città.', '[{"prompt":"A che ora inizia il lavoro il protagonista?","options":["Alle sette","Alle nove","Alle cinque","Alle dieci"],"answer_index":1,"explanation_pt_br":"O texto afirma explicitamente que o trabalho começa às nove."},{"prompt":"Cosa fa il protagonista subito dopo il caffè?","options":["Prende l''autobus","Si veste","Lavora","Guarda la TV"],"answer_index":1,"explanation_pt_br":"O texto diz que, após o café, ele se veste e prepara a mochila."},{"prompt":"Qual è il tema principale di questo testo?","options":["La vacanza a Roma","La routine quotidiana","La storia del Colosseo","Il cibo italiano"],"answer_index":1,"explanation_pt_br":"O texto descreve a rotina diária do personagem, desde o despertar até a noite."}]'::jsonb, 1),
('it-passage-a1-02', 'it', 'A1', 'Un viaggio in treno', 'Marco vuole visitare Firenze per il fine settimana. Lui compra un biglietto del treno online. Il treno parte sabato mattina presto dalla stazione centrale di Milano.

Durante il viaggio, Marco guarda il panorama dal finestrino. Vede colline verdi e piccoli villaggi antichi. Lui legge una guida turistica per scoprire i musei più famosi della città.

Finalmente arriva a Firenze a mezzogiorno. Va subito in albergo per lasciare la valigia. Adesso è pronto per camminare tra le strade storiche e vedere l''arte toscana con grande entusiasmo.', '[{"prompt":"Come viaggia Marco verso Firenze?","options":["In aereo","In macchina","In treno","In autobus"],"answer_index":2,"explanation_pt_br":"O texto menciona que ele compra um bilhete de trem."},{"prompt":"Cosa vede Marco dal finestrino?","options":["Il mare blu","Grandi uffici","Colline e villaggi","Solo tunnel"],"answer_index":2,"explanation_pt_br":"O texto descreve que ele vê colinas verdes e pequenas vilas antigas."},{"prompt":"Cosa fa Marco appena arriva a Firenze?","options":["Visita un museo","Va in albergo","Compra un regalo","Cerca un ristorante"],"answer_index":1,"explanation_pt_br":"O texto afirma que ele vai ao hotel para deixar a mala assim que chega."}]'::jsonb, 2),
('it-passage-a1-03', 'it', 'A1', 'Il mio nuovo ufficio', 'Lavoro in una grande azienda di design a Torino. Il mio ufficio è moderno e molto luminoso. Ogni mattina incontro i miei colleghi per parlare dei progetti importanti del giorno.

Parlo spesso al telefono con i nostri clienti internazionali. Uso il computer per scrivere molte email e creare presentazioni. Il mio capo è molto gentile e aiuta sempre tutto il team.

A mezzogiorno mangiamo insieme in una piccola mensa. Parliamo di lavoro ma anche di sport. Mi piace molto il mio ambiente professionale perché imparo sempre cose nuove e interessanti.', '[{"prompt":"Dove lavora il protagonista?","options":["A Roma","A Milano","A Torino","A Firenze"],"answer_index":2,"explanation_pt_br":"O texto especifica que a empresa de design fica em Turim (Torino)."},{"prompt":"Cosa fa il protagonista a mezzogiorno?","options":["Scrive email","Pranza con i colleghi","Incontra un cliente","Fa una presentazione"],"answer_index":1,"explanation_pt_br":"O texto diz que eles comem juntos em um refeitório ao meio-dia."},{"prompt":"Come descrive il protagonista il suo capo?","options":["Molto severo","Molto stanco","Molto gentile","Molto lontano"],"answer_index":2,"explanation_pt_br":"O texto descreve explicitamente o chefe como ''gentile'' (gentil)."}]'::jsonb, 3),
('it-passage-a1-04', 'it', 'A1', 'Una vita sana', 'Per stare bene, è importante mangiare frutta e verdura fresca. Io bevo molta acqua durante il giorno e cammino per trenta minuti ogni pomeriggio nel parco vicino casa.

Il riposo è fondamentale per la salute. Dormo otto ore ogni notte per avere energia. Evito lo stress e cerco di fare attività che mi piacciono molto, come ascoltare musica.

La salute è un grande tesoro. Quando mi sento bene, sono più creativo e felice al lavoro. Seguire queste regole semplici mi aiuta a vivere meglio e con molta serenità ogni giorno.', '[{"prompt":"Quanto tempo cammina il protagonista nel parco?","options":["Dieci minuti","Trenta minuti","Un''ora","Due ore"],"answer_index":1,"explanation_pt_br":"O texto menciona claramente trinta minutos de caminhada."},{"prompt":"Cosa evita il protagonista per la sua salute?","options":["L''acqua","La frutta","Lo stress","La musica"],"answer_index":2,"explanation_pt_br":"O autor diz que evita o estresse para manter a saúde."},{"prompt":"Cosa significa ''fondamentale'' nel contesto del testo?","options":["Inutile","Difficile","Molto importante","Noioso"],"answer_index":2,"explanation_pt_br":"No contexto de saúde e descanso, ''fondamentale'' indica algo essencial ou muito importante."}]'::jsonb, 4),
('it-passage-a1-05', 'it', 'A1', 'La cena in famiglia', 'La domenica è un giorno speciale per la mia famiglia. Ci riuniamo tutti a casa di mia nonna per preparare il pranzo. La nonna prepara sempre una pasta fatta a mano.

Tutti aiutano in cucina: mio fratello taglia il pane e io preparo l''insalata fresca. La casa profuma di sugo al pomodoro e basilico. È una tradizione che amiamo molto.

Mangiamo insieme e parliamo di tutto. La comunità è importante per noi. Questi momenti di convivialità sono il cuore della nostra vita. È il modo perfetto per finire bene la settimana.', '[{"prompt":"Dove si riunisce la famiglia la domenica?","options":["Al ristorante","A casa della nonna","Al parco","In ufficio"],"answer_index":1,"explanation_pt_br":"O texto diz que eles se reúnem na casa da avó."},{"prompt":"Cosa prepara il fratello?","options":["La pasta","Il sugo","L''insalata","Il pane"],"answer_index":3,"explanation_pt_br":"O texto especifica que o irmão corta o pão."},{"prompt":"Qual è il sentimento principale della famiglia?","options":["Tristezza","Convivialità","Noia","Fretta"],"answer_index":1,"explanation_pt_br":"O autor menciona que os momentos de convívio (convivialità) são o coração da vida deles."}]'::jsonb, 5),
('it-passage-a1-06', 'it', 'A1', 'La tecnologia a casa', 'Oggi uso molto lo smartphone per le mie attività quotidiane. Appena mi sveglio, controllo le email e leggo le notizie del mondo sul web.

Il mio computer è fondamentale per il lavoro. Scrivo documenti, organizzo riunioni virtuali e parlo con i miei colleghi tramite videochiamate ogni giorno.

La sera, invece, preferisco staccare tutto. Spengo il telefono e leggo un libro cartaceo. La tecnologia è utile, ma il relax è importante per la mia salute mentale.', '[{"prompt":"Cosa fa l''autore dopo essersi svegliato?","options":["Prepara la colazione","Controlla le email","Esce di casa","Guarda la televisione"],"answer_index":1,"explanation_pt_br":"Il testo dice esplicitamente che, appena sveglio, l''autore controlla le email."},{"prompt":"Cosa significa il verbo ''staccare'' nel testo?","options":["Rompere qualcosa","Spegnere i dispositivi","Andare a dormire","Lavorare di più"],"answer_index":1,"explanation_pt_br":"Nel contesto della tecnologia, ''staccare'' significa interrompere l''uso dei dispositivi digitali."},{"prompt":"Qual è l''idea principale del testo?","options":["La tecnologia è inutile","Il lavoro è difficile","L''equilibrio tra tecnologia e riposo","Lo smartphone è rotto"],"answer_index":2,"explanation_pt_br":"L''autore descrive l''uso della tecnologia ma sottolinea l''importanza di prendersi una pausa la sera."}]'::jsonb, 6),
('it-passage-a1-07', 'it', 'A1', 'Vivere in modo sostenibile', 'Molte persone oggi vogliono proteggere il pianeta. Io cerco di fare piccoli gesti ogni giorno per ridurre il mio impatto ambientale a casa.

Per esempio, faccio sempre la raccolta differenziata. Riciclo plastica, vetro e carta con attenzione. Inoltre, compro prodotti locali al mercato per evitare troppa plastica negli imballaggi.

Vado al lavoro in bicicletta quando c''è il sole. Questa scelta è buona per l''ambiente e anche per il mio corpo. Piccole azioni possono davvero cambiare il nostro futuro comune.', '[{"prompt":"Cosa fa l''autore con plastica, vetro e carta?","options":["Li butta insieme","Li ricicla","Li compra al mercato","Li usa per la bici"],"answer_index":1,"explanation_pt_br":"Il testo afferma chiaramente che l''autore ricicla questi materiali."},{"prompt":"Quale mezzo di trasporto usa l''autore per andare al lavoro?","options":["L''autobus","Il treno","La bicicletta","L''automobile"],"answer_index":2,"explanation_pt_br":"L''autore menziona esplicitamente l''uso della bicicletta per recarsi al lavoro."},{"prompt":"Perché l''autore compra prodotti locali?","options":["Per risparmiare soldi","Per parlare con gli amici","Per evitare troppa plastica","Perché sono più economici"],"answer_index":2,"explanation_pt_br":"Il testo indica che l''acquisto di prodotti locali serve a evitare l''uso di troppa plastica negli imballaggi."}]'::jsonb, 7),
('it-passage-a1-08', 'it', 'A1', 'Amicizia e tempo libero', 'Avere buoni amici è molto importante per essere felici. Durante la settimana sono sempre molto impegnato con il lavoro, quindi il tempo libero è prezioso.

Il sabato sera esco spesso con i miei amici più stretti. Ci piace andare al cinema o mangiare una pizza in centro. È il momento ideale per parlare e ridere insieme.

La domenica preferisco stare con la mia famiglia. Facciamo una passeggiata al parco o cuciniamo qualcosa di buono. Le relazioni sociali rendono la mia vita piena di gioia e serenità.', '[{"prompt":"Quando esce l''autore con i suoi amici?","options":["Ogni mattina","Il sabato sera","La domenica mattina","Durante il lavoro"],"answer_index":1,"explanation_pt_br":"Il testo specifica che l''autore esce con gli amici il sabato sera."},{"prompt":"Cosa fa l''autore la domenica?","options":["Va al cinema","Lavora in ufficio","Passa tempo con la famiglia","Va a fare la spesa"],"answer_index":2,"explanation_pt_br":"Il testo dichiara che la domenica l''autore preferisce stare con la sua famiglia."},{"prompt":"Qual è il sentimento espresso nel testo?","options":["Tristezza","Noia","Felicità nelle relazioni","Solitudine"],"answer_index":2,"explanation_pt_br":"L''autore descrive le relazioni sociali come fonte di gioia e serenità."}]'::jsonb, 8),
('it-passage-a1-09', 'it', 'A1', 'Gestire il denaro', 'Gestire le finanze personali è una competenza fondamentale per ogni adulto. Ogni mese controllo le mie spese per capire dove vanno i miei soldi.

Pago sempre l''affitto e le bollette appena ricevo lo stipendio. Dopo, metto da parte una piccola somma per le emergenze. Questo mi aiuta a vivere senza troppe preoccupazioni.

Evito di comprare cose inutili che non mi servono davvero. Preferisco risparmiare per un viaggio o per un corso interessante. Controllare i consumi è il primo passo verso una vita più tranquilla.', '[{"prompt":"Cosa fa l''autore dopo aver ricevuto lo stipendio?","options":["Compra vestiti","Paga affitto e bollette","Va in vacanza","Presta soldi"],"answer_index":1,"explanation_pt_br":"Il testo dice che l''autore paga le spese fisse subito dopo aver ricevuto lo stipendio."},{"prompt":"Perché l''autore risparmia denaro?","options":["Per comprare un''auto","Per le emergenze","Per regalare soldi","Per pagare meno tasse"],"answer_index":1,"explanation_pt_br":"L''autore mette da parte una somma specificamente per le emergenze."},{"prompt":"Qual è l''atteggiamento dell''autore verso il consumo?","options":["Compra tutto ciò che vede","Evita le spese inutili","Spende tutto subito","Non sa gestire i soldi"],"answer_index":1,"explanation_pt_br":"L''autore afferma esplicitamente di evitare di comprare cose inutili."}]'::jsonb, 9),
('it-passage-a1-10', 'it', 'A1', 'Imparare sempre', 'L''istruzione non finisce mai con la scuola. Credo che imparare cose nuove sia importante a ogni età per mantenere la mente attiva e curiosa.

Attualmente frequento un corso di italiano online. È difficile ma molto interessante. Studio la grammatica e ascolto dialoghi per migliorare la mia pronuncia ogni giorno.

Inoltre, leggo molti articoli di cultura generale. Imparare è un viaggio che dura tutta la vita. Sono felice di dedicare del tempo alla mia crescita personale ogni settimana.', '[{"prompt":"Cosa pensa l''autore dell''istruzione?","options":["Finisce con la scuola","È solo per bambini","Continua per tutta la vita","È molto noiosa"],"answer_index":2,"explanation_pt_br":"L''autore afferma che l''istruzione non finisce con la scuola e dura tutta la vita."},{"prompt":"Cosa sta studiando l''autore?","options":["La matematica","La lingua italiana","La cucina","La storia"],"answer_index":1,"explanation_pt_br":"Il testo specifica che l''autore sta frequentando un corso di italiano online."},{"prompt":"Perché l''autore studia?","options":["Per obbligo","Per mantenere la mente attiva","Per cambiare lavoro","Per fare amicizia"],"answer_index":1,"explanation_pt_br":"L''autore dice che imparare è importante per mantenere la mente attiva e curiosa."}]'::jsonb, 10),
('it-passage-a2-01', 'it', 'A2', 'La giornata di Marco', 'Marco vive a San Paolo e lavora in un ufficio nel centro della città. Ogni mattina, la sua sveglia suona alle sei e mezza. Lui si alza subito, prepara un caffè forte e legge le notizie sul suo telefono. È un momento tranquillo prima di iniziare la giornata frenetica.

Dopo la colazione, Marco si veste con cura e prende l''autobus per andare al lavoro. Il viaggio dura circa quaranta minuti. Durante il tragitto, ascolta spesso dei podcast in italiano per migliorare la sua comprensione. Gli piace molto imparare cose nuove mentre viaggia nel traffico cittadino.

In ufficio, Marco risponde a molte email e partecipa a diverse riunioni con i colleghi. Verso mezzogiorno, mangia un pranzo leggero con i suoi amici vicino al posto di lavoro. Parlano del fine settimana e dei loro progetti futuri. È un momento importante per rilassarsi e socializzare.

La sera, Marco torna a casa stanco ma soddisfatto. Cucina una cena semplice, guarda una serie televisiva e prepara i vestiti per il giorno seguente. Prima di dormire, organizza sempre la sua borsa. Questa routine costante lo aiuta a vivere con molta più indipendenza e serenità ogni singolo giorno.', '[{"prompt":"Cosa fa Marco subito dopo essersi alzato?","options":["Prepara una colazione ricca","Legge le notizie sul telefono","Prende l''autobus per l''ufficio","Ascolta i podcast in italiano"],"answer_index":1,"explanation_pt_br":"O texto afirma que ele se levanta, prepara um café e lê as notícias antes de qualquer outra coisa."},{"prompt":"Cosa significa ''frenetica'' nel primo paragrafo?","options":["Molto lenta","Molto calma","Molto movimentata","Molto difficile"],"answer_index":2,"explanation_pt_br":"No contexto da rotina de trabalho em uma grande cidade, frenetica descreve algo cheio de movimento e rapidez."},{"prompt":"Qual è l''ordine delle attività di Marco?","options":["Pranzo, lavoro, trasporto, riposo","Trasporto, pranzo, lavoro, riposo","Risveglio, trasporto, lavoro, riposo","Risveglio, lavoro, riposo, trasporto"],"answer_index":2,"explanation_pt_br":"O texto segue uma ordem cronológica: acorda, vai para o trabalho, trabalha, almoça e volta para casa."},{"prompt":"Qual è l''idea principale del testo?","options":["La vita lavorativa di un impiegato","L''importanza di una routine organizzata","Il traffico nella città di San Paolo","Come imparare l''italiano ogni giorno"],"answer_index":1,"explanation_pt_br":"O texto descreve como a rotina organizada ajuda Marco a ser mais independente e sereno."}]'::jsonb, 1),
('it-passage-a2-02', 'it', 'A2', 'Un viaggio in Italia', 'Giulia ama viaggiare e scoprire posti nuovi. L''anno scorso ha deciso di visitare l''Italia per la prima volta. Ha prenotato un volo per Roma, la città eterna. Era molto emozionata perché voleva vedere i monumenti antichi e mangiare il vero cibo italiano.

Appena arrivata, ha cercato un piccolo hotel vicino al centro storico. Ha camminato per ore tra le strade strette e accoglienti, guardando le vetrine dei negozi. Ha visitato il Colosseo e la Fontana di Trevi, restando incantata dalla bellezza di ogni singola pietra e scultura.

Durante il viaggio, ha incontrato molti turisti da tutto il mondo. Ha parlato con loro nei caffè e ha condiviso consigli preziosi sui musei. Nonostante la barriera linguistica iniziale, ha imparato molte parole utili per ordinare al ristorante e chiedere indicazioni stradali.

Questa esperienza ha cambiato il suo modo di vedere il mondo. Giulia ha scoperto che viaggiare non è solo visitare monumenti, ma è conoscere persone diverse e nuove culture. Ora sta già sognando la sua prossima avventura in un altro paese europeo per continuare a esplorare.', '[{"prompt":"Perché Giulia ha scelto di andare a Roma?","options":["Per motivi di lavoro","Per vedere monumenti e mangiare","Per incontrare i suoi parenti","Per studiare la lingua italiana"],"answer_index":1,"explanation_pt_br":"O texto menciona explicitamente o desejo de ver monumentos antigos e comer a comida italiana."},{"prompt":"Cosa significa ''incantata'' nel secondo paragrafo?","options":["Molto annoiata","Molto affascinata","Molto stanca","Molto confusa"],"answer_index":1,"explanation_pt_br":"Estar encantada com a beleza de algo significa estar fascinada ou maravilhada."},{"prompt":"Cosa ha fatto Giulia durante il suo viaggio?","options":["Ha lavorato in un hotel","Ha visitato solo musei","Ha camminato e parlato con altri turisti","Ha comprato molti vestiti nei negozi"],"answer_index":2,"explanation_pt_br":"O texto descreve que ela caminhou pelas ruas e conversou com outros turistas em cafés."},{"prompt":"Qual è il messaggio principale del testo?","options":["Viaggiare è costoso e difficile","Roma è la città più bella d''Italia","Il viaggio è una scoperta culturale","È meglio viaggiare da soli"],"answer_index":2,"explanation_pt_br":"O último parágrafo resume que viajar é sobre conhecer pessoas e culturas, não apenas monumentos."}]'::jsonb, 2),
('it-passage-a2-03', 'it', 'A2', 'Il nuovo ufficio di Elena', 'Elena ha trovato un nuovo lavoro in un''importante azienda di marketing. Il suo ufficio è moderno e molto luminoso. Ogni mattina, Elena arriva puntuale e saluta i suoi colleghi con un sorriso. L''ambiente è stimolante e tutti lavorano in grande sintonia.

Il suo compito principale è gestire i progetti per i clienti internazionali. Deve scrivere molte email e parlare al telefono con partner stranieri. Per fare questo, Elena usa il computer e diversi software specializzati. La comunicazione chiara è fondamentale per il successo del gruppo.

Durante la pausa caffè, Elena discute le nuove idee con il suo responsabile. Si siedono in una sala riunioni confortevole. Queste conversazioni sono molto utili per risolvere piccoli problemi quotidiani. La collaborazione è il segreto per lavorare bene e ottenere risultati eccellenti ogni mese.

Elena è molto felice del suo percorso professionale. Sente che sta imparando molto e sta crescendo ogni giorno di più. Il lavoro le offre sfide interessanti e la possibilità di viaggiare in futuro. È soddisfatta della sua scelta e guarda al domani con grande fiducia.', '[{"prompt":"Qual è il lavoro di Elena?","options":["Gestisce progetti di marketing","Scrive software per computer","Lavora in un hotel internazionale","Organizza viaggi per i colleghi"],"answer_index":0,"explanation_pt_br":"O texto afirma que ela trabalha em uma empresa de marketing gerenciando projetos."},{"prompt":"Cosa significa ''sintonia'' nel primo paragrafo?","options":["Lontananza","Disaccordo","Collaborazione","Silenzio"],"answer_println":"Collaborazione","answer_index":2,"explanation_pt_br":"Trabalhar em sintonia significa trabalhar em harmonia ou colaboração."},{"prompt":"Cosa fa Elena durante la pausa caffè?","options":["Mangia da sola","Scrive molte email","Discute idee con il responsabile","Viaggia per lavoro"],"answer_index":2,"explanation_pt_br":"O terceiro parágrafo descreve que ela discute ideias com seu superior durante a pausa."},{"prompt":"Come si sente Elena riguardo al suo lavoro?","options":["È stanca e vuole cambiare","È felice e ottimista","È preoccupata per le sfide","È annoiata dalla routine"],"answer_index":1,"explanation_pt_br":"O último parágrafo deixa claro que ela está feliz, crescendo e confiante no futuro."}]'::jsonb, 3),
('it-passage-a2-04', 'it', 'A2', 'La salute prima di tutto', 'Prendersi cura della propria salute è essenziale per vivere bene. Paolo ha deciso di cambiare il suo stile di vita. Ha iniziato a camminare nel parco ogni giorno per trenta minuti. Questo esercizio fisico lo aiuta a sentirsi più energico e meno stressato.

Oltre al movimento, Paolo mangia molta frutta e verdura fresca. Beve anche due litri di acqua al giorno. Ha ridotto il consumo di dolci e cibi grassi. Anche se all''inizio era difficile, ora segue questa dieta con molta facilità e piacere.

Il benessere non è solo fisico ma anche mentale. Paolo dedica tempo alla lettura e alla meditazione. Prima di dormire, spegne il cellulare per rilassarsi completamente. Dormire otto ore a notte è la sua regola d''oro per affrontare le sfide lavorative.

Grazie a queste abitudini, Paolo si sente una persona nuova. Non soffre più di mal di testa e ha più pazienza con gli altri. La salute è il suo bene più prezioso e vuole continuare così per molti anni, mantenendo un equilibrio costante tra corpo e mente.', '[{"prompt":"Cosa ha fatto Paolo per migliorare la salute?","options":["Ha iniziato a correre una maratona","Ha smesso di lavorare","Ha iniziato a camminare ogni giorno","Ha comprato nuove medicine"],"answer_index":2,"explanation_pt_br":"O primeiro parágrafo menciona que ele começou a caminhar no parque diariamente."},{"prompt":"Cosa significa ''essenziale'' nel primo paragrafo?","options":["Molto importante","Poco utile","Molto costoso","Molto strano"],"answer_index":0,"explanation_pt_br":"Algo essencial é algo fundamental ou muito importante."},{"prompt":"Quale abitudine segue Paolo prima di dormire?","options":["Legge le email del lavoro","Beve molta acqua","Spegne il cellulare","Mangia cibi grassi"],"answer_index":2,"explanation_pt_br":"O terceiro parágrafo afirma que ele desliga o celular antes de dormir para relaxar."},{"prompt":"Qual è l''idea principale del testo?","options":["Dormire poco fa bene alla salute","Lo sport è più importante del cibo","L''importanza di uno stile di vita sano","La dieta è l''unica cosa necessaria"],"answer_index":2,"explanation_pt_br":"O texto trata de forma geral sobre como adotar hábitos saudáveis traz bem-estar físico e mental."}]'::jsonb, 4),
('it-passage-a2-05', 'it', 'A2', 'Una cena speciale', 'In Italia, il cibo è un momento di unione molto importante. Ieri sera, la famiglia Rossi ha organizzato una cena a casa. Hanno preparato la pasta fatta in casa con il sugo di pomodoro fresco. Il profumo del basilico riempiva tutta la cucina della casa.

Tutti hanno aiutato a preparare la tavola. Hanno messo le posate, i bicchieri e una tovaglia colorata. Quando gli ospiti sono arrivati, c''era un''atmosfera di grande gioia. La tradizione di mangiare insieme rafforza il legame tra amici e familiari ogni volta.

Durante la cena, hanno raccontato storie divertenti e hanno riso molto. Hanno gustato anche del pane appena sfornato e un dolce fatto con la ricetta della nonna. La condivisione del pasto è una cultura che unisce le generazioni e crea ricordi bellissimi per tutti.

Alla fine della serata, tutti erano felici e soddisfatti. Queste tradizioni culinarie sono parte dell''identità italiana. Per la famiglia Rossi, la cucina non è solo cibo, ma è un gesto d''amore. Sperano di ripetere presto questo incontro speciale con le persone che amano davvero.', '[{"prompt":"Cosa ha preparato la famiglia Rossi?","options":["Una pizza surgelata","Pasta fatta in casa","Un arrosto di carne","Una torta di cioccolato"],"answer_index":1,"explanation_pt_br":"O primeiro parágrafo diz que eles prepararam massa feita em casa."},{"prompt":"Cosa significa ''unione'' nel primo paragrafo?","options":["Separazione","Incontro","Lavoro","Tristezza"],"answer_index":1,"explanation_pt_br":"Unione indica o ato de estar junto ou um encontro entre pessoas."},{"prompt":"Cosa hanno fatto gli ospiti durante la cena?","options":["Hanno guardato la televisione","Hanno lavorato al computer","Hanno raccontato storie e riso","Hanno pulito la cucina"],"answer_index":2,"explanation_pt_br":"O terceiro parágrafo descreve que eles conversaram, contaram histórias e riram."},{"prompt":"Qual è il significato del cibo per la famiglia Rossi?","options":["È solo una necessità","È un modo per mostrare amore","È un modo per risparmiare","È un lavoro professionale"],"answer_index":1,"explanation_pt_br":"O último parágrafo define explicitamente que para a família, a culinária é um gesto de amor."}]'::jsonb, 5),
('it-passage-a2-06', 'it', 'A2', 'La tecnologia nella mia giornata', 'Ogni mattina, Marco si sveglia con la sveglia del suo smartphone. Controlla subito le notifiche, le email di lavoro e i messaggi degli amici su WhatsApp. La tecnologia è diventata una parte fondamentale della sua routine quotidiana in ufficio.

Prima di uscire, usa un''applicazione per controllare il traffico e il meteo. Preferisce viaggiare in treno e usa il telefono per comprare il biglietto digitale. In questo modo, evita le lunghe code alla stazione e risparmia molto tempo prezioso.

Durante il pomeriggio, lavora spesso al computer per scrivere documenti importanti. Usa anche il cloud per salvare i file, così può vederli ovunque si trovi. Spesso partecipa a riunioni online con colleghi che vivono in altre città lontane.

La sera, Marco si rilassa guardando un film su una piattaforma di streaming. Prima di dormire, spegne il Wi-Fi per riposare meglio. La tecnologia semplifica la sua vita, ma lui cerca di usarla con molta attenzione e grande equilibrio.', '[{"prompt":"Cosa fa Marco appena si sveglia?","options":["Prepara una colazione sana","Controlla il suo smartphone","Esce subito di casa","Guarda un film online"],"answer_index":1,"explanation_pt_br":"Il testo dice chiaramente che Marco controlla le notifiche e i messaggi sullo smartphone appena sveglio."},{"prompt":"Cosa significa ''tempo prezioso'' nel testo?","options":["Tempo molto costoso","Tempo poco importante","Tempo di grande valore","Tempo che passa velocemente"],"answer_index":2,"explanation_pt_br":"In questo contesto, ''prezioso'' indica qualcosa di importante o che ha grande valore per la persona."},{"prompt":"Perché Marco usa il cloud?","options":["Per guardare film","Per evitare il traffico","Per accedere ai file ovunque","Per scrivere email ai colleghi"],"answer_index":2,"explanation_pt_br":"Il testo spiega che usa il cloud per poter vedere i suoi file da qualsiasi luogo si trovi."},{"prompt":"Qual è l''idea principale del brano?","options":["La tecnologia è pericolosa","La tecnologia aiuta la vita quotidiana","Marco lavora solo online","I treni sono sempre in ritardo"],"answer_index":1,"explanation_pt_br":"Il brano descrive come gli strumenti tecnologici facilitino e organizzino la routine di Marco."}]'::jsonb, 6),
('it-passage-a2-07', 'it', 'A2', 'Scelte verdi per il futuro', 'Elena vive in un piccolo appartamento e cerca di vivere in modo sostenibile. Ogni giorno, separa con molta attenzione i rifiuti di casa: plastica, carta, vetro e umido. Lei pensa che il riciclo sia un dovere di ogni cittadino moderno.

Per andare al supermercato, Elena porta sempre la sua borsa di tela. Non compra mai sacchetti di plastica perché inquinano troppo l''ambiente. Preferisce acquistare prodotti locali dai contadini del mercato perché hanno meno imballaggi e sono freschi.

In casa, Elena usa solo lampadine a basso consumo energetico. Quando esce da una stanza, spegne sempre la luce per non sprecare elettricità. Inoltre, chiude il rubinetto mentre si lava i denti per risparmiare molta acqua ogni giorno.

Queste piccole azioni quotidiane sono importanti per proteggere il nostro pianeta. Elena crede che, se tutti facciamo piccoli sacrifici, il futuro sarà più pulito. La sostenibilità non è difficile, richiede solo un po'' di buona volontà e costanza.', '[{"prompt":"Cosa fa Elena al supermercato?","options":["Compra molti sacchetti","Usa una borsa di tela","Compra solo plastica","Non fa la spesa"],"answer_index":1,"explanation_pt_br":"Il testo afferma che Elena porta sempre la sua borsa di tela per evitare i sacchetti di plastica."},{"prompt":"Cosa significa ''basso consumo''?","options":["Che usa molta energia","Che è molto economica","Che usa poca elettricità","Che è rotta"],"answer_index":2,"explanation_pt_br":"In questo contesto, si riferisce a dispositivi che consumano una quantità ridotta di energia."},{"prompt":"Qual è l''ordine delle azioni di Elena in casa?","options":["Spegne le luci e apre l''acqua","Lava i denti e accende la luce","Risparmia acqua e spegne le luci","Compra lampadine e le rompe"],"answer_index":2,"explanation_pt_br":"Il testo menziona il risparmio idrico e lo spegnimento delle luci come azioni concrete."},{"prompt":"Qual è il messaggio principale dell''autore?","options":["Vivere in modo sostenibile è facile","Il riciclo è inutile","Dobbiamo comprare molti prodotti","Elena vive in campagna"],"answer_index":0,"explanation_pt_br":"L''autore sottolinea che piccoli gesti quotidiani rendono lo stile di vita sostenibile accessibile a tutti."}]'::jsonb, 7),
('it-passage-a2-08', 'it', 'A2', 'Amicizie e vita sociale', 'Luigi ama passare il tempo libero con i suoi amici. Ogni sabato sera, il gruppo si incontra in un bar del centro per bere qualcosa. Parlano del lavoro, delle passioni comuni e dei viaggi che vogliono fare in futuro.

Recentemente, Luigi ha conosciuto nuove persone a un corso di cucina. È stato un modo divertente per ampliare il suo circolo sociale. Condividere un hobby, come preparare la pasta fresca, aiuta a costruire legami più forti e sinceri.

A volte, organizzano cene a casa di qualcuno. Ognuno porta un piatto diverso e si divertono molto insieme. Queste serate sono perfette per rilassarsi dopo una settimana di lavoro faticosa e per ridere in totale tranquillità.

La vita sociale è essenziale per la felicità di Luigi. Lui pensa che gli amici siano una ricchezza importante nella vita. Anche se a volte è stanco, uscire con gli altri gli regala sempre molta energia positiva.', '[{"prompt":"Dove si incontra Luigi con gli amici?","options":["A scuola","In un bar","Al lavoro","In cucina"],"answer_index":1,"explanation_pt_br":"Il testo specifica che il gruppo si incontra in un bar del centro il sabato sera."},{"prompt":"Cosa significa ''ampliare il suo circolo sociale''?","options":["Fare nuovi amici","Studiare sociologia","Cambiare casa","Lavorare di più"],"answer_index":0,"explanation_pt_br":"Significa conoscere persone nuove e aumentare il numero dei propri conoscenti o amici."},{"prompt":"Cosa succede alle cene a casa?","options":["Ognuno porta un regalo","Ognuno prepara un piatto","Luigi cucina per tutti","Comprano cibo pronto"],"answer_index":1,"explanation_pt_br":"Il testo dice che alle cene ognuno porta un piatto diverso da condividere."},{"prompt":"Come si sente Luigi dopo le uscite?","options":["Molto triste","Molto stanco","Pieno di energia","Annoiato"],"answer_index":2,"explanation_pt_br":"Il testo afferma chiaramente che uscire con gli amici gli regala energia positiva."}]'::jsonb, 8),
('it-passage-a2-09', 'it', 'A2', 'Gestire i propri soldi', 'Giulia è molto attenta al suo bilancio mensile. Prima di ogni mese, scrive su un quaderno tutte le sue entrate e le spese fisse. Questo metodo la aiuta a capire dove può risparmiare per il futuro.

Per evitare acquisti inutili, Giulia fa sempre una lista prima di andare al supermercato. Cerca di comprare solo ciò che è necessario e confronta i prezzi tra diverse marche. Spesso approfitta delle offerte speciali sui prodotti a lunga conservazione.

Non ama usare molto la carta di credito perché preferisce vedere i soldi che spende. Quando riesce a mettere da parte una piccola somma, la deposita sul suo conto di risparmio. È importante avere sempre un fondo per le emergenze.

Grazie a questa disciplina, Giulia non ha debiti e vive con serenità. Lei pensa che la finanza personale sia una competenza fondamentale per ogni adulto. Con un piano chiaro, è possibile gestire bene i soldi senza troppe rinunce.', '[{"prompt":"Cosa fa Giulia prima di andare al supermercato?","options":["Prende la carta di credito","Scrive una lista","Compra tutto in offerta","Non guarda i prezzi"],"answer_index":1,"explanation_pt_br":"Giulia fa sempre una lista per evitare acquisti non necessari."},{"prompt":"Cosa significa ''spese fisse''?","options":["Spese che cambiano ogni giorno","Costi obbligatori e prevedibili","Spese molto alte","Soldi prestati agli amici"],"answer_index":1,"explanation_pt_br":"Le spese fisse sono costi regolari, come l''affitto o le bollette, che si sanno in anticipo."},{"prompt":"Dove mette Giulia i soldi che risparmia?","options":["Nel quaderno","In un fondo di emergenza","In un conto di risparmio","Nella carta di credito"],"answer_index":2,"explanation_pt_br":"Il testo dice che deposita le somme risparmiate sul suo conto di risparmio."},{"prompt":"Qual è il tema principale del brano?","options":["Come diventare ricchi","L''importanza di fare debiti","La gestione delle finanze personali","Come spendere tutto lo stipendio"],"answer_index":2,"explanation_pt_br":"Il brano descrive le abitudini e le strategie di Giulia per gestire il proprio denaro."}]'::jsonb, 9),
('it-passage-a2-10', 'it', 'A2', 'Imparare sempre', 'Paolo ha finito l''università anni fa, ma continua a studiare ogni giorno. Crede che l''apprendimento non finisca mai e che sia necessario aggiornarsi costantemente. Per questo motivo, dedica un''ora ogni sera alla lettura di libri di saggistica.

Recentemente, ha iniziato un corso online di lingua straniera. Studia con entusiasmo perché vuole viaggiare e conoscere nuove culture. Gli piace molto ascoltare i podcast mentre va al lavoro in autobus, così usa bene il tempo libero.

Il suo obiettivo è imparare a usare nuovi programmi informatici per il suo lavoro. Si iscrive spesso a seminari gratuiti su internet. Anche i suoi colleghi lo ammirano perché è sempre pronto a imparare qualcosa di nuovo e utile.

Imparare durante tutta la vita è un investimento per il futuro. Paolo si sente più sicuro e preparato davanti alle sfide. Con la curiosità e la costanza, ogni persona può migliorare le proprie abilità professionali e personali.', '[{"prompt":"Cosa fa Paolo ogni sera?","options":["Guarda la televisione","Legge libri","Lavora in ufficio","Scrive un diario"],"answer_index":1,"explanation_pt_br":"Paolo dedica un''ora ogni sera alla lettura di libri di saggistica."},{"prompt":"Cosa significa ''aggiornarsi''?","options":["Cambiare lavoro","Imparare cose nuove","Dimenticare il passato","Comprare nuovi libri"],"answer_index":1,"explanation_pt_br":"Aggiornarsi significa acquisire conoscenze recenti per restare al passo con i tempi."},{"prompt":"Cosa fa Paolo mentre va al lavoro?","options":["Legge un libro","Ascolta dei podcast","Scrive al computer","Parla con i colleghi"],"answer_index":1,"explanation_pt_br":"Il testo specifica che ascolta podcast durante il viaggio in autobus verso il lavoro."},{"prompt":"Qual è il punto principale del testo?","options":["L''università è inutile","L''apprendimento deve continuare sempre","Paolo non ama il suo lavoro","Imparare è solo per i giovani"],"answer_index":1,"explanation_pt_br":"Il brano sostiene l''idea che imparare sia un processo continuo e fondamentale per tutta la vita."}]'::jsonb, 10),
('it-passage-b1-01', 'it', 'B1', 'La nuova indipendenza di Giulia', 'Giulia vive da sola a Milano da circa sei mesi. Trasferirsi in una grande città è stata una sfida importante, ma ora ha finalmente stabilito una routine quotidiana che le permette di gestire tutto con autonomia. Ogni mattina, la sveglia suona alle sette, un orario che le consente di prepararsi senza fretta prima di uscire per il lavoro.

La sua giornata inizia sempre con una colazione nutriente, solitamente a base di caffè e biscotti integrali. Dopo aver riordinato velocemente il piccolo appartamento, Giulia controlla la sua agenda digitale. Organizzare il tempo è fondamentale per lei, specialmente perché deve conciliare le responsabilità professionali con la cura della casa, che richiede attenzione costante.

Il tragitto verso l''ufficio è un momento di riflessione. Giulia preferisce usare la metropolitana, un mezzo efficiente che le dà l''opportunità di leggere le notizie del giorno o ascoltare un podcast in italiano. Questo tempo speso durante il pendolarismo è diventato, inaspettatamente, una parte integrante del suo benessere mentale e della sua crescita personale.

Una volta terminata la giornata lavorativa, Giulia si dedica alla spesa o a qualche commissione necessaria. La gestione delle finanze domestiche e della spesa settimanale è stata la lezione più complicata da imparare, ma ora si sente molto più sicura. Scegliere prodotti freschi al mercato locale è diventato un rito che le ricorda l''importanza di mangiare sano.

La sera, prima di andare a dormire, Giulia ama rilassarsi leggendo un libro o pianificando le attività del giorno successivo. Anche se a volte sente la mancanza della sua famiglia in Brasile, la soddisfazione di essere diventata una donna indipendente e capace di affrontare ogni imprevisto la ripaga di ogni fatica. La sua routine non è solo abitudine, ma libertà.', '[{"prompt":"Qual è il significato di ''conciliare'' nel testo?","options":["Separare nettamente due attività diverse","Trovare un equilibrio tra obblighi differenti","Dimenticare le proprie responsabilità","Delegare il lavoro ad altre persone"],"answer_index":1,"explanation_pt_br":"No contexto, conciliare significa equilibrar as exigências do trabalho com as tarefas domésticas."},{"prompt":"Come trascorre Giulia il tempo in metropolitana?","options":["Dorme per recuperare le energie","Lavora al computer portatile","Si informa o ascolta contenuti audio","Parla costantemente al telefono"],"answer_index":2,"explanation_pt_br":"O texto menciona que ela aproveita para ler notícias ou ouvir podcasts."},{"prompt":"Cosa ha trovato più difficile Giulia nella sua nuova vita?","options":["Svegliarsi presto ogni mattina","Trovare un appartamento a Milano","Gestire le spese e la spesa settimanale","Adattarsi al clima della città"],"answer_index":2,"explanation_pt_br":"Giulia afirma que a gestão das finanças e das compras foi a lição mais complicada."},{"prompt":"Qual è l''atteggiamento di Giulia verso la sua routine?","options":["La considera noiosa e limitante","La vive come un simbolo di indipendenza","La segue solo per obbligo lavorativo","Vorrebbe cambiarla radicalmente"],"answer_index":1,"explanation_pt_br":"O texto conclui dizendo que a rotina dela representa liberdade e satisfação."},{"prompt":"Qual è l''idea principale di questo testo?","options":["I problemi di vivere in una grande città","L''importanza di una dieta sana per i lavoratori","Il processo di adattamento e autonomia di una giovane donna","La difficoltà di vivere lontani dalla famiglia"],"answer_index":2,"explanation_pt_br":"O foco do texto é o crescimento pessoal e a independência alcançada por Giulia."}]'::jsonb, 1),
('it-passage-b1-02', 'it', 'B1', 'Un viaggio indimenticabile in Sicilia', 'L''anno scorso, Marco ha deciso di intraprendere un viaggio in solitaria attraverso la Sicilia, un''isola che sognava di visitare da molto tempo. Non voleva un pacchetto turistico organizzato, preferendo la libertà di muoversi senza un itinerario rigido. Aveva affittato una piccola auto per poter esplorare anche le zone più remote e meno conosciute della costa.

Il suo viaggio è iniziato a Palermo, una città vibrante e caotica, dove i colori e i profumi del mercato hanno subito catturato la sua attenzione. Camminare tra le bancarelle era come fare un salto indietro nel tempo, circondato da architetture che raccontano secoli di dominazioni diverse. La storia si percepiva in ogni angolo della città siciliana.

Proseguendo verso sud, Marco ha visitato la Valle dei Templi. Si è sentito piccolo di fronte alla maestosità delle rovine greche, che si stagliavano contro un cielo azzurro intenso. È stato uno dei momenti più significativi del viaggio, un''esperienza che gli ha permesso di riflettere sulla bellezza del patrimonio culturale italiano e sulla sua conservazione.

Non sono mancate le sorprese culinarie. In un piccolo villaggio di pescatori, Marco ha assaggiato piatti preparati con il pescato del giorno, scoprendo sapori unici che non avrebbe mai trovato in un ristorante di lusso. La gentilezza dei locali, sempre pronti a raccontare una storia o a dare un consiglio, ha reso il soggiorno ancora più autentico e speciale.

Al ritorno, Marco ha portato con sé non solo fotografie, ma anche una nuova prospettiva sul modo di viaggiare. Ha capito che scoprire un luogo significa immergersi nella sua cultura, parlando con le persone e rispettando le tradizioni locali. Questo viaggio in Sicilia è stato per lui una vera lezione di vita e di scoperta personale.', '[{"prompt":"Perché Marco ha scelto di non usare un pacchetto turistico?","options":["Perché costavano troppo cari","Perché voleva avere libertà di movimento","Perché non parlava bene la lingua","Perché preferiva viaggiare in gruppo"],"answer_index":1,"explanation_pt_br":"O texto diz que ele preferia a liberdade de se mover sem um roteiro rígido."},{"prompt":"Cosa significa l''espressione ''fare un salto indietro nel tempo'' nel contesto?","options":["Dimenticare le cose accadute","Sentire l''influenza della storia passata","Viaggiare fisicamente verso il passato","Correre molto velocemente"],"answer_index":1,"explanation_pt_br":"A expressão refere-se a sentir a história e as tradições antigas vivas no presente."},{"prompt":"Quale sensazione ha provato Marco alla Valle dei Templi?","options":["Tristezza per le rovine distrutte","Soddisfazione per aver completato il percorso","Senso di piccolezza davanti alla grandezza storica","Noia per la troppa cultura"],"answer_index":2,"explanation_pt_br":"O texto afirma explicitamente que ele se sentiu pequeno diante da majestosidade das ruínas."},{"prompt":"Cosa ha apprezzato di più Marco dell''esperienza nei villaggi?","options":["I ristoranti di lusso molto costosi","La possibilità di fare shopping","Il contatto umano e l''autenticità dei locali","La facilità di trovare parcheggio"],"answer_index":2,"explanation_pt_br":"Marco valorizou a gentileza dos moradores e a autenticidade das interações."},{"prompt":"Qual è il messaggio principale del racconto di Marco?","options":["La Sicilia è la regione più bella d''Italia","Viaggiare significa connettersi profondamente con le persone e la cultura","È necessario pianificare ogni dettaglio del viaggio","Il cibo è l''unico motivo valido per viaggiare"],"answer_index":1,"explanation_pt_br":"O autor conclui que viajar é imergir na cultura local e respeitar as tradições."}]'::jsonb, 2),
('it-passage-b1-03', 'it', 'B1', 'La comunicazione efficace in ufficio', 'Nel mondo del lavoro moderno, la capacità di comunicare in modo chiaro e professionale è diventata indispensabile. Elena, che lavora in un''azienda multinazionale, ha capito presto che il successo di un progetto non dipende solo dalle competenze tecniche, ma soprattutto dal modo in cui le idee vengono trasmesse ai colleghi durante le riunioni.

Ogni lunedì mattina, Elena partecipa a un briefing settimanale. Durante questi incontri, l''uso di un linguaggio preciso è fondamentale per evitare malintesi. Lei si assicura sempre di ascoltare attivamente gli altri prima di intervenire, una tecnica che ha migliorato notevolmente il clima collaborativo all''interno del suo team, riducendo le tensioni inutili.

Oltre alla comunicazione verbale, Elena presta molta attenzione alle e-mail professionali. Scrivere messaggi brevi, chiari e cortesi è il suo marchio di fabbrica. Ha imparato che inviare e-mail troppo lunghe o confuse spesso porta a una perdita di tempo prezioso per tutti, quindi cerca di andare dritta al punto, mantenendo sempre un tono rispettoso e formale.

Un altro aspetto cruciale è la gestione dei conflitti. Quando emergono opinioni contrastanti, Elena cerca di mantenere la calma e di focalizzarsi sulle soluzioni piuttosto che sulle colpe. Questa attitudine le ha permesso di costruire relazioni solide con i suoi superiori e con i collaboratori, venendo spesso scelta come mediatrice nei momenti di crisi aziendale più complessi.

In definitiva, essere una brava professionista significa essere capace di adattarsi a diversi contesti comunicativi. Elena continua a studiare tecniche di negoziazione e comunicazione assertiva, consapevole che nel mercato attuale, saper parlare con gli altri è una competenza che vale tanto quanto l''esperienza tecnica acquisita dopo anni di duro lavoro in ufficio.', '[{"prompt":"Perché Elena considera importante l''ascolto attivo?","options":["Perché le permette di parlare meno","Perché migliora il clima di collaborazione","Perché vuole copiare le idee degli altri","Perché le riunioni sono troppo lunghe"],"answer_index":1,"explanation_pt_br":"O texto menciona que essa técnica melhorou o clima colaborativo na equipe."},{"prompt":"Come descrive Elena il suo modo di scrivere e-mail?","options":["Molto creativo e ricco di dettagli","Informale e amichevole","Breve, chiaro e rispettoso","Complesso e pieno di termini tecnici"],"answer_index":2,"explanation_pt_br":"Elena prefere e-mails breves, claros e corteses para economizar tempo."},{"prompt":"Cosa fa Elena quando ci sono opinioni contrastanti?","options":["Cerca di imporre la sua idea","Evita di partecipare alla discussione","Si concentra sulla ricerca di una soluzione","Si arrabbia con i colleghi"],"answer_index":2,"explanation_pt_br":"Elena mantém a calma e foca em encontrar soluções em vez de buscar culpados."},{"prompt":"Qual è il ''marchio di fabbrica'' di Elena?","options":["La sua esperienza tecnica in azienda","La sua capacità di scrivere e-mail efficaci","La sua abilità nel parlare molte lingue","Il suo modo di gestire le riunioni"],"answer_index":1,"explanation_pt_br":"O texto identifica a escrita de e-mails claros e curtos como seu estilo pessoal."},{"prompt":"Qual è il tema centrale del testo?","options":["L''importanza delle competenze tecniche","Come diventare il capo di un''azienda","Il ruolo della comunicazione efficace nel lavoro","Le difficoltà di lavorare in una multinazionale"],"answer_index":2,"explanation_pt_br":"O texto foca na importância da comunicação profissional para o sucesso no trabalho."}]'::jsonb, 3),
('it-passage-b1-04', 'it', 'B1', 'Un equilibrio per la salute mentale', 'Prendersi cura della propria salute non significa solo fare attività fisica, ma anche mantenere un equilibrio psicologico adeguato. Roberto, un architetto di quarant''anni, ha compreso questa verità dopo un periodo di stress intenso legato al lavoro. Ha deciso quindi di introdurre piccole abitudini nella sua giornata per migliorare il suo benessere generale.

La sua giornata ora include una sessione di meditazione di dieci minuti al mattino. Anche se inizialmente era scettico, ha notato che questo breve momento di silenzio lo aiuta ad affrontare le sfide quotidiane con maggiore lucidità. È un piccolo investimento di tempo che produce grandi benefici sulla sua capacità di concentrazione durante le ore d''ufficio.

Un''altra abitudine fondamentale è quella di camminare nel parco vicino a casa durante la pausa pranzo. Staccare la spina dal computer e respirare aria fresca gli permette di ridurre la tensione accumulata. Roberto ha imparato che il movimento fisico all''aperto è un potente alleato contro l''ansia, specialmente nelle giornate in cui il carico di lavoro è particolarmente pesante.

Anche l''alimentazione gioca un ruolo chiave. Roberto ha iniziato a cucinare pasti più sani, privilegiando verdure di stagione e riducendo il consumo di cibi pronti. Questo cambiamento non ha influito solo sulla sua salute fisica, ma anche sulla qualità del suo sonno, che è diventato molto più regolare e profondo, permettendogli di svegliarsi riposato.

Infine, Roberto dedica del tempo ai suoi hobby, come la pittura, che gli permette di esprimere le sue emozioni in modo creativo. La salute, come ha imparato, è un mosaico composto da diverse tessere: riposo, alimentazione, movimento e interessi personali. Mantenere questo equilibrio è il modo migliore per affrontare le pressioni della vita adulta moderna.', '[{"prompt":"Perché Roberto ha iniziato a meditare?","options":["Perché voleva imparare una nuova disciplina","Perché il medico glielo ha ordinato","Perché voleva migliorare la sua lucidità mentale","Perché aveva troppo tempo libero"],"answer_index":2,"explanation_pt_br":"Roberto notou que a meditação o ajuda a lidar com desafios com mais lucidez."},{"prompt":"Cosa significa ''staccare la spina'' nel testo?","options":["Spegnere fisicamente il computer","Prendersi una pausa dal lavoro","Smettere di lavorare definitivamente","Dimenticare i propri doveri"],"answer_index":1,"explanation_pt_br":"A expressão idiomática significa interromper as atividades estressantes para descansar."},{"prompt":"Quale effetto ha avuto il cambiamento della dieta su Roberto?","options":["Ha perso molto peso in poco tempo","Ha migliorato la qualità del suo sonno","Ha iniziato a cucinare solo per gli amici","Ha smesso di mangiare verdure"],"answer_index":1,"explanation_pt_br":"O texto menciona que a alimentação saudável melhorou a qualidade do seu sono."},{"prompt":"Quale hobby aiuta Roberto a esprimere le emozioni?","options":["La lettura di libri di architettura","La pittura","Il giardinaggio","La cucina creativa"],"answer_index":1,"explanation_pt_br":"Roberto usa a pintura como uma forma de expressão criativa."},{"prompt":"Qual è il messaggio principale del testo sulla salute?","options":["Il lavoro è il principale nemico della salute","La salute è un insieme di diverse abitudini positive","Solo l''attività fisica può migliorare la vita","La meditazione è la soluzione a tutti i problemi"],"answer_index":1,"explanation_pt_br":"O autor descreve a saúde como um mosaico composto por vários hábitos diferentes."}]'::jsonb, 4),
('it-passage-b1-05', 'it', 'B1', 'La sagra del paese e il senso di comunità', 'Ogni anno, nel mese di settembre, il piccolo paese di Borgo Antico si trasforma per celebrare la tradizionale sagra del raccolto. Questo evento non è solo una fiera gastronomica, ma un momento fondamentale per rafforzare i legami tra gli abitanti. Per i residenti, è l''occasione perfetta per condividere le tradizioni culinarie tramandate da generazioni.

Le strade si riempiono di tavoli lunghi, profumi di pane appena sfornato e musica popolare. Ciascuna famiglia contribuisce preparando una ricetta tipica, come la pasta fatta a mano o le torte rustiche. La preparazione inizia settimane prima, coinvolgendo nonne, genitori e bambini in un lavoro collettivo che trasmette il senso di appartenenza alla comunità.

La sagra è anche un momento di accoglienza per i visitatori che arrivano dalle città vicine. Gli abitanti sono orgogliosi di mostrare i frutti del loro territorio e di raccontare la storia dietro ogni piatto. Questo scambio tra chi produce il cibo e chi lo assapora è un atto di rispetto verso la terra e verso il lavoro faticoso dei contadini locali.

Durante la serata, il sindaco tiene un breve discorso per ringraziare tutti i volontari che hanno reso possibile l''evento. È un momento emozionante, che sottolinea l''importanza di restare uniti. Senza la collaborazione di ogni singolo cittadino, la sagra perderebbe la sua anima autentica e diventerebbe solo un evento commerciale come tanti altri.

Alla fine della festa, quando le luci si spengono, rimane un profondo senso di gratitudine. La sagra di Borgo Antico insegna che le tradizioni sono il collante della società. Celebrare insieme non significa solo mangiare bene, ma ricordare chi siamo e da dove veniamo, costruendo insieme le basi per un futuro dove la comunità resta al centro di tutto.', '[{"prompt":"Qual è lo scopo principale della sagra oltre a mangiare?","options":["Guadagnare soldi per il comune","Rafforzare i legami tra gli abitanti","Promuovere il turismo di massa","Competere con i paesi vicini"],"answer_index":1,"explanation_pt_br":"O texto destaca que o evento serve para fortalecer os laços entre os moradores."},{"prompt":"Chi partecipa alla preparazione dei cibi secondo il testo?","options":["Solo i professionisti della cucina","Soltanto gli anziani del paese","Persone di diverse generazioni","I turisti in visita"],"answer_index":2,"explanation_pt_br":"O texto diz que avós, pais e filhos trabalham juntos na preparação."},{"prompt":"Cosa rappresenta lo scambio tra produttori e visitatori?","options":["Un modo per alzare i prezzi dei prodotti","Un atto di rispetto verso la terra e il lavoro","Una strategia di marketing per il paese","Una conversazione puramente casuale"],"answer_index":1,"explanation_pt_br":"O autor vê o intercâmbio como um sinal de respeito ao trabalho agrícola."},{"prompt":"Cosa succederebbe se mancasse la collaborazione dei cittadini?","options":["La sagra sarebbe comunque un grande successo","Il sindaco dovrebbe pagare più personale","L''evento perderebbe la sua autenticità","I turisti arriverebbero più numerosi"],"answer_index":2,"explanation_pt_br":"Sem a colaboração, o evento perderia sua essência e se tornaria puramente comercial."},{"prompt":"Qual è il messaggio finale dell''autore?","options":["Il cibo è la cosa più importante in un paese","Le tradizioni sono fondamentali per l''identità comunitaria","Le sagre dovrebbero essere eliminate in futuro","I discorsi politici sono il cuore della festa"],"answer_index":1,"explanation_pt_br":"O autor conclui que as tradições são o que mantém a sociedade unida."}]'::jsonb, 5),
('it-passage-b1-06', 'it', 'B1', 'La tecnologia nella nostra routine', 'Oggi la tecnologia è diventata una parte invisibile ma essenziale della nostra vita quotidiana. Dalla sveglia sul telefono al controllo della temperatura in casa, ogni gesto è mediato da dispositivi intelligenti che promettono di semplificare le nostre giornate.

Molti brasiliani che lavorano in ufficio utilizzano software avanzati per gestire il tempo e le riunioni online. Questi strumenti hanno cambiato profondamente il modo in cui comunichiamo con i colleghi, permettendo una flessibilità che anni fa sembrava impossibile da ottenere.

Tuttavia, esiste un dibattito crescente sulla dipendenza digitale. Molte persone sentono il bisogno di controllare le notifiche ogni pochi minuti, perdendo la capacità di concentrarsi su attività che richiedono uno sforzo mentale prolungato e una riflessione profonda.

D''altra parte, le applicazioni di salute e benessere ci aiutano a monitorare il sonno e l''attività fisica, incoraggiandoci a mantenere abitudini più sane. La tecnologia, se usata con equilibrio, può diventare un alleato prezioso per migliorare la qualità della nostra vita.

In definitiva, la chiave è l''autonomia. Dobbiamo imparare a gestire i dispositivi senza esserne schiavi, scegliendo attivamente quando connetterci e quando, invece, staccare la spina per godere del mondo reale intorno a noi in modo consapevole.', '[{"prompt":"Qual è l''idea principale del testo riguardo alla tecnologia?","options":["La tecnologia è negativa e dovrebbe essere evitata.","La tecnologia è utile se usata con equilibrio e consapevolezza.","La tecnologia ha reso il lavoro impossibile.","La tecnologia è utile solo per monitorare la salute."],"answer_index":1,"explanation_pt_br":"O texto defende que a tecnologia é uma aliada valiosa, desde que o usuário mantenha o controle e o equilíbrio no seu uso."},{"prompt":"Cosa si intende con l''espressione ''staccare la spina'' nel quinto paragrafo?","options":["Spegnere fisicamente tutti gli elettrodomestici di casa.","Smettere di usare dispositivi tecnologici per riposare.","Riparare un cavo elettrico danneggiato.","Lavorare con meno energia durante la giornata."],"answer_index":1,"explanation_pt_br":"A expressão idiomática ''staccare la spina'' significa fazer uma pausa ou desconectar-se das atividades estressantes, no caso, do mundo digital."},{"prompt":"Qual è un effetto negativo citato nel terzo paragrafo?","options":["La difficoltà a concentrarsi su compiti complessi.","L''impossibilità di usare software in ufficio.","Il costo elevato dei dispositivi intelligenti.","La mancanza di tempo per dormire bene."],"answer_index":0,"explanation_pt_br":"O texto menciona explicitamente que a constante checagem de notificações prejudica a capacidade de concentração em tarefas que exigem esforço mental."},{"prompt":"Come è cambiato il lavoro secondo il secondo paragrafo?","options":["È diventato più difficile a causa dei nuovi software.","Le riunioni online hanno ridotto la flessibilità.","La comunicazione è diventata più flessibile.","I colleghi si incontrano meno frequentemente di persona."],"answer_index":2,"explanation_pt_br":"O texto afirma que as ferramentas digitais trouxeram uma flexibilidade que antes não existia no ambiente de trabalho."},{"prompt":"Quale comportamento viene suggerito per mantenere il benessere?","options":["Usare app solo per controllare il sonno.","Evitare l''uso di qualsiasi dispositivo tecnologico.","Gestire i dispositivi in modo autonomo e consapevole.","Lavorare sempre in ufficio per evitare distrazioni."],"answer_index":2,"explanation_pt_br":"O último parágrafo conclui que a autonomia e a escolha consciente de quando se conectar são fundamentais para o bem-estar."}]'::jsonb, 6),
('it-passage-b1-07', 'it', 'B1', 'Verso uno stile di vita sostenibile', 'La crescente consapevolezza ambientale sta spingendo molti cittadini a modificare le proprie abitudini quotidiane. Non si tratta solo di riciclare, ma di ripensare l''intero ciclo di consumo per ridurre l''impatto sul nostro fragile ecosistema naturale.

Molti brasiliani hanno iniziato a ridurre l''uso della plastica monouso, preferendo borse di tela e contenitori riutilizzabili. Queste piccole scelte individuali, quando adottate da milioni di persone, possono generare un cambiamento significativo nella gestione dei rifiuti urbani.

Anche l''alimentazione gioca un ruolo centrale. Scegliere prodotti locali e di stagione non solo sostiene l''economia della comunità, ma diminuisce anche le emissioni di carbonio legate al trasporto delle merci su lunghe distanze tra le regioni.

Un altro aspetto fondamentale riguarda il risparmio energetico domestico. Sostituire le vecchie lampadine con quelle a LED e spegnere gli apparecchi in standby sono gesti semplici che riducono il consumo elettrico e abbassano le bollette mensili delle famiglie.

In conclusione, la sostenibilità non deve essere vista come una rinuncia, ma come un''opportunità per vivere in modo più intelligente. Ogni azione conta e il nostro impegno collettivo è indispensabile per garantire un futuro migliore alle generazioni che verranno dopo di noi.', '[{"prompt":"Qual è l''obiettivo principale delle azioni descritte nel testo?","options":["Aumentare il consumo di plastica monouso.","Ridurre l''impatto ambientale attraverso scelte quotidiane.","Smettere completamente di lavorare per salvare il pianeta.","Comprare solo prodotti importati da altri paesi."],"answer_index":1,"explanation_pt_br":"O texto foca na importância de mudar hábitos cotidianos para diminuir o impacto ambiental."},{"prompt":"Cosa significa ''prodotti di stagione'' nel terzo paragrafo?","options":["Prodotti che costano molto poco in estate.","Prodotti agricoli coltivati nel periodo naturale di maturazione.","Prodotti che vengono conservati in frigorifero per mesi.","Prodotti che si trovano solo nei grandi supermercati."],"answer_index":1,"explanation_pt_br":"Produtos de estação são aqueles cultivados na época correta do ano, sem necessidade de métodos artificiais intensivos."},{"prompt":"Quale vantaggio economico è menzionato nel quarto paragrafo?","options":["Il guadagno derivante dalla vendita di lampadine a LED.","La riduzione dei costi energetici domestici.","Il risparmio ottenuto comprando elettrodomestici costosi.","L''aumento dello stipendio grazie al riciclaggio."],"answer_index":1,"explanation_pt_br":"O texto menciona que trocar lâmpadas e desligar aparelhos reduz o consumo de energia e, consequentemente, o valor da conta de luz."},{"prompt":"Secondo il testo, perché comprare prodotti locali è positivo?","options":["Perché sono sempre più economici rispetto ai prodotti esteri.","Perché riduce le emissioni dovute al trasporto.","Perché garantisce una qualità superiore del cibo.","Perché impedisce alle persone di viaggiare."],"answer_index":1,"explanation_pt_br":"O terceiro parágrafo destaca que comprar localmente diminui as emissões de carbono associadas ao transporte de mercadorias."},{"prompt":"Qual è l''atteggiamento verso la sostenibilità proposto dall''autore?","options":["È una rinuncia dolorosa alla comodità.","È un''opportunità per vivere in modo più intelligente.","È un obbligo imposto solo dalle grandi aziende.","È qualcosa di impossibile da realizzare individualmente."],"answer_index":1,"explanation_pt_br":"O autor enfatiza no último parágrafo que a sustentabilidade é uma oportunidade de melhoria, não uma perda de qualidade de vida."}]'::jsonb, 7),
('it-passage-b1-08', 'it', 'B1', 'Relazioni e vita sociale nell''era moderna', 'Le dinamiche delle relazioni umane sono cambiate radicalmente negli ultimi decenni. Se un tempo le interazioni sociali avvenivano principalmente nei luoghi fisici, oggi gran parte della nostra vita sociale si svolge attraverso piattaforme digitali e social media.

Nonostante la facilità di comunicare con chiunque in ogni parte del mondo, molti lamentano un senso di solitudine crescente. La qualità delle conversazioni online è spesso superficiale e non riesce a sostituire il calore di un incontro faccia a faccia.

Le amicizie moderne richiedono un impegno diverso rispetto al passato. È facile restare in contatto visivo con le foto degli altri, ma coltivare un legame profondo richiede tempo, dedizione e la capacità di ascoltare senza distrazioni digitali.

Anche le relazioni di coppia si sono evolute. Le app di incontri hanno aperto nuove possibilità di conoscere persone al di fuori della propria cerchia sociale, ma hanno anche introdotto una logica di consumo che spesso rende difficile costruire un impegno a lungo termine.

In definitiva, la tecnologia resta uno strumento. Il segreto per una vita sociale appagante risiede nella nostra capacità di bilanciare le interazioni virtuali con momenti di condivisione autentica, dove il tempo è dedicato esclusivamente alla cura degli altri.', '[{"prompt":"Cosa lamentano molte persone riguardo alla comunicazione moderna?","options":["La difficoltà di usare le piattaforme digitali.","Un senso di solitudine nonostante la facilità di connessione.","Il costo eccessivo per mantenere i social media.","L''impossibilità di incontrare persone straniere."],"answer_index":1,"explanation_pt_br":"O texto menciona que, embora seja fácil se conectar, muitas pessoas se sentem sozinhas devido à superficialidade das interações online."},{"prompt":"Cosa significa ''faccia a faccia'' nel secondo paragrafo?","options":["Guardarsi allo specchio.","Incontrarsi di persona, fisicamente.","Parlare solo tramite videochiamata.","Indossare una maschera in pubblico."],"answer_index":1,"explanation_pt_br":"A expressão ''faccia a faccia'' refere-se a interações presenciais, sem mediação tecnológica."},{"prompt":"Secondo l''autore, cosa serve per coltivare un legame profondo?","options":["Pubblicare foto insieme sui social media.","Tempo, dedizione e ascolto senza distrazioni.","Usare esclusivamente le app di incontri.","Evitare di parlare di problemi personali."],"answer_index":1,"explanation_pt_br":"O terceiro parágrafo enfatiza que amizades profundas exigem tempo e atenção real, não apenas interações superficiais."},{"prompt":"Qual è un effetto delle app di incontri menzionato nel testo?","options":["Hanno reso impossibile trovare partner.","Hanno ridotto la cerchia sociale delle persone.","Hanno introdotto una logica di consumo nelle relazioni.","Hanno eliminato completamente la solitudine."],"answer_index":2,"explanation_pt_br":"O quarto parágrafo aponta que as apps de encontro introduziram uma lógica de consumo que pode dificultar o compromisso duradouro."},{"prompt":"Qual è il messaggio finale del testo?","options":["Dobbiamo abbandonare i social media per sempre.","Bisogna bilanciare il mondo virtuale con momenti autentici.","Le relazioni moderne sono migliori di quelle del passato.","Il tempo non è importante nelle relazioni."],"answer_index":1,"explanation_pt_br":"O autor conclui que a chave é equilibrar o uso da tecnologia com momentos reais de interação humana."}]'::jsonb, 8),
('it-passage-b1-09', 'it', 'B1', 'Gestire le proprie finanze personali', 'Gestire il denaro è una competenza fondamentale per la vita adulta. Molti brasiliani iniziano a interessarsi seriamente alla finanza personale solo quando si trovano ad affrontare le prime grandi spese, come l''acquisto di una casa o la pianificazione della pensione.

Il primo passo verso una gestione sana è il monitoraggio delle entrate e delle uscite. Annotare ogni piccolo acquisto, anche quello di un caffè al bar, aiuta a capire dove finisce il denaro e permette di identificare le spese superflue che possono essere eliminate.

Il risparmio non deve essere visto come un sacrificio, ma come un fondo di sicurezza per il futuro. Avere una riserva di emergenza protegge da imprevisti come la perdita del lavoro o spese mediche improvvise, riducendo drasticamente lo stress quotidiano.

La cultura del consumo spesso ci spinge ad acquistare oggetti di cui non abbiamo reale bisogno. Prima di fare un acquisto importante, è utile porsi una domanda: questo oggetto aggiunge valore alla mia vita o è solo un impulso passeggero?

Infine, l''educazione finanziaria è un percorso continuo. Leggere libri, seguire corsi o consultare esperti può fare la differenza nel lungo periodo, trasformando il rapporto con il denaro da fonte di ansia a strumento di libertà e serenità.', '[{"prompt":"Quando molti brasiliani iniziano a interessarsi alla finanza?","options":["Quando iniziano a lavorare da bambini.","Quando devono affrontare grandi spese o pianificare il futuro.","Quando hanno già risparmiato abbastanza denaro.","Quando non hanno più bisogno di lavorare."],"answer_index":1,"explanation_pt_br":"O texto indica que o interesse pela educação financeira surge geralmente diante de grandes desafios ou metas futuras."},{"prompt":"Qual è il primo passo consigliato per una gestione sana?","options":["Smettere di bere caffè al bar.","Monitorare entrate e uscite.","Comprare una casa il prima possibile.","Investire tutto il denaro in borsa."],"answer_index":1,"explanation_pt_br":"O segundo parágrafo afirma explicitamente que o monitoramento do fluxo financeiro é o passo inicial essencial."},{"prompt":"Cosa significa ''spese superflue'' nel secondo paragrafo?","options":["Spese necessarie per vivere.","Spese che si possono evitare.","Spese molto costose e inevitabili.","Spese fatte solo per pagare le tasse."],"answer_index":1,"explanation_pt_br":"Spese superflue são gastos desnecessários que podem ser cortados do orçamento."},{"prompt":"Perché è utile avere una riserva di emergenza?","options":["Per comprare beni di lusso.","Per proteggersi da imprevisti e ridurre lo stress.","Per evitare di pagare le tasse.","Per prestare denaro agli amici."],"answer_index":1,"explanation_pt_br":"O texto explica que a reserva serve para proteger contra imprevistos como perda de emprego ou problemas médicos."},{"prompt":"Quale consiglio viene dato prima di fare un acquisto importante?","options":["Chiedere un prestito in banca.","Valutare se l''acquisto porta un valore reale o è un impulso.","Comprare subito per non perdere l''offerta.","Chiedere consiglio a un amico che spende molto."],"answer_index":1,"explanation_pt_br":"O autor sugere refletir sobre a necessidade real do objeto antes de consumi-lo por impulso."}]'::jsonb, 9),
('it-passage-b1-10', 'it', 'B1', 'L''importanza della formazione continua', 'Il mondo del lavoro evolve rapidamente e le competenze che abbiamo acquisito anni fa potrebbero non essere più sufficienti oggi. Per questo motivo, il concetto di apprendimento permanente, o lifelong learning, è diventato cruciale per chiunque voglia restare competitivo.

Non si tratta solo di aggiornamento professionale. Imparare cose nuove, come una lingua straniera, uno strumento musicale o una tecnica artistica, mantiene la mente attiva e stimola la creatività, migliorando anche la nostra salute cognitiva durante l''invecchiamento.

Molti adulti temono di non avere abbastanza tempo per studiare, ma le risorse digitali hanno abbattuto molte barriere. Oggi è possibile seguire corsi online di alta qualità, ascoltare podcast educativi o partecipare a webinar durante il tragitto casa-lavoro.

L''educazione non formale è ugualmente importante. Lo scambio di esperienze tra colleghi o la partecipazione a gruppi di lettura sono modi validi per acquisire nuove prospettive e arricchire il proprio bagaglio culturale in modo informale ma efficace.

Investire in se stessi è la scelta migliore che una persona possa fare. Coltivare la curiosità e l''apertura mentale non solo apre porte professionali, ma rende anche la vita quotidiana più ricca, interessante e piena di significato.', '[{"prompt":"Cosa significa ''lifelong learning'' nel testo?","options":["Studiare solo durante l''infanzia.","Apprendimento continuo durante tutta la vita.","Frequentare l''università per tutta la vita.","Imparare solo le lingue straniere."],"answer_index":1,"explanation_pt_br":"O termo ''lifelong learning'' refere-se ao conceito de continuar aprendendo ao longo de toda a vida, não apenas na escola."},{"prompt":"Quali sono i benefici non professionali dell''apprendimento?","options":["Aumentare il proprio stipendio mensile.","Mantenere la mente attiva e stimolare la creatività.","Lavorare meno ore in ufficio.","Comprare più facilmente una casa."],"answer_index":1,"explanation_pt_br":"O segundo parágrafo explica que aprender coisas novas ajuda na saúde cognitiva e na criatividade."},{"prompt":"Come le risorse digitali hanno aiutato gli adulti?","options":["Hanno reso lo studio molto più costoso.","Hanno eliminato il bisogno di studiare.","Hanno abbattuto le barriere temporali e logistiche.","Hanno costretto tutti a tornare all''università."],"answer_index":2,"explanation_pt_br":"O texto menciona que cursos online, podcasts e webinars facilitam o acesso ao estudo, superando barreiras de tempo e lugar."},{"prompt":"Cosa intende l''autore con ''educazione non formale''?","options":["Studiare solo con professori universitari.","Apprendere tramite scambi di esperienze e gruppi di lettura.","Leggere solo libri di testo scolastici.","Non studiare affatto durante il tempo libero."],"answer_index":1,"explanation_pt_br":"O quarto parágrafo descreve a educação não formal como trocas informais entre colegas e grupos de interesse."},{"prompt":"Qual è la conclusione dell''autore riguardo all''investimento in se stessi?","options":["È una perdita di tempo prezioso.","È la scelta migliore per una vita ricca e significativa.","È utile solo per chi cerca un nuovo lavoro.","È troppo difficile da realizzare da adulti."],"answer_index":1,"explanation_pt_br":"O último parágrafo conclui que investir em si mesmo traz tanto benefícios profissionais quanto uma vida pessoal mais plena."}]'::jsonb, 10),
('it-passage-b2-01', 'it', 'B2', 'L''equilibrio della vita quotidiana', 'La ricerca dell''indipendenza personale rappresenta spesso una sfida complessa per il professionista moderno che vive in una grande metropoli. Gestire le proprie abitudini quotidiane richiede una disciplina ferrea e la capacità di organizzare il tempo in modo che le necessità lavorative non soffochino completamente lo spazio dedicato al sé. Molti credono che la libertà coincida con l''assenza di routine, ma la realtà suggerisce che è proprio attraverso una struttura consolidata che si può trovare la vera autonomia.

Il mattino inizia solitamente con una serie di gesti meccanici, quasi rituali, che preparano la mente alle pressioni della giornata. Per chi vive da solo, la gestione della casa diventa un esercizio di consapevolezza: fare la spesa, mantenere l''ordine e pianificare i pasti non sono solo incombenze domestiche, ma atti di cura verso la propria persona. Ignorare questi aspetti significa delegare ad altri la gestione della propria vita, rinunciando di fatto a una parte della propria indipendenza decisionale.

Il ritmo frenetico del lavoro spesso ci spinge a trascurare il valore del tempo speso in solitudine. Tuttavia, imparare a stare bene con se stessi è il primo passo per costruire relazioni sane con gli altri. Quando si è in grado di gestire le proprie giornate senza il costante bisogno di validazione esterna, si acquisisce una forma di sicurezza che si riflette positivamente in ogni ambito della vita privata e professionale, rendendo le interazioni più autentiche.

La tecnologia, pur facilitando molte operazioni, può diventare un''arma a doppio taglio. Se da una parte le applicazioni aiutano a ottimizzare le agende, dall''altra creano una dipendenza costante che frammenta l''attenzione. Riuscire a staccarsi dagli schermi per dedicarsi a una lettura, a un hobby manuale o semplicemente alla riflessione è un atto di resistenza contro l''omologazione. Mantenere il controllo sui propri strumenti digitali è fondamentale per preservare la propria identità.

Un aspetto spesso sottovalutato dell''indipendenza è la capacità di gestire gli imprevisti. La vita non segue mai un copione prestabilito e la vera autonomia risiede nella flessibilità mentale necessaria per adattarsi ai cambiamenti improvvisi senza perdere il proprio centro. Chi ha costruito una solida base di abitudini è solitamente più resiliente, poiché possiede gli strumenti necessari per ristrutturare la propria giornata quando le circostanze lo richiedono.

In definitiva, la vita indipendente non è un traguardo statico, ma un processo dinamico di costante riadattamento. Si tratta di trovare quel sottile equilibrio tra le responsabilità che ci legano al mondo esterno e lo spazio vitale che dobbiamo proteggere. Solo coltivando la consapevolezza delle proprie scelte quotidiane possiamo davvero dirci padroni del nostro tempo, trasformando la routine da prigione in un solido trampolino per l''autorealizzazione personale.', '[{"prompt":"Qual è la tesi principale dell''autore riguardo alla routine?","options":["La routine è un ostacolo alla libertà personale.","La routine è essenziale per raggiungere l''indipendenza.","La routine deve essere evitata per rimanere creativi.","La routine è una conseguenza necessaria del lavoro moderno."],"answer_index":1,"explanation_pt_br":"O texto defende que a estrutura da rotina permite a verdadeira autonomia, contradizendo a ideia de que liberdade é ausência de regras."},{"prompt":"Cosa intende l''autore con l''espressione ''atti di cura verso la propria persona''?","options":["Delegare i lavori domestici ad altre persone.","Investire denaro in servizi di assistenza privata.","Occuparsi personalmente della propria gestione quotidiana.","Ignorare le incombenze per dedicarsi al relax."],"answer_index":2,"explanation_pt_br":"O autor descreve cuidar da casa e planejar refeições como um exercício de autonomia e autocuidado."},{"prompt":"In che modo la tecnologia influenza l''indipendenza, secondo il testo?","options":["Migliora sempre la qualità della vita professionale.","Può minacciare l''autonomia se non gestita con consapevolezza.","È l''unico strumento efficace per organizzare le agende.","Non ha alcun impatto significativo sulla vita quotidiana."],"answer_index":1,"explanation_pt_br":"O texto alerta que a tecnologia pode ser uma ''arma de dois gumes'', criando dependência se não usada com critério."},{"prompt":"Cosa significa ''resiliente'' nel contesto del quinto paragrafo?","options":["Qualcuno che segue rigorosamente un copione.","Qualcuno che si arrende facilmente alle difficoltà.","Qualcuno che sa adattarsi e superare gli imprevisti.","Qualcuno che rifiuta ogni tipo di cambiamento."],"answer_index":2,"explanation_pt_br":"No contexto, resiliência refere-se à capacidade de adaptar-se e reestruturar o dia diante de imprevistos."},{"prompt":"Qual è l''importanza di stare bene con se stessi?","options":["Permette di isolarsi completamente dal mondo esterno.","Aiuta a costruire relazioni più sane e autentiche.","Evita la necessità di lavorare in un ambiente professionale.","È una condizione necessaria per usare la tecnologia."],"answer_index":1,"explanation_pt_br":"O texto afirma que aprender a estar bem sozinho é o primeiro passo para construir relações saudáveis com os outros."},{"prompt":"Secondo il testo, cos''è la vera autonomia?","options":["L''assenza totale di responsabilità.","La capacità di delegare i compiti difficili.","La flessibilità mentale nel gestire i cambiamenti.","Il possesso di numerosi strumenti digitali."],"answer_index":2,"explanation_pt_br":"O autor define a autonomia como a capacidade de se adaptar às mudanças repentinas mantendo o equilíbrio."},{"prompt":"Qual è il tono generale del brano?","options":["Critico nei confronti della vita urbana moderna.","Riflessivo sull''importanza dell''autodisciplina.","Ironico verso chi cerca l''indipendenza.","Tecnico e descrittivo sui metodi di organizzazione."],"answer_index":1,"explanation_pt_br":"O texto propõe uma reflexão sobre como o autogerenciamento da rotina contribui para a realização pessoal."}]'::jsonb, 1),
('it-passage-b2-02', 'it', 'B2', 'Orizzonti lontani: l''arte del viaggio', 'Viaggiare non significa semplicemente spostarsi da un luogo a un altro, ma intraprendere un percorso di scoperta che mette in discussione le proprie certezze. Per un viaggiatore consapevole, ogni destinazione è uno specchio che riflette aspetti sconosciuti della propria personalità. Mentre il turista cerca conferme e comfort familiari anche lontano da casa, il viaggiatore autentico accoglie l''imprevisto come una parte essenziale dell''esperienza, permettendo al luogo di trasformare il suo sguardo sul mondo.

La pianificazione gioca un ruolo fondamentale, ma non deve diventare una gabbia che impedisce la serendipità. Studiare la storia, la cultura e le tradizioni di un paese prima di partire è un atto di rispetto verso chi ci ospita. Tuttavia, lasciare spazio all''improvvisazione permette di scoprire angoli nascosti, mercati locali e storie che non si trovano nelle guide turistiche. È proprio in questi momenti di scarto rispetto al programma che avviene la vera scoperta culturale.

Il contatto con la popolazione locale è il cuore pulsante di ogni viaggio significativo. Superare la barriera linguistica è spesso la prima sfida, ma il linguaggio non verbale, i gesti e la curiosità sincera sono ponti potenti. Condividere un pasto in una taverna frequentata solo dai residenti, ascoltare racconti di vita vissuta o partecipare a una festività popolare offre una prospettiva che nessun libro potrebbe mai trasmettere. Si impara che le differenze sono ricchezze da esplorare.

Sostenibilità e turismo responsabile sono diventati temi centrali nel dibattito contemporaneo. Viaggiare significa anche essere consapevoli dell''impatto che lasciamo dietro di noi, sia a livello ambientale che sociale. Preferire trasporti locali, alloggiare in strutture gestite da residenti e rispettare gli ecosistemi fragili sono scelte che definiscono il viaggiatore moderno. Il rispetto per il patrimonio storico e naturale è il minimo tributo che dobbiamo alle generazioni future.

Nonostante la facilità con cui oggi possiamo esplorare il globo, il rischio di una visione superficiale è sempre presente. La globalizzazione tende a uniformare le esperienze, rendendo alcune città stranamente simili tra loro. Per sfuggire a questa omologazione, è necessario cercare l''autenticità, che spesso si nasconde nelle zone meno battute o nei ritmi lenti che ancora resistono alla frenesia del turismo di massa. La lentezza è, in questo senso, una forma di lusso intellettuale.

In conclusione, il viaggio rimane una delle esperienze più formanti che un individuo possa compiere. Attraverso l''incontro con l''altro, impariamo a comprendere meglio noi stessi e le nostre radici. Tornare a casa dopo un''esperienza significativa significa portare con sé non solo fotografie, ma un bagaglio di nuove consapevolezze che continueranno a influenzare il nostro modo di vivere e di interagire con il mondo per molto tempo dopo il ritorno.', '[{"prompt":"Qual è la differenza fondamentale tra ''turista'' e ''viaggiatore'' secondo il testo?","options":["Il turista viaggia solo per affari, il viaggiatore per piacere.","Il turista cerca il comfort, il viaggiatore cerca la trasformazione.","Il viaggiatore pianifica tutto, il turista non pianifica nulla.","Il turista parla la lingua locale, il viaggiatore usa solo i gesti."],"answer_index":1,"explanation_pt_br":"O texto diferencia o turista (que busca conforto) do viajante (que busca transformações e descobertas)."},{"prompt":"Cosa intende l''autore con ''serendipità''?","options":["La capacità di seguire rigorosamente un piano di viaggio.","La fortuna di fare scoperte positive in modo inaspettato.","La necessità di studiare la storia prima di partire.","La difficoltà di trovarsi in posti sconosciuti."],"answer_index":1,"explanation_pt_br":"Serendipidade refere-se à descoberta acidental de coisas boas, que o autor associa ao improviso no viajar."},{"prompt":"Perché è importante studiare la cultura locale prima di partire?","options":["Per evitare di dover parlare con la popolazione locale.","Per mostrare rispetto verso la comunità ospitante.","Per non dover mai improvvisare durante il viaggio.","Per risparmiare denaro sulle guide turistiche."],"answer_index":1,"explanation_pt_br":"O texto cita que estudar a cultura é um ato de respeito para com os hospedeiros."},{"prompt":"Qual è l''atteggiamento verso il turismo sostenibile?","options":["È visto come un ostacolo al divertimento del viaggiatore.","È considerato una responsabilità verso l''ambiente e la società.","È un tema superato che non interessa più ai viaggiatori.","Riguarda esclusivamente la protezione dei monumenti storici."],"answer_index":1,"explanation_pt_br":"O autor enfatiza o impacto ambiental e social, definindo o turismo responsável como uma escolha ética."},{"prompt":"Cosa minaccia l''autenticità dei viaggi moderni?","options":["Il desiderio dei viaggiatori di visitare posti famosi.","La globalizzazione che rende le esperienze uniformi.","L''eccessiva disponibilità di guide turistiche online.","La scarsità di trasporti locali nelle zone remote."],"answer_index":1,"explanation_pt_br":"A globalização é apontada como um fator que tende a uniformizar as experiências, ameaçando a autenticidade."},{"prompt":"Perché l''autore definisce la ''lentezza'' come un lusso?","options":["Perché viaggiare lentamente costa molto più denaro.","Perché permette di sfuggire all''omologazione del turismo di massa.","Perché richiede molto tempo libero che pochi possiedono.","Perché è l''unico modo per vedere tutte le attrazioni."],"answer_index":1,"explanation_pt_br":"A lentidão é vista como um luxo intelectual por permitir fugir da pressa do turismo de massa."},{"prompt":"Qual è il beneficio finale del viaggiare secondo il testo?","options":["Aumentare il numero di fotografie nei social media.","Acquisire una nuova prospettiva su se stessi e sul mondo.","Dimenticare completamente le proprie radici culturali.","Imparare a vivere senza alcuna forma di pianificazione."],"answer_index":1,"explanation_pt_br":"O autor conclui que o retorno do viajante traz uma bagagem de novas consciências sobre si mesmo."}]'::jsonb, 2),
('it-passage-b2-03', 'it', 'B2', 'Evoluzione del mondo del lavoro', 'Il panorama professionale contemporaneo sta vivendo una trasformazione senza precedenti, spinta dall''automazione e dalla digitalizzazione. Le competenze tecniche, pur rimanendo fondamentali, non sono più sufficienti per garantire una carriera solida. Oggi, le aziende cercano professionisti capaci di adattarsi rapidamente, dotati di una spiccata intelligenza emotiva e di una visione critica. La capacità di comunicare efficacemente in ambienti multiculturali è diventata una valuta preziosa nel mercato globale.

La comunicazione interna gioca un ruolo cruciale nella riuscita dei progetti. In un''era dominata dai messaggi istantanei e dalle videoconferenze, il rischio di fraintendimenti è elevato. Saper scegliere il canale di comunicazione appropriato, mantenere un tono professionale e ascoltare attivamente sono competenze che distinguono un leader. Non si tratta solo di trasmettere informazioni, ma di creare un clima di fiducia e trasparenza all''interno del team di lavoro.

Il concetto di ufficio è stato radicalmente ridefinito dall''avvento del lavoro ibrido. Se da una parte la flessibilità ha migliorato la qualità della vita, dall''altra ha reso più complessa la gestione dei confini tra vita privata e professionale. L''autodisciplina è diventata la competenza cardine per chi opera a distanza. Senza la supervisione diretta dei superiori, il lavoratore deve essere in grado di gestire le proprie scadenze e mantenere alta la motivazione in autonomia.

La formazione continua è l''unica strategia valida per rimanere competitivi. Il ritmo dell''innovazione è tale che le conoscenze acquisite durante il percorso accademico diventano obsolete in pochi anni. L''apprendimento non formale, la partecipazione a seminari e la curiosità intellettuale sono i motori del progresso individuale. Chi smette di imparare rischia di essere messo ai margini di un mercato che premia la versatilità e la capacità di aggiornamento costante.

Le dinamiche di gruppo rappresentano spesso una sfida per la produttività. La gestione dei conflitti e la negoziazione richiedono una profonda empatia. Un team eterogeneo, composto da persone con background diversi, è potenzialmente più creativo, ma necessita di un coordinamento attento per evitare che le divergenze diventino ostacoli insormontabili. Il ruolo del manager si sta trasformando da quello di supervisore a quello di facilitatore, il cui obiettivo è valorizzare il talento di ogni individuo.

In conclusione, il lavoro del futuro richiederà un perfetto equilibrio tra hard skills e soft skills. La tecnologia continuerà a evolversi, ma le caratteristiche intrinsecamente umane, come la creatività, l''empatia e il pensiero critico, rimarranno insostituibili. Chi saprà unire una solida competenza tecnica a una grande intelligenza relazionale sarà in grado di navigare con successo le complessità di un mercato del lavoro sempre più fluido e interconnesso.', '[{"prompt":"Cosa cercano oggi le aziende oltre alle competenze tecniche?","options":["Una lunga esperienza accademica.","Intelligenza emotiva e capacità di adattamento.","La capacità di lavorare solo in ufficio.","Una conoscenza approfondita della sola tecnologia digitale."],"answer_index":1,"explanation_pt_br":"O texto menciona que competências técnicas não bastam, sendo necessária inteligência emocional e adaptação."},{"prompt":"Qual è il rischio principale della comunicazione moderna citato nel testo?","options":["L''eccessiva lentezza dei messaggi istantanei.","La mancanza di strumenti per le videoconferenze.","L''alto rischio di fraintendimenti tra colleghi.","L''impossibilità di comunicare in modo trasparente."],"answer_index":2,"explanation_pt_br":"O texto destaca que a era das mensagens instantâneas e videoconferências aumenta o risco de mal-entendidos."},{"prompt":"Qual è la competenza ''cardine'' per il lavoro ibrido?","options":["L''uso di software avanzati di gestione.","La presenza fisica costante in ufficio.","L''autodisciplina nel gestire il tempo.","La capacità di supervisionare i colleghi."],"answer_index":2,"explanation_pt_br":"A autodisciplina é definida como a competência central para o trabalhador remoto."},{"prompt":"Cosa si intende per ''competenze obsolete'' nel quarto paragrafo?","options":["Competenze che sono diventate troppo costose.","Competenze che non sono più utili o attuali.","Competenze che richiedono troppo tempo per essere imparate.","Competenze che solo pochi professionisti possiedono."],"answer_index":1,"explanation_pt_br":"Obsoleto refere-se a algo que perdeu a utilidade ou não é mais atual frente à inovação."},{"prompt":"Come si sta trasformando il ruolo del manager?","options":["Da supervisore a facilitatore del team.","Da facilitatore a supervisore autoritario.","Da esperto tecnico a semplice impiegato.","Da coordinatore a lavoratore solitario."],"answer_index":0,"explanation_pt_br":"O texto descreve a mudança do gestor de um supervisor para alguém que facilita o talento do grupo."},{"prompt":"Qual è il vantaggio di un team eterogeneo?","options":["È più facile da coordinare rispetto a un team omogeneo.","Ha una maggiore capacità di innovazione creativa.","Non richiede alcuna negoziazione o gestione dei conflitti.","Lavora meglio se non c''è un coordinatore."],"answer_index":1,"explanation_pt_br":"Equipes diversas são vistas como potencialmente mais criativas."},{"prompt":"Qual è il messaggio principale del sesto paragrafo?","options":["La tecnologia sostituirà completamente l''uomo.","Le soft skills diventeranno inutili in futuro.","L''unione tra hard e soft skills garantisce il successo.","Il mercato del lavoro diventerà molto meno interconnesso."],"answer_index":2,"explanation_pt_br":"A conclusão reforça que o sucesso depende do equilíbrio entre competências técnicas e relacionais."}]'::jsonb, 3),
('it-passage-b2-04', 'it', 'B2', 'Salute e benessere nel XXI secolo', 'Il concetto di salute si è evoluto drasticamente: non è più intesa solo come assenza di malattie, ma come uno stato di completo benessere fisico, mentale e sociale. In un mondo che corre veloce, trovare un equilibrio salutare è diventato un obiettivo ambizioso. Molti si concentrano esclusivamente sulla dieta o sull''esercizio fisico, dimenticando che la salute è un ecosistema complesso dove lo stress, il riposo e la qualità delle relazioni giocano ruoli altrettanto determinanti.

La gestione dello stress è forse la sfida più grande per l''individuo moderno. La pressione costante di dover essere sempre performanti porta spesso a una condizione di esaurimento psicofisico. Pratiche come la meditazione, lo yoga o semplicemente la riscoperta di hobby manuali possono fungere da antidoti naturali. È essenziale imparare a riconoscere i segnali di allerta del proprio corpo prima che si trasformino in sintomi cronici o patologie più gravi.

L''alimentazione consapevole è un altro pilastro fondamentale. Non si tratta solo di contare le calorie, ma di capire cosa introduciamo nel nostro organismo e come questo influenzi i nostri livelli di energia. Un rapporto sano con il cibo implica ascoltare i segnali di sazietà e scegliere prodotti freschi e di stagione. La nutrizione è una forma di rispetto verso se stessi che ha un impatto diretto sulla prevenzione di molte malattie metaboliche e cardiovascolari.

Il riposo è stato ingiustamente demonizzato come una perdita di tempo. Al contrario, il sonno è un momento cruciale in cui il cervello elabora le informazioni e il corpo ripara i tessuti danneggiati. La privazione di sonno influisce negativamente sulla concentrazione, sull''umore e sul sistema immunitario. Adottare una ''igiene del sonno'' – limitando l''uso di dispositivi digitali prima di coricarsi e creando un ambiente confortevole – è un investimento necessario per la salute a lungo termine.

L''importanza delle relazioni sociali per il benessere è spesso sottovalutata. Gli esseri umani sono creature intrinsecamente sociali; l''isolamento prolungato può avere effetti deleteri sulla salute mentale tanto quanto il fumo o la sedentarietà. Coltivare amicizie autentiche e partecipare alla vita della comunità non solo arricchisce l''anima, ma fornisce una rete di supporto preziosa nei momenti di difficoltà, contribuendo a una maggiore longevità e qualità della vita.

In definitiva, il benessere è una responsabilità individuale che richiede scelte consapevoli ogni giorno. Non esistono soluzioni magiche o scorciatoie; il percorso verso una vita sana è fatto di piccoli cambiamenti costanti. Ascoltare il proprio corpo, prendersi cura della mente e circondarsi di persone positive sono i passi necessari per costruire una vita in cui la salute non sia solo un obiettivo, ma il fondamento su cui poggiano tutte le nostre attività quotidiane.', '[{"prompt":"Come è cambiata la definizione di salute secondo il testo?","options":["Si riferisce solo alla cura delle malattie gravi.","È intesa come benessere fisico, mentale e sociale.","È considerata un''assenza totale di problemi lavorativi.","Riguarda esclusivamente l''aspetto nutrizionale."],"answer_index":1,"explanation_pt_br":"O primeiro parágrafo define saúde como um estado integral de bem-estar físico, mental e social."},{"prompt":"Qual è il ruolo dello stress nella vita moderna?","options":["È un elemento necessario per migliorare le performance.","È una sfida che può portare a un esaurimento psicofisico.","È un problema che si risolve solo con farmaci.","Non ha effetti significativi sulla salute fisica."],"answer_index":1,"explanation_pt_br":"O texto descreve o estresse como um desafio que pode levar ao esgotamento físico e mental."},{"prompt":"Cosa si intende per ''alimentazione consapevole''?","options":["Seguire una dieta rigida basata solo sul conteggio calorico.","Mangiare solo prodotti confezionati per risparmiare tempo.","Ascoltare il corpo e scegliere cibi sani e di stagione.","Evitare completamente il cibo per lunghi periodi."],"answer_index":2,"explanation_pt_br":"Alimentação consciente é descrita como ouvir sinais de saciedade e escolher alimentos frescos."},{"prompt":"Perché il sonno è considerato fondamentale?","options":["Perché permette di evitare la vita sociale.","Perché il corpo ripara i tessuti e il cervello elabora le informazioni.","Perché riduce la necessità di fare esercizio fisico.","Perché aiuta a dimenticare i problemi lavorativi."],"answer_index":1,"explanation_pt_br":"O sono é crucial para processos biológicos de reparação e processamento de informações."},{"prompt":"Quale effetto ha l''isolamento sulla salute?","options":["Ha effetti negativi paragonabili a comportamenti dannosi.","Migliora la concentrazione e la salute mentale.","È l''unico modo per evitare lo stress quotidiano.","Non ha alcun impatto significativo sulla longevità."],"answer_index":0,"explanation_pt_br":"O autor compara o isolamento a fatores de risco como fumo ou sedentarismo."},{"prompt":"Cosa significa ''igiene del sonno''?","options":["Lavarsi prima di andare a dormire.","Dormire sempre in un luogo pubblico.","Adottare abitudini che favoriscono un buon riposo.","Utilizzare dispositivi digitali per rilassarsi."],"answer_index":2,"explanation_pt_br":"Higiene do sono refere-se a práticas que melhoram a qualidade do repouso, como evitar telas antes de dormir."},{"prompt":"Qual è la conclusione principale sull''idea di benessere?","options":["È un obiettivo che si raggiunge con scorciatoie.","È una responsabilità individuale fatta di piccole scelte costanti.","Dipende esclusivamente da fattori genetici.","È un traguardo statico e definitivo."],"answer_index":1,"explanation_pt_br":"O texto conclui que o bem-estar é uma construção diária baseada em escolhas conscientes."}]'::jsonb, 4),
('it-passage-b2-05', 'it', 'B2', 'Cibo, tradizioni e identità comunitaria', 'Il cibo è molto più di una necessità biologica; è un linguaggio universale che racconta la storia di un popolo, le sue migrazioni, i suoi incontri e le sue radici. In Italia, la tavola rappresenta il centro della vita comunitaria, un luogo dove le tradizioni si tramandano di generazione in generazione. Preparare una ricetta antica non significa solo cucinare, ma onorare una memoria collettiva che definisce chi siamo e da dove veniamo.

Le tradizioni culinarie regionali italiane sono un mosaico di diversità. Ogni paese, ogni valle ha i suoi prodotti tipici, legati indissolubilmente al territorio. Questa ricchezza è il frutto di secoli di scambi e di un profondo rispetto per la stagionalità. Mangiare locale significa sostenere l''economia di prossimità e preservare una biodiversità che altrimenti rischierebbe di scomparire sotto la spinta dell''agricoltura industriale globalizzata.

La convivialità è l''ingrediente segreto della dieta mediterranea. Non si tratta solo di ciò che si mangia, ma di come lo si mangia. Condividere il pasto con amici e familiari trasforma l''atto del nutrirsi in un momento di socializzazione e conforto emotivo. In una società sempre più atomizzata, il rito del pranzo domenicale o della cena in compagnia rappresenta un antidoto potente alla solitudine e un modo per rafforzare i legami comunitari.

Tuttavia, le tradizioni non devono essere considerate dei musei statici. La cucina è un''arte viva che evolve costantemente attraverso l''innovazione e la contaminazione. I grandi chef contemporanei, pur partendo dalla tradizione, sperimentano nuove tecniche che rendono i piatti classici accessibili e attuali. Questo dialogo tra passato e futuro permette alla cultura gastronomica di rimanere rilevante, adattandosi ai gusti e alle esigenze di una società in continuo mutamento.

L''educazione alimentare ha un ruolo chiave nella salvaguardia di questo patrimonio. Insegnare ai più giovani il valore degli ingredienti, il rispetto per la terra e la pazienza necessaria per la preparazione di certi piatti è un atto politico. Una comunità consapevole è una comunità che sa difendere le proprie origini contro la standardizzazione del gusto. La consapevolezza di ciò che mangiamo è, in fondo, la consapevolezza della nostra identità culturale.

In definitiva, preservare le tradizioni culinarie significa proteggere una parte fondamentale della nostra umanità. In un mondo che tende a uniformare i consumi, il ritorno ai sapori autentici e ai ritmi lenti della tavola è un atto di resistenza. Ogni volta che cuciniamo un piatto tradizionale, stiamo tessendo un filo invisibile che ci unisce agli altri, celebrando la ricchezza delle nostre differenze e la gioia profonda dello stare insieme.', '[{"prompt":"Perché il cibo è definito un ''linguaggio universale''?","options":["Perché si può mangiare ovunque senza parlare.","Perché comunica la storia e le radici di un popolo.","Perché le ricette sono identiche in tutto il mondo.","Perché è la lingua ufficiale di molti paesi."],"answer_index":1,"explanation_pt_br":"O texto afirma que o cibo comunica a história, as migrações e as raízes de um povo."},{"prompt":"Cosa significa ''biodiversità'' nel secondo paragrafo?","options":["La varietà di prodotti e specie legati al territorio.","L''uniformità dei prodotti agricoli industriali.","La tecnologia necessaria per cucinare velocemente.","La capacità di esportare prodotti in tutto il mondo."],"answer_index":0,"explanation_pt_br":"Biodiversidade refere-se à variedade de recursos naturais e agrícolas preservados localmente."},{"prompt":"Qual è il ruolo della convivialità nella dieta mediterranea?","options":["È un modo per mangiare più velocemente.","È un momento di socializzazione e legame affettivo.","Serve a nascondere la qualità dei piatti preparati.","È un obbligo formale senza valore emotivo."],"answer_index":1,"explanation_pt_br":"A convivialidade transforma a refeição em um momento de socialização e conforto."},{"prompt":"Come viene descritta l''evoluzione della cucina?","options":["Come un rifiuto totale del passato.","Come un processo statico che non deve cambiare.","Come un dialogo vivo tra tradizione e innovazione.","Come un''imposizione dei grandi chef internazionali."],"answer_index":2,"explanation_pt_br":"O autor defende que a cozinha é uma arte viva que evolui através do diálogo entre passado e futuro."},{"prompt":"Perché l''educazione alimentare è definita un ''atto politico''?","options":["Perché serve a votare nei partiti politici.","Perché difende l''identità culturale dalla standardizzazione.","Perché obbliga le persone a seguire una dieta specifica.","Perché è gestita direttamente dai governi centrali."],"answer_index":1,"explanation_pt_br":"O texto sugere que proteger as origens contra a padronização do gosto é um ato de resistência cultural."},{"prompt":"Cosa intende l''autore con ''società atomizzata''?","options":["Una società molto unita e solidale.","Una società composta da individui isolati.","Una società che vive solo in grandi città.","Una società basata sulla tecnologia scientifica."],"answer_index":1,"explanation_pt_br":"Sociedade atomizada refere-se a um grupo onde os indivíduos estão separados, perdendo o sentido de comunidade."},{"prompt":"Qual è il messaggio finale del testo?","options":["Dobbiamo smettere di cucinare piatti tradizionali.","La globalizzazione è l''unica via per il progresso culinario.","Il cibo è un filo che unisce le persone e protegge l''umanità.","Le tradizioni culinarie sono ormai superate dal tempo."],"answer_index":2,"explanation_pt_br":"A conclusão enfatiza que cozinhar pratos tradicionais une as pessoas e celebra a humanidade."}]'::jsonb, 5),
('it-passage-b2-06', 'it', 'B2', 'La tecnologia invisibile: oltre lo schermo', 'Viviamo in un''epoca in cui la tecnologia non è più un oggetto che teniamo in tasca, ma un''infrastruttura invisibile che permea ogni nostro gesto quotidiano. Dalle case domotiche che regolano la temperatura in base alla nostra presenza, fino agli algoritmi che suggeriscono i nostri percorsi stradali, il confine tra l''analogico e il digitale è diventato estremamente labile. Questa integrazione profonda ci ha regalato un''efficienza senza precedenti, permettendoci di ottimizzare tempi che un tempo venivano sprecati in attese burocratiche o spostamenti inutili.

Tuttavia, questa comodità ha un costo implicito che spesso ignoriamo: la costante frammentazione dell''attenzione. Siamo costantemente sollecitati da notifiche che frammentano il nostro flusso di lavoro e riducono la nostra capacità di concentrazione profonda. Il paradosso tecnologico risiede proprio qui: più siamo connessi con il mondo globale, più rischiamo di disconnetterci dalla nostra capacità di riflessione critica, delegando le nostre scelte quotidiane a sistemi automatizzati che conoscono i nostri gusti meglio di quanto facciamo noi stessi.

Molti esperti sottolineano come l''uso eccessivo di dispositivi intelligenti stia alterando la nostra percezione dello spazio e del tempo. La gratificazione istantanea offerta dai social media crea un ciclo di dipendenza dopaminergica che rende difficile tollerare la noia o il silenzio. Eppure, la noia è spesso il terreno fertile in cui nasce la creatività. Se riempiamo ogni istante vuoto con l''interazione digitale, stiamo involontariamente potando le radici della nostra immaginazione più autentica.

D''altra parte, non si può negare che la tecnologia abbia democratizzato l''accesso alla conoscenza. Chiunque, con una connessione internet, può oggi accedere a biblioteche digitali, corsi universitari e dibattiti di alto livello che un tempo erano riservati a una ristretta élite accademica. Questo potenziale di emancipazione è enorme, ma richiede un''alfabetizzazione digitale consapevole, capace di distinguere tra l''informazione di qualità e il rumore di fondo che spesso domina le piattaforme di condivisione rapida.

Il futuro della nostra convivenza con la tecnologia dipenderà dalla nostra capacità di imporre dei limiti. Non si tratta di rifiutare il progresso, ma di riappropriarsi della tecnologia come strumento anziché subirla come padrona. È necessario coltivare momenti di disconnessione programmata, riscoprendo il valore di attività analogiche che richiedono tempo e pazienza, come la lettura di un libro cartaceo o la conversazione faccia a faccia senza il supporto di alcun dispositivo elettronico intermediario.

In definitiva, la sfida non è tecnologica, ma antropologica. Dobbiamo imparare a gestire la nostra presenza digitale in modo che essa arricchisca la nostra esistenza invece di svuotarla. La tecnologia dovrebbe essere il riflesso delle nostre intenzioni più nobili, un''estensione della nostra volontà creativa piuttosto che un labirinto in cui ci perdiamo. Solo mantenendo il controllo sul mezzo potremo garantire che il progresso rimanga sempre al servizio dell''essere umano e non il contrario.', '[{"prompt":"Qual è il paradosso della tecnologia citato nel testo?","options":["La tecnologia migliora l''efficienza ma riduce la capacità di concentrazione.","Siamo più connessi globalmente ma meno capaci di usare i dispositivi.","La tecnologia rende la vita più facile ma aumenta i costi burocratici.","Siamo più intelligenti grazie ai dispositivi ma meno inclini alla socialità."],"answer_index":0,"explanation_pt_br":"O texto afirma que a conectividade constante fragmenta a atenção e reduz a concentração, apesar de aumentar a eficiência."},{"prompt":"Cosa intende l''autore con il termine ''frammentazione dell''attenzione''?","options":["L''incapacità di utilizzare più dispositivi contemporaneamente.","La divisione del lavoro in compiti troppo piccoli e ripetitivi.","L''interruzione costante del pensiero profondo a causa di notifiche.","La perdita di memoria causata dall''eccessiva quantità di dati."],"answer_index":2,"explanation_pt_br":"O autor descreve a interrupção constante do fluxo de trabalho pelas notificações digitais."},{"prompt":"Quale ruolo attribuisce l''autore alla noia?","options":["È una condizione negativa da eliminare tramite il digitale.","È un sintomo di dipendenza dai social media.","È un terreno fertile per lo sviluppo della creatività.","È un''emozione che la tecnologia ha finalmente superato."],"answer_index":2,"explanation_pt_br":"O texto explica que o tédio é o terreno onde nasce a criatividade."},{"prompt":"Cosa si intende per ''alfabetizzazione digitale consapevole''?","options":["Saper programmare software complessi.","Capacità di distinguere tra informazioni valide e rumore di fondo.","Utilizzare i social media per scopi puramente educativi.","Possedere i dispositivi tecnologici più moderni sul mercato."],"answer_index":1,"explanation_pt_br":"O texto define a alfabetização como a habilidade de distinguir informação de qualidade do ruído de fundo."},{"prompt":"Quale soluzione propone l''autore per migliorare il rapporto con la tecnologia?","options":["Abbandonare completamente l''uso dei dispositivi digitali.","Sostituire i libri digitali con quelli cartacei in ogni ambito.","Imporre limiti personali e praticare la disconnessione programmata.","Affidarsi totalmente ai sistemi di domotica per risparmiare tempo."],"answer_index":2,"explanation_pt_br":"O autor sugere estabelecer limites e praticar momentos de desconexão."},{"prompt":"Che cosa suggerisce la frase ''la sfida non è tecnologica, ma antropologica''?","options":["La tecnologia è troppo difficile da comprendere per gli esseri umani.","Il problema principale riguarda la natura umana e come usiamo gli strumenti.","Dobbiamo studiare l''antropologia per costruire software migliori.","La tecnologia ha ormai superato le capacità umane di evoluzione."],"answer_index":1,"explanation_pt_br":"Refere-se ao fato de que o desafio está em como o ser humano lida com a ferramenta, não na ferramenta em si."},{"prompt":"Qual è l''idea principale del brano?","options":["La tecnologia è l''unica causa del declino intellettuale moderno.","La tecnologia deve essere governata dall''uomo per arricchire la sua vita.","Dobbiamo smettere di usare la tecnologia per ritrovare la creatività.","L''efficienza tecnologica è l''unico valore da perseguire nel futuro."],"answer_index":1,"explanation_pt_br":"O texto defende o uso consciente e controlado da tecnologia para que ela sirva ao homem."}]'::jsonb, 6),
('it-passage-b2-07', 'it', 'B2', 'Sostenibilità: una scelta consapevole', 'La sostenibilità ambientale non è più un concetto astratto relegato ai dibattiti scientifici, ma una necessità impellente che richiede un cambiamento radicale nelle nostre abitudini quotidiane. Spesso pensiamo che il peso delle nostre azioni sia irrilevante di fronte alla vastità della crisi climatica, ma la somma di piccoli gesti consapevoli può generare un impatto significativo. La transizione ecologica inizia, infatti, dalle decisioni che prendiamo nel supermercato, nel guardaroba e durante i nostri spostamenti urbani.

Un primo passo fondamentale riguarda il consumo critico, ovvero l''atto di informarsi sulla provenienza dei prodotti che acquistiamo. Scegliere prodotti locali e di stagione non solo riduce drasticamente l''impronta di carbonio legata al trasporto, ma sostiene anche le economie agricole locali, creando un circolo virtuoso di benessere. La filiera corta è uno strumento potente per riappropriarsi del valore del cibo, sottraendolo alla logica massiva della grande distribuzione che spesso ignora i costi ambientali.

Il settore della moda rappresenta un''altra sfida cruciale. Il fenomeno del ''fast fashion'' ha abituato i consumatori a un turnover rapidissimo di capi di abbigliamento, spesso prodotti in condizioni eticamente discutibili e con materiali altamente inquinanti. Adottare un approccio più sostenibile significa privilegiare la qualità sulla quantità, riparare ciò che si è rotto e preferire materiali riciclati o naturali. Non si tratta solo di estetica, ma di un impegno etico verso le generazioni future.

Anche la gestione dei rifiuti domestici gioca un ruolo decisivo. Non è sufficiente differenziare, bisogna innanzitutto ridurre la produzione di scarti a monte. L''acquisto di prodotti sfusi, l''eliminazione della plastica monouso e la corretta manutenzione degli oggetti elettronici sono pratiche che allungano la vita dei beni, prevenendo l''accumulo di rifiuti difficili da smaltire. La cultura dell''usa e getta deve essere sostituita da una cultura della cura e del riutilizzo costante.

La sostenibilità è inoltre una questione di mobilità. Nelle grandi città, l''abuso dell''automobile privata è la causa principale di inquinamento atmosferico e congestione. Promuovere l''uso del trasporto pubblico, della bicicletta o del car-sharing non è solo un atto di civiltà, ma una scelta che migliora la qualità della vita urbana. Una città costruita a misura d''uomo, meno rumorosa e meno inquinata, è un obiettivo realizzabile se supportato da politiche pubbliche coraggiose.

In conclusione, la sostenibilità è una forma di rispetto verso il pianeta che ci ospita. Richiede una revisione critica del proprio stile di vita, superando la tentazione di una comodità effimera a favore di una visione di lungo periodo. Ogni nostra scelta è un voto per il mondo che vogliamo costruire. La consapevolezza è la prima arma che abbiamo per trasformare l''utopia di un futuro verde in una realtà concreta e tangibile per tutti noi.', '[{"prompt":"Cosa intende l''autore con ''filiera corta''?","options":["Un sistema di distribuzione che riduce gli intermediari tra produttore e consumatore.","Un metodo per riciclare i materiali di scarto agricolo.","Una tecnica per coltivare prodotti agricoli in spazi urbani ristretti.","La scelta di acquistare solo prodotti confezionati in piccole quantità."],"answer_index":0,"explanation_pt_br":"A filiera corta refere-se a reduzir intermediários, aproximando o produtor do consumidor."},{"prompt":"Perché il ''fast fashion'' è considerato problematico?","options":["Perché utilizza tessuti troppo costosi per il consumatore medio.","Perché promuove un ricambio veloce con impatti etici e ambientali negativi.","Perché produce capi che durano troppo a lungo e non stimolano l''economia.","Perché non permette la personalizzazione dell''abbigliamento."],"answer_index":1,"explanation_pt_br":"O texto menciona que o fast fashion causa impacto ambiental e ético devido ao ritmo rápido de produção."},{"prompt":"Qual è il rapporto tra rifiuti e sostenibilità secondo il testo?","options":["Bisogna riciclare il più possibile senza preoccuparsi della produzione.","La riduzione dei rifiuti a monte è più importante del semplice riciclo.","Il riciclo è una pratica inutile se non si usano materiali biodegradabili.","La produzione di rifiuti è inevitabile nel mondo moderno."],"answer_index":1,"explanation_pt_br":"O autor enfatiza que a redução de resíduos na fonte é crucial, além da reciclagem."},{"prompt":"Quale vantaggio offre la scelta di prodotti locali?","options":["Maggiore varietà di scelta durante tutto l''anno.","Riduzione dell''impronta di carbonio e supporto all''economia locale.","Eliminazione completa del bisogno di imballaggi.","Prezzi sempre inferiori rispetto alla grande distribuzione."],"answer_index":1,"explanation_pt_br":"O texto destaca a redução da pegada de carbono e o apoio à economia local."},{"prompt":"Cosa si suggerisce per migliorare la mobilità urbana?","options":["Aumentare il numero di parcheggi per auto private.","Privilegiare l''uso di veicoli elettrici personali.","Promuovere mezzi pubblici, biciclette e condivisione dei veicoli.","Costruire più strade per evitare il traffico."],"answer_index":2,"explanation_pt_br":"O autor sugere o uso de transporte público, bicicletas e car-sharing."},{"prompt":"Il tono del brano è:","options":["Pessimista riguardo al futuro climatico.","Propositivo e orientato alla responsabilità individuale.","Critico verso le politiche pubbliche esistenti.","Tecnico e rivolto solo agli specialisti del settore."],"answer_index":1,"explanation_pt_br":"O texto é propositivo, focando na responsabilidade de cada indivíduo."},{"prompt":"Qual è il messaggio centrale dell''ultimo paragrafo?","options":["La sostenibilità è un compito esclusivo dei governi.","La nostra comodità deve venire prima dell''ambiente.","Le nostre scelte quotidiane determinano il futuro del pianeta.","L''utopia di un futuro verde è impossibile da realizzare."],"answer_index":2,"explanation_pt_br":"O autor conclui que cada escolha é um voto para o mundo que queremos."}]'::jsonb, 7),
('it-passage-b2-08', 'it', 'B2', 'Relazioni umane nell''era della fluidità', 'Nel panorama contemporaneo, le relazioni sociali stanno attraversando una fase di profonda trasformazione, segnata da una fluidità che un tempo era sconosciuta. I legami, siano essi di amicizia o sentimentali, sembrano meno stabili e più soggetti alle dinamiche di un mondo che corre veloce. Se da una parte questa libertà offre la possibilità di esplorare nuove forme di connessione, dall''altra espone l''individuo a una sorta di precarietà affettiva che genera spesso un senso di solitudine diffuso.

La tecnologia, ancora una volta, gioca un ruolo ambiguo in questo contesto. Da un lato, ci permette di mantenere contatti con persone lontane, abbattendo le barriere geografiche che un tempo rendevano i legami impossibili da coltivare. D''altro canto, la facilità con cui possiamo iniziare o terminare una conversazione digitale può svuotare le relazioni di profondità. La comunicazione mediata dallo schermo spesso manca di quella componente non verbale che è fondamentale per costruire una vera empatia.

L''amicizia, in particolare, sta subendo un processo di ridefinizione. Il concetto di ''amico'' sui social network, spesso ridotto a un semplice numero in una lista, ha poco a che fare con la qualità del legame. Tuttavia, esistono ancora spazi per amicizie autentiche, quelle che richiedono tempo, presenza fisica e la condivisione di momenti significativi. È in questi spazi protetti che la fiducia viene costruita, lentamente e con cura, sfidando la velocità del mondo esterno.

Nelle relazioni di coppia, la sfida è altrettanto complessa. La ricerca della realizzazione personale, spesso enfatizzata come valore assoluto, può entrare in conflitto con la necessità di compromesso che ogni relazione richiede. Il rischio è quello di approcciarsi all''altro come a un prodotto da consumare, cercando la perfezione invece di accettare le imperfezioni altrui. La stabilità affettiva richiede oggi un atto di coraggio: quello di scegliere l''altro giorno dopo giorno, nonostante le incertezze.

La vita sociale non si limita però ai legami stretti. La partecipazione a comunità, associazioni o gruppi di interesse rappresenta un pilastro fondamentale per il benessere psicologico. Condividere passioni o impegnarsi in cause comuni aiuta a combattere l''isolamento e a sentirsi parte di un tessuto sociale più ampio. In un''epoca segnata dall''individualismo, ritrovare il senso del collettivo è un antidoto potente contro la frammentazione della società moderna.

In conclusione, costruire relazioni solide richiede consapevolezza e intenzione. Non basta la vicinanza fisica o digitale; serve un impegno costante verso l''altro. La qualità di una vita sociale non si misura in quantità di interazioni, ma nella capacità di creare legami che diano sostegno reciproco. In un mondo che cambia, la capacità di prendersi cura degli altri rimane la competenza umana più preziosa e, forse, la più rivoluzionaria di tutte.', '[{"prompt":"Cosa intende l''autore per ''precarietà affettiva''?","options":["La difficoltà di trovare un partner adatto ai nostri bisogni.","L''instabilità e l''incertezza che caratterizzano i legami moderni.","Il timore di essere giudicati negativamente dagli altri.","La mancanza di tempo per dedicarsi alla propria vita privata."],"answer_index":1,"explanation_pt_br":"O termo refere-se à instabilidade e à transitoriedade nas relações atuais."},{"prompt":"Qual è il limite principale della comunicazione digitale secondo il testo?","options":["La lentezza nel trasmettere messaggi complessi.","L''assenza di componenti non verbali essenziali per l''empatia.","L''impossibilità di raggiungere persone geograficamente lontane.","Il costo elevato delle piattaforme di comunicazione."],"answer_index":1,"explanation_pt_br":"O autor menciona a ausência de elementos não verbais na comunicação mediada por telas."},{"prompt":"Cosa differenzia un''amicizia autentica dai legami sui social network?","options":["La frequenza con cui si pubblicano contenuti insieme.","La necessità di essere iscritti alle stesse piattaforme digitali.","La presenza fisica, il tempo condiviso e la costruzione della fiducia.","Il numero di persone che confermano il valore dell''amicizia."],"answer_index":2,"explanation_pt_br":"O texto define a amizade autêntica através da presença e da confiança construída."},{"prompt":"Qual è il rischio principale nelle relazioni di coppia moderne?","options":["La troppa vicinanza che soffoca la libertà individuale.","La difficoltà di trovare persone con interessi simili.","Trattare il partner come un prodotto da consumare invece di valorizzarlo.","L''eccessiva pressione sociale verso il matrimonio."],"answer_index":2,"explanation_pt_br":"O autor alerta para o risco de ver o outro como um objeto de consumo."},{"prompt":"Perché partecipare ad associazioni è utile per l''individuo?","options":["Aiuta a combattere l''isolamento e a sentirsi parte di un collettivo.","Permette di guadagnare denaro extra attraverso il volontariato.","È l''unico modo per conoscere nuove persone nel mondo moderno.","Riduce il tempo passato a casa davanti al computer."],"answer_index":0,"explanation_pt_br":"O texto aponta que o engajamento comunitário ajuda a combater o isolamento."},{"prompt":"Che cosa suggerisce l''autore per migliorare la qualità delle relazioni?","options":["Evitare di impegnarsi in relazioni stabili per non soffrire.","Usare solo app di messaggistica per mantenere le distanze.","Scegliere l''altro con intenzione e impegno costante.","Smettere di cercare la perfezione e stare da soli."],"answer_index":2,"explanation_pt_br":"O autor enfatiza a escolha consciente e o esforço contínuo pelo outro."},{"prompt":"Qual è il tono dell''autore verso il cambiamento sociale?","options":["Nostalgico verso il passato.","Riflessivo e propositivo.","Estremamente critico e cinico.","Totalmente ottimista."],"answer_index":1,"explanation_pt_br":"O texto reflete sobre as mudanças e propõe caminhos para manter a qualidade dos vínculos."}]'::jsonb, 8),
('it-passage-b2-09', 'it', 'B2', 'Finanza personale: gestire il proprio futuro', 'La gestione delle finanze personali è una competenza fondamentale che spesso viene trascurata durante il percorso scolastico, lasciando molti adulti impreparati di fronte alle complessità del mondo economico moderno. Avere una visione chiara delle proprie entrate e uscite non significa solo evitare il debito, ma è il primo passo per costruire una sicurezza a lungo termine e realizzare i propri obiettivi di vita. La consapevolezza finanziaria è, in sostanza, una forma di libertà che permette di fare scelte basate sui valori personali piuttosto che sulla necessità immediata.

Il primo pilastro di una gestione finanziaria solida è il budget. Monitorare regolarmente dove finisce il proprio denaro aiuta a identificare le spese superflue e a dare priorità a ciò che conta davvero. Molte persone vedono il budget come una restrizione, mentre in realtà è uno strumento di pianificazione che dà potere decisionale. Sapere esattamente quanto si può spendere in svago o in risparmio trasforma il rapporto con il denaro, riducendo l''ansia legata agli imprevisti.

Il risparmio deve essere considerato come una priorità e non come ciò che resta alla fine del mese. Creare un fondo di emergenza, capace di coprire almeno tre o sei mesi di spese essenziali, è fondamentale per navigare le incertezze della vita lavorativa. Questo ''cuscinetto'' finanziario permette di affrontare periodi di disoccupazione, spese mediche improvvise o riparazioni domestiche senza dover ricorrere a prestiti ad alto interesse, che rappresentano una trappola per molti consumatori.

Oltre al risparmio, il tema dell''investimento è sempre più attuale. Con l''inflazione che erode il potere d''acquisto nel tempo, lasciare il denaro fermo sul conto corrente non è una strategia prudente. Tuttavia, investire richiede conoscenza e cautela. Non si tratta di cercare guadagni facili o speculazioni rischiose, ma di pianificare una crescita graduale attraverso strumenti diversificati. L''educazione finanziaria, in questo senso, è l''investimento più redditizio che una persona possa fare su se stessa.

Il consumo consapevole è l''altra faccia della medaglia. Siamo costantemente bombardati da messaggi pubblicitari che ci spingono all''acquisto compulsivo per soddisfare desideri immediati. Resistere a queste tentazioni richiede una riflessione critica sul perché acquistiamo determinati beni. Spesso, ciò che compriamo serve a colmare vuoti emotivi o a proiettare un''immagine sociale. Distinguere tra bisogni reali e desideri indotti dal marketing è essenziale per mantenere l''equilibrio del proprio bilancio.

In definitiva, la finanza personale è un viaggio che richiede disciplina e pazienza. Non si diventa esperti da un giorno all''altro, ma è possibile imparare a gestire le proprie risorse con saggezza. L''obiettivo finale non è l''accumulo di ricchezza fine a se stesso, ma l''acquisizione di una serenità che permetta di vivere in linea con le proprie aspirazioni. Prendersi cura dei propri soldi significa, in ultima analisi, prendersi cura del proprio futuro e della propria autonomia.', '[{"prompt":"Perché l''autore definisce il budget come ''strumento di pianificazione''?","options":["Perché serve esclusivamente a ridurre le spese per il divertimento.","Perché permette di avere il controllo e il potere di scegliere come usare il denaro.","Perché è obbligatorio per legge gestire le proprie finanze tramite un budget.","Perché serve ad aumentare le entrate lavorative mensili."],"answer_index":1,"explanation_pt_br":"O texto explica que o orçamento não é uma restrição, mas um meio de ter controle e decisão."},{"prompt":"Cosa si intende per ''fondo di emergenza''?","options":["Un prestito bancario garantito dallo Stato.","Un investimento ad alto rischio per guadagnare velocemente.","Una riserva di denaro per coprire spese impreviste per alcuni mesi.","Il risparmio destinato esclusivamente alla pensione futura."],"answer_index":2,"explanation_pt_br":"O autor define o fundo de emergência como uma reserva para despesas essenciais inesperadas."},{"prompt":"Secondo il testo, perché lasciare i soldi fermi sul conto è rischioso?","options":["Perché le banche impongono commissioni molto alte.","Perché l''inflazione riduce il valore reale del denaro nel tempo.","Perché si rischia di dimenticare quanto denaro si ha a disposizione.","Perché il conto corrente può essere chiuso improvvisamente."],"answer_index":1,"explanation_pt_br":"O texto menciona que a inflação corrói o poder de compra do dinheiro parado."},{"prompt":"Quale consiglio dà l''autore riguardo agli investimenti?","options":["Cercare sempre speculazioni ad alto rendimento.","Affidarsi totalmente ai consulenti bancari senza studiare.","Pianificare una crescita graduale e diversificata.","Evitare qualsiasi tipo di investimento per non rischiare nulla."],"answer_index":2,"explanation_pt_br":"O autor sugere cautela, diversificação e planejamento gradual."},{"prompt":"Che cosa spinge spesso le persone ad acquistare beni inutili?","options":["La necessità di risparmiare sui costi di manutenzione.","La pressione del marketing e il tentativo di colmare vuoti emotivi.","Il consiglio degli esperti finanziari.","La disponibilità di troppa liquidità sul conto corrente."],"answer_index":1,"explanation_pt_br":"O texto explica que o consumo compulsivo é influenciado pelo marketing e por razões emocionais."},{"prompt":"Qual è il vero obiettivo della gestione finanziaria?","options":["Diventare milionari il prima possibile.","Accumulare ricchezza senza mai spenderla.","Vivere in linea con le proprie aspirazioni e mantenere l''autonomia.","Dimostrare agli altri la propria stabilità economica."],"answer_index":2,"explanation_pt_br":"O objetivo final é a serenidade e viver conforme as próprias aspirações."},{"prompt":"Qual è il tema centrale del brano?","options":["L''importanza di non spendere mai denaro.","La necessità di un''educazione finanziaria per la libertà personale.","La corruzione del sistema bancario moderno.","La difficoltà di vivere in un mondo dominato dal denaro."],"answer_index":1,"explanation_pt_br":"O texto foca na educação financeira como ferramenta para a liberdade e autonomia."}]'::jsonb, 9),
('it-passage-b2-10', 'it', 'B2', 'L''educazione permanente: imparare a ogni età', 'L''idea che l''istruzione sia un capitolo della vita che si chiude dopo il conseguimento di un diploma o di una laurea è ormai un retaggio del passato. Nel mondo contemporaneo, caratterizzato da un''evoluzione tecnologica frenetica e da cambiamenti socio-economici costanti, l''apprendimento permanente, noto anche come ''lifelong learning'', è diventato una necessità imprescindibile. Non si tratta più solo di aggiornarsi professionalmente, ma di coltivare una mentalità aperta che permetta di adattarsi a nuove sfide e di arricchire costantemente il proprio bagaglio culturale.

L''educazione continua non riguarda solo le competenze tecniche, spesso chiamate ''hard skills'', ma investe anche le competenze trasversali, o ''soft skills''. La capacità di risolvere problemi complessi, di comunicare efficacemente in contesti multiculturali e di gestire le proprie emozioni è fondamentale in ogni ambito lavorativo e personale. Investire in se stessi significa riconoscere che il potenziale umano non ha una data di scadenza e che ogni momento è adatto per scoprire nuove passioni o raffinare abilità già esistenti.

Uno dei maggiori benefici dell''educazione permanente è il mantenimento della plasticità cerebrale. Mantenere la mente attiva attraverso lo studio di una nuova lingua, la pratica di uno strumento musicale o l''approfondimento di temi scientifici stimola il cervello e ritarda il declino cognitivo. Inoltre, il processo di apprendimento stesso apporta un senso di gratificazione e autostima. Superare le difficoltà iniziali in un nuovo campo di studio ci ricorda che siamo in grado di crescere e di superare i nostri limiti, indipendentemente dall''età.

La tecnologia ha reso il lifelong learning più accessibile che mai. Piattaforme online, corsi aperti a tutti e webinar offrono la possibilità di imparare da esperti di fama mondiale senza dover lasciare la propria casa. Questa democratizzazione del sapere è un''opportunità straordinaria, ma richiede una forte autodisciplina. Senza un ambiente strutturato come quello di una scuola tradizionale, spetta all''individuo gestire il proprio tempo, definire i propri obiettivi e mantenere alta la motivazione necessaria per proseguire nel percorso scelto.

Tuttavia, l''apprendimento non deve essere visto esclusivamente in un''ottica utilitaristica legata al lavoro. Imparare per il puro piacere della conoscenza, per curiosità intellettuale o per arricchimento personale è altrettanto importante. La lettura, la partecipazione a conferenze, l''esplorazione di nuove forme d''arte: tutto ciò contribuisce a formare cittadini più critici, consapevoli e partecipi alla vita democratica. La cultura è un antidoto contro il pregiudizio e un ponte verso la comprensione reciproca tra le persone.

In ultima analisi, il lifelong learning è uno stile di vita che promuove la curiosità e la resilienza. Accettare di tornare ad essere studenti, spogliandosi della presunzione di sapere già tutto, è un atto di umiltà intellettuale. Chi continua ad imparare non solo rimane competitivo in un mercato del lavoro mutevole, ma vive un''esistenza più piena e dinamica. L''apprendimento è il motore che tiene viva la fiamma della scoperta, rendendo ogni fase della vita un''occasione preziosa per evolvere.', '[{"prompt":"Cosa significa il concetto di ''lifelong learning'' nel testo?","options":["La necessità di studiare tutta la vita per ottenere titoli accademici.","L''apprendimento continuo come necessità per adattarsi e crescere.","Il processo di aggiornamento lavorativo obbligatorio per legge.","La capacità di insegnare agli altri ciò che si è imparato."],"answer_index":1,"explanation_pt_br":"O texto define o lifelong learning como a necessidade de aprender continuamente ao longo da vida."},{"prompt":"Qual è la differenza citata tra ''hard skills'' e ''soft skills''?","options":["Le prime riguardano la tecnica, le seconde le competenze trasversali.","Le prime sono per giovani, le seconde per adulti.","Le prime si imparano a scuola, le seconde solo lavorando.","Non c''è differenza, sono sinonimi nello studio."],"answer_index":0,"explanation_pt_br":"O autor distingue habilidades técnicas (hard) de habilidades comportamentais/sociais (soft)."},{"prompt":"Quale beneficio cognitivo viene menzionato riguardo all''apprendimento?","options":["La capacità di memorizzare tutto più velocemente.","Il mantenimento della plasticità cerebrale e il contrasto al declino cognitivo.","La riduzione drastica della necessità di dormire.","Il miglioramento della vista attraverso lo studio costante."],"answer_index":1,"explanation_pt_br":"O texto destaca que manter a mente ativa ajuda a preservar a plasticidade cerebral."},{"prompt":"Qual è la sfida principale dell''apprendimento online?","options":["Il costo proibitivo delle piattaforme digitali.","La scarsa qualità degli esperti che insegnano online.","La necessità di avere molta autodisciplina e gestione del tempo.","L''impossibilità di ottenere certificazioni ufficiali."],"answer_index":2,"explanation_pt_br":"O autor aponta que a falta de estrutura tradicional exige autodisciplina do estudante."},{"prompt":"Perché l''autore dice che l''apprendimento non deve essere solo ''utilitaristico''?","options":["Perché il lavoro non è importante nella vita adulta.","Perché imparare per piacere personale arricchisce il cittadino e la sua criticità.","Perché gli hobby non hanno alcun valore pratico.","Perché è meglio non mescolare lavoro e studio."],"answer_index":1,"explanation_pt_br":"O autor defende que o aprendizado também deve focar no enriquecimento pessoal e crítico."},{"prompt":"Cosa intende l''autore con ''umiltà intellettuale''?","options":["La capacità di ammettere di non sapere tutto e voler imparare ancora.","La tendenza a nascondere le proprie conoscenze agli altri.","Il rispetto verso i professori universitari.","La convinzione che l''istruzione sia inferiore all''esperienza."],"answer_index":0,"explanation_pt_br":"Refere-se a estar aberto ao aprendizado, reconhecendo que nunca se sabe o suficiente."},{"prompt":"Qual è il messaggio conclusivo del brano?","options":["L''istruzione è un dovere che finisce con l''età adulta.","L''apprendimento è un motore di evoluzione che arricchisce ogni fase della vita.","Solo chi ha molto tempo libero può permettersi di studiare.","Il mercato del lavoro è l''unico motivo per continuare a imparare."],"answer_index":1,"explanation_pt_br":"O autor conclui que o aprendizado contínuo torna a vida mais plena e dinâmica."}]'::jsonb, 10)
